import React, { Component } from "react";
import Select from "react-select";
import { connect } from "react-redux";
import { commonUtils } from "_helpers";

class ChecklistChangeModal extends Component {
    componentDidUpdate(prevProps) {
        if (this.props.show && !prevProps.show) {
            this.props.onResetSelection();
        }
    }

    render() {
        if (!this.props.show) return null;

        return (
            <div className="lux-checklist-change-modal" role="dialog" aria-modal="true">
                <div className="lux-checklist-change-modal__backdrop" onClick={this.props.onClose} />
                <div className="lux-checklist-change-modal__panel">
                    <header className="lux-checklist-change-modal__head">
                        <div>
                            <span className="lux-checklist-change-modal__kicker">Checklist template</span>
                            <h3 className="lux-checklist-change-modal__title">Change checklist</h3>
                        </div>
                        <button type="button" className="pd-icon-btn link" onClick={this.props.onClose} aria-label="Close">
                            <i className="fe fe-x" />
                        </button>
                    </header>

                    <div className="lux-checklist-change-modal__body">
                        <label className="lux-estimate-field__label">Select a checklist</label>
                        <Select
                            isSearchable
                            isClearable={false}
                            placeholder="Select checklist"
                            classNamePrefix="custom-select"
                            menuPlacement="auto"
                            value={this.props.selectedChecklist}
                            onChange={this.props.onSelect}
                            options={this.props.checklistDataList
                                && commonUtils.convertObjectToSelectObject(this.props.checklistDataList)}
                        />
                        <p className="lux-checklist-change-modal__hint">
                            Switching templates will replace current questions. Save after confirming your selection.
                        </p>
                    </div>

                    <footer className="lux-checklist-change-modal__foot">
                        <button type="button" className="lux-estimate-btn lux-estimate-btn--ghost" onClick={this.props.onClose}>
                            Cancel
                        </button>
                        <button
                            type="button"
                            className="lux-estimate-btn lux-estimate-btn--primary"
                            disabled={!this.props.changeButtonEnabled}
                            onClick={this.props.onApply}
                        >
                            Apply template
                        </button>
                    </footer>
                </div>
            </div>
        );
    }
}

const mapStateToProps = (state) => ({
    checklistDataList: state.checklist.items,
});

export default connect(mapStateToProps)(ChecklistChangeModal);
