import dateUtils from "_helpers/date.utils";
import { formatPlannerHours } from "./planner.utils";

export function buildDayCapacityMapFromRow(row) {
  if (!row || !row.dayCells) return {};
  const map = {};
  row.dayCells.forEach((cell) => {
    const clientDate = dateUtils.convertDateToMoment(cell.dayMoment).format(dateUtils.CLIENT_DATE_FORMAT);
    const info = {
      dayKey: cell.dayKey,
      weekday: cell.label,
      dateLabel: cell.dateLabel,
      dayNumber: cell.dayMoment.day(),
      allocated: cell.allocated,
      capacity: cell.capacity,
      free: cell.free,
      utilization: cell.utilization,
      isOnLeave: cell.isOnLeave,
      isWeekend: cell.isWeekend,
      isHoliday: cell.isHoliday,
      allocatedLabel: formatPlannerHours(cell.allocated),
      capacityLabel: formatPlannerHours(cell.capacity),
      freeLabel: formatPlannerHours(cell.free),
    };
    map[clientDate] = info;
    map[cell.dayKey] = info;
  });
  return map;
}

export function lookupDayCapacity(dayCapacityMap, dateString) {
  if (!dayCapacityMap || !dateString) return null;
  if (dayCapacityMap[dateString]) return dayCapacityMap[dateString];
  const m = dateUtils.convertDateStringToMoment(dateString);
  if (!m) return null;
  const iso = m.format("YYYY-MM-DD");
  return dayCapacityMap[iso] || null;
}

export function hoursDecimalToMinutes(hoursValue) {
  if (hoursValue === "" || hoursValue == null) return 0;
  const h = parseFloat(hoursValue);
  if (Number.isNaN(h)) return 0;
  return parseInt(h, 10) * 60 + Math.round((h - parseInt(h, 10)) * 100);
}

export function minutesToHoursDecimal(mins) {
  const m = Math.max(0, Math.round(mins || 0));
  const hours = Math.floor(m / 60);
  const rem = m % 60;
  return hours + rem / 100;
}

export function formatHoursDecimalForInput(mins) {
  const dec = minutesToHoursDecimal(mins);
  return dec === 0 ? "" : String(dec);
}

export function summarizePlannerTimeEntry(timeEntry, dayCapacityMap) {
  if (!timeEntry) return null;

  let dayCount = 0;
  let totalDraftMins = 0;
  let overDayCount = 0;
  let totalOverMins = 0;

  Object.keys(timeEntry).forEach((dateKey) => {
    const entry = timeEntry[dateKey];
    const dayInfo = lookupDayCapacity(dayCapacityMap, dateKey);
    const draftMins =
      entry.timesheetTimeMins != null
        ? entry.timesheetTimeMins
        : hoursDecimalToMinutes(entry.timesheetTimeHours);
    const allocated = dayInfo ? dayInfo.allocated : 0;
    const capacity = dayInfo ? dayInfo.capacity : 0;

    dayCount += 1;
    totalDraftMins += draftMins;

    if (capacity > 0) {
      const totalAfter = allocated + draftMins;
      if (totalAfter > capacity) {
        overDayCount += 1;
        totalOverMins += totalAfter - capacity;
      }
    }
  });

  return {
    dayCount,
    totalDraftMins,
    totalDraftLabel: formatPlannerHours(totalDraftMins),
    overDayCount,
    totalOverLabel: formatPlannerHours(totalOverMins),
    hasOverUtilization: overDayCount > 0,
  };
}
