const COLLAPSED_KEY = "famstack-timesheet-batch-reopen-collapsed";

function selectionKey(employeeId, weekId) {
  return `famstack-timesheet-batch-reopen-selection:${employeeId}:${weekId}`;
}

export function readBatchReopenCollapsed() {
  try {
    return localStorage.getItem(COLLAPSED_KEY) === "1";
  } catch (error) {
    return false;
  }
}

export function writeBatchReopenCollapsed(collapsed) {
  try {
    localStorage.setItem(COLLAPSED_KEY, collapsed ? "1" : "0");
  } catch (error) {
    /* ignore quota / private mode */
  }
}

export function readBatchReopenSelection(employeeId, weekId) {
  if (employeeId == null || weekId == null) {
    return null;
  }
  try {
    const value = localStorage.getItem(selectionKey(employeeId, weekId));
    return value != null && value !== "" ? value : null;
  } catch (error) {
    return null;
  }
}

export function writeBatchReopenSelection(employeeId, weekId, submissionId) {
  if (employeeId == null || weekId == null || submissionId == null || submissionId === "") {
    return;
  }
  try {
    localStorage.setItem(selectionKey(employeeId, weekId), String(submissionId));
  } catch (error) {
    /* ignore quota / private mode */
  }
}
