import { UNIVERSAL_APPROVAL_STATUSES } from "./universal-approval.config";
import { resolveApprovalSlaState } from "./approval-sla.utils";

/** Payroll-critical domains that should visually demand immediate manager action. */
export const OPERATIONAL_URGENT_DOMAINS = new Set([
  "TIMESHEET",
  "ATTENDANCE",
  "ATTENDANCE_REGULARIZATION",
]);

export function isOperationalUrgentDomain(domain) {
  return OPERATIONAL_URGENT_DOMAINS.has(String(domain || "").toUpperCase());
}

export function resolveApprovalAttentionLevel(item, now = new Date()) {
  if (!item || item.status !== UNIVERSAL_APPROVAL_STATUSES.PENDING) {
    return null;
  }
  if (!isOperationalUrgentDomain(item.domain)) {
    return null;
  }

  const sla = resolveApprovalSlaState(item, now);
  const isHigh = String(item.priority || "").toUpperCase() === "HIGH";
  const meta = (item && item.metadata) || {};
  const hasConflict =
    item.domain === "TIMESHEET" &&
    (Number(meta.conflictCount) > 0 ||
      meta.timesheetConflict === "Yes" ||
      String(meta.timesheetConflict || "").toLowerCase() === "yes");

  if (sla.bucket === "overdue" || hasConflict) {
    return "critical";
  }
  if (isHigh || sla.bucket === "dueSoon") {
    return "urgent";
  }
  return "elevated";
}

export function getApprovalAttentionMeta(item, now = new Date()) {
  const level = resolveApprovalAttentionLevel(item, now);
  if (!level) {
    return null;
  }

  const domain = String(item.domain || "").toUpperCase();
  const domainShort =
    domain === "TIMESHEET"
      ? "Timesheet"
      : domain === "ATTENDANCE_REGULARIZATION"
        ? "Punch regularization"
        : "Attendance";

  const byLevel = {
    critical: {
      label: "Urgent — approve now",
      shortLabel: "Urgent",
      hint: `${domainShort} is overdue and blocking payroll operations.`,
      icon: "fe-alert-triangle",
      tone: "critical",
    },
    urgent: {
      label: "High priority — review today",
      shortLabel: "High",
      hint: `${domainShort} needs your sign-off before the SLA window closes.`,
      icon: "fe-zap",
      tone: "urgent",
    },
    elevated: {
      label: "Action needed",
      shortLabel: "Pending",
      hint: `${domainShort} is waiting for manager approval.`,
      icon: "fe-clock",
      tone: "elevated",
    },
  };

  return {
    level,
    domainShort,
    ...(byLevel[level] || byLevel.elevated),
  };
}
