import React from "react";
import classNames from "classnames/bind";
import { WorkflowLuxPanel } from "views/automation/components/WorkflowLuxShared";

export default function TriggerConfigPanel({ triggers, selectedTrigger, onSelect, loading }) {
  const list = triggers || [];

  return (
    <WorkflowLuxPanel title="Trigger registry" meta="Event sources" icon="fe fe-radio" accent="blue">
      {loading ? (
        <div className="lux-wf-skeleton lux-wf-skeleton--panel" />
      ) : (
        <ul className="lux-wf-trigger-list">
          {list.map((item) => (
            <li key={item.id}>
              <button
                type="button"
                className={classNames("lux-wf-trigger-chip", item.tone && `is-${item.tone}`, selectedTrigger === item.id && "is-selected")}
                onClick={() => onSelect && onSelect(item)}
              >
                <span className="lux-wf-trigger-chip__module">{item.module}</span>
                <strong>{item.label}</strong>
                <span>{item.description}</span>
              </button>
            </li>
          ))}
        </ul>
      )}
    </WorkflowLuxPanel>
  );
}
