import {
  PAYROLL_RUN_STATUSES,
  PAYROLL_EXCEPTION_SEVERITIES,
} from "config/payroll.config";

export function getPayrollRunStatusTone(status) {
  switch (status) {
    case PAYROLL_RUN_STATUSES.LOCKED:
    case PAYROLL_RUN_STATUSES.FINALIZED:
      return "success";
    case PAYROLL_RUN_STATUSES.PENDING_APPROVAL:
    case PAYROLL_RUN_STATUSES.CALCULATED:
      return "warning";
    case PAYROLL_RUN_STATUSES.APPROVED:
      return "slate";
    case PAYROLL_RUN_STATUSES.REOPENED:
      return "danger";
    default:
      return "slate";
  }
}

export function formatPayrollDate(value) {
  if (!value) {
    return "—";
  }
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {
    return value;
  }
  return date.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

export function buildSalaryStructureMetrics(structures) {
  const rows = structures || [];
  const active = rows.filter((row) => row.status === "Active").length;
  const employees = rows.reduce((sum, row) => sum + (Number(row.employeeCount) || 0), 0);
  const components = rows.reduce((sum, row) => sum + (Number(row.componentCount) || 0), 0);
  return {
    total: rows.length,
    active,
    draft: rows.length - active,
    employees,
    avgComponents: rows.length ? Math.round(components / rows.length) : 0,
  };
}

export function buildPayrollGroupMetrics(groups) {
  const rows = groups || [];
  const employees = rows.reduce((sum, row) => sum + (Number(row.employeeCount) || 0), 0);
  const nextPayDate = rows.map((row) => row.nextPayDate).filter(Boolean).sort()[0] || null;
  return {
    total: rows.length,
    employees,
    frequencies: [...new Set(rows.map((row) => row.payFrequency).filter(Boolean))].length,
    nextPayDate,
  };
}

export function buildPayrollRunLifecycleSteps(currentStatus) {
  const steps = [
    { id: "draft", label: "Draft", statuses: [PAYROLL_RUN_STATUSES.DRAFT] },
    { id: "calculate", label: "Calculate", statuses: [PAYROLL_RUN_STATUSES.CALCULATED, PAYROLL_RUN_STATUSES.REOPENED] },
    { id: "approve", label: "Approve", statuses: [PAYROLL_RUN_STATUSES.PENDING_APPROVAL, PAYROLL_RUN_STATUSES.APPROVED] },
    { id: "finalize", label: "Finalize", statuses: [PAYROLL_RUN_STATUSES.FINALIZED] },
    { id: "lock", label: "Lock", statuses: [PAYROLL_RUN_STATUSES.LOCKED] },
  ];
  const currentIndex = steps.findIndex((step) => step.statuses.includes(currentStatus));
  return steps.map((step, index) => ({
    ...step,
    state: currentIndex < 0
      ? "upcoming"
      : index < currentIndex
        ? "complete"
        : index === currentIndex
          ? "current"
          : "upcoming",
  }));
}

export function formatPayrollCurrency(value, currency = "USD") {
  if (value == null || Number.isNaN(Number(value))) {
    return "—";
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency,
    maximumFractionDigits: value % 1 === 0 ? 0 : 2,
  }).format(Number(value));
}

export function filterPayrollRuns(runs, filters = {}) {
  const rows = runs || [];
  const { status, groupId, query } = filters;
  return rows.filter((row) => {
    if (status && status !== "ALL" && row.status !== status) {
      return false;
    }
    if (groupId && row.groupId !== groupId) {
      return false;
    }
    if (query) {
      const q = String(query).toLowerCase();
      const haystack = [row.name, row.groupName, row.periodStart, row.periodEnd]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      if (!haystack.includes(q)) {
        return false;
      }
    }
    return true;
  });
}

export function buildPayrollDashboardMetrics(runs, exceptions, groups) {
  const runRows = runs || [];
  const exceptionRows = exceptions || [];
  const openRuns = runRows.filter(
    (row) =>
      row.status !== PAYROLL_RUN_STATUSES.LOCKED &&
      row.status !== PAYROLL_RUN_STATUSES.FINALIZED
  );
  const pendingApproval = runRows.filter(
    (row) => row.status === PAYROLL_RUN_STATUSES.PENDING_APPROVAL
  ).length;
  const blockers = exceptionRows.filter(
    (row) => !row.resolved && row.severity === PAYROLL_EXCEPTION_SEVERITIES.BLOCKER
  ).length;
  const readinessScores = runRows
    .map((row) => row.readinessScore)
    .filter((score) => score != null);
  const avgReadiness =
    readinessScores.length === 0
      ? 0
      : Math.round(readinessScores.reduce((sum, score) => sum + score, 0) / readinessScores.length);

  return {
    totalRuns: runRows.length,
    openRuns: openRuns.length,
    pendingApproval,
    blockers,
    avgReadiness,
    groups: (groups || []).length,
    nextPayDate: (groups || []).map((g) => g.nextPayDate).filter(Boolean).sort()[0] || null,
  };
}

export function buildPayrollReadinessChartRows(runs) {
  return (runs || [])
    .filter((row) => row.readinessScore != null)
    .map((row) => ({
      id: row.id,
      label: row.name,
      score: row.readinessScore,
      blockers: row.blockerCount || 0,
      status: row.status,
    }))
    .sort((a, b) => a.score - b.score);
}

export function buildPayrollCostByDepartment(lines) {
  const buckets = {};
  (lines || []).forEach((row) => {
    const key = row.department || "Unassigned";
    if (!buckets[key]) {
      buckets[key] = { label: key, gross: 0, net: 0, count: 0 };
    }
    buckets[key].gross += Number(row.gross) || 0;
    buckets[key].net += Number(row.net) || 0;
    buckets[key].count += 1;
  });
  return Object.values(buckets).sort((a, b) => b.gross - a.gross);
}

export function canTransitionRunStatus(currentStatus, nextStatus) {
  const transitions = {
    [PAYROLL_RUN_STATUSES.DRAFT]: [PAYROLL_RUN_STATUSES.CALCULATED],
    [PAYROLL_RUN_STATUSES.CALCULATED]: [PAYROLL_RUN_STATUSES.PENDING_APPROVAL],
    [PAYROLL_RUN_STATUSES.PENDING_APPROVAL]: [PAYROLL_RUN_STATUSES.APPROVED],
    [PAYROLL_RUN_STATUSES.APPROVED]: [PAYROLL_RUN_STATUSES.FINALIZED],
    [PAYROLL_RUN_STATUSES.FINALIZED]: [PAYROLL_RUN_STATUSES.LOCKED],
    [PAYROLL_RUN_STATUSES.LOCKED]: [PAYROLL_RUN_STATUSES.REOPENED],
    [PAYROLL_RUN_STATUSES.REOPENED]: [PAYROLL_RUN_STATUSES.CALCULATED],
  };
  const allowed = transitions[currentStatus] || [];
  return allowed.includes(nextStatus);
}

export function getNextRunActions(status) {
  switch (status) {
    case PAYROLL_RUN_STATUSES.DRAFT:
      return [{ action: "calculate", label: "Calculate", nextStatus: PAYROLL_RUN_STATUSES.CALCULATED }];
    case PAYROLL_RUN_STATUSES.CALCULATED:
      return [{ action: "submit", label: "Submit for approval", nextStatus: PAYROLL_RUN_STATUSES.PENDING_APPROVAL }];
    case PAYROLL_RUN_STATUSES.PENDING_APPROVAL:
      return [{ action: "approve", label: "Approve", nextStatus: PAYROLL_RUN_STATUSES.APPROVED }];
    case PAYROLL_RUN_STATUSES.APPROVED:
      return [{ action: "finalize", label: "Finalize", nextStatus: PAYROLL_RUN_STATUSES.FINALIZED }];
    case PAYROLL_RUN_STATUSES.FINALIZED:
      return [{ action: "lock", label: "Lock period", nextStatus: PAYROLL_RUN_STATUSES.LOCKED }];
    case PAYROLL_RUN_STATUSES.LOCKED:
      return [{ action: "reopen", label: "Reopen", nextStatus: PAYROLL_RUN_STATUSES.REOPENED }];
    case PAYROLL_RUN_STATUSES.REOPENED:
      return [{ action: "calculate", label: "Recalculate", nextStatus: PAYROLL_RUN_STATUSES.CALCULATED }];
    default:
      return [];
  }
}

export function toEmployee360PayrollSummary(employeeId, lines, groupName) {
  const employeeLines = (lines || []).filter((row) => String(row.employeeId) === String(employeeId));
  const latest = employeeLines[0];
  return {
    payFrequency: "Monthly",
    baseSalary: latest && latest.gross != null ? latest.gross : null,
    payStatus: latest ? latest.status : "—",
    lastPaycheckAmount: latest && latest.net != null ? latest.net : null,
    lastPaycheckDate: null,
    ytdNet: employeeLines.reduce((sum, row) => sum + (Number(row.net) || 0), 0) || null,
    costCenter: latest && latest.department,
    paychecks: employeeLines.map((row, index) => ({
      id: row.id || `line-${index}`,
      period: row.period || "Current period",
      gross: row.gross,
      net: row.net,
      status: row.status,
      paidOn: row.paidOn || null,
    })),
    payrollGroup: groupName || "—",
  };
}

