import React from "react";
import classNames from "classnames/bind";
import {
  TicketPriorityBadge,
  TicketSlaBadge,
  TicketStatusBadge,
} from "views/tickets/components/TicketsLuxShared";

export default function TicketRegister({ tickets = [], loading, onSelect, selectedId }) {
  if (loading) {
    return <div className="lux-ticket-register__skeleton" aria-busy="true" />;
  }
  if (!tickets.length) {
    return (
      <div className="lux-ticket-register__empty">
        <i className="fe fe-life-buoy" aria-hidden="true" />
        <strong>No tickets match filters</strong>
        <p>Adjust queue or status filters to see the register.</p>
      </div>
    );
  }

  return (
    <div className="lux-ticket-register-wrap">
      <table className="lux-ticket-register">
        <thead>
          <tr>
            <th>Ticket</th>
            <th>Priority</th>
            <th>Status</th>
            <th>SLA</th>
            <th>Assignee</th>
            <th>Project</th>
            <th>Billable</th>
          </tr>
        </thead>
        <tbody>
          {tickets.map((row) => (
            <tr
              key={row.id}
              className={classNames("lux-ticket-register__row", {
                "is-selected": selectedId === row.id,
                "is-breached": row.slaStatus === "breached",
              })}
              onClick={() => onSelect && onSelect(row)}
            >
              <td>
                <div className="lux-ticket-register__title">{row.number}</div>
                <div className="lux-ticket-register__meta">{row.title}</div>
                {row.externalRef ? <small className="lux-ticket-register__ext">{row.externalRef}</small> : null}
              </td>
              <td>
                <TicketPriorityBadge priority={row.priority} />
              </td>
              <td>
                <TicketStatusBadge status={row.status} />
              </td>
              <td>
                <TicketSlaBadge slaStatus={row.slaStatus} />
              </td>
              <td>{row.assigneeName || "—"}</td>
              <td>{row.projectName || "—"}</td>
              <td>{row.billableHours}h</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}
