import React, { Component } from "react";
import ScopeBadge from "components/persona/ScopeBadge";
import { getWorkspaceWidgetsForPersona } from "components/persona/PersonaWidgetRegistry";
import { PersonaContext } from "context/PersonaContextProvider";
import { accessUtils } from "_helpers";
import { isUniversalApprovalInboxEnabled } from "config/universal-approval.config";
import { isMyWorkQueueEnabled, isWorkspaceNotificationsEnabled } from "config/workspace.config";
import {
  buildWorkspaceHomeKpiCards,
  enrichPersonaWidgets,
} from "config/workspace-home.utils";
import { workspaceService } from "_services/workspace.service";
import WorkspaceApprovalsShortcut from "views/workspace/components/WorkspaceApprovalsShortcut";
import WorkspaceAttentionPanel from "views/workspace/components/WorkspaceAttentionPanel";
import WorkspaceDailyBriefingPanel from "views/workspace/components/WorkspaceDailyBriefingPanel";
import WorkspaceFavoritesPanel from "views/workspace/components/WorkspaceFavoritesPanel";
import WorkspaceRoleWidgetsPanel from "views/workspace/components/WorkspaceRoleWidgetsPanel";
import WorkspaceSavedViewsPanel from "views/workspace/components/WorkspaceSavedViewsPanel";
import { isWorkspaceFavoritesEnabled } from "config/workspace-personalization.config";
import {
  WorkspaceActionButton,
  WorkspaceInsightStrip,
  WorkspaceKpiStrip,
} from "views/workspace/components/WorkspaceLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";

/**
 * F21-T2/T5: Luxury workspace home — aggregated KPIs, insights, persona widgets, approval shortcuts.
 */
class RoleBasedWorkspaceHome extends Component {
  static contextType = PersonaContext;

  state = {
    dashboard: null,
    loading: true,
    loadError: null,
    dataSource: null,
  };

  componentDidMount() {
    const { pageHeaderNameChangeHandler } = this.props;
    if (pageHeaderNameChangeHandler) {
      pageHeaderNameChangeHandler("Home");
    }
    this.loadDashboard();
  }

  componentDidUpdate(_prevProps, _prevState) {
    const personaCtx = this.context || {};
    const prevPersona = this._loadedPersona;
    const nextPersona = personaCtx.activePersona || "EMPLOYEE";
    if (prevPersona && prevPersona !== nextPersona) {
      this.loadDashboard();
    }
    this._loadedPersona = nextPersona;
  }

  loadDashboard = async () => {
    const personaCtx = this.context || {};
    const activePersona = personaCtx.activePersona || "EMPLOYEE";
    this.setState({ loading: true, loadError: null });
    try {
      const result = await workspaceService.getHomeDashboard(activePersona);
      if (!result || result.source === "api-error" || !result.payload) {
        this.setState({
          dashboard: null,
          loading: false,
          dataSource: (result && result.source) || "api-error",
          loadError: "Unable to load your workspace dashboard from the live API.",
        });
        return;
      }
      this.setState({
        dashboard: result.payload,
        loading: false,
        dataSource: result.source || null,
        loadError: null,
      });
    } catch (e) {
      this.setState({
        loading: false,
        loadError: "Unable to load your workspace dashboard.",
        dashboard: null,
      });
    }
  };

  getModuleFlags() {
    const menu = accessUtils.getMenuAccessControl();
    const workspace = (menu && menu.workspaceModules) || {};
    return {
      myWorkEnabled: workspace.myWorkEnabled === true,
      notificationsEnabled: workspace.notificationsEnabled === true,
      approvalsEnabled: workspace.approvalsEnabled === true && isUniversalApprovalInboxEnabled(),
    };
  }

  render() {
    const personaCtx = this.context || {};
    const activePersona = personaCtx.activePersona || "EMPLOYEE";
    const activePersonaLabel = personaCtx.activePersonaLabel || "Employee";
    const { dashboard, loading, loadError, dataSource } = this.state;
    const metrics = (dashboard && dashboard.metrics) || {};
    const moduleFlags = this.getModuleFlags();
    const kpiCards = buildWorkspaceHomeKpiCards(metrics, {
      approvalsEnabled: moduleFlags.approvalsEnabled,
      notificationsEnabled: moduleFlags.notificationsEnabled && isWorkspaceNotificationsEnabled(),
      myWorkEnabled: moduleFlags.myWorkEnabled && isMyWorkQueueEnabled(),
    });
    const widgets = enrichPersonaWidgets(getWorkspaceWidgetsForPersona(activePersona), metrics);

    return (
      <div className="lux-workspace-home-page lux-register-page">
        <PageDataSourceReporter dataSource={dataSource} />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.workspaceHome}
          actions={
            <>
              <ScopeBadge showPersona />
              {moduleFlags.approvalsEnabled && (
                <WorkspaceActionButton to="/workspace/approvals" icon="fe fe-inbox" variant="primary">
                  Approvals
                </WorkspaceActionButton>
              )}
              {moduleFlags.myWorkEnabled && isMyWorkQueueEnabled() && (
                <WorkspaceActionButton to="/workspace/my-work" icon="fe fe-check-square" variant="ghost">
                  My work
                </WorkspaceActionButton>
              )}
            </>
          }
        />

        <WorkspaceKpiStrip cards={kpiCards} loading={loading} />

        {loadError && (
          <div className="lux-employee-360__error lux-workspace-home__error" role="alert">
            <span>{loadError}</span>
            <WorkspaceActionButton variant="ghost" onClick={this.loadDashboard}>
              Retry
            </WorkspaceActionButton>
          </div>
        )}

        <WorkspaceInsightStrip insights={(dashboard && dashboard.insights) || []} />

        <WorkspaceDailyBriefingPanel
          dashboard={dashboard}
          activePersona={activePersona}
          loading={loading}
        />

        <WorkspaceAttentionPanel
          items={(dashboard && dashboard.attentionItems) || []}
          loading={loading}
        />

        <div className="lux-workspace-home-grid">
          <WorkspaceApprovalsShortcut
            items={(dashboard && dashboard.approvalShortcuts) || []}
            loading={loading}
            approvalsEnabled={moduleFlags.approvalsEnabled}
          />
          <WorkspaceRoleWidgetsPanel
            widgets={widgets}
            loading={loading}
            activePersonaLabel={activePersonaLabel}
          />
        </div>

        {isWorkspaceFavoritesEnabled() && (
          <div className="lux-workspace-home-personalization">
            <WorkspaceFavoritesPanel onChange={this.loadDashboard} />
            <WorkspaceSavedViewsPanel onChange={this.loadDashboard} />
          </div>
        )}
      </div>
    );
  }
}

export default RoleBasedWorkspaceHome;
