import React from "react";
import classNames from "classnames/bind";

/**
 * Live API = green dot. Mock/demo = amber dot (tooltip only).
 * Accepts "api" / "live" for connected backends.
 */
export default function DataSourceIndicator({ dataSource, demoLabel, className, title }) {
  if (!dataSource || dataSource === "client" || dataSource === "empty") {
    return null;
  }

  if (dataSource === "api" || dataSource === "live") {
    return (
      <span
        className={classNames("lux-data-source-dot", "is-live", className)}
        title={title || "Connected to live API"}
        aria-label="Live data"
        role="status"
      />
    );
  }

  if (dataSource === "mock" && demoLabel) {
    return (
      <span
        className={classNames("lux-data-source-dot", "is-demo", className)}
        title={demoLabel}
        aria-label={demoLabel}
        role="status"
      />
    );
  }

  return null;
}
