import React from "react";
import { Link } from "react-router-dom";
import moment from "moment";

/**
 * Compact holiday cue for the Activities calendar sidebar.
 * Holidays are marked on the calendar; management lives under People → Holidays.
 */
export default function ActivitiesCalendarHolidayCue({ holidayItems }) {
  const today = moment().startOf("day");
  const upcoming = (holidayItems || [])
    .map((item) => {
      const date = moment(item.holidayDate);
      if (!date.isValid() || date.isBefore(today, "day")) {
        return null;
      }
      return { ...item, date };
    })
    .filter(Boolean)
    .sort((a, b) => a.date.valueOf() - b.date.valueOf());

  const next = upcoming[0] || null;
  const countInView = (holidayItems || []).length;

  return (
    <div className="lux-activity-holiday-cue lux-activity-holiday-cue--atelier" aria-label="Holiday calendar cue">
      <div className="lux-activity-holiday-cue__legend">
        <span className="lux-activity-holiday-cue__swatch" aria-hidden="true" />
        <div>
          <span className="lux-activity-holiday-cue__label">Organization holidays</span>
          {countInView > 0 ? (
            <span className="lux-activity-holiday-cue__count">{countInView} in this month view</span>
          ) : (
            <span className="lux-activity-holiday-cue__count is-muted">None in this month view</span>
          )}
        </div>
      </div>
      {next ? (
        <p className="lux-activity-holiday-cue__next">
          Next: <strong>{next.name || "Holiday"}</strong>
          <span> · {next.date.format("ddd, D MMM")}</span>
        </p>
      ) : null}
      <Link to="/people/holidays" className="lux-activity-holiday-cue__link">
        Manage holidays
        <i className="fe fe-arrow-right" aria-hidden="true" />
      </Link>
    </div>
  );
}
