import React from "react";
import classNames from "classnames/bind";

export default function AttendanceAnomalyRecommendationPanel({ recommendation }) {
  if (!recommendation) return null;

  const confidence = Math.round((recommendation.confidence || 0) * 100);

  return (
    <section className="lux-att-intel__ai">
      <header className="lux-att-intel__ai-head">
        <div>
          <span className="lux-att-intel__ai-kicker">
            <i className="fe fe-zap" aria-hidden="true" />
            AI anomaly draft
          </span>
          <h4>Recommended manager action</h4>
        </div>
        <span className="lux-att-intel__ai-badge">Draft only</span>
      </header>

      <p className="lux-att-intel__ai-summary">{recommendation.summary}</p>
      <p className="lux-att-intel__ai-rec">{recommendation.recommendation}</p>

      <div className="lux-att-intel__ai-meta">
        <span className={classNames("lux-att-intel__ai-confidence", {
          "is-high": confidence >= 75,
          "is-medium": confidence >= 50 && confidence < 75,
        })}
        >
          Confidence {confidence}%
        </span>
        <span className="lux-att-intel__ai-note">Full AI agent workflow is coming in a future release.</span>
      </div>

      {recommendation.disclaimer && (
        <p className="lux-att-intel__ai-disclaimer">{recommendation.disclaimer}</p>
      )}
    </section>
  );
}
