import { POLICY_ACK_STATUSES } from "config/document-vault.config";
import {
  POLICY_CAMPAIGN_STATUSES,
  POLICY_VERSION_STATUSES,
  normalizePolicy,
  normalizePolicyCampaign,
} from "config/policy-hub.config";
import {
  buildOrgChartMetrics,
  computeSpanOfControl,
  getOrgDepartments,
} from "config/org-structure.utils";

export function buildPolicyHubMetrics(policies, campaigns, acknowledgments) {
  const policyRows = (policies || []).map(normalizePolicy).filter(Boolean);
  const campaignRows = (campaigns || []).map(normalizePolicyCampaign).filter(Boolean);
  const ackRows = acknowledgments || [];

  const pending = ackRows.filter((row) => row.status === POLICY_ACK_STATUSES.PENDING).length;
  const overdue = ackRows.filter((row) => row.status === POLICY_ACK_STATUSES.OVERDUE).length;
  const acknowledged = ackRows.filter((row) => row.status === POLICY_ACK_STATUSES.ACKNOWLEDGED).length;
  const activeCampaigns = campaignRows.filter((row) => row.status === POLICY_CAMPAIGN_STATUSES.ACTIVE).length;
  const publishedVersions = policyRows.reduce(
    (sum, policy) => sum + (policy.versions || []).filter((v) => v.status === POLICY_VERSION_STATUSES.PUBLISHED).length,
    0
  );

  const assignedTotal = campaignRows.reduce((sum, row) => sum + (row.assignedCount || 0), 0);
  const ackTotal = campaignRows.reduce((sum, row) => sum + (row.acknowledgedCount || 0), 0);
  const complianceRate =
    assignedTotal > 0 ? Math.round((ackTotal / assignedTotal) * 100) : acknowledged > 0 ? 100 : 0;

  return {
    policies: policyRows.length,
    activeCampaigns,
    pending,
    overdue,
    acknowledged,
    publishedVersions,
    complianceRate,
    missingAcks: Math.max(assignedTotal - ackTotal, pending + overdue),
  };
}

export function buildPolicyHubInsights(metrics) {
  const insights = [];
  if (metrics.overdue > 0) {
    insights.push({
      id: "overdue",
      tone: "rose",
      icon: "fe fe-alert-circle",
      title: `${metrics.overdue} overdue acknowledgment(s)`,
      copy: "Escalate to managers or extend campaign due dates.",
    });
  }
  if (metrics.complianceRate > 0 && metrics.complianceRate < 90) {
    insights.push({
      id: "compliance",
      tone: "amber",
      icon: "fe fe-shield",
      title: `${metrics.complianceRate}% policy compliance`,
      copy: `${metrics.missingAcks} employee(s) still need to acknowledge active policies.`,
    });
  }
  if (metrics.activeCampaigns > 0) {
    insights.push({
      id: "campaigns",
      tone: "blue",
      icon: "fe fe-send",
      title: `${metrics.activeCampaigns} active campaign(s)`,
      copy: "Track version rollouts and acknowledgment progress from the policy hub.",
    });
  }
  if (insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      title: `${metrics.policies} published policies on file`,
      copy: `${metrics.complianceRate}% compliance across active campaigns.`,
    });
  }
  return insights.slice(0, 3);
}

export function buildHeadcountByDepartmentSeries(employees) {
  const counts = {};
  (employees || []).forEach((row) => {
    const dept = row.department || "Unassigned";
    counts[dept] = (counts[dept] || 0) + 1;
  });
  return Object.entries(counts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 6)
    .map(([label, value]) => ({ label, value }));
}

export function buildSpanOfControlSeries(employees, limit = 5) {
  const spans = computeSpanOfControl(employees || []);
  return Object.entries(spans)
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([label, value]) => ({ label: label.split(" ")[0], value }));
}

export function buildPolicyComplianceSeries(campaigns) {
  return (campaigns || [])
    .map(normalizePolicyCampaign)
    .filter(Boolean)
    .slice(0, 5)
    .map((row) => {
      const assigned = row.assignedCount || 0;
      const acknowledged = row.acknowledgedCount || 0;
      const rate = assigned > 0 ? Math.round((acknowledged / assigned) * 100) : 0;
      return {
        label: row.policyTitle.split(" ")[0],
        value: rate,
        meta: `${acknowledged}/${assigned}`,
      };
    });
}

export function buildMissingAcknowledgmentsSeries(acknowledgments) {
  const rows = acknowledgments || [];
  const groups = {
    Pending: rows.filter((row) => row.status === POLICY_ACK_STATUSES.PENDING).length,
    Overdue: rows.filter((row) => row.status === POLICY_ACK_STATUSES.OVERDUE).length,
    Done: rows.filter((row) => row.status === POLICY_ACK_STATUSES.ACKNOWLEDGED).length,
  };
  return Object.entries(groups)
    .filter((entry) => entry[1] > 0)
    .map(([label, value]) => ({ label, value }));
}

export function buildOrgPolicyAnalytics(employees, orgUnits, policies, campaigns, acknowledgments) {
  const orgMetrics = buildOrgChartMetrics(employees, orgUnits);
  const policyMetrics = buildPolicyHubMetrics(policies, campaigns, acknowledgments);

  return {
    orgMetrics,
    policyMetrics,
    headcountByDept: buildHeadcountByDepartmentSeries(employees),
    spanOfControl: buildSpanOfControlSeries(employees),
    policyCompliance: buildPolicyComplianceSeries(campaigns),
    missingAcks: buildMissingAcknowledgmentsSeries(acknowledgments),
    departments: getOrgDepartments(employees),
  };
}

export function getLatestPublishedVersion(policy) {
  const versions = (policy && policy.versions) || [];
  return (
    versions.find((row) => row.status === POLICY_VERSION_STATUSES.PUBLISHED) ||
    versions[0] ||
    null
  );
}

export function buildNextPolicyVersion(currentVersion) {
  const raw = String(currentVersion || "2026.0");
  const match = raw.match(/^(\d{4})\.(\d+)$/);
  if (match) {
    return `${match[1]}.${Number(match[2]) + 1}`;
  }
  return `${raw}.1`;
}

export function summarizeVersionChanges(previousVersion, nextSummary) {
  const changes = (previousVersion && previousVersion.changes) || [];
  if (changes.length) {
    return changes.slice(0, 3);
  }
  if (nextSummary) {
    return [nextSummary];
  }
  return ["Policy content updated"];
}
