/**
 * F20-T1 — Best-effort client audit writes (API or local buffer).
 */
import { auditService } from "_services/audit.service";
import { shouldUseAuditWrite, shouldUseAuditWriteApi } from "config/audit-write.config";
import { buildAuditRecordRequest } from "config/audit-write.utils";
import {
  appendBufferedAuditEvent,
  clearBufferedAuditEvents,
  listBufferedAuditRecords,
} from "config/audit-write.storage";

function rewriteBufferedAuditRecords(rows) {
  clearBufferedAuditEvents();
  (rows || []).forEach((row) => appendBufferedAuditEvent(row));
}

/**
 * Record an audit event. Fire-and-forget; never throws to callers.
 */
export function recordAuditEvent(input = {}) {
  if (!shouldUseAuditWrite()) {
    return Promise.resolve(null);
  }

  const request = buildAuditRecordRequest(input);
  if (!request.actorUserId || !request.userTeamId || !request.actionType || !request.entityType) {
    return Promise.resolve(null);
  }

  if (shouldUseAuditWriteApi()) {
    return flushBufferedAuditEvents()
      .catch(() => null)
      .then(() =>
        auditService
          .recordEvent(request)
          .catch(() => {
            appendBufferedAuditEvent(request);
            return null;
          })
      );
  }

  appendBufferedAuditEvent(request);
  return Promise.resolve({ buffered: true, payload: request });
}

/**
 * POST buffered client audit events to the backend API (best-effort).
 */
export async function flushBufferedAuditEvents() {
  if (!shouldUseAuditWriteApi()) {
    return { flushed: 0, failed: 0 };
  }
  const buffered = listBufferedAuditRecords();
  if (!buffered.length) {
    return { flushed: 0, failed: 0 };
  }

  let flushed = 0;
  let failed = 0;
  const remaining = [];

  for (const row of buffered) {
    try {
      await auditService.recordEvent({
        userTeamId: row.userTeamId,
        actorType: row.actorType,
        actorUserId: row.actorUserId,
        actionType: row.actionType,
        entityType: row.entityType,
        entityId: row.entityId,
        entityRef: row.entityRef,
        headline: row.headline,
        correlationId: row.correlationId,
        eventNaturalKey: row.eventNaturalKey,
        metadata: row.metadata,
        source: row.source,
      });
      flushed += 1;
    } catch (e) {
      failed += 1;
      remaining.push(row);
    }
  }

  if (remaining.length === 0) {
    clearBufferedAuditEvents();
  } else {
    rewriteBufferedAuditRecords(remaining);
  }

  return { flushed, failed, remaining: remaining.length };
}
