import React from "react";
import LuxBackNav from "views/common/fragments/LuxBackNav";
import HowToUseLink from "views/common/fragments/HowToUseLink";
import Employee360ProfileEntryLink from "views/people/components/employee360/Employee360ProfileEntryLink";
import { usePersonaContext } from "hooks/usePersonaContext";
import { canShowEmployee360Entry } from "config/employee360.utils";
import { getProfileDetailsReturnTarget } from "../profileDetailsNavigation.utils";

export default function ProfileDetailsBackNav({ location, employeeLabel, employeeId }) {
  const { menuAccessControl, activePersona } = usePersonaContext();
  const { path, label } = getProfileDetailsReturnTarget(location);
  const showEmployee360 =
    employeeId && canShowEmployee360Entry(menuAccessControl, activePersona);

  return (
    <LuxBackNav
      to={path}
      destinationLabel={label}
      currentLabel={employeeLabel || undefined}
      actions={
        <>
          {showEmployee360 ? (
            <Employee360ProfileEntryLink employeeId={employeeId} location={location} />
          ) : null}
          <HowToUseLink href="/documentation/hrms/profile.html" testId="profile-howto-link" />
        </>
      }
    />
  );
}
