import moment from "moment";
import dateUtils from "_helpers/date.utils";
import { normalizePoStatus } from "../purchaseOrderList.utils";

const STATUS_TONES = {
  NEW: "sky",
  CREATED: "indigo",
  INPROGRESS: "amber",
  COMPLETED: "green",
  CLOSED: "slate",
};

const STATUS_LABELS = {
  NEW: "New",
  CREATED: "Created",
  INPROGRESS: "In progress",
  COMPLETED: "Completed",
  CLOSED: "Closed",
};

const PROJECT_TYPE_LABELS = {
  ADHOC: "Adhoc",
  FTEMS: "FTE–MS",
  FTESA: "FTE–Staff aug",
  SERVICES: "Services",
  PRODUCT: "Product",
  TRACKER: "Tracker",
  TMHB: "T&M hourly",
};

const SOURCE_LABELS = { SF: "Salesforce", MANUAL: "Manual entry" };
const SOURCE_TONES = { SF: "sky", MANUAL: "indigo" };

const TIMELINE_LABELS = {
  OVERDUE: "Overdue",
  DUE_SOON: "Due in 14 days",
  ON_TRACK: "On track",
  NO_DATE: "No end date",
};
const TIMELINE_TONES = {
  OVERDUE: "rose",
  DUE_SOON: "amber",
  ON_TRACK: "green",
  NO_DATE: "slate",
};

const PIPELINE_STATUSES = ["NEW", "CREATED", "INPROGRESS"];
const FUNNEL_STAGES = ["NEW", "CREATED", "INPROGRESS", "COMPLETED"];
const TREND_MONTHS = 6;
const DUE_SOON_DAYS = 14;

function pct(count, total) {
  if (!total) return 0;
  return Math.round((count / total) * 100);
}

function itemStatus(item) {
  return normalizePoStatus(item && item.status);
}

function toMoment(value) {
  if (!value) return null;
  const m = dateUtils.convertDateStringToMoment(value);
  return m && m.isValid() ? m : null;
}

function buildMixSegments(counts, total, labelMap = STATUS_LABELS, toneMap = STATUS_TONES) {
  return Object.entries(counts)
    .filter(([, count]) => count > 0)
    .map(([key, count]) => ({
      key,
      label: (labelMap && labelMap[key]) || key,
      count,
      pct: pct(count, total),
      tone: (toneMap && toneMap[key]) || "slate",
    }))
    .sort((a, b) => b.count - a.count);
}

function classifyTimelineHealth(item, today, dueSoonEnd) {
  const end = toMoment(item.estCompletionTime);
  if (!end) return "NO_DATE";
  if (end.isBefore(today, "day")) return "OVERDUE";
  if (end.isSameOrBefore(dueSoonEnd, "day")) return "DUE_SOON";
  return "ON_TRACK";
}

function buildCreatedTrend(activeList) {
  const today = moment().startOf("month");
  const buckets = [];
  for (let i = TREND_MONTHS - 1; i >= 0; i -= 1) {
    const month = today.clone().subtract(i, "months");
    buckets.push({
      key: month.format("YYYY-MM"),
      label: month.format("MMM YY"),
      count: 0,
    });
  }
  const bucketMap = buckets.reduce((acc, b) => {
    acc[b.key] = b;
    return acc;
  }, {});

  activeList.forEach((item) => {
    const created = toMoment(item.createdDate);
    if (!created) return;
    const key = created.startOf("month").format("YYYY-MM");
    if (bucketMap[key]) bucketMap[key].count += 1;
  });

  return buckets;
}

function buildEmptyStats(userTeams) {
  const empty = {
    total: 0,
    active: 0,
    archived: 0,
    deleted: 0,
    pipeline: 0,
    completed: 0,
    closed: 0,
    completionRate: 0,
    pipelineRate: 0,
    salesforceCount: 0,
    manualCount: 0,
    salesforceRate: 0,
    bidLinkedCount: 0,
    bidLinkedRate: 0,
    overdueCount: 0,
    dueSoonCount: 0,
    selectedTeams: 0,
    statusMix: [],
    projectTypeMix: [],
    accountMix: [],
    teamMix: [],
    sourceMix: [],
    timelineMix: [],
    createdTrend: buildCreatedTrend([]),
    funnel: [],
    outcomes: { open: 0, completed: 0, closed: 0, other: 0 },
    kpis: [],
    highlights: [],
    insights: [],
    stageCounts: { newCount: 0, createdCount: 0, inProgressCount: 0, completedCount: 0 },
    inProgressRate: 0,
  };
  if (userTeams && userTeams.length) {
    empty.selectedTeams = userTeams.filter((t) => t.isChecked).length;
  }
  return empty;
}

export function buildPurchaseOrderSummaryStats(items, userTeams) {
  if (!items || !items.length) {
    return buildEmptyStats(userTeams);
  }

  const all = items;
  const activeList = all.filter((item) => !item.archived && !item.deleted);
  const archived = all.filter((item) => item.archived).length;
  const deleted = all.filter((item) => item.deleted).length;
  const pipeline = activeList.filter((item) =>
    PIPELINE_STATUSES.includes(itemStatus(item))
  ).length;
  const completed = activeList.filter((item) => itemStatus(item) === "COMPLETED").length;
  const closed = activeList.filter((item) => itemStatus(item) === "CLOSED").length;
  const completionRate = activeList.length ? pct(completed, activeList.length) : 0;
  const pipelineRate = activeList.length ? pct(pipeline, activeList.length) : 0;
  const salesforceCount = activeList.filter((item) => item.source === "SF").length;
  const manualCount = Math.max(activeList.length - salesforceCount, 0);
  const salesforceRate = activeList.length ? pct(salesforceCount, activeList.length) : 0;
  const bidLinkedCount = activeList.filter((item) => item.bidId).length;
  const bidLinkedRate = activeList.length ? pct(bidLinkedCount, activeList.length) : 0;

  const today = moment().startOf("day");
  const dueSoonEnd = today.clone().add(DUE_SOON_DAYS, "days");
  const trackable = activeList.filter(
    (item) => !["COMPLETED", "CLOSED"].includes(itemStatus(item))
  );

  const timelineCounts = { OVERDUE: 0, DUE_SOON: 0, ON_TRACK: 0, NO_DATE: 0 };
  trackable.forEach((item) => {
    const bucket = classifyTimelineHealth(item, today, dueSoonEnd);
    timelineCounts[bucket] = (timelineCounts[bucket] || 0) + 1;
  });
  const overdueCount = timelineCounts.OVERDUE;
  const dueSoonCount = timelineCounts.DUE_SOON;

  const statusCounts = {};
  const projectTypeCounts = {};
  const accountCounts = {};
  const teamCounts = {};
  const sourceCounts = { SF: 0, MANUAL: 0 };

  activeList.forEach((item) => {
    const statusKey = itemStatus(item);
    statusCounts[statusKey] = (statusCounts[statusKey] || 0) + 1;
    const typeKey = item.projectType || item.type || "OTHER";
    projectTypeCounts[typeKey] = (projectTypeCounts[typeKey] || 0) + 1;
    if (item.accountName) {
      accountCounts[item.accountName] = (accountCounts[item.accountName] || 0) + 1;
    }
    const teamKey = item.teamName || item.userTeamName;
    if (teamKey) {
      teamCounts[teamKey] = (teamCounts[teamKey] || 0) + 1;
    }
    if (item.source === "SF") {
      sourceCounts.SF += 1;
    } else {
      sourceCounts.MANUAL += 1;
    }
  });

  const funnelMax = Math.max(
    ...FUNNEL_STAGES.map(
      (stage) => activeList.filter((item) => itemStatus(item) === stage).length
    ),
    1
  );

  const funnel = FUNNEL_STAGES.map((stage) => ({
    key: stage,
    label: STATUS_LABELS[stage] || stage,
    count: activeList.filter((item) => itemStatus(item) === stage).length,
    tone: STATUS_TONES[stage] || "slate",
    widthPct: Math.max(
      18,
      Math.round(
        (activeList.filter((item) => itemStatus(item) === stage).length / funnelMax) *
          100
      )
    ),
  }));

  const newCount = activeList.filter((item) => itemStatus(item) === "NEW").length;
  const createdCount = activeList.filter((item) => itemStatus(item) === "CREATED").length;
  const inProgressCount = activeList.filter((item) => itemStatus(item) === "INPROGRESS").length;
  const completedCount = completed;
  const inProgressRate = activeList.length ? pct(inProgressCount, activeList.length) : 0;

  const activeTotal = Math.max(activeList.length, 1);
  const trackableTotal = Math.max(trackable.length, 1);

  const statusMix = buildMixSegments(statusCounts, activeTotal);
  const sourceMix = buildMixSegments(sourceCounts, activeTotal, SOURCE_LABELS, SOURCE_TONES);
  const timelineMix = buildMixSegments(
    timelineCounts,
    trackableTotal,
    TIMELINE_LABELS,
    TIMELINE_TONES
  );

  const accountMix = Object.entries(accountCounts)
    .map(([key, count]) => ({
      key,
      label: key,
      count,
      pct: pct(count, activeList.length),
      tone: "indigo",
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 6);

  const teamMix = Object.entries(teamCounts)
    .map(([key, count]) => ({
      key,
      label: key,
      count,
      pct: pct(count, activeList.length),
      tone: "violet",
    }))
    .sort((a, b) => b.count - a.count)
    .slice(0, 6);

  const createdTrend = buildCreatedTrend(all);

  const highlights = [
    {
      key: "overdue",
      label: "Overdue",
      value: overdueCount,
      tone: "rose",
      icon: "fe-alert-circle",
      hint: trackable.length ? `${pct(overdueCount, trackable.length)}% of open delivery` : "No open contracts",
    },
    {
      key: "dueSoon",
      label: "Due in 14 days",
      value: dueSoonCount,
      tone: "amber",
      icon: "fe-calendar",
      hint: "Approaching estimated completion",
    },
    {
      key: "bidLinked",
      label: "Bid linked",
      value: bidLinkedCount,
      tone: "indigo",
      icon: "fe-link",
      hint: `${bidLinkedRate}% linked to a bid`,
    },
    {
      key: "salesforce",
      label: "Salesforce",
      value: salesforceCount,
      tone: "sky",
      icon: "fe-cloud",
      hint: `${salesforceRate}% imported from SF`,
    },
  ];

  const insights = [
    {
      key: "status",
      title: "Status distribution",
      subtitle: `${activeList.length} active in portfolio`,
      icon: "fe-pie-chart",
      mix: statusMix,
      emptyLabel: "No active contracts",
    },
    {
      key: "source",
      title: "Creation channel",
      subtitle:
        salesforceCount > 0
          ? `${salesforceCount} Salesforce · ${manualCount} manual`
          : "All manual entries",
      icon: "fe-cloud",
      mix: sourceMix,
      emptyLabel: "No source data",
    },
    {
      key: "timeline",
      title: "Delivery health",
      subtitle:
        trackable.length > 0
          ? `${pct(timelineCounts.ON_TRACK || 0, trackable.length)}% on track`
          : "No open delivery windows",
      icon: "fe-clock",
      mix: timelineMix,
      emptyLabel: "No timeline data",
    },
  ];

  const summary = {
    total: all.length,
    active: activeList.length,
    archived,
    deleted,
    pipeline,
    completed,
    closed,
    completionRate,
    pipelineRate,
    salesforceCount,
    manualCount,
    salesforceRate,
    bidLinkedCount,
    bidLinkedRate,
    overdueCount,
    dueSoonCount,
    selectedTeams: 0,
    statusMix,
    projectTypeMix: buildMixSegments(
      projectTypeCounts,
      activeTotal,
      PROJECT_TYPE_LABELS,
      {
        ADHOC: "indigo",
        FTEMS: "violet",
        FTESA: "sky",
        SERVICES: "amber",
        PRODUCT: "teal",
        TRACKER: "green",
        TMHB: "slate",
        OTHER: "slate",
      }
    ),
    accountMix,
    teamMix,
    sourceMix,
    timelineMix,
    createdTrend,
    funnel,
    outcomes: {
      open: pipeline,
      completed,
      closed,
      other: archived,
    },
    kpis: [
      {
        key: "active",
        label: "Active contracts",
        value: activeList.length,
        hint: "Not archived or deleted",
        icon: "fe-layers",
        tone: "indigo",
      },
      {
        key: "inProgress",
        label: "In progress",
        value: inProgressCount,
        hint:
          pipeline > 0
            ? `${inProgressRate}% of active · ${pipeline} in pipeline`
            : `${inProgressRate}% of active`,
        icon: "fe-loader",
        tone: "amber",
      },
      {
        key: "completed",
        label: "Completed",
        value: completed,
        hint: `${completionRate}% completion rate`,
        icon: "fe-check-circle",
        tone: "green",
      },
      {
        key: "archived",
        label: "Archived",
        value: archived,
        hint: salesforceCount ? `${salesforceCount} from Salesforce` : "Stored contracts",
        icon: "fe-archive",
        tone: "slate",
      },
    ],
    highlights,
    insights,
    stageCounts: { newCount, createdCount, inProgressCount, completedCount },
    inProgressRate,
  };

  if (userTeams && userTeams.length) {
    summary.selectedTeams = userTeams.filter((t) => t.isChecked).length;
  }

  return summary;
}
