import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { employeeFinanceService } from "_services/employeeFinance.service";
import { buildFinanceTabStats } from "config/employee360Tab.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";

function formatCurrency(value) {
  if (value == null || value === "Restricted" || Number.isNaN(Number(value))) {
    return value == null ? "—" : value;
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: value % 1 === 0 ? 0 : 2,
  }).format(Number(value));
}

function FinanceField({ label, value, hint }) {
  return (
    <div className="lux-employee-360__field">
      <span className="lux-employee-360__field-label">{label}</span>
      <strong className="lux-employee-360__field-value">{value}</strong>
      {hint ? <span className="lux-employee-360__field-hint">{hint}</span> : null}
    </div>
  );
}

export default class Employee360FinanceTab extends Component {
  state = {
    loading: true,
    loadError: null,
    bundle: null,
  };

  componentDidMount() {
    this.loadFinance();
  }

  componentDidUpdate(prevProps) {
    const prevId = prevProps.employee && prevProps.employee.id;
    const nextId = this.props.employee && this.props.employee.id;
    if (prevId !== nextId) {
      this.loadFinance();
    }
  }

  loadFinance = async () => {
    const { employee, viewerPersona } = this.props;
    if (!employee) {
      return;
    }
    this.setState({ loading: true, loadError: null });
    try {
      const result = await employeeFinanceService.getEmployeeFinanceProfile(employee.id, {
        employeeName: getEmployeeDisplayName(employee),
        viewerPersona: viewerPersona || "ADMIN",
      });
      this.setState({ loading: false, bundle: result.payload });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load employee finance profile.",
      });
    }
  };

  renderRegister(title, rows, columns) {
    if (!rows.length) {
      return (
        <LuxRegisterEmptyState
          className="lux-register-empty--compact lux-employee-360__embed-empty"
          icon="fe fe-inbox"
          title={`No ${title.toLowerCase()}`}
          description="Records will appear when employee finance data is linked."
        />
      );
    }

    return (
      <div className="lux-employee-360__register-wrap">
        <table className="lux-employee-360__register">
          <thead>
            <tr>
              {columns.map((col) => (
                <th key={col.key}>{col.label}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {rows.map((row) => (
              <tr key={row.id}>
                {columns.map((col) => (
                  <td key={col.key}>{col.render(row)}</td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    );
  }

  render() {
    const { employee } = this.props;
    const { loading, loadError, bundle } = this.state;

    if (!employee) {
      return null;
    }

    const displayName = getEmployeeDisplayName(employee);
    const profile = bundle && bundle.profile;
    const masked = profile && profile.masked;
    const stats = buildFinanceTabStats(bundle, masked);

    if (loading) {
      return (
        <ProjectDetailsTabShell
          icon="fe fe-pie-chart"
          eyebrow="employee finance"
          title="Finance profile"
          subtitle={`Loading compensation, benefits, and balance schedules for ${displayName}.`}
          stats={[]}
          className="lux-employee-360__embed lux-employee-360__embed--finance"
        >
          <div className="lux-employee-360__finance-skeleton" aria-busy="true" />
        </ProjectDetailsTabShell>
      );
    }

    if (loadError) {
      return (
        <ProjectDetailsTabShell
          icon="fe fe-pie-chart"
          eyebrow="employee finance"
          title="Finance profile"
          subtitle={displayName}
          stats={[]}
          className="lux-employee-360__embed lux-employee-360__embed--finance"
        >
          <LuxRegisterEmptyState
            className="lux-register-empty--compact"
            title="Finance profile unavailable"
            description={loadError}
            showSecondary
            secondaryLabel="Retry"
            secondaryIcon="fe fe-refresh-cw"
            onSecondary={this.loadFinance}
          />
        </ProjectDetailsTabShell>
      );
    }

    if (!profile) {
      return (
        <ProjectDetailsTabShell
          icon="fe fe-pie-chart"
          eyebrow="employee finance"
          title="Finance profile"
          subtitle={displayName}
          stats={stats}
          className="lux-employee-360__embed lux-employee-360__embed--finance"
        >
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-employee-360__embed-empty"
            icon="fe fe-pie-chart"
            title="No finance profile"
            description="Benefits, compensation, and margin analytics will appear when employee finance is linked to this employee."
          />
          <div className="lux-employee-360__embed-links">
            <Link to="/payroll/benefits" className="lux-employee-360__embed-link">
              Open benefits admin
            </Link>
            <Link to="/payroll/employee-finance" className="lux-employee-360__embed-link">
              Open employee finance hub
            </Link>
          </div>
        </ProjectDetailsTabShell>
      );
    }

    const advances = bundle.advances || [];
    const loans = bundle.loans || [];
    const deductions = bundle.deductions || [];

    return (
      <ProjectDetailsTabShell
        icon="fe fe-pie-chart"
        eyebrow="employee finance"
        title="Finance profile"
        subtitle={`Compensation economics, benefit enrollment, and balance schedules for ${displayName}.`}
        stats={stats}
        className="lux-employee-360__embed lux-employee-360__embed--finance"
      >
        {masked ? (
          <p className="lux-employee-360__finance-mask-note">
            <i className="fe fe-lock" aria-hidden="true" /> Sensitive compensation fields are masked for your role.
          </p>
        ) : null}

        <div className="lux-employee-360__embed-links">
          <Link to="/payroll/compensation" className="lux-employee-360__embed-link">
            Compensation register
          </Link>
          <Link to="/payroll/benefits" className="lux-employee-360__embed-link">
            Benefit plans
          </Link>
          <Link to="/payroll/employee-finance" className="lux-employee-360__embed-link">
            Employee finance hub
          </Link>
        </div>

        <section className="lux-employee-360__finance-section">
          <h3 className="lux-employee-360__section-title">Compensation economics</h3>
          <div className="lux-employee-360__field-grid">
            <FinanceField
              label="Base salary"
              value={masked && profile.baseSalaryUsd == null ? "Restricted" : formatCurrency(profile.baseSalaryUsd)}
            />
            <FinanceField
              label="CTC"
              value={masked && profile.ctcUsd == null ? "Restricted" : formatCurrency(profile.ctcUsd)}
            />
            <FinanceField
              label="Billing rate"
              value={masked && profile.billingRateUsd == null ? "Restricted" : formatCurrency(profile.billingRateUsd)}
              hint="Client bill rate / hr"
            />
            <FinanceField
              label="Cost rate"
              value={masked && profile.costRateUsd == null ? "Restricted" : formatCurrency(profile.costRateUsd)}
              hint="Loaded cost / hr"
            />
            <FinanceField
              label="Margin"
              value={profile.marginPct != null ? `${profile.marginPct}%` : "—"}
              hint={profile.marginPct != null && profile.marginPct < 25 ? "Below target band" : "Delivery margin"}
            />
            <FinanceField label="Benefit plans" value={profile.benefitPlanCount != null ? String(profile.benefitPlanCount) : "—"} />
            <FinanceField label="Cost center" value={profile.costCenter || "—"} />
            <FinanceField label="Department" value={profile.department || "—"} />
          </div>
        </section>

        <section className="lux-employee-360__finance-section">
          <h3 className="lux-employee-360__section-title">Advances</h3>
          {this.renderRegister("advances", advances, [
            { key: "amount", label: "Amount", render: (row) => formatCurrency(row.amountUsd) },
            { key: "status", label: "Status", render: (row) => row.status || "—" },
            { key: "reason", label: "Reason", render: (row) => row.reason || "—" },
            {
              key: "repay",
              label: "Repayment",
              render: (row) => (row.repaymentMonths ? `${row.repaymentMonths} mo` : "—"),
            },
          ])}
        </section>

        <section className="lux-employee-360__finance-section">
          <h3 className="lux-employee-360__section-title">Loans</h3>
          {this.renderRegister("loans", loans, [
            { key: "principal", label: "Principal", render: (row) => formatCurrency(row.principalUsd) },
            { key: "balance", label: "Balance", render: (row) => formatCurrency(row.balanceUsd) },
            { key: "status", label: "Status", render: (row) => row.status || "—" },
            { key: "rate", label: "Rate", render: (row) => (row.interestRatePct != null ? `${row.interestRatePct}%` : "—") },
          ])}
        </section>

        <section className="lux-employee-360__finance-section">
          <h3 className="lux-employee-360__section-title">Deduction schedules</h3>
          {this.renderRegister("deductions", deductions, [
            { key: "label", label: "Deduction", render: (row) => row.label || row.type || "—" },
            { key: "amount", label: "Amount", render: (row) => formatCurrency(row.amountUsd) },
            { key: "cadence", label: "Cadence", render: (row) => row.frequency || "—" },
            {
              key: "remaining",
              label: "Remaining",
              render: (row) =>
                row.remainingInstallments != null ? `${row.remainingInstallments} installments` : "—",
            },
          ])}
        </section>
      </ProjectDetailsTabShell>
    );
  }
}
