import React, { Component } from "react";
import LuxRegisterListSkeletonRows from "views/common/fragments/LuxRegisterListSkeletonRows";
import classNames from "classnames/bind";
import InvoiceLineItem from "./InvoiceLineItem";

const LIST_COLUMNS = [
  { key: "invoice", label: "Invoice", icon: "fe-file-text" },
  { key: "period", label: "Date", icon: "fe-calendar" },
  { key: "users", label: "Users", icon: "fe-users", center: true },
  { key: "status", label: "Status", icon: "fe-activity" },
  { key: "amount", label: "Amount", icon: "fe-dollar-sign" },
  { key: "actions", label: "Actions", icon: null, center: true },
];

class InvoiceListTable extends Component {

  render() {
    return (
      <div className="lux-inv-list" aria-label="Invoice list">
        <div className="lux-inv-list__head" role="row">
          {LIST_COLUMNS.map((col) => (
            <div
              key={col.key}
              className={classNamesCol(col)}
              role="columnheader"
            >
              {col.icon ? (
                <span className="lux-inv-list__head-label">
                  <i className={`fe ${col.icon}`} aria-hidden="true" />
                  {col.label}
                </span>
              ) : (
                <span className="lux-inv-list__head-label">{col.label}</span>
              )}
            </div>
          ))}
        </div>

        <div
          className={classNames("lux-inv-list__body", { "is-loading": this.props.isLoading })}
          role="list"
        >
          {this.props.isLoading && <LuxRegisterListSkeletonRows variant="inv" />}
          {!this.props.isLoading &&
            this.props.items &&
            this.props.items.map((item) => (
              <InvoiceLineItem
                key={item.id}
                item={item}
                header={this.props.header}
                removeInvoice={this.props.removeInvoice}
                handleUpdateStatus={this.props.handleUpdateStatus}
                permission={this.props.permission}
              />
            ))}
        </div>
      </div>
    );
  }
}

function classNamesCol(col) {
  const classes = [`lux-inv-list__head-cell`, `lux-inv-list__head-cell--${col.key}`];
  if (col.center) classes.push("is-center");
  return classes.join(" ");
}

export default InvoiceListTable;
