import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseAiWorkIntelligenceApi } from "config/ai-work-intelligence.config";

import { apiErrorResult } from "config/mock-fallback.utils";

export const aiWorkIntelligenceService = {
  getAgentConsoleOverview,
  listAgents,
  getAgent,
  listAgentRuns,
  listRecommendations,
  runAgent,
  decideRecommendation,
  exportRecommendationsCsv,
  listAuditTrail,
  exportAuditTrailCsv,
};

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function getAgentConsoleOverview(filters = {}) {
  if (!shouldUseAiWorkIntelligenceApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.AI_WORK_INTELLIGENCE_API_PATH}/console/overview`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response, source: "api" };
}

async function listAgents(filters = {}) {
  if (!shouldUseAiWorkIntelligenceApi()) {
    return apiErrorResult(null);
  }
  const response = await axiosUtils.getWithParam(
    `${urlConfig.AI_WORK_INTELLIGENCE_API_PATH}/agents`,
    teamQuery(filters)
  );
  return { payload: (response && response.payload) || response || [], source: "api" };
}

