
import { axiosUtils } from '../_helpers';
import urlConfig from 'url.config'

export const appConfigService = {
    initializeConfig,
    createNewConfig,
    deleteUserTeamItem,
    removeUserTeamItem,
    updateConfig,
    getAppConfig,
    updateConfigProperty,
    getModuleConfig,
    getAllTeams,
    getAllRoles,
    appendModuleListValue,
    removeModuleListValue,
    getCompanyBranding,
    updateCompanyBranding,
    getImplementationChecklist,
    updateImplementationChecklist,
};

async function initializeConfig(configId) {
    return await axiosUtils.get(urlConfig.APPCONFIG_INITIALIZE + `/${configId}`, {});
}
async function createNewConfig(type, name, parentId) {
    return await axiosUtils.post(urlConfig.APPCONFIG_CREATE+ `?parentId=${parentId}&type=${type}&name=${name}`, null);
}
async function updateConfigProperty(configId, propertyName, propertyValue) {
    return await axiosUtils.put(urlConfig.APPCONFIG_UPDATE_PROPERTY+ `/${configId}/${propertyName}?propertyValue=${propertyValue}`, null);
}

async function updateConfig(configRequest, configId) {
    return await axiosUtils.put(urlConfig.APPCONFIG_UPDATE +  `/${configId}`, configRequest);
}
async function getAppConfig(configId, useCache) {
    return await axiosUtils.get(urlConfig.APPCONFIG_GET + `/${configId}/${useCache}`, {});
}

async function getModuleConfig(configId, moudleName) {
    return await axiosUtils.get(urlConfig.APPCONFIG_GET_MODULE + `/${configId}/${moudleName}`, {});
}

/** W2-B02 / ADMIN-005 — append department/designation/teamName to Application Config list. */
async function appendModuleListValue(configId, moduleName, listKey, value) {
    return await axiosUtils.post(
        `${urlConfig.APPCONFIG_PATH}/${configId}/module/${encodeURIComponent(moduleName)}/list/${encodeURIComponent(listKey)}`,
        { value }
    );
}

/** W2-B02 / ADMIN-005 — remove a value from Application Config list. */
async function removeModuleListValue(configId, moduleName, listKey, value) {
    const encoded = encodeURIComponent(value);
    return await axiosUtils.remove(
        `${urlConfig.APPCONFIG_PATH}/${configId}/module/${encodeURIComponent(moduleName)}/list/${encodeURIComponent(listKey)}?value=${encoded}`
    );
}

async function getAllTeams(isGroupByEnabled) {
    return await axiosUtils.get(urlConfig.APPCONFIG_GET_ALL_TEAMS  + `${isGroupByEnabled ? "/groupbyparent" : "?includeParent=true"}`, {});
}

async function getAllRoles(isGroupByEnabled) {
    return await axiosUtils.get(urlConfig.APPCONFIG_GET_ALL_ROLES + `${isGroupByEnabled ? "/groupbyparent" : ""}`, {});
}

async function deleteUserTeamItem(itemId, idDelete) {
    return await axiosUtils.remove(urlConfig.APPCONFIG_PATH+ `/${itemId}/${idDelete}`);
}
async function removeUserTeamItem(itemId) {
    return await axiosUtils.remove(urlConfig.APPCONFIG_PATH+ `/${itemId}`);
}

/** W0A / CUST-003 — company branding/locale from Application Config. */
async function getCompanyBranding(configId) {
    return await axiosUtils.get(`${urlConfig.APPCONFIG_PATH}/${configId}/company-branding`, {});
}

async function updateCompanyBranding(configId, payload) {
    return await axiosUtils.put(`${urlConfig.APPCONFIG_PATH}/${configId}/company-branding`, payload || {});
}

/** W0A / CUST-008 / MIG-001 — customer implementation checklist document. */
async function getImplementationChecklist(configId) {
    return await axiosUtils.get(`${urlConfig.APPCONFIG_PATH}/${configId}/implementation-checklist`, {});
}

async function updateImplementationChecklist(configId, payload) {
    return await axiosUtils.put(`${urlConfig.APPCONFIG_PATH}/${configId}/implementation-checklist`, payload || {});
}
