import React from "react";
import classNames from "classnames/bind";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { COMPENSATION_CHANGE_STATUSES, getCompensationChangeTone } from "config/employee-finance.config";
import { EmployeeFinanceActionButton } from "views/payroll/components/EmployeeFinanceLuxShared";

function formatUsd(value) {
  if (value == null) {
    return "—";
  }
  return `$${Number(value).toLocaleString()}`;
}

export default function CompensationRegister({ rows = [], loading, busyId, onApprove, onReject, onPropose }) {
  if (loading) {
    return <div className="lux-empfin-register__skeleton" aria-busy="true" />;
  }
  if (!rows.length) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact"
        title="No compensation changes"
        description="Propose a merit, promotion, or adjustment to start the approval workflow."
        showCreate
        createLabel="Propose change"
        onCreate={onPropose}
      />
    );
  }

  return (
    <div className="lux-empfin-register-wrap">
      <table className="lux-empfin-register">
        <thead>
          <tr>
            <th>Employee</th>
            <th>Type</th>
            <th>Base salary</th>
            <th>CTC</th>
            <th>Effective</th>
            <th>Status</th>
            <th aria-label="Actions" />
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const canApprove = row.status === COMPENSATION_CHANGE_STATUSES.PENDING_APPROVAL;
            const delta = row.proposedBaseUsd != null && row.currentBaseUsd != null ? row.proposedBaseUsd - row.currentBaseUsd : null;
            return (
              <tr key={`${row.userTeamId || "t"}-${row.id}`}>
                <td>
                  <div className="lux-empfin-register__title">{row.employeeName}</div>
                  <div className="lux-empfin-register__meta">{row.department}</div>
                </td>
                <td>{row.changeType}</td>
                <td>
                  <div>{formatUsd(row.currentBaseUsd)} → {formatUsd(row.proposedBaseUsd)}</div>
                  {delta != null ? (
                    <div className={classNames("lux-empfin-register__meta", delta >= 0 ? "is-up" : "is-down")}>
                      {delta >= 0 ? "+" : ""}
                      {formatUsd(delta)}
                    </div>
                  ) : null}
                </td>
                <td>
                  {formatUsd(row.currentCtcUsd)} → {formatUsd(row.proposedCtcUsd)}
                </td>
                <td>{row.effectiveDate || "—"}</td>
                <td>
                  <span className={classNames("lux-portfolio-badge", `is-${getCompensationChangeTone(row.status)}`)}>
                    {row.status.replace(/_/g, " ")}
                  </span>
                </td>
                <td>
                  <div className="lux-empfin-register__actions">
                    {canApprove ? (
                      <>
                        <EmployeeFinanceActionButton
                          icon="fe fe-check"
                          variant="primary"
                          className="lux-onb-action--sm"
                          disabled={busyId === row.id}
                          onClick={() => onApprove(row.id, row.userTeamId)}
                        >
                          Approve
                        </EmployeeFinanceActionButton>
                        <EmployeeFinanceActionButton
                          icon="fe fe-x"
                          variant="ghost"
                          className="lux-onb-action--sm"
                          disabled={busyId === row.id}
                          onClick={() => onReject(row.id, row.userTeamId)}
                        >
                          Reject
                        </EmployeeFinanceActionButton>
                      </>
                    ) : null}
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
