import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";

export function PayrollDrawerLinks({ links, onNavigate }) {
  if (!links || !links.length) {
    return null;
  }

  return (
    <nav className="lux-gov-drawer__links lux-payroll-drawer__links" aria-label="Related payroll workspaces">
      {links.map((link) => (
        <Link
          key={`${link.to}-${link.label}`}
          to={link.to}
          className="lux-gov-drawer__link-card lux-payroll-drawer__link-card"
          onClick={onNavigate}
        >
          <span className="lux-gov-drawer__link-icon" aria-hidden="true">
            <i className={link.icon || "fe fe-arrow-up-right"} />
          </span>
          <span className="lux-gov-drawer__link-copy">
            <strong>{link.label}</strong>
            {link.hint ? <small>{link.hint}</small> : null}
          </span>
          <i className="fe fe-chevron-right lux-gov-drawer__link-chevron" aria-hidden="true" />
        </Link>
      ))}
    </nav>
  );
}

export function PayrollDrawerStatStrip({ stats }) {
  if (!stats || !stats.length) {
    return null;
  }

  return (
    <div className="lux-gov-drawer__stat-strip lux-payroll-drawer__stat-strip" role="list">
      {stats.map((stat) => (
        <article
          key={stat.label}
          className={classNames("lux-gov-drawer__stat", stat.tone && `is-${stat.tone}`)}
          role="listitem"
        >
          <span className="lux-gov-drawer__stat-label">{stat.label}</span>
          <strong className="lux-gov-drawer__stat-value">{stat.value}</strong>
          {stat.hint ? <small className="lux-gov-drawer__stat-hint">{stat.hint}</small> : null}
        </article>
      ))}
    </div>
  );
}

export function PayrollDrawerCard({ title, subtitle, children, className, tone }) {
  return (
    <section className={classNames("lux-gov-drawer__card lux-payroll-drawer__card", tone && `is-${tone}`, className)}>
      <header className="lux-gov-drawer__card-head">
        <h3>{title}</h3>
        {subtitle ? <p>{subtitle}</p> : null}
      </header>
      <div className="lux-gov-drawer__card-body">{children}</div>
    </section>
  );
}

export function PayrollDrawerField({ label, hint, children }) {
  return (
    <label className="lux-gov-drawer__field lux-payroll-drawer__field">
      <span>{label}</span>
      {children}
      {hint ? <small className="lux-payroll-drawer__field-hint">{hint}</small> : null}
    </label>
  );
}

export function PayrollDrawerBanner({ icon = "fe-info", tone = "info", children }) {
  const iconClass = icon.startsWith("fe-") ? icon : `fe-${icon}`;

  return (
    <div className={classNames("lux-gov-drawer__banner lux-payroll-drawer__banner", tone && `is-${tone}`)}>
      <span className="lux-gov-drawer__banner-icon" aria-hidden="true">
        <i className={classNames("fe", iconClass)} />
      </span>
      <div className="lux-gov-drawer__banner-copy">{children}</div>
    </div>
  );
}

export function PayrollDrawerMeta({ items }) {
  if (!items || !items.length) {
    return null;
  }

  return (
    <dl className="lux-gov-drawer__meta-grid lux-payroll-drawer__meta">
      {items.map((item) => (
        <div key={item.label}>
          <dt>{item.label}</dt>
          <dd>{item.value != null && item.value !== "" ? item.value : "—"}</dd>
        </div>
      ))}
    </dl>
  );
}

export function PayrollDrawerStepRail({ steps, activeStep }) {
  if (!steps || !steps.length) {
    return null;
  }

  const activeIndex = steps.findIndex((step) => step.id === activeStep);

  return (
    <nav className="lux-payroll-drawer__steps" aria-label="Wizard progress">
      <ol>
        {steps.map((step, index) => {
          const stepNumber = index + 1;
          const isActive = step.id === activeStep;
          const isComplete = activeIndex >= 0 && index < activeIndex;
          return (
            <li
              key={step.id}
              className={classNames("lux-payroll-drawer__step", {
                "is-active": isActive,
                "is-complete": isComplete,
              })}
            >
              <span className="lux-payroll-drawer__step-marker" aria-hidden="true">
                {isComplete ? <i className="fe fe-check" /> : stepNumber}
              </span>
              <span className="lux-payroll-drawer__step-copy">
                <strong>{step.label}</strong>
                {step.hint ? <small>{step.hint}</small> : null}
              </span>
            </li>
          );
        })}
      </ol>
    </nav>
  );
}

export function PayrollDrawerGroupPicker({ groups, value, onChange }) {
  if (!groups || groups.length === 0) {
    return (
      <PayrollDrawerBanner icon="fe-alert-circle" tone="warning">
        No payroll groups found. Create a payroll group before starting a run.
      </PayrollDrawerBanner>
    );
  }

  return (
    <div className="lux-payroll-drawer__group-grid" role="listbox" aria-label="Payroll group">
      {groups.map((group) => {
        const selected = value === group.id;
        return (
          <button
            key={group.id}
            type="button"
            role="option"
            aria-selected={selected}
            className={classNames("lux-payroll-drawer__group-card", { "is-selected": selected })}
            onClick={() => onChange(group.id)}
          >
            <span className="lux-payroll-drawer__group-top">
              <span className="lux-doc-badge is-success">{group.status || "Active"}</span>
              {group.code ? <span className="lux-payroll-drawer__group-code">{group.code}</span> : null}
            </span>
            <strong className="lux-payroll-drawer__group-name">{group.name}</strong>
            <span className="lux-payroll-drawer__group-meta">
              {group.payFrequency}
              {group.currency ? ` · ${group.currency}` : ""}
            </span>
            <span className="lux-payroll-drawer__group-foot">
              <span>{group.employeeCount || 0} employees</span>
              {group.currentPeriod ? <span>{group.currentPeriod}</span> : null}
            </span>
            {selected ? (
              <span className="lux-payroll-drawer__group-check" aria-hidden="true">
                <i className="fe fe-check-circle" />
              </span>
            ) : null}
          </button>
        );
      })}
    </div>
  );
}
