/**
 * F20-T6 — Data retention / legal hold administration service.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import envconfig from "env.config";
import { normalizeRetentionPolicy } from "config/data-retention.config";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ENTITY_TYPES } from "_constants/audit.constants";

import { apiErrorResult } from "config/mock-fallback.utils";

export const dataRetentionService = {
  listPolicies,
  getPolicy,
  updateRetentionDays,
  updateLegalHold,
  updateAutoPurge,
};

const API_BASE = `${urlConfig.APPCONFIG_API_PATH}/retention-policies`;

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function listPolicies() {
  if (envconfig.USE_DATA_RETENTION_ADMIN_API === true) {
    try {
      const response = await axiosUtils.getWithParam(API_BASE, teamQuery());
      const rows = (response && response.payload) || response || [];
      return {
        payload: (Array.isArray(rows) ? rows : []).map(normalizeRetentionPolicy).filter(Boolean),
        source: "api",
      };
    } catch (e) {
      // fall through
    }
  }

  return apiErrorResult(null);
}

async function getPolicy(policyId) {
  if (envconfig.USE_DATA_RETENTION_ADMIN_API === true) {
    try {
      const response = await axiosUtils.getWithParam(`${API_BASE}/${policyId}`, teamQuery());
      const row = (response && response.payload) || response;
      return { payload: normalizeRetentionPolicy(row), source: "api" };
    } catch (e) {
      // fall through
    }
  }
  return apiErrorResult(null);
}

async function updateRetentionDays(policyId, retentionDays) {
  if (envconfig.USE_DATA_RETENTION_ADMIN_API === true) {
    try {
      const response = await axiosUtils.patch(
        `${API_BASE}/${policyId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
        { retentionDays }
      );
      const row = (response && response.payload) || response;
      const result = { payload: normalizeRetentionPolicy(row), source: "api" };
      recordAuditEvent({
        actionType: "UPDATED",
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: `${result.payload && result.payload.name} · retention`,
        metadata: { policyId, retentionDays },
      });
      return result;
    } catch (e) {
      // fall through
    }
  }
  throw new Error("Unable to complete action via API.");

}

async function updateLegalHold(policyId, legalHold) {
  if (envconfig.USE_DATA_RETENTION_ADMIN_API === true) {
    try {
      const response = await axiosUtils.patch(
        `${API_BASE}/${policyId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
        { legalHold }
      );
      const row = (response && response.payload) || response;
      const result = { payload: normalizeRetentionPolicy(row), source: "api" };
      recordAuditEvent({
        actionType: legalHold ? "STATUS_CHANGED" : "UPDATED",
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: `${result.payload && result.payload.name} · legal hold`,
        metadata: { policyId, legalHold },
      });
      return result;
    } catch (e) {
      // fall through
    }
  }
  throw new Error("Unable to complete action via API.");

}

async function updateAutoPurge(policyId, autoPurge) {
  if (envconfig.USE_DATA_RETENTION_ADMIN_API === true) {
    try {
      const response = await axiosUtils.patch(
        `${API_BASE}/${policyId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
        { autoPurge }
      );
      const row = (response && response.payload) || response;
      const result = { payload: normalizeRetentionPolicy(row), source: "api" };
      recordAuditEvent({
        actionType: "UPDATED",
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: `${result.payload && result.payload.name} · auto-purge`,
        metadata: { policyId, autoPurge },
      });
      return result;
    } catch (e) {
      // fall through
    }
  }
  throw new Error("Unable to complete action via API.");

}
