/**
 * F03-T6 — Document / IT / asset integration hooks (client + mock).
 */

import { LIFECYCLE_HOOK_STATUSES } from "config/onboarding.schema";

const HOOK_CATEGORIES = new Set(["Documents", "IT", "Access", "Assets", "Asset", "Payroll"]);

export function isHookCategory(category) {
  if (!category) {
    return false;
  }
  return HOOK_CATEGORIES.has(category) || HOOK_CATEGORIES.has(String(category).trim());
}

export function resolveIntegrationType(category, lifecycle = "onboarding") {
  const normalized = String(category || "").trim();
  if (normalized === "IT" || normalized === "Access") {
    return lifecycle === "offboarding" ? "ACCESS_REVOKE" : "IT_ACCESS";
  }
  if (normalized === "Assets" || normalized === "Asset") {
    return lifecycle === "offboarding" ? "ASSET_RETURN" : "ASSET_ASSIGN";
  }
  if (normalized === "Documents") {
    return "DOCUMENT";
  }
  if (normalized === "Payroll") {
    return "PAYROLL_SETUP";
  }
  return "GENERIC";
}

export function dispatchLifecycleTaskHook(task, lifecycle = "onboarding", hooksEnabled = true) {
  if (!task || !isHookCategory(task.category)) {
    return {
      hookStatus: LIFECYCLE_HOOK_STATUSES.NOT_APPLICABLE,
    };
  }
  if (!hooksEnabled) {
    return {
      hookStatus: LIFECYCLE_HOOK_STATUSES.PENDING,
      hookLastError: "Lifecycle hooks disabled for organization",
      integrationType: resolveIntegrationType(task.category, lifecycle),
    };
  }

  const integrationType = resolveIntegrationType(task.category, lifecycle);
  const integrationRef = `${lifecycle.toUpperCase()}-${task.id}-${Date.now()}`;
  return {
    hookStatus: LIFECYCLE_HOOK_STATUSES.SUCCEEDED,
    integrationType,
    integrationRef,
    hookPayload: {
      lifecycle,
      category: task.category,
      taskId: task.id,
      title: task.title,
      integrationType,
      integrationRef,
      dispatchedAt: new Date().toISOString(),
    },
    hookLastError: null,
    hookLastAttemptAt: new Date().toISOString().slice(0, 10),
  };
}

export function getHookStatusMeta(hookStatus) {
  const map = {
    [LIFECYCLE_HOOK_STATUSES.NOT_APPLICABLE]: { label: "No integration", tone: "neutral" },
    [LIFECYCLE_HOOK_STATUSES.PENDING]: { label: "Hook pending", tone: "amber" },
    [LIFECYCLE_HOOK_STATUSES.SUCCEEDED]: { label: "Integrated", tone: "green" },
    [LIFECYCLE_HOOK_STATUSES.FAILED]: { label: "Hook failed", tone: "rose" },
  };
  return map[hookStatus] || { label: hookStatus || "Unknown", tone: "neutral" };
}
