import React, { Component } from "react";
import { connect } from "react-redux";
import { taskActions } from "_actions";
import { store } from "_helpers";
import dateUtils from "_helpers/date.utils";
import classNames from "classnames/bind";
import LuxStatusControl, {
  DELIVERABLE_STATUS_OPTIONS,
} from "views/common/fragments/LuxStatusControl";

class DeliverableDetailsHero extends Component {
  handleUpdateStatus = (taskId, status) => {
    store.dispatch(this.props.updateTaskStatus(taskId, status));
  };

  renderFact = (icon, label, value) => {
    const display = value == null || value === "" ? "—" : value;
    return (
      <div className="pd-hero__fact">
        <span className="pd-hero__fact-icon" aria-hidden="true">
          <i className={icon} />
        </span>
        <div className="pd-hero__fact-copy">
          <span className="pd-hero__fact-label">{label}</span>
          <strong className="pd-hero__fact-value" title={String(display)}>
            {display}
          </strong>
        </div>
      </div>
    );
  };

  render() {
    const { item, permission, readOnly, compact } = this.props;
    if (!item) return null;

    const projectName = item.projectInfo && item.projectInfo.name;
    const teamName =
      (item.ownerUserTeamDetails && item.ownerUserTeamDetails.name) || item.teamName;
    const startLabel = dateUtils.convertDateFormat(item.estStartTime);
    const dueLabel = dateUtils.convertDateFormat(item.estCompletionTime);
    const durationLabel = item.estDurationMins
      ? dateUtils.minuteToHourString(item.estDurationMins)
      : null;

    return (
      <header
        className={classNames("pd-hero", "lux-del-hero", "lux-pd-hero", "pd-hero--dense", {
          "pd-hero--compact": compact,
        })}
      >
        <div className="pd-hero__glow" aria-hidden="true" />
        <div className="pd-hero__accent" aria-hidden="true" />
        <div className="pd-hero__inner">
          <div className="pd-hero__identity">
            <div className="pd-hero__meta-row">
              <span className="pd-hero__badge">{teamName || "Team"}</span>
              {item.itemIdUserTeamPrefix && (
                <span className="pd-hero__id">{item.itemIdUserTeamPrefix}</span>
              )}
              {projectName && (
                <span className="pd-hero__meta-chip">{projectName}</span>
              )}
              {item.category && (
                <span className="pd-hero__meta-chip">{item.category}</span>
              )}
              {item.taskType && (
                <span className="pd-hero__meta-chip">{item.taskType}</span>
              )}
            </div>
            <h1 className="pd-hero__title">
              {item.code && <span className="pd-hero__code">[{item.code}]</span>}{" "}
              {item.name}
            </h1>
            <div className="pd-hero__chips">
              <span className="pd-chip pd-chip--soft">
                <i className="fe fe-user" />{" "}
                {(item.ownerDetails && item.ownerDetails.name) || "Unassigned"}
              </span>
              {item.priority && (
                <span className="pd-chip pd-chip--accent">{item.priority}</span>
              )}
              {item.complexity && (
                <span className="pd-chip pd-chip--soft">
                  <i className="fe fe-layers" /> {item.complexity}
                </span>
              )}
              {dueLabel && (
                <span className="pd-chip pd-chip--soft">
                  <i className="fe fe-calendar" /> Due {dueLabel}
                </span>
              )}
            </div>
          </div>
          <div className="pd-hero__actions">
            <LuxStatusControl
              className="pd-hero__status"
              label="Deliverable status"
              options={DELIVERABLE_STATUS_OPTIONS}
              value={item.status}
              allowLevelDown={permission.allowStatusLevelDown}
              changeableStatus={permission.changeableStatus}
              isReadOnly={
                !permission.allowStatusChange ||
                readOnly ||
                !!(item && item.deleted)
              }
              itemId={item.id}
              onChange={this.handleUpdateStatus}
            />
          </div>
        </div>

        <div
          className={classNames("pd-hero__facts", {
            "pd-hero__facts--compact": compact,
          })}
          aria-label="Deliverable at a glance"
        >
          {this.renderFact("fe fe-flag", "Start", startLabel)}
          {this.renderFact("fe fe-target", "Due", dueLabel)}
          {this.renderFact("fe fe-clock", "Duration", durationLabel)}
          {this.renderFact("fe fe-layers", "Complexity", item.complexity)}
          {this.renderFact("fe fe-flag", "Priority", item.priority)}
          {this.renderFact("fe fe-briefcase", "Project", projectName)}
        </div>
      </header>
    );
  }
}

const mapDispatchToProps = () => ({
  updateTaskStatus: taskActions.updateTaskStatus,
});

export default connect(null, mapDispatchToProps)(DeliverableDetailsHero);
