import React from 'react';

export function tourStep(config) {
  const { target, title, lead, bullets, tip, placement, spotlightPadding, styles } = config;

  return {
    target: target || 'body',
    title: title || '',
    placement: placement || 'bottom',
    disableBeacon: true,
    spotlightPadding: spotlightPadding === undefined ? 14 : spotlightPadding,
    styles: styles,
    content: (
      <div className="lux-guided-tour__step">
        {lead ? <p className="lux-guided-tour__lead">{lead}</p> : null}
        {bullets && bullets.length > 0 ? (
          <ul className="lux-guided-tour__list">
            {bullets.map(function (item, index) {
              return <li key={index}>{item}</li>;
            })}
          </ul>
        ) : null}
        {tip ? (
          <p className="lux-guided-tour__tip">
            <strong>Tip: </strong>
            {tip}
          </p>
        ) : null}
      </div>
    ),
  };
}

export function registerTourSteps(stepList) {
  return [
    tourStep({
      target: 'body',
      placement: 'center',
      title: stepList.welcomeTitle,
      lead: stepList.welcomeLead,
      bullets: stepList.welcomeBullets,
      tip: stepList.welcomeTip,
      spotlightPadding: 0,
    }),
    tourStep({
      target: '[data-tour="lux-page-header"]',
      title: 'Page controls',
      lead: stepList.headerLead,
      bullets: stepList.headerBullets,
      tip: stepList.headerTip,
      placement: 'bottom',
    }),
    tourStep({
      target: '[data-tour="lux-summary"], .lux-bid-summary, .lux-po-summary, .lux-project-summary',
      title: 'Summary & charts',
      lead: stepList.summaryLead,
      bullets: stepList.summaryBullets,
      placement: 'bottom',
    }),
    tourStep({
      target: '[data-tour="lux-register"]',
      title: stepList.registerTitle || 'Main workspace',
      lead: stepList.registerLead,
      bullets: stepList.registerBullets,
      tip: stepList.registerTip,
      placement: 'top',
    }),
    tourStep({
      target: '[data-tour="lux-pagination"]',
      title: 'Pagination',
      lead: 'Move through large registers without losing your filters.',
      bullets: ['Change page size when you need denser review sessions.'],
      placement: 'top',
    }),
  ];
}
