import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { ONE_ON_ONE_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, { PerformanceActionButton, PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";
import OneOnOneRegister from "views/performance/components/OneOnOneRegister";
import { OneOnOneCreateDrawer } from "views/performance/components/PerformanceCreateDrawers";

class OneOnOnePage extends Component {
  state = { loading: true, notes: [], kpiCards: [], dataSource: null, createOpen: false, busy: false };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true });
    try {
      const [overview, notesResult] = await Promise.all([
        performanceManagementService.getOverview({}),
        performanceManagementService.listOneOnOnes({}),
      ]);
      this.setState({
        loading: false,
        dataSource: notesResult.source,
        notes: notesResult.payload || [],
        kpiCards: (overview.payload && overview.payload.kpiCards) || [],
      });
    } catch (error) {
      this.setState({ loading: false, notes: [] });
    }
  };

  handleCreate = async (payload) => {
    this.setState({ busy: true });
    try {
      await performanceManagementService.createOneOnOne(payload);
      this.setState({ createOpen: false, busy: false });
      await this.loadData();
    } catch (error) {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="1:1 notes" />;
    }

    const { loading, notes, kpiCards, dataSource, createOpen, busy } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={ONE_ON_ONE_PAGE_META}
        pageId="one-on-ones"
        shellTitle="1:1 notes"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><PerformanceActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Record 1:1
            </PerformanceActionButton>
          </>}
      >
        <PerformanceLuxPanel title="1:1 register" meta="Manager check-ins and action items" icon="fe fe-users" accent="cyan" featured>
          <OneOnOneRegister notes={notes} loading={loading} />
        </PerformanceLuxPanel>
        <OneOnOneCreateDrawer open={createOpen} onClose={() => this.setState({ createOpen: false })} onCreate={this.handleCreate} busy={busy} />
      </PerformanceLuxPage>
    );
  }
}

export default OneOnOnePage;
