import React, { Component, createRef } from "react";
import { connect } from "react-redux";
import { Link } from "react-router-dom";
import Skeleton from "react-loading-skeleton";
import { itemAdditionalActions } from "_actions";
import { itemAdditionalConstants } from "_constants";
import {
  buildPageNumbers,
  buildRankedResults,
  getSearchCounts,
  paginateRankedResults,
  SEARCH_PAGE_SIZE,
  SEARCH_PAGE_SIZE_OPTIONS,
  SEARCH_TIPS,
  SEARCH_VIEWS,
  splitHighlight,
} from "./searchPage.utils";

function HighlightText({ text, query, className, as: Tag = "span" }) {
  const parts = splitHighlight(text, query);
  return (
    <Tag className={className}>
      {parts.map((part, index) =>
        part.match ? (
          <mark key={index}>{part.text}</mark>
        ) : (
          <React.Fragment key={index}>{part.text}</React.Fragment>
        )
      )}
    </Tag>
  );
}

function SearchResultCard({ entry, query }) {
  const { type, item, rank, relevancePct, relevanceLabel, matchReasons } = entry;
  const isProject = type === "project";
  const isDeleted = isProject && item.deleted === true;
  const to = isProject ? `/project/details/${item.id}` : `/project/deliverable/${item.id}`;
  const path = isProject ? `/project/${item.id}` : `/deliverable/${item.id}`;

  return (
    <article className="lux-search-result">
      <div className="lux-search-result__rank-col" aria-hidden="true">
        <span className={`lux-search-result__rank${rank <= 3 ? " is-top" : ""}`}>#{rank}</span>
      </div>

      <div
        className={`lux-search-result__icon lux-search-result__icon--${isProject ? "project" : "task"}`}
        aria-hidden="true"
      >
        <i className={`fe ${isProject ? "fe-folder" : "fe-layers"}`} />
      </div>

      <div className="lux-search-result__body">
        <div className="lux-search-result__head">
          <span
            className={`lux-search-result__type lux-search-result__type--${isProject ? "project" : "task"}`}
          >
            {isProject ? "Project" : "Deliverable"}
          </span>
          <span className="lux-search-result__path">{path}</span>
          {isDeleted && <span className="lux-search-result__badge">Archived</span>}
          <span className="lux-search-result__relevance-label">{relevanceLabel}</span>
        </div>

        <Link to={to} className="lux-search-result__title">
          {isDeleted ? (
            <del>{item.name}</del>
          ) : (
            <HighlightText text={item.name} query={query} />
          )}
        </Link>

        <p className="lux-search-result__summary">
          {isDeleted ? (
            item.summary ? <del>{item.summary}</del> : null
          ) : (
            <HighlightText text={item.summary || "No description available."} query={query} />
          )}
        </p>

        <div className="lux-search-result__footer">
          <div className="lux-search-result__reasons">
            {matchReasons.map((reason) => (
              <span key={reason} className="lux-search-result__reason">
                {reason}
              </span>
            ))}
          </div>
          <div className="lux-search-result__meter" aria-label={`${relevancePct}% relevance`}>
            <div className="lux-search-result__meter-track">
              <div
                className="lux-search-result__meter-fill"
                style={{ width: `${relevancePct}%` }}
              />
            </div>
            <span className="lux-search-result__meter-value">{relevancePct}%</span>
          </div>
        </div>
      </div>

      <Link to={to} className="lux-search-result__open" aria-label={`Open ${item.name}`}>
        <i className="fe fe-arrow-up-right" aria-hidden="true" />
      </Link>
    </article>
  );
}

function SearchPagination({ pagination, onPageChange, onPageSizeChange }) {
  const { page, totalPages, total, rangeStart, rangeEnd, pageSize } = pagination;
  if (total === 0) return null;

  const pageNumbers = buildPageNumbers(page, totalPages);

  return (
    <footer className="lux-search-pagination">
      <div className="lux-search-pagination__summary">
        Showing <strong>{rangeStart}–{rangeEnd}</strong> of <strong>{total}</strong> ranked results
      </div>

      <div className="lux-search-pagination__controls">
        <button
          type="button"
          className="lux-search-pagination__btn"
          disabled={page <= 1}
          onClick={() => onPageChange(page - 1)}
          aria-label="Previous page"
        >
          <i className="fe fe-chevron-left" aria-hidden="true" />
        </button>

        <div className="lux-search-pagination__pages" role="navigation" aria-label="Pagination">
          {pageNumbers.map((item, index) =>
            item === "ellipsis" ? (
              <span key={`ellipsis-${index}`} className="lux-search-pagination__ellipsis">
                …
              </span>
            ) : (
              <button
                key={item}
                type="button"
                className={`lux-search-pagination__page${page === item ? " is-active" : ""}`}
                onClick={() => onPageChange(item)}
                aria-current={page === item ? "page" : undefined}
              >
                {item}
              </button>
            )
          )}
        </div>

        <button
          type="button"
          className="lux-search-pagination__btn"
          disabled={page >= totalPages}
          onClick={() => onPageChange(page + 1)}
          aria-label="Next page"
        >
          <i className="fe fe-chevron-right" aria-hidden="true" />
        </button>
      </div>

      <div className="lux-search-pagination__size">
        <label htmlFor="lux-search-page-size">Per page</label>
        <select
          id="lux-search-page-size"
          value={pageSize}
          onChange={(e) => onPageSizeChange(Number(e.target.value))}
        >
          {SEARCH_PAGE_SIZE_OPTIONS.map((size) => (
            <option key={size} value={size}>
              {size}
            </option>
          ))}
        </select>
      </div>
    </footer>
  );
}

function SearchSkeletonList() {
  return (
    <div className="lux-search-skeleton" aria-hidden="true">
      {[1, 2, 3, 4, 5].map((key) => (
        <div key={key} className="lux-search-skeleton__row">
          <Skeleton width={36} height={36} borderRadius={8} />
          <Skeleton className="lux-search-skeleton__icon" borderRadius={12} />
          <div className="lux-search-skeleton__lines">
            <Skeleton height={14} width="28%" borderRadius={6} />
            <Skeleton height={18} width="68%" borderRadius={6} />
            <Skeleton height={12} width="92%" borderRadius={6} />
            <Skeleton height={8} width="40%" borderRadius={6} />
          </div>
        </div>
      ))}
    </div>
  );
}

class SearchResults extends Component {
  state = {
    view: SEARCH_VIEWS.ALL,
    page: 1,
    pageSize: SEARCH_PAGE_SIZE,
  };

  componentDidUpdate(prevProps) {
    if (
      prevProps.searchText !== this.props.searchText ||
      prevProps.searchResults !== this.props.searchResults
    ) {
      this.setState({ page: 1 });
    }
  }

  onChangeView = (viewName) => {
    this.setState({ view: viewName, page: 1 });
  };

  onPageChange = (page) => {
    this.setState({ page });
    this.scrollResultsIntoView();
  };

  onPageSizeChange = (pageSize) => {
    this.setState({ pageSize, page: 1 });
    this.scrollResultsIntoView();
  };

  scrollResultsIntoView = () => {
    const panel = document.getElementById("lux-search-results-panel");
    if (panel) {
      panel.scrollIntoView({ behavior: "smooth", block: "start" });
    }
  };

  renderSidebar = (counts, meta, isEmpty) => {
    const { searchText, isSearchLoading, hasSearched } = this.props;

    return (
      <aside className="lux-search-sidebar">
        <div className="lux-search-sidebar__card">
          <h3 className="lux-search-sidebar__title">Filters</h3>
          <div className="lux-search-filters lux-search-filters--stack" role="tablist" aria-label="Filter results">
            {[
              { id: SEARCH_VIEWS.ALL, label: "All results", count: counts.total, icon: "fe-grid" },
              { id: SEARCH_VIEWS.PROJECT, label: "Projects", count: counts.projects, icon: "fe-folder" },
              { id: SEARCH_VIEWS.TASK, label: "Deliverables", count: counts.tasks, icon: "fe-layers" },
            ].map((filter) => (
              <button
                key={filter.id}
                type="button"
                role="tab"
                aria-selected={this.state.view === filter.id}
                disabled={!hasSearched || isSearchLoading || isEmpty}
                className={`lux-search-filter lux-search-filter--stack${this.state.view === filter.id ? " is-active" : ""}`}
                onClick={() => this.onChangeView(filter.id)}
              >
                <span className="lux-search-filter__leading">
                  <i className={`fe ${filter.icon}`} aria-hidden="true" />
                  {filter.label}
                </span>
                <span className="lux-search-filter__count">{filter.count}</span>
              </button>
            ))}
          </div>
        </div>

        {hasSearched && searchText && meta && !isEmpty && (
          <div className="lux-search-sidebar__card">
            <h3 className="lux-search-sidebar__title">Search insights</h3>
            <ul className="lux-search-insights">
              <li>
                <span>Total matches</span>
                <strong>{meta.numberOfResults}</strong>
              </li>
              <li>
                <span>Query time</span>
                <strong>{meta.timeTakenInSecs}s</strong>
              </li>
              <li>
                <span>Ranking</span>
                <strong>By relevance</strong>
              </li>
            </ul>
          </div>
        )}

        {!hasSearched && !isSearchLoading && (
          <div className="lux-search-sidebar__card lux-search-sidebar__card--tips">
            <h3 className="lux-search-sidebar__title">Quick tips</h3>
            <ul className="lux-search-sidebar-tips">
              {SEARCH_TIPS.map((tip) => (
                <li key={tip.label}>
                  <i className={`fe ${tip.icon}`} aria-hidden="true" />
                  <div>
                    <strong>{tip.label}</strong>
                    <span>{tip.hint}</span>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        )}
      </aside>
    );
  };

  renderResultsPanel = () => {
    const { searchResults, searchText, isSearchLoading, hasSearched } = this.props;
    const { view, page, pageSize } = this.state;
    const counts = getSearchCounts(searchResults);
    const meta = searchResults && searchResults.metaData;
    const isEmpty =
      hasSearched &&
      !isSearchLoading &&
      searchResults &&
      meta &&
      meta.numberOfResults === 0;

    const ranked = buildRankedResults(searchResults, view, searchText);
    const pagination = paginateRankedResults(ranked, page, pageSize);

    return (
      <section id="lux-search-results-panel" className="lux-search-panel">
        <header className="lux-search-panel__header">
          <div>
            {hasSearched && searchText ? (
              <>
                <p className="lux-search-panel__kicker">Ranked results</p>
                <h3 className="lux-search-panel__title">
                  Matches for <strong>&ldquo;{searchText}&rdquo;</strong>
                </h3>
              </>
            ) : (
              <>
                <p className="lux-search-panel__kicker">Results</p>
                <h3 className="lux-search-panel__title">Start typing to search your workspace</h3>
              </>
            )}
          </div>
          {hasSearched && meta && !isEmpty && (
            <span className="lux-search-panel__badge">
              {pagination.total} ranked · sorted by relevance
            </span>
          )}
        </header>

        <div className="lux-search-panel__body">
          {isSearchLoading && <SearchSkeletonList />}

          {!isSearchLoading && hasSearched && searchResults && !isEmpty && (
            <>
              <div className="lux-search-results">
                {pagination.items.map((entry) => (
                  <SearchResultCard
                    key={`${entry.type}-${entry.item.id}-${entry.rank}`}
                    entry={entry}
                    query={searchText}
                  />
                ))}
              </div>
              <SearchPagination
                pagination={pagination}
                onPageChange={this.onPageChange}
                onPageSizeChange={this.onPageSizeChange}
              />
            </>
          )}

          {isEmpty && (
            <div className="lux-search-empty">
              <div className="lux-search-empty__icon" aria-hidden="true">
                <i className="fe fe-search" />
              </div>
              <h3 className="lux-search-empty__title">No results found</h3>
              <p className="lux-search-empty__text">
                We couldn&apos;t find anything matching &ldquo;{searchText}&rdquo;. Try different
                keywords, check spelling, or search by project or deliverable ID.
              </p>
            </div>
          )}

          {!hasSearched && !isSearchLoading && (
            <div className="lux-search-landing">
              <div className="lux-search-landing__icon" aria-hidden="true">
                <i className="fe fe-compass" />
              </div>
              <h3 className="lux-search-landing__title">Search your entire workspace</h3>
              <p className="lux-search-landing__text">
                Results are ranked by relevance — exact title and ID matches appear first, followed
                by summary matches and related items.
              </p>
            </div>
          )}
        </div>
      </section>
    );
  };

  render() {
    const { searchResults, isSearchLoading, hasSearched } = this.props;
    const counts = getSearchCounts(searchResults);
    const meta = searchResults && searchResults.metaData;
    const isEmpty =
      hasSearched &&
      !isSearchLoading &&
      searchResults &&
      meta &&
      meta.numberOfResults === 0;

    return (
      <div className="lux-search-layout">
        {this.renderSidebar(counts, meta, isEmpty)}
        {this.renderResultsPanel()}
      </div>
    );
  }
}

class SearchPage extends Component {
  searchInputRef = createRef();

  constructor(props) {
    super(props);
    this.state = {
      searchText: props.searchText || "",
      hasSearched: Boolean(props.searchText && props.searchResults),
    };
  }

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name);
    if (this.searchInputRef.current) {
      this.searchInputRef.current.focus();
    }
    if (this.props.searchText && !this.props.searchResults && !this.props.isSearchLoading) {
      this.runSearch(this.props.searchText);
    }
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.searchText !== this.props.searchText &&
      this.props.searchText !== this.state.searchText
    ) {
      this.setState({
        searchText: this.props.searchText || "",
        hasSearched: Boolean(this.props.searchText),
      });
    }
    if (prevProps.isSearchLoading && !this.props.isSearchLoading && this.props.searchResults) {
      this.setState({ hasSearched: true });
    }
  }

  onSearchTextChange = (event) => {
    this.setState({ searchText: event.target.value });
  };

  clearSearch = () => {
    this.setState({ searchText: "", hasSearched: false });
    this.props.onSearchInputChange("");
    if (this.searchInputRef.current) {
      this.searchInputRef.current.focus();
    }
  };

  runSearch = (term) => {
    const query = (term != null ? term : this.state.searchText || "").trim();
    if (!query) return;

    this.setState({ searchText: query, hasSearched: true });
    this.props.onSearchInputChange(query);
    this.props.getSearchResults(query);
  };

  handleSubmit = (event) => {
    event.preventDefault();
    this.runSearch();
  };

  handleKeyDown = (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      this.runSearch();
    }
  };

  render() {
    const { searchText } = this.state;
    const trimmed = (searchText || "").trim();

    return (
      <div className="lux-search-page" data-testid="page-project-search">
        <section className="lux-search-hero lux-search-hero--compact">
          <div className="lux-search-hero__glow" aria-hidden="true" />
          <div className="lux-search-hero__glow lux-search-hero__glow--left" aria-hidden="true" />
          <div className="lux-search-hero__inner lux-search-hero__inner--split">
            <div className="lux-search-hero__copy">
              <p className="lux-search-hero__kicker">
                <i className="fe fe-search" aria-hidden="true" /> Workspace search
              </p>
              <h2 className="lux-search-hero__title">Find anything, instantly</h2>
              <p className="lux-search-hero__subtitle">
                Search projects and deliverables — ranked by relevance across your workspace.
              </p>
            </div>

            <form className="lux-search-bar" onSubmit={this.handleSubmit} role="search">
              <span className="lux-search-bar__icon" aria-hidden="true">
                <i className="fe fe-search" />
              </span>
              <input
                ref={this.searchInputRef}
                type="search"
                className="lux-search-bar__input"
                placeholder="Search projects, deliverables, summaries, IDs..."
                value={searchText || ""}
                onChange={this.onSearchTextChange}
                onKeyDown={this.handleKeyDown}
                aria-label="Search workspace"
                autoComplete="off"
              />
              {trimmed && (
                <button
                  type="button"
                  className="lux-search-bar__clear"
                  onClick={this.clearSearch}
                  aria-label="Clear search"
                >
                  <i className="fe fe-x" aria-hidden="true" />
                </button>
              )}
              <button
                type="submit"
                className={`lux-search-bar__submit${this.props.isSearchLoading ? " is-loading" : ""}`}
                disabled={!trimmed || this.props.isSearchLoading}
              >
                {this.props.isSearchLoading ? (
                  <>
                    <i className="fe fe-loader" aria-hidden="true" />
                    Searching
                  </>
                ) : (
                  <>
                    <i className="fe fe-arrow-right" aria-hidden="true" />
                    Search
                  </>
                )}
              </button>
            </form>
          </div>
        </section>

        <SearchResults
          searchResults={this.props.searchResults}
          searchText={this.props.searchText}
          isSearchLoading={this.props.isSearchLoading}
          hasSearched={this.state.hasSearched}
        />
      </div>
    );
  }
}

const mapStateToProps = (state) => ({
  authentication: state.authentication,
  searchText: state.itemAdditional.searchText,
  searchResults: state.itemAdditional.searchResults,
  isSearchLoading: state.itemAdditional.isSearchLoading,
});

const mapDispatchToProps = (dispatch) => ({
  getSearchResults: (searchText) => dispatch(itemAdditionalActions.getSearchResults(searchText)),
  onSearchInputChange: (searchText) =>
    dispatch({ type: itemAdditionalConstants.SEARCH_INPUT_CHANGE, searchText }),
});

export default connect(mapStateToProps, mapDispatchToProps)(SearchPage);
