import envconfig from "env.config";
import { isUniversalApprovalInboxEnabled } from "config/universal-approval.config";

export function isApprovalAiSummaryEnabled() {
  return envconfig.APPROVAL_AI_SUMMARY_ENABLED === true && isUniversalApprovalInboxEnabled();
}

export function shouldUseApprovalAiSummaryApi() {
  return envconfig.USE_APPROVAL_AI_SUMMARY_API === true && isApprovalAiSummaryEnabled();
}
