/**
 * W18 — Vendor invoices FE service. Real API only (no mock fallback path).
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";

export const vendorInvoicesService = {
  listInvoices,
  getByRef,
  createInvoice,
  submitInvoice,
  approveInvoice,
  rejectInvoice,
  attachDocument,
  listVendorCosts,
  getProjectCosts,
};

const API_ERROR = { payload: null, source: "api-error" };

function resolveUserTeamId(explicit) {
  if (explicit != null && explicit !== "") {
    return explicit;
  }
  return commonUtils.getCurrentUserTeamId();
}

function resolveActorId() {
  return commonUtils.getCurrentUserId();
}

function financeListTeamQuery(extra) {
  const query = {};
  const explicitIds = extra && extra.userTeamIds;
  const currentIds = commonUtils.getCurrentUserTeamIds() || [];
  const currentId = commonUtils.getCurrentUserTeamId();
  if (Array.isArray(explicitIds) && explicitIds.length) {
    query.userTeamIds = explicitIds;
  } else if (currentIds.length > 0) {
    query.userTeamIds = currentIds;
  } else if (currentId != null && currentId !== "") {
    query.userTeamId = currentId;
  }
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (key === "userTeamId" || key === "userTeamIds") return;
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

async function listInvoices(extra = {}) {
  try {
    const response = await axiosUtils.getWithParam(
      urlConfig.VENDOR_INVOICES_API_PATH,
      financeListTeamQuery(extra)
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (Array.isArray(payload)) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    console.warn("[VendorInvoices] list unavailable.", e);
    return { ...API_ERROR, error: e };
  }
}

async function getByRef(vendorInvoiceRef, userTeamId) {
  try {
    const response = await axiosUtils.getWithParam(
      `${urlConfig.VENDOR_INVOICES_API_PATH}/by-ref/${encodeURIComponent(vendorInvoiceRef)}`,
      { userTeamId: resolveUserTeamId(userTeamId) }
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function createInvoice(body = {}) {
  try {
    const response = await axiosUtils.post(urlConfig.VENDOR_INVOICES_API_PATH, {
      ...body,
      userTeamId: body.userTeamId || resolveUserTeamId(),
      actorId: body.actorId || resolveActorId(),
    });
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function submitInvoice(vendorInvoiceRef, userTeamId) {
  return transition(vendorInvoiceRef, "submit", null, userTeamId);
}

async function approveInvoice(vendorInvoiceRef, userTeamId) {
  return transition(vendorInvoiceRef, "approve", null, userTeamId);
}

async function rejectInvoice(vendorInvoiceRef, reason, userTeamId) {
  return transition(vendorInvoiceRef, "reject", reason, userTeamId);
}

async function attachDocument(vendorInvoiceRef, documentRef, userTeamId) {
  try {
    const params = new URLSearchParams({
      userTeamId: String(resolveUserTeamId(userTeamId)),
      actorId: String(resolveActorId()),
      documentRef: String(documentRef),
    });
    const response = await axiosUtils.post(
      `${urlConfig.VENDOR_INVOICES_API_PATH}/${encodeURIComponent(vendorInvoiceRef)}/attach-document?${params}`,
      null
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

async function transition(vendorInvoiceRef, action, reason, userTeamId) {
  try {
    const params = new URLSearchParams({
      userTeamId: String(resolveUserTeamId(userTeamId)),
      actorId: String(resolveActorId()),
    });
    if (reason) {
      params.set("reason", reason);
    }
    const response = await axiosUtils.post(
      `${urlConfig.VENDOR_INVOICES_API_PATH}/${encodeURIComponent(vendorInvoiceRef)}/${action}?${params.toString()}`,
      null
    );
    const payload = response && response.payload != null ? response.payload : response;
    if (payload) {
      return { payload, source: "api" };
    }
    return { ...API_ERROR };
  } catch (e) {
    return { ...API_ERROR, error: e };
  }
}

