/** Pure util for FE unit tests — mirrors backend duplicate detection. */
export function isDuplicateVendorInvoice(existingList, vendorId, invoiceNumber) {
  if (!Array.isArray(existingList) || vendorId == null || !invoiceNumber) {
    return false;
  }
  const needle = String(invoiceNumber).trim().toLowerCase();
  return existingList.some(
    (row) =>
      row &&
      Number(row.vendorId) === Number(vendorId) &&
      String(row.invoiceNumber || "")
        .trim()
        .toLowerCase() === needle
  );
}
