import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { GOALS_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, { PerformanceActionButton, PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";
import GoalRegister from "views/performance/components/GoalRegister";
import { GoalCreateDrawer } from "views/performance/components/PerformanceCreateDrawers";

class GoalsPage extends Component {
  state = { loading: true, goals: [], cycles: [], kpiCards: [], dataSource: null, statusFilter: "ALL", createOpen: false, busy: false };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { statusFilter } = this.state;
    this.setState({ loading: true });
    try {
      const filters = statusFilter !== "ALL" ? { status: statusFilter } : {};
      const [overview, goalsResult] = await Promise.all([
        performanceManagementService.getOverview(filters),
        performanceManagementService.listGoals(filters),
      ]);
      this.setState({
        loading: false,
        dataSource: goalsResult.source,
        goals: goalsResult.payload || [],
        cycles: (overview.payload && overview.payload.cycles) || [],
        kpiCards: (overview.payload && overview.payload.kpiCards) || [],
      });
    } catch (error) {
      this.setState({ loading: false, goals: [] });
    }
  };

  handleCreate = async (payload) => {
    this.setState({ busy: true });
    try {
      await performanceManagementService.createGoal(payload);
      this.setState({ createOpen: false, busy: false });
      await this.loadData();
    } catch (error) {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Goals / OKRs" />;
    }

    const { loading, goals, cycles, kpiCards, dataSource, statusFilter, createOpen, busy } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={GOALS_PAGE_META}
        pageId="goals"
        shellTitle="Goals / OKRs"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><PerformanceActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Create goal
            </PerformanceActionButton>
          </>}
      >
        <PerformanceLuxPanel title="Goal register" meta="OKRs and individual outcomes" icon="fe fe-target" accent="amber" featured>
          <div className="lux-perf-filter-row">
            <label htmlFor="goal-status-filter">Status</label>
            <select
              id="goal-status-filter"
              className="lux-perf-filter"
              value={statusFilter}
              onChange={(e) => this.setState({ statusFilter: e.target.value }, this.loadData)}
            >
              <option value="ALL">All</option>
              <option value="on_track">On track</option>
              <option value="at_risk">At risk</option>
              <option value="behind">Behind</option>
              <option value="completed">Completed</option>
            </select>
          </div>
          <GoalRegister goals={goals} loading={loading} />
        </PerformanceLuxPanel>
        <GoalCreateDrawer open={createOpen} onClose={() => this.setState({ createOpen: false })} onCreate={this.handleCreate} busy={busy} cycles={cycles} />
      </PerformanceLuxPage>
    );
  }
}

export default GoalsPage;
