import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { formatBackNavLabel } from "../backNavigation.utils";

/**
 * Consistent “Back to &lt;page&gt;” link — small type, pill style.
 * @param {string} destinationLabel Page name (e.g. "Projects", "Deliverables").
 * @param {import('react-router-dom').Link} [component] Link or NavLink.
 */
export default function LuxBackNavLink({
  to,
  destinationLabel,
  component: RouterLink = Link,
  className,
  children,
  ...rest
}) {
  const text = children != null ? children : formatBackNavLabel(destinationLabel);

  return (
    <RouterLink
      to={to}
      className={classNames("lux-back-nav__link", className)}
      {...rest}
    >
      <i className="fe fe-arrow-left lux-back-nav__icon" aria-hidden="true" />
      <span className="lux-back-nav__text">{text}</span>
    </RouterLink>
  );
}
