import React, { Component } from "react";
import { connect } from "react-redux";
import CustomInput from "views/common/fragments/formfields/CustomInput";
import LuxCreatePanelShell from "views/common/create/LuxCreatePanelShell";
import LuxCreateSectionCard from "views/common/create/LuxCreateSectionCard";
import LuxCreateFooter from "views/common/create/LuxCreateFooter";
import { validationUtils } from "_helpers";
import { commonUtils } from "_helpers";
import ProjectTaskAccessRestrictionControlInput from "../fragments/ProjectTaskAccessRestrictionControlInput";
import dateUtils from "_helpers/date.utils";
import workItemUtils from "_helpers/workitem.utils";

/** Portal menus/calendars above overflow:hidden create sections / scroll workspace. */
const SELECT_MENU_PORTAL = { menuPortal: true, menuPortalZIndex: 10120 };
const DATE_PORTAL = { datePortal: true, datePopperPlacement: "bottom-start" };

class CreateTaskSidebar extends Component {
  componentDidMount() {}

  render() {
    const { editMode, duplicateMode, show, projectInfo } = this.props;
    const ready =
      show &&
      ((editMode && this.props.selectedTaskInfo) ||
        (duplicateMode && this.props.selectedTaskInfo) ||
        (!editMode && !duplicateMode));

    const title = editMode
      ? "Update deliverable"
      : duplicateMode
      ? "Duplicate deliverable"
      : "Create deliverable";

    const projectLabel =
      projectInfo &&
      ([projectInfo.code, projectInfo.name].filter(Boolean).join(" · ") ||
        projectInfo.name ||
        "Current project");

    const subtitle = editMode
      ? "Refine scope, schedule, ownership, and access for this deliverable."
      : duplicateMode
      ? "Clone this deliverable, then adjust schedule and ownership before saving."
      : projectLabel
      ? `Define scope and ownership under ${projectLabel}.`
      : "Define scope, schedule, ownership, and access for this deliverable.";

    return (
      <LuxCreatePanelShell
        show={show}
        onClose={this.props.closeActionHandler}
        panelId="createtasksidebar"
        className="lux-create-panel--deliverable lux-overlay-shell--create create_task_right_sidebar"
        kicker="Deliverables"
        title={title}
        subtitle={subtitle}
        size="lg"
      >
        {ready && (
          <CreateTaskSidebarSection
            projectId={this.props.projectId}
            handleSubmit={this.props.handleSubmit}
            editMode={this.props.editMode}
            duplicateMode={this.props.duplicateMode}
            selectedTaskInfo={this.props.selectedTaskInfo}
            currentUser={this.props.currentUser}
            fieldConfig={this.props.fieldConfig}
            createConfig={this.props.createConfig}
            allEmployees={this.props.allEmployees}
            employeeAppConfig={this.props.employeeAppConfig}
            allRoles={this.props.allRoles}
            userTeams={this.props.userTeams}
            projectInfo={this.props.projectInfo}
            isProcessing={this.props.creating || this.props.updating}
            permission={this.props.permission}
            allUserTeams={
              (this.props.editMode &&
              this.props.selectedTaskInfo.projectInfo
                .restrictedByUserTeamDetails &&
              this.props.selectedTaskInfo.projectInfo
                .restrictedByUserTeamDetails.length > 0
                ? this.props.selectedTaskInfo.projectInfo
                    .restrictedByUserTeamDetails
                : this.props.allUserTeams) ||
              (this.props.projectInfo &&
              this.props.projectInfo.restrictedByUserTeamDetails &&
              this.props.projectInfo.restrictedByUserTeamDetails.length > 0
                ? this.props.projectInfo.restrictedByUserTeamDetails
                : this.props.allUserTeams)
            }
            projectRestrictedByUserTeamIds={
              (this.props.editMode &&
                this.props.selectedTaskInfo.projectInfo
                  .restrictedByUserTeamIds) ||
              (this.props.projectInfo &&
                this.props.projectInfo.restrictedByUserTeamIds)
            }
            projectRestrictedByEmployeeDetails={
              (this.props.editMode &&
                this.props.selectedTaskInfo.projectInfo
                  .restrictedByEmployeeDetails) ||
              (this.props.projectInfo &&
                this.props.projectInfo.restrictedByEmployeeDetails)
            }
            projectRestrictedByEmployeeSkills={
              (this.props.editMode &&
                this.props.selectedTaskInfo.projectInfo
                  .restrictedByEmployeeSkills) ||
              (this.props.projectInfo &&
                this.props.projectInfo.restrictedByEmployeeSkills)
            }
          />
        )}
      </LuxCreatePanelShell>
    );
  }
}

class CreateTaskSidebarSection extends Component {
  constructor() {
    super();
    this.state = {
      formErrors: {},
      hasFormError: false,
    };
  }

  componentDidMount() {
    this.initializeRequest();
  }
  onResetFormError = () => {
    this.setState({
      hasFormError: false,
    });
  };

  initializeRequest = () => {
    let userTeamId = commonUtils.getCurrentUserTeamId();
    let taskRequest = this.props.editMode
      ? this.props.selectedTaskInfo
      : this.props.duplicateMode
      ? {
          ...this.props.selectedTaskInfo,
          id: null,
          createdBy: commonUtils.getCurrentUserId(),
          modifiedBy: null,
        }
      : {
          userTeamId: userTeamId,
          projectId: this.props.projectId,
        };
    this.setState({
      taskRequest: {
        ...taskRequest,
        estDurationHrs: dateUtils.minuteToHourDecimal(
          taskRequest.estDurationMins || 0
        ),
      },
    });
  };

  onFormError = (fieldName, hasError) => {
    this.setState((prevState) => ({
      formErrors: {
        ...prevState.formErrors,
        [fieldName]: hasError,
      },
    }));
  };

  onCategoryChage = (fieldName, value) => {
    this.setState((prevState) => ({
      taskRequest: {
        ...prevState.taskRequest,
        name: value,
        [fieldName]: value,
      },
    }));
  };
  onServiceLineChage = (fieldName, value) => {
    this.setState((prevState) => ({
      taskRequest: {
        ...prevState.taskRequest,
        taskCategory: null,
        [fieldName]: value,
      },
    }));
  };

  onEstimateChange = (fieldName, valueInHours) => {
    let valueInMins =
      parseInt(valueInHours) * 60 +
      Math.round((parseFloat(valueInHours) - parseInt(valueInHours)) * 100);
    this.setState(
      (prevState) => ({
        taskRequest: {
          ...prevState.taskRequest,
          estDurationMins: valueInMins,
        },
      }),
      () => {
        this.onChange(fieldName, valueInHours);
      }
    );
  };

  onChange = (fieldName, value) => {
    this.onResetFormError();

    this.setState(
      (prevState) => ({
        taskRequest: {
          ...prevState.taskRequest,
          [fieldName]: value,
        },
      }),
      () => {
        if (fieldName === "estStartTime" || fieldName === "estCompletionTime") {
          if (
            this.state.taskRequest.estStartTime &&
            this.state.taskRequest.estCompletionTime
          ) {
            let startDateMoment = dateUtils.convertDateStringToMoment(
              this.state.taskRequest.estStartTime
            );
            let endDateMoment = dateUtils.convertDateStringToMoment(
              this.state.taskRequest.estCompletionTime
            );
            if (
              dateUtils.compareTwoMoments(
                startDateMoment.startOf("day"),
                endDateMoment.endOf("day")
              ) === -1
            ) {
              this.setState((prevState) => ({
                taskRequest: {
                  ...prevState.taskRequest,
                  [fieldName === "estStartTime"
                    ? "estCompletionTime"
                    : fieldName]: undefined,
                },
              }));
            }
          }
        }
      }
    );
  };

  handleSubmit = (isCreateAnotherEnabled) => {
    let isValid = validationUtils.isValidRequest(
      this.getFieldConfig(),
      this.state.taskRequest,
      this.state.formErrors
    );
    if (isValid) {
      this.props.handleSubmit(
        this.state.taskRequest,
        this.props.editMode,
        isCreateAnotherEnabled,
        !this.props.editMode ? this.initializeRequest : null
      );
    } else {
      this.setState({
        hasFormError: true,
      });
    }
  };

  getFieldConfig = () => {
    return commonUtils.getAppConfigValue(
      this.props.createConfig,
      "enableServiceLineEstimate"
    ) === true
      ? this.props.fieldConfig.map((field) => {
          if (field.name === "serviceLine") {
            field.mandatory = true;
          }
          return field;
        })
      : this.props.fieldConfig;
  };

  isConfigEnabled = (key) =>
    commonUtils.getAppConfigValue(this.props.createConfig, key) === true;

  renderCategoryFields = () => {
    const enableServiceLineEstimate = this.isConfigEnabled(
      "enableServiceLineEstimate"
    );
    const enableCategorySelection = this.isConfigEnabled(
      "enableCategorySelection"
    );
    const enableServiceLineSelection = this.isConfigEnabled(
      "enableServiceLineSelection"
    );

    return (
      <>
        {enableServiceLineEstimate && (
          <div className="lux-deliverable-create__field">
            <CustomInput
              type="select"
              label="Service Line"
              name="serviceLine"
              fieldConfig={this.getFieldConfig()}
              mappingObject={this.state.taskRequest}
              onChange={this.onServiceLineChage}
              placeholder="Service Line..."
              options={
                this.props.createConfig &&
                this.props.projectInfo &&
                commonUtils.convertConfigListToSelectObject(
                  this.props.projectInfo.serviceLines
                )
              }
              onFormError={this.onFormError}
              {...SELECT_MENU_PORTAL}
            />
          </div>
        )}

        {enableCategorySelection && !enableServiceLineEstimate && (
          <div className="lux-deliverable-create__field">
            <CustomInput
              type="select"
              label="Category"
              name="taskCategory"
              fieldConfig={this.props.fieldConfig}
              mappingObject={this.state.taskRequest}
              onChange={this.onCategoryChage}
              placeholder="Delivery Category..."
              isAppConfig={true}
              createConfig={this.props.createConfig}
              configName={"taskCategory"}
              onFormError={this.onFormError}
              {...SELECT_MENU_PORTAL}
            />
          </div>
        )}

        {enableServiceLineSelection && !enableServiceLineEstimate && (
          <div className="lux-deliverable-create__field">
            <CustomInput
              type="select"
              label="Category"
              name="taskCategory"
              fieldConfig={this.props.fieldConfig}
              mappingObject={this.state.taskRequest}
              onChange={this.onCategoryChage}
              placeholder="Delivery Category..."
              options={
                this.props.createConfig &&
                this.props.projectInfo &&
                workItemUtils.getTaskCategories(
                  this.props.createConfig,
                  this.props.projectInfo.category
                )
              }
              onFormError={this.onFormError}
              {...SELECT_MENU_PORTAL}
            />
          </div>
        )}

        {enableServiceLineEstimate && (
          <div className="lux-deliverable-create__field">
            <CustomInput
              type="select"
              label="Category"
              name="taskCategory"
              fieldConfig={this.props.fieldConfig}
              mappingObject={this.state.taskRequest}
              onChange={this.onCategoryChage}
              placeholder="Delivery Category..."
              options={
                this.props.createConfig &&
                this.props.projectInfo &&
                workItemUtils.getTaskCategories(
                  this.props.createConfig,
                  this.state.taskRequest.serviceLine
                )
              }
              onFormError={this.onFormError}
              {...SELECT_MENU_PORTAL}
            />
          </div>
        )}
      </>
    );
  };

  renderProjectContext = () => {
    const { projectInfo } = this.props;
    if (!projectInfo) return null;

    const startLabel = dateUtils.convertDateFormat(projectInfo.estStartTime);
    const dueLabel = dateUtils.convertDateFormat(projectInfo.estCompletionTime);
    const windowLabel =
      startLabel || dueLabel
        ? `${startLabel || "—"} → ${dueLabel || "—"}`
        : null;

    return (
      <div className="lux-deliverable-create__context" aria-label="Project context">
        <div className="lux-deliverable-create__context-card">
          <span className="lux-deliverable-create__context-icon" aria-hidden="true">
            <i className="fe fe-briefcase" />
          </span>
          <div className="lux-deliverable-create__context-copy">
            <span className="lux-deliverable-create__context-label">Parent project</span>
            <strong className="lux-deliverable-create__context-value">
              {projectInfo.code ? `[${projectInfo.code}] ` : ""}
              {projectInfo.name || "—"}
            </strong>
          </div>
        </div>
        {windowLabel && (
          <div className="lux-deliverable-create__context-card">
            <span className="lux-deliverable-create__context-icon" aria-hidden="true">
              <i className="fe fe-calendar" />
            </span>
            <div className="lux-deliverable-create__context-copy">
              <span className="lux-deliverable-create__context-label">Project window</span>
              <strong className="lux-deliverable-create__context-value">{windowLabel}</strong>
            </div>
          </div>
        )}
        {(projectInfo.ownerDetails && projectInfo.ownerDetails.name) && (
          <div className="lux-deliverable-create__context-card">
            <span className="lux-deliverable-create__context-icon" aria-hidden="true">
              <i className="fe fe-user" />
            </span>
            <div className="lux-deliverable-create__context-copy">
              <span className="lux-deliverable-create__context-label">Project lead</span>
              <strong className="lux-deliverable-create__context-value">
                {projectInfo.ownerDetails.name}
              </strong>
            </div>
          </div>
        )}
      </div>
    );
  };

  render() {
    const projectInfo = this.props.projectInfo || {};

    return (
      <>
        {this.state.taskRequest && (
          <div className="lux-deliverable-create">
            <div className="lux-deliverable-create__scroll">
              {this.renderProjectContext()}

              <div className="lux-deliverable-create__workspace">
                <LuxCreateSectionCard
                  icon="fe fe-package"
                  title="Identity & scope"
                  hint="Name, classification, and what this deliverable covers"
                  className="lux-deliverable-create__section"
                >
                  <div className="lux-deliverable-create__fields">
                    {this.renderCategoryFields()}
                    <div className="lux-deliverable-create__field lux-deliverable-create__field--full">
                      <CustomInput
                        inputtype="text"
                        label="Deliverable Name"
                        name="name"
                        autoComplete="on"
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onChange}
                        onFormError={this.onFormError}
                        placeholder="e.g. Design system handoff"
                        datatype="alpnumspl"
                      />
                    </div>
                    <div className="lux-deliverable-create__field lux-deliverable-create__field--full">
                      <CustomInput
                        type="textarea"
                        label="Description"
                        name="description"
                        height={"96px"}
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onChange}
                        placeholder="Outcomes, constraints, and acceptance notes…"
                        onFormError={this.onFormError}
                        datatype="alpnumspl"
                      />
                    </div>
                  </div>
                </LuxCreateSectionCard>

                <LuxCreateSectionCard
                  icon="fe fe-calendar"
                  title="Schedule & ownership"
                  hint="Dates stay within the project window; assign lead and effort"
                  className="lux-deliverable-create__section"
                >
                  <div className="lux-deliverable-create__fields">
                    <div className="lux-deliverable-create__field">
                      <CustomInput
                        type="dateselect"
                        label="Estimated Start Date"
                        name="estStartTime"
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onChange}
                        time={false}
                        minDate={projectInfo.estStartTime}
                        maxDate={projectInfo.estCompletionTime}
                        onFormError={this.onFormError}
                        {...DATE_PORTAL}
                      />
                    </div>
                    <div className="lux-deliverable-create__field">
                      <CustomInput
                        type="dateselect"
                        label="Estimated End Date"
                        name="estCompletionTime"
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onChange}
                        time={false}
                        minDate={projectInfo.estStartTime}
                        maxDate={projectInfo.estCompletionTime}
                        onFormError={this.onFormError}
                        {...DATE_PORTAL}
                      />
                    </div>
                    <div className="lux-deliverable-create__field">
                      <CustomInput
                        type="select"
                        label="Delivery Lead"
                        name="taskOwner"
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onChange}
                        placeholder="Select lead…"
                        options={
                          this.props.allEmployees &&
                          commonUtils.convertObjectToSelectObject(
                            commonUtils.filterEmployeesByTeams(
                              this.props.allEmployees,
                              (this.props.allUserTeams || []).map(
                                (userTeam) => userTeam.id
                              )
                            )
                          )
                        }
                        onFormError={this.onFormError}
                        {...SELECT_MENU_PORTAL}
                      />
                    </div>
                    <div className="lux-deliverable-create__field">
                      <CustomInput
                        type="select"
                        label="Type"
                        name="taskType"
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onChange}
                        placeholder="Deliverable type…"
                        options={[
                          { value: "PRODUCTIVE", label: "Productive" },
                          { value: "REVIEW", label: "Review" },
                          { value: "ITERATION", label: "Iteration" },
                        ]}
                        onFormError={this.onFormError}
                        {...SELECT_MENU_PORTAL}
                      />
                    </div>
                    <div className="lux-deliverable-create__field">
                      <CustomInput
                        type="text"
                        readOnly={
                          this.props.editMode &&
                          !this.props.permission
                            .enableDeliverableEstimateHourEditable
                        }
                        label="Estimated Duration (Hrs)"
                        name="estDurationHrs"
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onEstimateChange}
                        placeholder="0"
                        datatype="hourdecimal"
                        onFormError={this.onFormError}
                      />
                    </div>
                    <div className="lux-deliverable-create__field">
                      <CustomInput
                        type="select"
                        label="Priority"
                        name="priority"
                        fieldConfig={this.props.fieldConfig}
                        mappingObject={this.state.taskRequest}
                        onChange={this.onChange}
                        placeholder="Priority…"
                        options={[
                          { value: "URGENT", label: "Urgent" },
                          { value: "HIGH", label: "High" },
                          { value: "MEDIUM", label: "Medium" },
                          { value: "LOW", label: "Low" },
                        ]}
                        onFormError={this.onFormError}
                        {...SELECT_MENU_PORTAL}
                      />
                    </div>
                  </div>
                </LuxCreateSectionCard>

                <LuxCreateSectionCard
                  icon="fe fe-shield"
                  title="Access & restrictions"
                  hint="Limit which teams, skills, or people can work on this deliverable"
                  className="lux-deliverable-create__section lux-deliverable-create__section--access"
                >
                  <ProjectTaskAccessRestrictionControlInput
                    userTeams={this.props.allUserTeams}
                    employeeAppConfig={this.props.employeeAppConfig}
                    allEmployees={this.props.allEmployees}
                    fieldConfig={this.props.fieldConfig}
                    mappingObject={this.state.taskRequest}
                    onChange={this.onChange}
                    onFormError={this.onFormError}
                    teamClasssName={"col-12"}
                    inputClassName={"col-12"}
                    permission={this.props.permission}
                    projectRestrictedByUserTeamIds={
                      this.props.projectRestrictedByUserTeamIds
                    }
                    projectRestrictedByEmployeeDetails={
                      this.props.projectRestrictedByEmployeeDetails
                    }
                    projectRestrictedByEmployeeSkills={
                      this.props.projectRestrictedByEmployeeSkills
                    }
                  />
                </LuxCreateSectionCard>
              </div>
            </div>

            <LuxCreateFooter
              handleSubmit={this.handleSubmit}
              editMode={this.props.editMode}
              duplicateMode={this.props.duplicateMode}
              initializeRequest={this.initializeRequest}
              isProcessing={this.props.isProcessing}
              hasFormError={this.state.hasFormError}
              onResetFormError={this.onResetFormError}
              createButtonLabel={
                this.props.editMode
                  ? "Save changes"
                  : this.props.duplicateMode
                    ? "Duplicate deliverable"
                    : "Create deliverable"
              }
            />
          </div>
        )}
      </>
    );
  }
}
const mapStateToProps = (state) => ({
  currentUser: state.authentication.user,
  allEmployees: state.employees.allEmployees,
  fieldConfig: state.tasks.fieldConfig,
  createConfig: state.tasks.createConfig,
  employeeAppConfig: state.employees.createConfig,
  allUserTeams: state.appconfig.allTeams,
  creating: state.tasks.taskCreating,
  updating: state.tasks.taskUpdating,
  selectedTaskInfo: state.tasks.selectedTaskInfo,
});

const mapDispatchToProps = (dispatch) => ({});

export default connect(mapStateToProps, mapDispatchToProps)(CreateTaskSidebar);
