import React from "react";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import { getLuxInlineAlertProps } from "_helpers/apiError.utils";

export default function FinanceLoadAlert({ error, fallback, onDismiss }) {
  if (!error) {
    return null;
  }
  const alertProps = getLuxInlineAlertProps(error, fallback);
  return <LuxInlineAlert {...alertProps} onDismiss={onDismiss} />;
}
