import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import { buildPayrollReadinessChartRows } from "config/payroll.utils";
import { PayrollStatusBadge } from "views/payroll/components/PayrollLuxShared";

export default function PayrollReadinessPanel({ runs }) {
  const chartRows = buildPayrollReadinessChartRows(runs);

  if (chartRows.length === 0) {
    return <p className="lux-payroll-readiness__empty">No readiness scores available yet. Create and calculate a run to see scores.</p>;
  }

  return (
    <ul className="lux-payroll-readiness__bars">
      {chartRows.map((row) => (
        <li key={row.id} className="lux-payroll-readiness__row">
          <div className="lux-payroll-readiness__label">
            <div className="lux-payroll-readiness__label-main">
              <Link to={`/payroll/runs/${row.id}`} className="lux-payroll-readiness__link">{row.label}</Link>
              <PayrollStatusBadge status={row.status} />
            </div>
            <strong className={`lux-payroll-readiness-pill ${row.score >= 95 ? "is-high" : row.score >= 80 ? "is-mid" : "is-low"}`}>
              {row.score}%
            </strong>
          </div>
          <div className="lux-payroll-readiness__track" aria-hidden="true">
            <span
              className={classNames({
                "is-low": row.score < 80,
                "is-mid": row.score >= 80 && row.score < 95,
                "is-high": row.score >= 95,
              })}
              style={{ width: `${row.score}%` }}
            />
          </div>
          <span className="lux-payroll-readiness__meta">
            {row.blockers > 0 ? `${row.blockers} blocker(s) remaining` : "No blockers"}
          </span>
        </li>
      ))}
    </ul>
  );
}
