import React, { PureComponent } from "react";
import classNames from "classnames/bind";
import CountUp from "react-countup";
import Skeleton from "react-loading-skeleton";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import {
  readSummaryExpanded,
  writeSummaryExpanded,
  getSummaryToggleLabel,
} from "_helpers/summaryExpandedStorage";

const STORAGE_KEY = "famstack-workitems-summary-expanded";

const QUICK_FILTERS = [
  { value: "ALL", label: "All" },
  { value: "ONGOING", label: "On going" },
  { value: "COMPLETED", label: "Completed" },
  { value: "MYASSIGNED", label: "My assigned" },
  { value: "CREATEDBYME", label: "Created by me" },
];

class WorkItemPageSummary extends PureComponent {
  constructor(props) {
    super(props);
    this.state = { expanded: readSummaryExpanded(STORAGE_KEY) };
  }

  toggleExpanded = () => {
    this.setState(
      (prev) => ({ expanded: !prev.expanded }),
      () => writeSummaryExpanded(STORAGE_KEY, this.state.expanded)
    );
  };

  getShowFilter = () => {
    const options = this.props.filterOptions;
    return (options && options.SHOW && options.SHOW.selected) || "ONGOING";
  };

  quickFilter = (value) => {
    if (this.props.onQuickFilter) {
      this.props.onQuickFilter(value);
    }
  };

  buildContextLine = (stat, visibleCount, filterOptions) => {
    const parts = [];
    parts.push(
      `${stat.total} work items · ${stat.active} in delivery · ${stat.completed} done`
    );
    if (visibleCount !== stat.total) {
      parts.push(`${visibleCount} shown`);
    }
    if (filterOptions && filterOptions.filterText) {
      parts.push(`matching “${filterOptions.filterText}”`);
    }
    return parts.join(" · ");
  };

  renderFilterChips = (showFilter, compact) => (
    <div
      className={classNames("lux-bid-summary__filters", {
        "lux-bid-summary__filters--compact": compact,
      })}
      role="group"
      aria-label="Filter work items"
    >
      {QUICK_FILTERS.map((option) => (
        <button
          key={option.value}
          type="button"
          className={classNames("lux-bid-summary__filter-chip", {
            "is-active": showFilter === option.value,
          })}
          onClick={() => this.quickFilter(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );

  renderKpiStrip = (stat, isLoading) => (
    <div className="lux-bid-summary__kpi-strip" role="list" aria-label="Work item metrics">
      {stat.kpis.map((kpi) => (
        <article
          key={kpi.key}
          className={classNames("lux-bid-summary__kpi", kpi.tone && `is-${kpi.tone}`)}
          role="listitem"
        >
          <div className="lux-bid-summary__kpi-top">
            <span className="lux-bid-summary__kpi-label">{kpi.label}</span>
            <span className="lux-bid-summary__kpi-icon" aria-hidden="true">
              <i className={kpi.icon} />
            </span>
          </div>
          <strong className="lux-bid-summary__kpi-value">
            {isLoading ? (
              <Skeleton width={40} />
            ) : (
              <>
                <CountUp end={Number(kpi.value) || 0} duration={0.65} />
                {kpi.suffix || ""}
              </>
            )}
          </strong>
          {kpi.hint && <span className="lux-bid-summary__kpi-hint">{kpi.hint}</span>}
        </article>
      ))}
    </div>
  );

  renderHighlights = (stat) => (
    <div
      className="lux-po-summary__highlights lux-workitem-summary__highlights"
      role="list"
      aria-label="Work item highlights"
    >
      {stat.highlights.map((item) => (
        <article
          key={item.key}
          className={classNames("lux-po-summary__highlight", item.tone && `is-${item.tone}`)}
          role="listitem"
        >
          <span className="lux-po-summary__highlight-icon" aria-hidden="true">
            <i className={item.icon} />
          </span>
          <div className="lux-po-summary__highlight-copy">
            <span className="lux-po-summary__highlight-label">{item.label}</span>
            <strong>
              <CountUp end={item.value} duration={0.65} />
              {item.suffix || ""}
            </strong>
            <span className="lux-po-summary__highlight-hint">{item.hint}</span>
          </div>
        </article>
      ))}
    </div>
  );

  renderInsightCard = (insight) => (
    <article key={insight.key} className="lux-bid-summary__insight lux-po-summary__insight">
      <header>
        <i className={insight.icon} aria-hidden="true" />
        <div>
          <strong>{insight.title}</strong>
          <span>{insight.subtitle}</span>
        </div>
      </header>
      {!insight.mix || !insight.mix.length ? (
        <div className="lux-bid-summary__bar lux-bid-summary__bar--empty">{insight.emptyLabel}</div>
      ) : (
        <>
          <div className="lux-bid-summary__bar" aria-hidden="true">
            {insight.mix.map((seg) => (
              <span
                key={seg.key}
                className={classNames("lux-bid-summary__bar-segment", `is-${seg.tone}`)}
                style={{ flexGrow: Math.max(seg.count, 0.15) }}
                title={`${seg.label}: ${seg.count}`}
              />
            ))}
          </div>
          <ul className="lux-bid-summary__legend">
            {insight.mix.map((seg) => (
              <li key={seg.key}>
                <span className={classNames("lux-bid-summary__legend-dot", `is-${seg.tone}`)} />
                <span>{seg.label}</span>
                <strong>{seg.count}</strong>
                <em>{seg.pct}%</em>
              </li>
            ))}
          </ul>
        </>
      )}
    </article>
  );

  renderStageFlow = (stat) => (
    <div className="lux-bid-summary__stage-flow lux-workitem-summary__stage-flow" aria-label="Work item lifecycle">
      {stat.funnel.map((stage, index, arr) => (
        <React.Fragment key={stage.key}>
          <div className={classNames("lux-bid-summary__stage-node", `is-${stage.tone}`)}>
            <span className="lux-bid-summary__stage-node-label">{stage.label}</span>
            <strong>
              <CountUp end={stage.count} duration={0.65} />
            </strong>
          </div>
          {index < arr.length - 1 && (
            <span className="lux-bid-summary__stage-arrow" aria-hidden="true">
              <i className="fe fe-arrow-right" />
            </span>
          )}
        </React.Fragment>
      ))}
    </div>
  );

  render() {
    const { stat, isLoading, visibleCount, filterOptions } = this.props;
    const { expanded } = this.state;
    const showFilter = this.getShowFilter();

    return (
      <section
        className={classNames("lux-bid-summary lux-po-summary lux-workitem-summary", {
          "is-collapsed": !expanded,
        })}
        aria-label="Work items overview"
      >
        <div className="lux-bid-summary__header-bar">
          <div className="lux-bid-summary__header-main">
            <LuxSummaryEyebrow variant="work-items" className="lux-bid-summary__eyebrow">
              Work items intelligence
            </LuxSummaryEyebrow>
            {!expanded ? (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--compact">
                <CountUp end={stat.active} duration={0.65} />{" "}
                <span>
                  in delivery · {stat.completed} done · {stat.total} total
                </span>
              </h2>
            ) : (
              <h2 className="lux-bid-summary__title lux-bid-summary__title--bar">Deliverable work items</h2>
            )}
          </div>
          <button
            type="button"
            className="lux-bid-summary__toggle"
            onClick={this.toggleExpanded}
            aria-expanded={expanded}
            aria-controls="lux-workitem-summary-body"
            title={expanded ? "Collapse summary" : "Expand insights"}
          >
            <span>{getSummaryToggleLabel(expanded)}</span>
            <i className={classNames("fe", expanded ? "fe-chevron-up" : "fe-chevron-down")} aria-hidden="true" />
          </button>
        </div>

        {!expanded && (
          <div className="lux-bid-summary__collapsed-strip">
            <p className="lux-bid-summary__collapsed-line">
              {this.buildContextLine(stat, visibleCount, filterOptions)}
            </p>
            {this.renderFilterChips(showFilter, true)}
          </div>
        )}

        <div id="lux-workitem-summary-body" className="lux-bid-summary__body" aria-hidden={!expanded}>
          <div className="lux-bid-summary__toolbar">
            <p className="lux-bid-summary__subtitle">
              {this.buildContextLine(stat, visibleCount, filterOptions)}
              {" · "}
              Hours, status mix, and priority load for this deliverable.
            </p>
            {this.renderFilterChips(showFilter, false)}
          </div>

          <div className="lux-bid-summary__metrics-row lux-po-summary__metrics-row lux-workitem-summary__metrics-row">
            {this.renderKpiStrip(stat, isLoading)}
          </div>

          {this.renderHighlights(stat)}

          {this.renderStageFlow(stat)}

          <div className="lux-bid-summary__insights lux-po-summary__insights lux-workitem-summary__insights">
            {stat.insights.map(this.renderInsightCard)}
          </div>
        </div>
      </section>
    );
  }
}

export default WorkItemPageSummary;
