import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import LuxSummaryEyebrow from "views/common/fragments/LuxSummaryEyebrow";
import LuxFeedbackRecipientRow from "./LuxFeedbackRecipientRow";
import {
  countRecipientStatuses,
  getCampaignStatusSummary,
  getFeedbackTypeLabel,
  isFeedbackCampaignExpired,
} from "./feedback.utils";

const POPOVER_ID = "lux-feedback-campaign-popover-dialog";

function DetailCell({ label, value, wide }) {
  return (
    <div className={classNames("lux-feedback-popover__detail", { "is-wide": wide })}>
      <span className="lux-feedback-popover__detail-label">{label}</span>
      <span className="lux-feedback-popover__detail-value">{value}</span>
    </div>
  );
}

export default class LuxFeedbackCampaignPopover extends Component {
  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    this.lockBodyScroll();
  }

  componentDidUpdate(prevProps) {
    if (prevProps.show !== this.props.show) {
      if (this.props.show) {
        document.addEventListener("keydown", this.onKeyDown);
        this.lockBodyScroll();
      } else {
        document.removeEventListener("keydown", this.onKeyDown);
        this.unlockBodyScroll();
      }
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
    this.unlockBodyScroll();
  }

  lockBodyScroll = () => {
    if (this._scrollLocked) return;
    this._prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    this._scrollLocked = true;
  };

  unlockBodyScroll = () => {
    if (!this._scrollLocked) return;
    document.body.style.overflow = this._prevOverflow || "";
    this._scrollLocked = false;
  };

  onKeyDown = (event) => {
    if (event.key === "Escape") {
      this.props.onClose();
    }
  };

  renderKpis = (counts) => {
    const rate = counts.total > 0 ? Math.round((counts.responded / counts.total) * 100) : 0;
    const items = [
      { label: "Recipients", value: counts.total, icon: "fe-users" },
      { label: "Responded", value: counts.responded, icon: "fe-inbox" },
      { label: "Awaiting", value: counts.awaiting, icon: "fe-clock" },
      { label: "Response rate", value: `${rate}%`, icon: "fe-activity" },
    ];
    return (
      <div className="lux-feedback-popover__kpis" role="list" aria-label="Campaign metrics">
        {items.map((kpi) => (
          <div key={kpi.label} className="lux-feedback-popover__kpi" role="listitem">
            <i className={`fe ${kpi.icon}`} aria-hidden="true" />
            <span className="lux-feedback-popover__kpi-label">{kpi.label}</span>
            <strong className="lux-feedback-popover__kpi-value">{kpi.value}</strong>
          </div>
        ))}
      </div>
    );
  };

  render() {
    const { show, onClose, item, permission, editMode, editEnabled } = this.props;
    if (!show || !item) return null;

    const counts = countRecipientStatuses(item.feedbackRequestInfos);
    const status = getCampaignStatusSummary(item);
    const expired = item.recurring !== true && isFeedbackCampaignExpired(item);
    const canEdit =
      editMode === false &&
      editEnabled === true &&
      permission.editEnabled === true &&
      counts.total > 0 &&
      counts.draft === counts.total;

    const content = (
      <>
        <button
          type="button"
          className="lux-feedback-popover__backdrop"
          aria-label="Close campaign details"
          onClick={onClose}
        />
        <div
          id={POPOVER_ID}
          className="lux-feedback-popover"
          role="dialog"
          aria-modal="true"
          aria-labelledby="lux-feedback-popover-title"
        >
          <header className="lux-feedback-popover__head">
            <div className="lux-feedback-popover__head-main">
              <LuxSummaryEyebrow variant="feedback" className="lux-feedback-popover__eyebrow">
                Feedback campaign
              </LuxSummaryEyebrow>
              <div className="lux-feedback-popover__title-row">
                <h2 id="lux-feedback-popover-title">{item.name || "Untitled campaign"}</h2>
                <span className={`lux-feedback-popover__status is-${status.tone}`}>
                  <i className={`fe ${status.icon}`} aria-hidden="true" />
                  {status.label}
                </span>
              </div>
              <p className="lux-feedback-popover__subtitle">
                #{item.id}
                {item.itemName ? ` · ${item.itemName}` : ""}
                {item.type ? ` · ${getFeedbackTypeLabel(item.type)}` : ""}
                {status.hint ? ` — ${status.hint}` : ""}
              </p>
              {item.description && (
                <p className="lux-feedback-popover__description">{item.description}</p>
              )}
            </div>
            <button
              type="button"
              className="lux-feedback-popover__close"
              onClick={onClose}
              aria-label="Close"
            >
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          {this.renderKpis(counts)}

          <div className="lux-feedback-popover__body">
            <section className="lux-feedback-popover__section">
              <h3 className="lux-feedback-popover__section-title">
                <i className="fe fe-file-text" aria-hidden="true" /> Campaign details
              </h3>
              <div className="lux-feedback-popover__detail-grid">
                <DetailCell
                  label="Requested by"
                  value={
                    (item.requestedEmployeeInfo && item.requestedEmployeeInfo.name) || "—"
                  }
                />
                <DetailCell
                  label="Created"
                  value={
                    item.createdDate
                      ? dateUtils.convertDateTimeFormat(item.createdDate)
                      : "—"
                  }
                />
                <DetailCell label="Sub type" value={item.subType || "—"} />
                <DetailCell label="Service lines" value={item.serviceLines || "—"} />
                <DetailCell
                  label="Expiry"
                  value={
                    item.expiryDate
                      ? dateUtils.convertDateTimeFormat(item.expiryDate)
                      : "—"
                  }
                />
                <DetailCell
                  label="Template"
                  value={
                    <a
                      target="_blank"
                      rel="noopener noreferrer"
                      href={`/document/feedback/${item.id}`}
                    >
                      {(item.feedbackTemplateInfo && item.feedbackTemplateInfo.name) ||
                        item.templateId ||
                        "—"}
                    </a>
                  }
                />
                <DetailCell
                  label="Email subject"
                  value={item.emailSubject || "Default"}
                  wide
                />
                {item.recurring && (
                  <>
                    <DetailCell
                      label="Schedule"
                      value={
                        (item.scheduleData && item.scheduleData.cronString) ||
                        item.cronString ||
                        "—"
                      }
                    />
                    <DetailCell
                      label="Schedule ends"
                      value={
                        item.scheduleData && item.scheduleData.endDate
                          ? dateUtils.convertDateTimeFormat(item.scheduleData.endDate)
                          : "—"
                      }
                    />
                    <DetailCell
                      label="Create as draft"
                      value={
                        item.scheduleData && item.scheduleData.draft === false ? "No" : "Yes"
                      }
                    />
                  </>
                )}
              </div>
            </section>

            <section className="lux-feedback-popover__section">
              <h3 className="lux-feedback-popover__section-title">
                <i className="fe fe-users" aria-hidden="true" /> Recipients
                <span className="lux-feedback-popover__section-count">{counts.total}</span>
              </h3>
              <div className="lux-feedback-popover__recipients">
                {item.feedbackRequestInfos &&
                  item.feedbackRequestInfos.map((recipient) => (
                    <LuxFeedbackRecipientRow
                      key={recipient.id}
                      permission={permission}
                      feedbackId={item.id}
                      isRecurring={item.recurring}
                      feedbackItem={item}
                      isFeedbackExpired={expired}
                      item={recipient}
                      removeFeedbackRequest={this.props.removeFeedbackRequest}
                      remindFeedbackRequest={this.props.remindFeedbackRequest}
                      updateFeedbackRequestStatus={this.props.updateFeedbackRequestStatus}
                    />
                  ))}
                {(!item.feedbackRequestInfos || item.feedbackRequestInfos.length === 0) && (
                  <p className="lux-feedback-recipients__empty">
                    No recipients yet. Edit the campaign to add email addresses.
                  </p>
                )}
              </div>
            </section>
          </div>

          <footer className="lux-feedback-popover__foot">
            {permission.activateEnabled === true && (
              <button
                type="button"
                className="lux-planner-btn lux-planner-btn--ghost"
                onClick={() => this.props.onToggleActive(!item.active)}
              >
                <i className={`fe ${item.active ? "fe-pause" : "fe-play"}`} aria-hidden="true" />
                {item.active ? "Deactivate" : "Activate"}
              </button>
            )}
            {canEdit && (
              <button
                type="button"
                className="lux-planner-btn lux-planner-btn--ghost"
                onClick={() => {
                  this.props.onEdit(item);
                  onClose();
                }}
              >
                <i className="fe fe-edit-2" aria-hidden="true" />
                Edit campaign
              </button>
            )}
            <a
              className="lux-planner-btn lux-planner-btn--ghost"
              target="_blank"
              rel="noopener noreferrer"
              href={`/document/feedback/${item.id}`}
            >
              <i className="fe fe-external-link" aria-hidden="true" />
              Open template
            </a>
            <button
              type="button"
              className="lux-planner-btn lux-planner-btn--primary"
              onClick={onClose}
            >
              Done
            </button>
          </footer>
        </div>
      </>
    );

    if (typeof document !== "undefined") {
      return createPortal(content, document.body);
    }
    return content;
  }
}
