import React, { Component } from "react";
import classNames from "classnames/bind";

const HERO_COLOR_CLASSES = [
  "",
  "colorred",
  "colororange",
  "colorblue",
  "colorlightgreen1",
  "colorgreen",
];

export default class LuxFeedbackStarRating extends Component {
  state = { hover: 0 };

  getDisplayValue = () => {
    const selected = Number(this.props.value) || 0;
    return this.state.hover || selected;
  };

  onMouseEnter = (stars) => {
    if (!this.props.readonly) {
      this.setState({ hover: stars });
    }
  };

  onMouseLeave = () => {
    if (!this.props.readonly) {
      this.setState({ hover: 0 });
    }
  };

  onClick = (stars) => {
    if (!this.props.readonly && this.props.onChange) {
      this.props.onChange(stars);
    }
  };

  getStarClass = (number) => {
    const display = this.getDisplayValue();
    const isHero = this.props.variant === "hero";
    const lit = number <= display;

    if (!lit) return "";

    if (isHero) {
      return HERO_COLOR_CLASSES[display] || "";
    }
    return "is-lit";
  };

  render() {
    const { readonly, variant = "compact", hint, showHint = true } = this.props;
    const display = this.getDisplayValue();
    const numbers = [1, 2, 3, 4, 5];

    return (
      <div className={classNames("lux-fb-stars", `lux-fb-stars--${variant}`)}>
        <div
          className="lux-fb-stars__row"
          role="group"
          aria-label={this.props.ariaLabel || "Star rating"}
        >
          {numbers.map((number) => (
            <button
              key={number}
              type="button"
              className={classNames("lux-fb-stars__btn", this.getStarClass(number), {
                "is-selected": number <= display,
              })}
              disabled={readonly}
              onMouseEnter={() => this.onMouseEnter(number)}
              onMouseLeave={this.onMouseLeave}
              onClick={() => this.onClick(number)}
              aria-label={`${number} star${number > 1 ? "s" : ""}`}
              aria-pressed={number <= (Number(this.props.value) || 0)}
            >
              <i className="fa fa-star lux-fb-stars__icon" aria-hidden="true" />
            </button>
          ))}
        </div>
        {showHint && (
          <span className="lux-fb-stars__hint">
            {hint || (readonly ? "Your rating" : display ? `${display} of 5 selected` : "Click to rate")}
          </span>
        )}
      </div>
    );
  }
}
