import React from "react";
import classNames from "classnames/bind";
import { IntegrationActionButton } from "views/integrations/components/IntegrationsLuxShared";

export function IntegrationSnapshotStrip({ badgeIcon, badgeLabel, metrics, loading }) {
  if (loading) {
    return <div className="lux-integ-snapshot lux-integ-snapshot--loading" aria-busy="true" />;
  }
  return (
    <section className="lux-integ-snapshot">
      <div className="lux-integ-snapshot__badge">
        <i className={badgeIcon || "fe fe-activity"} aria-hidden="true" />
        <span>{badgeLabel || "Observability"}</span>
      </div>
      <div className="lux-integ-snapshot__metrics">
        {(metrics || []).map((metric) => (
          <article key={metric.id} className={classNames("lux-integ-snapshot__metric", metric.tone && `is-${metric.tone}`)}>
            <span>{metric.label}</span>
            <strong>{metric.value}</strong>
          </article>
        ))}
      </div>
    </section>
  );
}

export function SyncJobsRegister({ jobs = [], loading, onRetry, busyId }) {
  if (loading) {
    return <div className="lux-integ-register__skeleton" aria-busy="true" />;
  }
  if (!jobs.length) {
    return (
      <div className="lux-integ-register__empty lux-integ-register__empty--inline">
        <i className="fe fe-repeat" aria-hidden="true" />
        <strong>No sync jobs recorded</strong>
        <p>Jobs appear here after connectors run import or export cycles.</p>
      </div>
    );
  }
  return (
    <div className="lux-integ-register-wrap">
      <table className="lux-integ-register">
        <thead>
          <tr>
            <th>Connector</th>
            <th>Type</th>
            <th>Status</th>
            <th>Records</th>
            <th>Errors</th>
            <th>Retries</th>
            <th />
          </tr>
        </thead>
        <tbody>
          {jobs.map((job) => (
            <tr key={job.id} className={classNames({ "is-failed": job.status === "failed" })}>
              <td>
                <div className="lux-integ-register__title">{job.connectorName}</div>
                <div className="lux-integ-register__meta">{job.startedAt ? new Date(job.startedAt).toLocaleString() : "—"}</div>
              </td>
              <td>
                <span className="lux-integ-register__pill">{job.jobType}</span>
              </td>
              <td>
                <span className={classNames("lux-integ-status", `is-${job.status}`)}>{job.status}</span>
              </td>
              <td>{job.recordsProcessed}</td>
              <td>{job.errorCount}</td>
              <td>{job.retryCount}</td>
              <td>
                {job.status === "failed" && onRetry ? (
                  <IntegrationActionButton variant="ghost" disabled={busyId === job.id} onClick={() => onRetry(job.id)}>
                    Retry
                  </IntegrationActionButton>
                ) : null}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export function MappingRegister({ mappings = [], loading }) {
  if (loading) {
    return <div className="lux-integ-register__skeleton" aria-busy="true" />;
  }
  if (!mappings.length) {
    return (
      <div className="lux-integ-register__empty lux-integ-register__empty--inline">
        <i className="fe fe-shuffle" aria-hidden="true" />
        <strong>No field maps yet</strong>
        <p>Canonical mappings will appear once connectors are validated.</p>
      </div>
    );
  }
  return (
    <div className="lux-integ-mapping-grid">
      {mappings.map((row) => (
        <article
          key={row.id}
          className={classNames("lux-integ-mapping-card", row.coveragePct < 85 && "is-warning")}
        >
          <header>
            <div>
              <strong>{row.connectorName}</strong>
              <small>{row.sourceObject} → {row.targetObject}</small>
            </div>
            <span className={classNames("lux-integ-status", `is-${row.status}`)}>{row.status}</span>
          </header>
          <div className="lux-integ-mapping-card__coverage">
            <div className="lux-integ-mapping-card__coverage-head">
              <span>Coverage</span>
              <strong>{row.coveragePct}%</strong>
            </div>
            <div className="lux-integ-mapping-card__coverage-bar" aria-hidden="true">
              <span style={{ width: `${row.coveragePct}%` }} />
            </div>
          </div>
          <div className="lux-integ-mapping-card__metrics">
            <span>
              Fields <strong>{row.fieldCount}</strong>
            </span>
            <span>
              Validated <strong>{row.lastValidatedAt ? new Date(row.lastValidatedAt).toLocaleDateString() : "—"}</strong>
            </span>
          </div>
        </article>
      ))}
    </div>
  );
}

export function IntegrationLevelFilter({ value, onChange }) {
  const levels = [
    { id: "ALL", label: "All" },
    { id: "info", label: "Info" },
    { id: "warn", label: "Warning" },
    { id: "error", label: "Error" },
  ];
  return (
    <div className="lux-integ-filter-bar" role="tablist" aria-label="Log level filter">
      {levels.map((level) => (
        <button
          key={level.id}
          type="button"
          role="tab"
          aria-selected={value === level.id}
          className={classNames("lux-integ-filter-bar__chip", { "is-active": value === level.id })}
          onClick={() => onChange(level.id)}
        >
          {level.label}
        </button>
      ))}
    </div>
  );
}

export function IntegrationLogsRegister({ logs = [], loading }) {
  if (loading) {
    return <div className="lux-integ-register__skeleton" aria-busy="true" />;
  }
  if (!logs.length) {
    return (
      <div className="lux-integ-register__empty lux-integ-register__empty--inline">
        <i className="fe fe-file-text" aria-hidden="true" />
        <strong>No log events</strong>
        <p>Connector telemetry will stream here during sync windows.</p>
      </div>
    );
  }
  return (
    <div className="lux-integ-logs">
      {logs.map((row) => (
        <article key={row.id} className={classNames("lux-integ-log-card", `is-${row.level}`)}>
          <header>
            <span
              className={classNames(
                "lux-integ-chip",
                `is-${row.level === "error" ? "danger" : row.level === "warn" ? "warning" : "success"}`
              )}
            >
              {row.level}
            </span>
            <strong>{row.connectorName}</strong>
            <small>{row.createdAt ? new Date(row.createdAt).toLocaleString() : "—"}</small>
          </header>
          <p>{row.message}</p>
          {row.correlationId ? <code className="lux-integ-log-card__corr">{row.correlationId}</code> : null}
        </article>
      ))}
    </div>
  );
}

export function SyncHealthSnapshot({ summary, loading }) {
  const s = summary || {};
  return (
    <IntegrationSnapshotStrip
      loading={loading}
      badgeIcon="fe fe-activity"
      badgeLabel="Sync observability"
      metrics={[
        { id: "latency", label: "Avg latency", value: `${s.avgLatencyMs != null ? s.avgLatencyMs : 0}ms`, tone: "blue" },
        { id: "records", label: "Records synced", value: s.recordsSynced != null ? s.recordsSynced : 0, tone: "green" },
        { id: "degraded", label: "Degraded", value: s.degraded != null ? s.degraded : 0, tone: "amber" },
        { id: "failed", label: "Failed", value: s.failed != null ? s.failed : 0, tone: "rose" },
      ]}
    />
  );
}

export function buildMappingSnapshotMetrics(mappings) {
  const rows = mappings || [];
  const avgCoverage = rows.length
    ? Math.round(rows.reduce((sum, row) => sum + (Number(row.coveragePct) || 0), 0) / rows.length)
    : 0;
  const fields = rows.reduce((sum, row) => sum + (Number(row.fieldCount) || 0), 0);
  return [
    { id: "maps", label: "Field maps", value: rows.length, tone: "indigo" },
    { id: "coverage", label: "Avg coverage", value: `${avgCoverage}%`, tone: "violet" },
    { id: "fields", label: "Mapped fields", value: fields, tone: "green" },
    { id: "validated", label: "Validated", value: rows.filter((row) => row.status === "validated").length, tone: "blue" },
  ];
}

export function buildJobsSnapshotMetrics(jobs) {
  const rows = jobs || [];
  const failed = rows.filter((job) => job.status === "failed").length;
  const running = rows.filter((job) => job.status === "running").length;
  const records = rows.reduce((sum, job) => sum + (Number(job.recordsProcessed) || 0), 0);
  return [
    { id: "total", label: "Total jobs", value: rows.length, tone: "amber" },
    { id: "running", label: "Running", value: running, tone: "blue" },
    { id: "failed", label: "Failed", value: failed, tone: "rose" },
    { id: "records", label: "Records", value: records, tone: "green" },
  ];
}

export function buildLogsSnapshotMetrics(logs) {
  const rows = logs || [];
  return [
    { id: "events", label: "Events", value: rows.length, tone: "blue" },
    { id: "info", label: "Info", value: rows.filter((row) => row.level === "info").length, tone: "green" },
    { id: "warn", label: "Warnings", value: rows.filter((row) => row.level === "warn").length, tone: "amber" },
    { id: "error", label: "Errors", value: rows.filter((row) => row.level === "error").length, tone: "rose" },
  ];
}
