import React from "react";

export default function AttendancePayrollLockBanner({ policy, intelligence }) {
  if (!policy) return null;
  const lockDay = policy.payrollLockDayOfMonth;
  const payrollRisk = (intelligence && intelligence.payrollRiskCount) || 0;
  const now = new Date();
  const daysUntilLock = lockDay ? Math.max(0, lockDay - now.getDate()) : null;

  return (
    <div className="lux-att-lock-banner" role="status">
      <i className="fe fe-lock" aria-hidden="true" />
      <div>
        <strong>Payroll lock alignment</strong>
        <p>
          Regularizations for prior months are blocked after day {lockDay} of the current month.
          {daysUntilLock != null && daysUntilLock <= 5
            ? ` Lock applies in ${daysUntilLock} day(s).`
            : ""}
          {payrollRisk > 0 ? ` ${payrollRisk} request(s) flagged with payroll lock.` : ""}
        </p>
      </div>
    </div>
  );
}
