import React from "react";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import {
  isFieldVisible,
  resolveMaskedFieldValue,
} from "config/employee360-field.utils";
import {
  buildPayrollTabStats,
  resolvePayrollSummary,
} from "config/employee360Tab.utils";
import { getEmployeeDisplayName } from "config/employee360.utils";

function PayrollField({ label, value, fieldKey, maskingPolicy, hint }) {
  if (fieldKey && !isFieldVisible(fieldKey, maskingPolicy)) {
    return null;
  }
  const displayValue =
    fieldKey && maskingPolicy
      ? resolveMaskedFieldValue(fieldKey, value, maskingPolicy)
      : value || "—";

  return (
    <div className="lux-employee-360__field">
      <span className="lux-employee-360__field-label">{label}</span>
      <strong className="lux-employee-360__field-value">{displayValue}</strong>
      {hint && <span className="lux-employee-360__field-hint">{hint}</span>}
    </div>
  );
}

function formatCurrency(value) {
  if (value == null || Number.isNaN(Number(value))) {
    return "—";
  }
  return new Intl.NumberFormat("en-US", {
    style: "currency",
    currency: "USD",
    maximumFractionDigits: value % 1 === 0 ? 0 : 2,
  }).format(Number(value));
}

function PaycheckRegister({ paychecks, maskingPolicy }) {
  if (!isFieldVisible("payrollLines", maskingPolicy)) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-employee-360__embed-empty"
        icon="fe fe-lock"
        title="Paycheck history restricted"
        description="Your role cannot view detailed payroll lines for this employee."
      />
    );
  }

  if (!Array.isArray(paychecks) || paychecks.length === 0) {
    return (
      <LuxRegisterEmptyState
        className="lux-register-empty--compact lux-employee-360__embed-empty"
        icon="fe fe-dollar-sign"
        title="No paycheck history"
        description="Payroll runs will appear here when the aggregate payroll API connects."
      />
    );
  }

  return (
    <div className="lux-employee-360__register-wrap">
      <table className="lux-employee-360__register">
        <thead>
          <tr>
            <th>Period</th>
            <th>Gross</th>
            <th>Net</th>
            <th>Status</th>
            <th>Paid on</th>
          </tr>
        </thead>
        <tbody>
          {paychecks.map((row) => (
            <tr key={row.id || row.period}>
              <td>{row.period || "—"}</td>
              <td>{resolveMaskedFieldValue("payrollLines", formatCurrency(row.gross), maskingPolicy)}</td>
              <td>{resolveMaskedFieldValue("paycheckAmount", formatCurrency(row.net), maskingPolicy)}</td>
              <td>
                <span
                  className={classNames("lux-employee-360__badge", {
                    "is-success": String(row.status).toLowerCase() === "paid",
                    "is-warning": String(row.status).toLowerCase().includes("pending"),
                  })}
                >
                  {row.status || "—"}
                </span>
              </td>
              <td>{row.paidOn || "—"}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default function Employee360PayrollTab({ employee, summary, maskingPolicy }) {
  if (!employee) {
    return null;
  }

  const payroll = resolvePayrollSummary(summary);
  const stats = buildPayrollTabStats(summary, maskingPolicy);
  const displayName = getEmployeeDisplayName(employee);
  const paychecks = (payroll && payroll.paychecks) || [];

  return (
    <ProjectDetailsTabShell
      icon="fe fe-dollar-sign"
      eyebrow="Compensation"
      title="Payroll & finance"
      subtitle={`Pay group, compensation, and paycheck history for ${displayName}. Sensitive fields follow your persona masking policy.`}
      stats={stats}
      className="lux-employee-360__embed lux-employee-360__embed--payroll"
    >
      <div className="lux-employee-360__embed-toolbar">
        <strong className="lux-employee-360__embed-period">
          Pay group · {(summary && summary.payrollGroup) || "—"}
        </strong>
        <Link to="/payroll/dashboard" className="lux-employee-360__embed-link">
          Open payroll dashboard
          <i className="fe fe-external-link" aria-hidden="true" />
        </Link>
      </div>

      <section className="lux-employee-360__panel">
        <h4 className="lux-employee-360__panel-title">Compensation profile</h4>
        <div className="lux-employee-360__field-grid">
          <PayrollField
            label="Payroll group"
            value={summary && summary.payrollGroup}
            fieldKey="payrollGroup"
            maskingPolicy={maskingPolicy}
          />
          <PayrollField
            label="Pay frequency"
            value={payroll && payroll.payFrequency}
            maskingPolicy={maskingPolicy}
          />
          <PayrollField
            label="Base salary"
            value={payroll && payroll.baseSalary != null ? formatCurrency(payroll.baseSalary) : null}
            fieldKey="salary"
            maskingPolicy={maskingPolicy}
          />
          <PayrollField
            label="Cost center"
            value={payroll && payroll.costCenter}
            fieldKey="financeMargin"
            maskingPolicy={maskingPolicy}
          />
          <PayrollField
            label="Bank account"
            value={payroll && payroll.bankAccountLast4 ? `****${payroll.bankAccountLast4}` : null}
            fieldKey="bankAccount"
            maskingPolicy={maskingPolicy}
            hint="Last four digits"
          />
          <PayrollField
            label="Tax ID"
            value={payroll && payroll.taxIdLast4 ? `***-**-${payroll.taxIdLast4}` : null}
            fieldKey="taxId"
            maskingPolicy={maskingPolicy}
            hint="Masked identifier"
          />
        </div>
      </section>

      <section className="lux-employee-360__panel">
        <h4 className="lux-employee-360__panel-title">Paycheck register</h4>
        <p className="lux-employee-360__panel-desc">
          Recent payroll runs with gross and net amounts from the payroll register.
        </p>
        <PaycheckRegister paychecks={paychecks} maskingPolicy={maskingPolicy} />
      </section>
    </ProjectDetailsTabShell>
  );
}
