import { appConfigConstants } from "_constants";
import { store } from "_helpers";

export function closeLuxShellPanels() {
  store.dispatch({ type: appConfigConstants.CLOSE_LUX_SHELL_PANELS });
}

export function closeLuxSettingsPanel() {
  store.dispatch({ type: appConfigConstants.CLOSE_SETTINGS_WINDOW });
}

export function openLuxThemePanel() {
  store.dispatch({ type: appConfigConstants.OPEN_LUX_THEME_PANEL });
}

export function toggleLuxSettingsPanel() {
  store.dispatch({ type: appConfigConstants.SHOW_SETTINGS_WINDOW });
}

export function toggleLuxThemePanel() {
  store.dispatch({ type: appConfigConstants.TOGGLE_LUX_THEME_PANEL });
}
