import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isProjectGovernanceEnabled, RISK_SEVERITIES, RISK_STATUSES } from "config/project-governance.config";
import {
  buildProjectOptionsFromRisks,
  buildRiskHeatmap,
  buildRiskInsights,
  buildRiskMetrics,
  filterRisks,
  RISK_SEVERITY_FILTER_OPTIONS,
  RISK_STATUS_FILTER_OPTIONS,
  validateRiskPayload,
} from "config/project-governance.utils";
import { projectGovernanceService } from "_services/projectGovernance.service";
import { GOVERNANCE_PAGE_IDS, getGovernanceQuickLinks } from "config/project-governance-nav.config";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import GovernanceLuxPage, {
  GovernanceLuxFilters,
  GovernanceLuxPanel,
} from "views/project/components/ProjectGovernanceLuxShared";
import RiskDrawer from "views/project/components/RiskDrawer";
import RiskHeatmapPanel from "views/project/components/RiskHeatmapPanel";
import RiskRegister from "views/project/components/RiskRegister";

class ProjectRisksPage extends Component {
  state = {
    risks: [],
    loading: true,
    loadError: null,
    dataSource: null,
    query: "",
    severityFilter: "ALL",
    statusFilter: "ALL",
    projectFilter: "ALL",
    drawerOpen: false,
    selectedRisk: null,
    creating: false,
    createError: null,
    draft: {
      title: "",
      projectId: "",
      severity: RISK_SEVERITIES.MEDIUM,
      ownerName: "",
      mitigationPlan: "",
      dueDate: "",
    },
  };

  componentDidMount() {
    this.props.pageHeaderNameChangeHandler("Risks");
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const result = await projectGovernanceService.listRisks();
      this.setState({
        risks: result.payload || [],
        loading: false,
        dataSource: result.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load risks.", risks: [] });
    }
  };

  openDrawer = (risk) => {
    this.setState({ drawerOpen: true, selectedRisk: risk });
  };

  closeDrawer = () => {
    this.setState({ drawerOpen: false, selectedRisk: null });
  };

  handleSaveRisk = async (riskId, payload) => {
    await projectGovernanceService.updateRisk(riskId, payload);
    await this.loadData();
  };

  handleEscalateRisk = async (riskId, payload) => {
    await projectGovernanceService.escalateRisk(riskId, payload);
    await this.loadData();
  };

  handleCreateRisk = async (e) => {
    e.preventDefault();
    const { draft, risks } = this.state;
    const project = buildProjectOptionsFromRisks(risks).find((row) => row.id === draft.projectId);
    const payload = {
      ...draft,
      projectName: project && project.label,
      projectCode: project && project.code,
      status: RISK_STATUSES.OPEN,
    };
    const validation = validateRiskPayload(payload);
    if (!validation.valid) {
      this.setState({ createError: validation.reason });
      return;
    }

    this.setState({ creating: true, createError: null });
    try {
      await projectGovernanceService.createRisk(payload);
      await this.loadData();
      this.setState({
        creating: false,
        draft: {
          title: "",
          projectId: "",
          severity: RISK_SEVERITIES.MEDIUM,
          ownerName: "",
          mitigationPlan: "",
          dueDate: "",
        },
      });
    } catch (err) {
      this.setState({
        creating: false,
        createError: (err && err.message) || "Unable to create risk.",
      });
    }
  };

  render() {
    if (!isProjectGovernanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Project risks" />;
    }

    const {
      risks,
      loading,
      loadError,
      dataSource,
      query,
      severityFilter,
      statusFilter,
      projectFilter,
      drawerOpen,
      selectedRisk,
      creating,
      createError,
      draft,
    } = this.state;

    const filtered = filterRisks(risks, {
      query,
      severity: severityFilter,
      status: statusFilter,
      projectId: projectFilter === "ALL" ? undefined : projectFilter,
    });
    const metrics = buildRiskMetrics(risks);
    const insights = buildRiskInsights(metrics, risks);
    const projectOptions = buildProjectOptionsFromRisks(risks);
    const heatmap = buildRiskHeatmap(risks, { projectId: projectFilter });

    return (
      <GovernanceLuxPage
        pageId={GOVERNANCE_PAGE_IDS.RISKS}
        dataSource={dataSource}
        demoLabel="Demo risk data"
        loading={loading}
        insights={insights}
        quickLinks={getGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.RISKS)}
        kpiCards={[
          { id: "open", label: "Open risks", value: metrics.open, tone: "blue", icon: "fe fe-alert-triangle" },
          { id: "high", label: "High / critical", value: metrics.highOrCritical, tone: "rose", icon: "fe fe-alert-octagon" },
          { id: "escalated", label: "Escalated", value: metrics.escalated, tone: "amber", icon: "fe fe-trending-up" },
          { id: "overdue", label: "Past due", value: metrics.overdue, tone: "violet", icon: "fe fe-clock" },
        ]}
        heroActions={
          <ResourcesActionButton to="/project/governance" icon="fe fe-shield" variant="ghost">
            Governance hub
          </ResourcesActionButton>
        }
      >
        <GovernanceLuxPanel
          title="Risk heatmap"
          meta={`${heatmap.rows.length} projects · open exposure`}
          icon="fe fe-grid"
          accent="amber"
        >
          <RiskHeatmapPanel heatmap={heatmap} loading={loading} />
        </GovernanceLuxPanel>

        <GovernanceLuxPanel
          title="Risk register"
          meta={`${filtered.length} visible · ${metrics.open} open`}
          icon="fe fe-alert-triangle"
          accent="rose"
        >
          <GovernanceLuxFilters>
            <label className="lux-gov-filters__search">
              <i className="fe fe-search" aria-hidden="true" />
              <input
                type="search"
                placeholder="Search risk, project, owner, or mitigation"
                value={query}
                onChange={(e) => this.setState({ query: e.target.value })}
              />
            </label>
            <select
              className="lux-gov-filters__select"
              value={projectFilter}
              onChange={(e) => this.setState({ projectFilter: e.target.value })}
            >
              {projectOptions.map((option) => (
                <option key={option.id} value={option.id}>
                  {option.label}
                </option>
              ))}
            </select>
            <div className="lux-gov-filters__chips" role="tablist" aria-label="Risk severity">
              {RISK_SEVERITY_FILTER_OPTIONS.map((option) => (
                <button
                  key={option.id}
                  type="button"
                  role="tab"
                  aria-selected={severityFilter === option.id}
                  className={classNames("lux-gov-filters__chip", { "is-active": severityFilter === option.id })}
                  onClick={() => this.setState({ severityFilter: option.id })}
                >
                  {option.label}
                </button>
              ))}
            </div>
            <div className="lux-gov-filters__chips" role="tablist" aria-label="Risk status">
              {RISK_STATUS_FILTER_OPTIONS.map((option) => (
                <button
                  key={option.id}
                  type="button"
                  role="tab"
                  aria-selected={statusFilter === option.id}
                  className={classNames("lux-gov-filters__chip", { "is-active": statusFilter === option.id })}
                  onClick={() => this.setState({ statusFilter: option.id })}
                >
                  {option.label}
                </button>
              ))}
            </div>
          </GovernanceLuxFilters>

          <form className="lux-gov-risk-form" onSubmit={this.handleCreateRisk}>
            <p className="lux-gov-risk-form__title">Log new risk</p>
            <div className="lux-gov-risk-form__fields">
              <label>
                Title
                <input
                  value={draft.title}
                  onChange={(e) => this.setState({ draft: { ...draft, title: e.target.value } })}
                  placeholder="Describe the delivery risk"
                />
              </label>
              <label>
                Project
                <select
                  value={draft.projectId}
                  onChange={(e) => this.setState({ draft: { ...draft, projectId: e.target.value } })}
                >
                  <option value="">Select project</option>
                  {projectOptions
                    .filter((row) => row.id !== "ALL")
                    .map((option) => (
                      <option key={option.id} value={option.id}>
                        {option.label}
                      </option>
                    ))}
                </select>
              </label>
              <label>
                Severity
                <select
                  value={draft.severity}
                  onChange={(e) => this.setState({ draft: { ...draft, severity: e.target.value } })}
                >
                  {Object.values(RISK_SEVERITIES).map((value) => (
                    <option key={value} value={value}>
                      {value}
                    </option>
                  ))}
                </select>
              </label>
              <label>
                Owner
                <input
                  value={draft.ownerName}
                  onChange={(e) => this.setState({ draft: { ...draft, ownerName: e.target.value } })}
                />
              </label>
              <label>
                Due
                <input
                  type="date"
                  value={draft.dueDate}
                  onChange={(e) => this.setState({ draft: { ...draft, dueDate: e.target.value } })}
                />
              </label>
              <button type="submit" className="lux-gov-risk-form__submit" disabled={creating}>
                {creating ? "Logging…" : "Add risk"}
              </button>
            </div>
            <label className="lux-gov-risk-form__wide">
              Mitigation plan
              <textarea
                rows={2}
                value={draft.mitigationPlan}
                onChange={(e) => this.setState({ draft: { ...draft, mitigationPlan: e.target.value } })}
              />
            </label>
            {createError ? <p className="lux-gov-risk-form__error">{createError}</p> : null}
          </form>

          {loadError ? (
            <LuxRegisterEmptyState title="Unable to load risks" copy={loadError} onRetry={this.loadData} />
          ) : null}

          {!loadError && !loading && filtered.length === 0 ? (
            <LuxRegisterEmptyState
              title="No risks match"
              copy="Adjust filters or log a new delivery risk for this program."
            />
          ) : null}

          <RiskRegister rows={filtered} loading={loading} onSelect={this.openDrawer} />
        </GovernanceLuxPanel>

        <RiskDrawer
          open={drawerOpen}
          risk={selectedRisk}
          onClose={this.closeDrawer}
          onSave={this.handleSaveRisk}
          onEscalate={this.handleEscalateRisk}
        />
      </GovernanceLuxPage>
    );
  }
}

export default ProjectRisksPage;
