import React, { useEffect } from "react";
import { useReportPageDataSource } from "views/common/PageChromeContext";
import classNames from "classnames/bind";
import { Link } from "react-router-dom";
import { AdminInsightStrip } from "views/admin/components/AdminLuxShared";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import { GovernanceKpiStrip } from "views/project/components/ProjectGovernanceLuxShared";

export default function WorkGraphLuxPage({
  pageMeta,
  dataSource,
  demoLabel = "Demo graph data",
  heroActions,
  kpiCards,
  loading,
  onRefresh,
  refreshLoading,
  pageHeaderNameChangeHandler,
  shellTitle,
  children,
}) {
  useReportPageDataSource(dataSource);
  const meta = pageMeta || {
    tone: "violet",
    icon: "fe fe-git-merge",
    eyebrow: "Workspace",
    titleLead: "Work",
    titleAccent: "graph",
    lede: "Connected operational truth across modules.",
  };

  useEffect(() => {
    if (pageHeaderNameChangeHandler && shellTitle) {
      pageHeaderNameChangeHandler(shellTitle);
    }
  }, [pageHeaderNameChangeHandler, shellTitle]);

  return (
    <div className={classNames("lux-register-page", "lux-wg-module", "lux-wg-lux", meta.tone && `is-${meta.tone}`)}>
      <div className="lux-wg-lux__ambient" aria-hidden="true">
        <span className="lux-wg-lux__orb lux-wg-lux__orb--a" />
        <span className="lux-wg-lux__orb lux-wg-lux__orb--b" />
        <span className="lux-wg-lux__orb lux-wg-lux__orb--c" />
      </div>
      <LuxModuleIntro
        meta={meta}
        actions={heroActions || undefined}
        onRefresh={onRefresh}
        refreshLoading={refreshLoading != null ? refreshLoading : loading}
      />
      <div className="lux-register-page__body">
        {kpiCards && kpiCards.length ? (
          <GovernanceKpiStrip cards={kpiCards} loading={loading} className="lux-wg-lux__kpi-strip" />
        ) : null}

        <div className="lux-wg-lux__content">{children}</div>
      </div>
    </div>
  );
}

export function WorkGraphActionButton({ to, onClick, icon, variant = "ghost", children, disabled, className }) {
  const classes = classNames("lux-onb-action", "lux-wg-action", `lux-onb-action--${variant}`, className);
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes}>
        {content}
      </Link>
    );
  }
  return (
    <button type="button" className={classes} onClick={onClick} disabled={disabled}>
      {content}
    </button>
  );
}

export function WorkGraphLuxPanel({ title, meta, icon, accent, featured, actions, children, className }) {
  return (
    <section
      className={classNames(
        "lux-hrms-dash__panel",
        "lux-wg-lux__panel",
        accent && `is-${accent}`,
        featured && "lux-wg-lux__panel--featured",
        className
      )}
    >
      <header className="lux-hrms-dash__panel-head lux-wg-lux__panel-head">
        <div className="lux-wg-lux__panel-head-main">
          {icon ? <i className={icon} aria-hidden="true" /> : null}
          <div>
            <h2 className="lux-hrms-dash__panel-title">{title}</h2>
            {meta ? <p className="lux-hrms-dash__panel-sub">{meta}</p> : null}
          </div>
        </div>
        {actions ? <div className="lux-hrms-dash__panel-actions lux-wg-lux__panel-actions">{actions}</div> : null}
      </header>
      <div className="lux-hrms-dash__panel-body lux-wg-lux__panel-body">{children}</div>
    </section>
  );
}

export function WorkGraphInsightPanel({ insights, loading }) {
  return <AdminInsightStrip insights={insights} loading={loading} className="lux-wg-lux__insights" />;
}
