import {
  toAreaChart,
  toDonutChart,
  toGroupedBarChart,
} from "views/hrms/components/dashboard/employeeDashboard.utils";

const STATUS_COLORS = {
  NEW: "#0ea5e9",
  ASSIGNED: "#6366f1",
  INPROGRESS: "#f59e0b",
  IN_PROGRESS: "#f59e0b",
  "IN PROGRESS": "#f59e0b",
  WON: "#10b981",
  LOST: "#94a3b8",
  CANCELLED: "#f43f5e",
  REJECTED: "#64748b",
  CLOSED: "#475569",
};

const AGE_COLORS = {
  FRESH: "#10b981",
  ACTIVE: "#f59e0b",
  STALE: "#f43f5e",
};

const PALETTE = [
  "#5b5ff4",
  "#8b5cf6",
  "#0ea5e9",
  "#f59e0b",
  "#14b8a6",
  "#10b981",
  "#64748b",
];

const LUX_CHART_FONT = {
  fontFamily: "Inter, system-ui, sans-serif",
  fontSize: "11px",
  fontWeight: 600,
};

function applyLuxChartBase(options) {
  return {
    ...options,
    chart: {
      ...(options.chart || {}),
      fontFamily: LUX_CHART_FONT.fontFamily,
      toolbar: { show: false },
    },
    grid: {
      borderColor: "rgba(226,232,240,0.85)",
      strokeDashArray: 4,
      ...(options.grid || {}),
    },
  };
}

function withDonutCenter(chart, centerLabel, centerValue) {
  chart.options.plotOptions = {
    pie: {
      donut: {
        size: "76%",
        labels: {
          show: true,
          name: { show: true, fontSize: "11px", fontWeight: 600, color: "#64748b" },
          value: {
            show: true,
            fontSize: "15px",
            fontWeight: 800,
            color: "#0f172a",
          },
          total: {
            show: true,
            label: centerLabel,
            fontSize: "11px",
            fontWeight: 700,
            color: "#64748b",
            formatter: () => String(centerValue),
          },
        },
      },
    },
  };
  chart.options.legend = {
    position: "bottom",
    fontSize: "10px",
    fontWeight: 600,
    offsetY: 0,
    itemMargin: { horizontal: 6, vertical: 2 },
    labels: { colors: "#475569" },
  };
  chart.options.chart = {
    ...chart.options.chart,
    sparkline: { enabled: false },
    parentHeightOffset: 0,
    fontFamily: LUX_CHART_FONT.fontFamily,
  };
  chart.options.stroke = { width: 2, colors: ["#fff"] };
  return chart;
}

export function buildBidStatusDonutChart(stat) {
  if (!stat.statusMix || !stat.statusMix.length) return null;
  const labels = stat.statusMix.map((s) => s.label);
  const series = stat.statusMix.map((s) => s.count);
  const colors = stat.statusMix.map((s) => STATUS_COLORS[s.key] || "#94a3b8");
  const chart = toDonutChart(labels, series, colors);
  return withDonutCenter(chart, "Active bids", stat.active);
}

export function buildBidOutcomeDonutChart(stat) {
  const { outcomes } = stat;
  const segments = [
    { label: "Open pipeline", value: outcomes.open, color: "#6366f1" },
    { label: "Won", value: outcomes.won, color: "#10b981" },
    { label: "Lost", value: outcomes.lost, color: "#94a3b8" },
    { label: "Other closed", value: outcomes.otherClosed, color: "#f43f5e" },
  ].filter((s) => s.value > 0);

  if (!segments.length) return null;

  const chart = toDonutChart(
    segments.map((s) => s.label),
    segments.map((s) => s.value),
    segments.map((s) => s.color)
  );
  const total = segments.reduce((a, s) => a + s.value, 0);
  return withDonutCenter(chart, "Outcomes", total);
}

export function buildBidPipelineAgeDonutChart(stat) {
  if (!stat.pipelineAgeMix || !stat.pipelineAgeMix.length) return null;
  const labels = stat.pipelineAgeMix.map((s) => s.label);
  const series = stat.pipelineAgeMix.map((s) => s.count);
  const colors = stat.pipelineAgeMix.map((s) => AGE_COLORS[s.key] || "#94a3b8");
  const total = series.reduce((a, b) => a + b, 0);
  const chart = toDonutChart(labels, series, colors);
  return withDonutCenter(chart, "Open pipeline", total);
}

export function buildBidSfLinkDonutChart(stat) {
  const linked = stat.salesforceCount || 0;
  const manual = Math.max((stat.active || 0) - linked, 0);
  if (!linked && !manual) return null;
  const chart = toDonutChart(
    ["Salesforce", "Not linked"],
    [linked, manual],
    ["#0ea5e9", "#94a3b8"]
  );
  return withDonutCenter(chart, "CRM link", stat.active);
}

export function buildBidStudyTypeBarChart(stat) {
  if (!stat.studyTypeMix || !stat.studyTypeMix.length) return null;

  const categories = stat.studyTypeMix.map((s) => s.label);
  const data = stat.studyTypeMix.map((s) => s.count);
  const chart = toGroupedBarChart(categories, [{ name: "Bids", data }], PALETTE);

  chart.options = applyLuxChartBase({
    ...chart.options,
    plotOptions: {
      bar: {
        horizontal: false,
        borderRadius: 8,
        columnWidth: "48%",
        distributed: true,
      },
    },
    xaxis: {
      categories,
      labels: {
        style: { fontSize: "10px", fontWeight: 600, colors: "#64748b" },
        rotate: -20,
        trim: true,
      },
    },
    yaxis: {
      labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      tickAmount: 4,
    },
    legend: { show: false },
    colors: stat.studyTypeMix.map((_, i) => PALETTE[i % PALETTE.length]),
    grid: { padding: { top: -8, right: 4, bottom: -4, left: 4 } },
  });

  return chart;
}

export function buildBidStudyDisciplineBarChart(stat) {
  if (!stat.studyDisciplineMix || !stat.studyDisciplineMix.length) return null;
  return buildBidHorizontalBar(stat.studyDisciplineMix, "Tagged bids");
}

export function buildBidKindBarChart(stat) {
  if (!stat.kindMix || !stat.kindMix.length) return null;
  return buildBidHorizontalBar(stat.kindMix, "Bids");
}

export function buildBidCountriesBarChart(stat) {
  if (!stat.countryMix || !stat.countryMix.length) return null;
  return buildBidHorizontalBar(stat.countryMix, "Bids");
}

export function buildBidOwnerBarChart(stat) {
  if (!stat.ownerMix || !stat.ownerMix.length) return null;
  return buildBidHorizontalBar(stat.ownerMix, "Owned bids");
}

function buildBidHorizontalBar(mix, seriesName) {
  const categories = mix.map((s) => s.label);
  const data = mix.map((s) => s.count);

  return {
    series: [{ name: seriesName, data }],
    options: applyLuxChartBase({
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 8,
          barHeight: "62%",
          distributed: true,
          dataLabels: { position: "center" },
        },
      },
      colors: categories.map((_, i) => PALETTE[i % PALETTE.length]),
      dataLabels: {
        enabled: true,
        style: { fontSize: "10px", fontWeight: 800, colors: ["#fff"] },
        formatter: (val) => (val > 0 ? String(val) : ""),
      },
      xaxis: {
        categories,
        labels: { style: { fontSize: "10px", fontWeight: 600, colors: "#64748b" } },
      },
      yaxis: {
        labels: {
          style: { fontSize: "10px", colors: "#475569" },
          maxWidth: 110,
        },
      },
      legend: { show: false },
      tooltip: {
        theme: "light",
        y: { formatter: (val) => `${val} bid${val === 1 ? "" : "s"}` },
      },
      grid: { padding: { left: 4, right: 8 } },
    }),
  };
}

export function buildBidFunnelBarChart(stat) {
  if (!stat.funnel || !stat.funnel.some((f) => f.count > 0)) return null;

  const categories = stat.funnel.map((f) => f.label);
  const data = stat.funnel.map((f) => f.count);
  const colors = stat.funnel.map((f) => STATUS_COLORS[f.key] || "#94a3b8");

  return {
    series: [{ name: "Bids", data }],
    options: applyLuxChartBase({
      plotOptions: {
        bar: {
          horizontal: true,
          borderRadius: 8,
          barHeight: "62%",
          distributed: true,
          dataLabels: { position: "center" },
        },
      },
      colors,
      dataLabels: {
        enabled: true,
        style: { fontSize: "11px", fontWeight: 800, colors: ["#fff"] },
        formatter: (val) => (val > 0 ? String(val) : ""),
      },
      xaxis: {
        categories,
        labels: { style: { fontSize: "11px", fontWeight: 600, colors: "#475569" } },
      },
      yaxis: {
        labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      },
      legend: { show: false },
      tooltip: {
        theme: "light",
        y: { formatter: (val) => `${val} bid${val === 1 ? "" : "s"}` },
      },
      grid: { padding: { left: 8, right: 12 } },
    }),
  };
}

export function buildBidCreatedTrendAreaChart(stat) {
  if (!stat.createdTrend || !stat.createdTrend.length) return null;
  if (!stat.createdTrend.some((b) => b.count > 0)) return null;

  const categories = stat.createdTrend.map((b) => b.label);
  const data = stat.createdTrend.map((b) => b.count);
  const chart = toAreaChart(categories, [{ name: "New bids", data }], ["#10b981"]);

  chart.options = applyLuxChartBase({
    ...chart.options,
    stroke: { curve: "smooth", width: 2.5 },
    fill: {
      type: "gradient",
      gradient: {
        shadeIntensity: 0.9,
        opacityFrom: 0.4,
        opacityTo: 0.06,
        stops: [0, 92, 100],
      },
    },
    markers: {
      size: 4,
      strokeWidth: 2,
      strokeColors: "#fff",
      hover: { size: 5 },
    },
    xaxis: {
      categories,
      labels: {
        style: { fontSize: "10px", fontWeight: 600, colors: "#64748b" },
      },
      axisBorder: { show: false },
      axisTicks: { show: false },
    },
    yaxis: {
      labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
      tickAmount: 4,
      min: 0,
      forceNiceScale: true,
    },
    legend: { show: false },
    tooltip: {
      theme: "light",
      y: { formatter: (val) => `${val} bid${val === 1 ? "" : "s"}` },
    },
    grid: { padding: { top: 4, right: 8, bottom: 0, left: 4 } },
  });

  return chart;
}

export function buildBidWinLossColumnChart(stat) {
  const segments = [
    { label: "Won", value: stat.won, color: "#10b981" },
    { label: "Lost", value: stat.lost, color: "#94a3b8" },
    { label: "Open", value: stat.pipeline, color: "#6366f1" },
  ].filter((s) => s.value > 0);

  if (!segments.length) return null;

  const categories = segments.map((s) => s.label);
  const data = segments.map((s) => s.value);

  return {
    series: [{ name: "Bids", data }],
    options: applyLuxChartBase({
      plotOptions: {
        bar: {
          horizontal: false,
          borderRadius: 10,
          columnWidth: "42%",
          distributed: true,
          dataLabels: { position: "top" },
        },
      },
      colors: segments.map((s) => s.color),
      dataLabels: {
        enabled: true,
        offsetY: -6,
        style: { fontSize: "11px", fontWeight: 800, colors: ["#475569"] },
      },
      xaxis: {
        categories,
        labels: { style: { fontSize: "10px", fontWeight: 700, colors: "#475569" } },
      },
      yaxis: {
        labels: { style: { fontSize: "10px", colors: "#94a3b8" } },
        tickAmount: 4,
      },
      legend: { show: false },
      tooltip: {
        theme: "light",
        y: { formatter: (val) => `${val} bid${val === 1 ? "" : "s"}` },
      },
      grid: { padding: { top: 8, right: 4, bottom: 0, left: 4 } },
    }),
  };
}
