import React from "react";
import classNames from "classnames/bind";
import { KnowledgeLuxPanel } from "views/knowledge/components/KnowledgeLuxShared";

export default function PatternInsightsPanel({ analytics, loading }) {
  if (loading || !analytics) {
    return (
      <KnowledgeLuxPanel title="Pattern analytics" meta="Recurring defects" icon="fe fe-trending-up" accent="amber">
        <div className="lux-krca-skeleton lux-krca-skeleton--panel" />
      </KnowledgeLuxPanel>
    );
  }

  const patterns = analytics.patterns || [];
  const categories = analytics.categoryCounts || {};
  const closureRate = analytics.closureRate || 0;

  return (
    <div className="lux-krca-analytics-stack">
      <div className="lux-krca-snapshot">
        <span className="lux-krca-snapshot__badge">
          <i className="fe fe-activity" aria-hidden="true" />
          Pattern intelligence
        </span>
        <div className="lux-krca-snapshot__metrics">
          <article className="lux-krca-snapshot__metric is-rose">
            <span>Active patterns</span>
            <strong>{patterns.length}</strong>
          </article>
          <article className="lux-krca-snapshot__metric is-indigo">
            <span>RCA categories</span>
            <strong>{Object.keys(categories).length}</strong>
          </article>
          <article className="lux-krca-snapshot__metric is-emerald">
            <span>Preventive closure</span>
            <strong>{closureRate}%</strong>
          </article>
          <article className="lux-krca-snapshot__metric is-amber">
            <span>Risk clusters</span>
            <strong>{analytics.riskClusters || 0}</strong>
          </article>
        </div>
      </div>

      <div className="lux-krca-analytics-grid">
        <KnowledgeLuxPanel title="Recurring patterns" meta="Signal library" icon="fe fe-activity" accent="rose">
          <ul className="lux-krca-pattern-list">
            {patterns.map((row) => (
              <li key={row.id} className={classNames("lux-krca-pattern-row", row.tone && `is-${row.tone}`)}>
                <span className="lux-krca-pattern-row__label">{row.label}</span>
                <div className="lux-krca-pattern-row__bar">
                  <span style={{ width: `${Math.min(row.preventiveClosurePct || 0, 100)}%` }} />
                </div>
                <span className="lux-krca-pattern-row__meta">
                  {row.recurrenceCount}x · {row.preventiveClosurePct}% closed · {row.lessonsLinked} lessons
                </span>
              </li>
            ))}
          </ul>
        </KnowledgeLuxPanel>

        <KnowledgeLuxPanel title="RCA categories" meta="Distribution" icon="fe fe-pie-chart" accent="indigo">
          <ul className="lux-krca-category-list">
            {Object.keys(categories).map((key) => (
              <li key={key}>
                <span>{key}</span>
                <strong>{categories[key]}</strong>
              </li>
            ))}
          </ul>
          <p className="lux-krca-analytics-foot">
            Preventive closure rate: <strong>{closureRate}%</strong>
          </p>
        </KnowledgeLuxPanel>
      </div>
    </div>
  );
}
