import React from 'react';
import { connect } from 'react-redux';
import { withRouter } from 'react-router-dom';
import { leavePhase2Service as api } from '_services/leavePhase2.service';
import { getApiErrorMessage } from '_helpers/apiError.utils';
import { AdminActionButton } from 'views/admin/components/AdminLuxShared';
import {
  LeavePhase2AdminBase,
  LeavePhase2Panel,
  LeavePhase2Register,
  mapLeavePhase2State,
  renderLeavePhase2Nav,
  LEAVE_PHASE2_EMPTY_DESCRIPTION,
  cell,
} from './leavePhase2.shared';
import '../leaveLuxForms.css';

const BASE = '/admin/leave/policy-test-lab';

const NAV = [
  { path: `${BASE}/scenarios`, label: 'Scenarios', icon: 'fe fe-layers' },
  { path: `${BASE}/runs`, label: 'Runs', icon: 'fe fe-play' },
  { path: `${BASE}/regression`, label: 'Regression', icon: 'fe fe-git-merge' },
];

const EMPTY_SCENARIO = { name: '', leaveTypeCode: '', policyId: '' };
const EMPTY_BATCH = { versionId: '', policyId: '' };
const EMPTY_GATE = { versionId: '' };

function sectionFromPath(pathname) {
  if (pathname.includes('/runs')) return 'runs';
  if (pathname.includes('/regression')) return 'regression';
  if (pathname.includes('/scenarios')) return 'scenarios';
  return 'overview';
}

class PolicyTestLabPage extends LeavePhase2AdminBase {
  state = {
    ...this.state,
    scenarios: [],
    runs: [],
    results: [],
    regression: null,
    publishGate: null,
    selectedRunId: null,
    saving: false,
    scenarioForm: { ...EMPTY_SCENARIO },
    batchForm: { ...EMPTY_BATCH },
    gateForm: { ...EMPTY_GATE },
  };

  fetchSectionData = async (teamId) => {
    const section = sectionFromPath(this.props.location.pathname);
    if (section === 'overview') {
      const [scenarios, runs] = await Promise.all([
        api.listTestScenarios(teamId),
        api.listTestRuns(teamId),
      ]);
      this.setState({
        scenarios: Array.isArray(scenarios) ? scenarios : [],
        runs: Array.isArray(runs) ? runs : [],
        results: [],
        regression: null,
      });
      return;
    }
    if (section === 'scenarios') {
      const scenarios = (await api.listTestScenarios(teamId)) || [];
      this.setState({ scenarios: Array.isArray(scenarios) ? scenarios : [] });
      return;
    }
    if (section === 'runs') {
      const runs = (await api.listTestRuns(teamId)) || [];
      const list = Array.isArray(runs) ? runs : [];
      this.setState({ runs: list, results: [] });
      if (list.length && list[0].id) {
        const results = (await api.listTestResults(list[0].id).catch(() => [])) || [];
        this.setState({
          selectedRunId: list[0].id,
          results: Array.isArray(results) ? results : [],
        });
      }
      return;
    }
    this.setState({ regression: null, publishGate: null });
  };

  runAction = async (fn, successNotice) => {
    const teamId = this.teamId();
    if (!teamId) {
      this.setState({ error: 'Select a team first.' });
      return;
    }
    this.setState({ saving: true, error: null, notice: null });
    try {
      await fn(teamId);
      this.setState({ saving: false, notice: successNotice });
      await this.loadAll();
    } catch (e) {
      this.setState({
        saving: false,
        error: getApiErrorMessage(e, 'Action failed.'),
      });
    }
  };

  createScenario = (event) => {
    event.preventDefault();
    const { scenarioForm } = this.state;
    const name = (scenarioForm.name || '').trim();
    if (!name) return;
    const leaveType = (scenarioForm.leaveTypeCode || '').trim().toUpperCase();
    this.runAction(async (teamId) => {
      await api.createTestScenario({
        userTeamId: teamId,
        actorId: this.actorId(),
        name,
        policyId: scenarioForm.policyId ? Number(scenarioForm.policyId) : null,
        mandatory: true,
        active: true,
        inputJson: leaveType
          ? JSON.stringify({ leaveTypeCode: leaveType })
          : JSON.stringify({}),
        goldenJson: JSON.stringify({ ok: true }),
      });
      this.setState({ scenarioForm: { ...EMPTY_SCENARIO } });
    }, 'Scenario created.');
  };

  runBatch = (event) => {
    event.preventDefault();
    const { batchForm } = this.state;
    const versionId = Number(batchForm.versionId);
    if (!versionId) {
      this.setState({ error: 'Version ID is required to run a batch.' });
      return;
    }
    this.runAction(
      (teamId) =>
        api.runTestBatch({
          userTeamId: teamId,
          actorId: this.actorId(),
          versionId,
          policyId: batchForm.policyId ? Number(batchForm.policyId) : null,
        }),
      'Batch run started.'
    );
  };

  checkGate = (event) => {
    event.preventDefault();
    const versionId = Number(this.state.gateForm.versionId);
    if (!versionId) {
      this.setState({ error: 'Version ID is required for publish gate.' });
      return;
    }
    this.runAction(async (teamId) => {
      const publishGate = await api.checkPublishGate(teamId, versionId);
      this.setState({ publishGate });
    }, 'Publish gate refreshed.');
  };

  renderScenarios() {
    const { loading, scenarios, scenarioForm, saving } = this.state;
    return (
      <>
        <LeavePhase2Panel
          title="Add scenario"
          subtitle="Minimal golden scenario for publish-gate coverage."
          testId="glp20-create-scenario"
        >
          <form className="lux-glp-form" onSubmit={this.createScenario} data-testid="glp20-create-scenario-form">
            <label>
              Name
              <input
                required
                value={scenarioForm.name}
                onChange={(e) =>
                  this.setState({ scenarioForm: { ...scenarioForm, name: e.target.value } })
                }
                placeholder="Accrual smoke"
              />
            </label>
            <label>
              Leave type (optional)
              <input
                value={scenarioForm.leaveTypeCode}
                onChange={(e) =>
                  this.setState({ scenarioForm: { ...scenarioForm, leaveTypeCode: e.target.value } })
                }
                placeholder="CL"
              />
            </label>
            <label>
              Policy ID (optional)
              <input
                value={scenarioForm.policyId}
                onChange={(e) =>
                  this.setState({ scenarioForm: { ...scenarioForm, policyId: e.target.value } })
                }
                placeholder="123"
              />
            </label>
            <div className="lux-glp-form__actions">
              <AdminActionButton type="submit" icon="fe fe-plus" disabled={saving || loading}>
                Add scenario
              </AdminActionButton>
            </div>
          </form>
        </LeavePhase2Panel>
        <LeavePhase2Panel
          title="Scenario library"
          subtitle="Golden inputs and expected outputs for policy regression."
          testId="glp20-scenarios"
        >
          <LeavePhase2Register
            loading={loading}
            rows={scenarios}
            testId="glp20-scenario-register"
            emptyTitle="No test scenarios"
            emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
            columns={[
              { key: 'id', label: 'ID' },
              { key: 'name', label: 'Name' },
              { key: 'policyId', label: 'Policy' },
              { key: 'status', label: 'Status' },
              { key: 'updatedAt', label: 'Updated', render: (r) => cell(r.updatedAt || r.lastModified) },
            ]}
          />
        </LeavePhase2Panel>
      </>
    );
  }

  renderRuns() {
    const { loading, runs, results, batchForm, saving } = this.state;
    return (
      <>
        <LeavePhase2Panel
          title="Run batch"
          subtitle="Execute active scenarios against a policy version."
          testId="glp20-run-batch"
        >
          <form className="lux-glp-form" onSubmit={this.runBatch} data-testid="glp20-run-batch-form">
            <label>
              Version ID
              <input
                required
                value={batchForm.versionId}
                onChange={(e) =>
                  this.setState({ batchForm: { ...batchForm, versionId: e.target.value } })
                }
                placeholder="Version id"
              />
            </label>
            <label>
              Policy ID (optional)
              <input
                value={batchForm.policyId}
                onChange={(e) =>
                  this.setState({ batchForm: { ...batchForm, policyId: e.target.value } })
                }
              />
            </label>
            <div className="lux-glp-form__actions">
              <AdminActionButton type="submit" icon="fe fe-play" disabled={saving || loading}>
                Run batch
              </AdminActionButton>
            </div>
          </form>
        </LeavePhase2Panel>
        <LeavePhase2Panel
          title="Test runs"
          subtitle="Batch execution history against published or draft versions."
          testId="glp20-runs"
        >
          <LeavePhase2Register
            loading={loading}
            rows={runs}
            testId="glp20-runs-register"
            emptyTitle="No test runs"
            emptyDescription={LEAVE_PHASE2_EMPTY_DESCRIPTION}
            columns={[
              { key: 'id', label: 'Run' },
              { key: 'versionId', label: 'Version' },
              { key: 'status', label: 'Status' },
              { key: 'passedCount', label: 'Passed' },
              { key: 'failedCount', label: 'Failed' },
              { key: 'createdAt', label: 'Started' },
            ]}
          />
        </LeavePhase2Panel>
        {runs.length ? (
          <LeavePhase2Panel title="Latest run results" subtitle="Per-scenario comparison output.">
            <LeavePhase2Register
              loading={loading}
              rows={results}
              testId="glp20-results-register"
              emptyTitle="No results for selected run"
              columns={[
                { key: 'scenarioId', label: 'Scenario' },
                { key: 'outcome', label: 'Outcome' },
                { key: 'message', label: 'Message' },
              ]}
            />
          </LeavePhase2Panel>
        ) : null}
      </>
    );
  }

  renderRegression() {
    const { loading, gateForm, publishGate, saving } = this.state;
    const allowed = publishGate && (publishGate.allowed === true || publishGate.allowed === 'true');
    const gateRows = publishGate
      ? [
          {
            id: 'gate',
            allowed: allowed ? 'Allowed' : 'Blocked',
            reason: publishGate.reason || publishGate.message || cell(publishGate),
          },
        ]
      : [];
    return (
      <>
        <LeavePhase2Panel
          title="Publish gate"
          subtitle="Mandatory scenarios must exist and pass before publish."
          testId="glp20-publish-gate"
        >
          <form className="lux-glp-form" onSubmit={this.checkGate} data-testid="glp20-publish-gate-form">
            <label>
              Version ID
              <input
                required
                value={gateForm.versionId}
                onChange={(e) =>
                  this.setState({ gateForm: { ...gateForm, versionId: e.target.value } })
                }
              />
            </label>
            <div className="lux-glp-form__actions">
              <AdminActionButton type="submit" icon="fe fe-shield" disabled={saving || loading}>
                Check gate
              </AdminActionButton>
            </div>
          </form>
          <LeavePhase2Register
            loading={loading}
            rows={gateRows}
            testId="glp20-regression-register"
            emptyTitle="No gate check yet"
            emptyDescription="Enter a version ID and check publish readiness."
            columns={[
              { key: 'allowed', label: 'Status' },
              { key: 'reason', label: 'Detail' },
            ]}
          />
        </LeavePhase2Panel>
      </>
    );
  }

  render() {
    const { loading, scenarios, runs } = this.state;
    const section = sectionFromPath(this.props.location.pathname);
    const kpiCards = [
      { id: 'scenarios', label: 'Scenarios', value: scenarios.length, tone: 'primary', icon: 'fe fe-layers' },
      { id: 'runs', label: 'Runs', value: runs.length, tone: 'blue', icon: 'fe fe-play' },
    ];

    return this.renderChrome({
      testId: 'page-leave-policy-test-lab',
      className: 'lux-glp-test-lab-page',
      kpiCards,
      pageMeta: {
        tone: 'emerald',
        icon: 'fe fe-activity',
        eyebrow: 'Admin · Leave',
        titleLead: 'Policy',
        titleAccent: 'Test Lab',
        lede: 'Minimal scenario create, batch run, and publish-gate check — registers stay the primary view.',
      },
      heroNav: renderLeavePhase2Nav(
        [{ path: BASE, label: 'Overview', icon: 'fe fe-grid', exact: true }, ...NAV],
        this.props.location.pathname
      ),
      children: (
        <>
          {section === 'scenarios' && this.renderScenarios()}
          {section === 'runs' && this.renderRuns()}
          {section === 'regression' && this.renderRegression()}
          {section !== 'scenarios' && section !== 'runs' && section !== 'regression' && (
            <LeavePhase2Panel title="Policy test automation" subtitle="Select a tab for scenarios, batch runs, or publish gate.">
              <p className="lux-leave-subpanel__sub">
                {loading ? 'Loading…' : `${scenarios.length} scenarios · ${runs.length} runs in scope.`}
              </p>
            </LeavePhase2Panel>
          )}
        </>
      ),
    });
  }
}

export default connect(mapLeavePhase2State)(withRouter(PolicyTestLabPage));
