import React from "react";
import classNames from "classnames/bind";
import { getCompliancePackSectionMeta } from "config/compliance-pack.config";

export default function CompliancePackRegister({ sections, selectedIds, onToggle }) {
  return (
    <div className="lux-compliance-register-wrap">
      <table className="lux-compliance-register">
        <thead>
          <tr>
            <th aria-label="Include" />
            <th>Section</th>
            <th>Records</th>
            <th>Status</th>
            <th>Checksum</th>
          </tr>
        </thead>
        <tbody>
          {sections.map((section) => {
            const meta = getCompliancePackSectionMeta(section.id);
            const selected = selectedIds.includes(section.id);
            return (
              <tr
                key={section.id}
                className={classNames("lux-compliance-register__row", {
                  "is-selected": selected,
                  "is-attention": !section.ready,
                })}
                onClick={() => onToggle && onToggle(section.id)}
              >
                <td>
                  <input
                    type="checkbox"
                    checked={selected}
                    onChange={() => onToggle && onToggle(section.id)}
                    onClick={(e) => e.stopPropagation()}
                    aria-label={`Include ${meta.label}`}
                  />
                </td>
                <td>
                  <div className="lux-compliance-register__primary">
                    <span className={classNames("lux-compliance-register__avatar", meta.tone && `is-${meta.tone}`)} aria-hidden="true">
                      <i className={meta.icon} />
                    </span>
                    <span className="lux-compliance-register__primary-copy">
                      <strong className="lux-compliance-register__primary-title">{meta.label}</strong>
                      <span className="lux-compliance-register__primary-meta">{meta.description}</span>
                    </span>
                  </div>
                </td>
                <td>
                  <span className="lux-compliance-register__count">{section.recordCount.toLocaleString()}</span>
                </td>
                <td>
                  <span className={classNames("lux-compliance-register__status", { "is-ready": section.ready, "is-gap": !section.ready })}>
                    {section.ready ? "Ready" : "Gap"}
                  </span>
                </td>
                <td>
                  <span className="lux-compliance-register__checksum">{section.checksum || "—"}</span>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
