import { summarizeDelegations, getDelegationStatus } from "_helpers/approvalDelegation.utils";
import { summarizeDelegationCalendar } from "config/delegation-calendar.utils";

export function buildDelegationAdminMetrics(mine, acting) {
  const mineSummary = summarizeDelegations(mine || []);
  const actingRows = acting || [];
  const actingActive = actingRows.filter((row) => getDelegationStatus(row) === "active").length;
  const calendar = summarizeDelegationCalendar([
    ...(mine || []).map((row) => ({ ...row, calendarRole: "outgoing" })),
    ...actingRows.map((row) => ({ ...row, calendarRole: "incoming" })),
  ]);

  return {
    activeOutgoing: mineSummary.active,
    upcomingOutgoing: mineSummary.upcoming,
    actingActive,
    actingTotal: actingRows.length,
    totalSpans: mineSummary.total + actingRows.length,
    outgoing: calendar.outgoing,
    incoming: calendar.incoming,
  };
}

export function buildDelegationInsights(mine, acting) {
  const mineSummary = summarizeDelegations(mine || []);
  const actingRows = acting || [];
  const actingActive = actingRows.filter((row) => getDelegationStatus(row) === "active").length;
  const actingCount = actingActive || actingRows.length;
  const insights = [];

  if (mineSummary.upcoming > 0) {
    insights.push({
      id: "upcoming",
      tone: "amber",
      icon: "fe fe-calendar",
      eyebrow: "Schedule",
      stat: mineSummary.upcoming,
      title: "Upcoming delegation(s)",
      copy: "Coverage will start automatically on the scheduled start date.",
      hint: "Confirm delegates before the leave window.",
    });
  }
  if (actingCount > 0) {
    insights.push({
      id: "acting",
      tone: "green",
      icon: "fe fe-shield",
      eyebrow: "Inbox",
      stat: actingCount,
      title: actingActive > 0 ? `Acting for ${actingActive} manager(s)` : `${actingCount} acting span(s)`,
      copy: "Pending approvals appear in your inbox with an acting-for badge.",
      hint: "Open Approvals to clear acting queues.",
      path: "/workspace/approvals",
    });
  }
  if (mineSummary.active === 0 && actingCount === 0 && mineSummary.total + actingRows.length === 0) {
    insights.push({
      id: "empty",
      tone: "blue",
      icon: "fe fe-user-plus",
      eyebrow: "Coverage",
      stat: 0,
      title: "No delegation coverage yet",
      copy: "Add a delegate before leave or travel to keep approvals moving.",
      hint: "Outgoing coverage prevents stalled timesheets and leave.",
    });
  } else if (mineSummary.active > 0) {
    insights.push({
      id: "active",
      tone: "green",
      icon: "fe fe-check-circle",
      eyebrow: "Live",
      stat: mineSummary.active,
      title: "Active outgoing coverage",
      copy: `${mineSummary.active} delegate(s) can approve on your behalf.`,
      hint: "Revoke early if you return before the end date.",
    });
  }
  return insights.slice(0, 6);
}

export function buildDelegationSummary(mine, acting) {
  const metrics = buildDelegationAdminMetrics(mine, acting);
  const mineSummary = summarizeDelegations(mine || []);
  const statusMixTotal = Math.max(
    mineSummary.active + mineSummary.upcoming + Math.max(mineSummary.total - mineSummary.active - mineSummary.upcoming, 0),
    1
  );
  const ended = Math.max(mineSummary.total - mineSummary.active - mineSummary.upcoming, 0);

  return {
    metrics,
    attention: buildDelegationInsights(mine, acting),
    kpis: [
      {
        key: "active",
        label: "Active outgoing",
        value: metrics.activeOutgoing,
        hint: "Delegates covering you",
        tone: "green",
        icon: "fe fe-user-check",
      },
      {
        key: "upcoming",
        label: "Upcoming",
        value: metrics.upcomingOutgoing,
        hint: "Scheduled coverage",
        tone: "amber",
        icon: "fe fe-calendar",
      },
      {
        key: "acting",
        label: "Acting for",
        value: metrics.actingActive || metrics.actingTotal,
        hint: `${metrics.incoming} incoming span(s)`,
        tone: "violet",
        icon: "fe fe-shield",
      },
      {
        key: "total",
        label: "Total spans",
        value: metrics.totalSpans,
        hint: `${metrics.outgoing} out · ${metrics.incoming} in`,
        tone: "primary",
        icon: "fe fe-layers",
      },
    ],
    highlights: [
      {
        key: "outgoing",
        label: "Outgoing spans",
        value: metrics.outgoing,
        hint: "You → delegates",
        tone: "blue",
        icon: "fe fe-log-out",
      },
      {
        key: "incoming",
        label: "Incoming spans",
        value: metrics.incoming,
        hint: "Managers → you",
        tone: "indigo",
        icon: "fe fe-log-in",
      },
    ],
    mixInsights: [
      {
        key: "outgoing-status",
        icon: "fe fe-activity",
        title: "Outgoing coverage mix",
        subtitle: "Active, upcoming, and ended spans you own",
        mix: [
          {
            key: "active",
            label: "Active",
            count: mineSummary.active,
            pct: Math.round((mineSummary.active / statusMixTotal) * 100),
            tone: "green",
          },
          {
            key: "upcoming",
            label: "Upcoming",
            count: mineSummary.upcoming,
            pct: Math.round((mineSummary.upcoming / statusMixTotal) * 100),
            tone: "amber",
          },
          {
            key: "ended",
            label: "Ended",
            count: ended,
            pct: Math.round((ended / statusMixTotal) * 100),
            tone: "slate",
          },
        ],
      },
      {
        key: "direction",
        icon: "fe fe-repeat",
        title: "Coverage direction",
        subtitle: "Outgoing vs incoming calendar spans",
        mix: [
          {
            key: "out",
            label: "Outgoing",
            count: metrics.outgoing,
            pct:
              metrics.totalSpans > 0
                ? Math.round((metrics.outgoing / metrics.totalSpans) * 100)
                : 0,
            tone: "blue",
          },
          {
            key: "in",
            label: "Incoming",
            count: metrics.incoming,
            pct:
              metrics.totalSpans > 0
                ? Math.round((metrics.incoming / metrics.totalSpans) * 100)
                : 0,
            tone: "violet",
          },
        ],
        emptyLabel: "No coverage spans yet",
      },
    ],
    series: [
      {
        id: "coverage",
        title: "Coverage posture",
        subtitle: "Live admin metrics",
        rows: [
          {
            key: "active-out",
            label: "Active outgoing",
            icon: "fe fe-user-check",
            tone: "green",
            value: metrics.activeOutgoing,
            pct: metrics.totalSpans
              ? Math.round((metrics.activeOutgoing / metrics.totalSpans) * 100)
              : 0,
            meta: String(metrics.activeOutgoing),
          },
          {
            key: "upcoming-out",
            label: "Upcoming outgoing",
            icon: "fe fe-calendar",
            tone: "amber",
            value: metrics.upcomingOutgoing,
            pct: metrics.totalSpans
              ? Math.round((metrics.upcomingOutgoing / metrics.totalSpans) * 100)
              : 0,
            meta: String(metrics.upcomingOutgoing),
          },
          {
            key: "acting",
            label: "Acting for",
            icon: "fe fe-shield",
            tone: "violet",
            value: metrics.actingActive || metrics.actingTotal,
            pct: metrics.totalSpans
              ? Math.round(((metrics.actingActive || metrics.actingTotal) / metrics.totalSpans) * 100)
              : 0,
            meta: String(metrics.actingActive || metrics.actingTotal),
          },
        ],
      },
    ],
  };
}
