import React, { Component } from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";
import {
  WORKSPACE_FAVORITE_CATALOG,
  isWorkspaceFavoritesEnabled,
} from "config/workspace-personalization.config";
import { isFavoritePath } from "config/workspace-personalization.utils";
import { workspaceService } from "_services/workspace.service";
import { WorkspacePanelHead } from "views/workspace/components/WorkspaceLuxShared";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";

export default class WorkspaceFavoritesPanel extends Component {
  state = {
    favorites: [],
    loading: true,
    acting: false,
    showCatalog: false,
  };

  componentDidMount() {
    this.loadFavorites();
    this._listener = () => this.loadFavorites();
    window.addEventListener("famstack-workspace-personalization-changed", this._listener);
  }

  componentWillUnmount() {
    window.removeEventListener("famstack-workspace-personalization-changed", this._listener);
  }

  loadFavorites = async () => {
    if (!isWorkspaceFavoritesEnabled()) {
      this.setState({ loading: false, favorites: [] });
      return;
    }
    this.setState({ loading: true });
    try {
      const result = await workspaceService.listFavorites();
      this.setState({ favorites: result.payload || [], loading: false });
    } catch (e) {
      this.setState({ favorites: [], loading: false });
    }
  };

  toggleFavorite = async (entry) => {
    if (!entry || !entry.path) {
      return;
    }
    this.setState({ acting: true });
    try {
      if (isFavoritePath(this.state.favorites, entry.path)) {
        await workspaceService.removeFavorite(entry.path);
      } else {
        await workspaceService.addFavorite(entry);
      }
      await this.loadFavorites();
      if (this.props.onChange) {
        this.props.onChange();
      }
    } finally {
      this.setState({ acting: false });
    }
  };

  render() {
    if (!isWorkspaceFavoritesEnabled()) {
      return null;
    }

    const { favorites, loading, acting, showCatalog } = this.state;
    const pinned = favorites || [];

    return (
      <section className="lux-hrms-dash__panel lux-workspace-favorites" aria-label="Workspace favorites">
        <WorkspacePanelHead
          title="Favorites"
          subtitle="Pin routes you open every day"
          actions={
            <button
              type="button"
              className="lux-onb-action lux-onb-action--ghost lux-workspace-favorites__catalog-btn"
              onClick={() => this.setState({ showCatalog: !showCatalog })}
            >
              <i className="fe fe-plus" aria-hidden="true" />
              {showCatalog ? "Hide catalog" : "Add favorite"}
            </button>
          }
        />
        <div className="lux-hrms-dash__panel-body">
          {loading ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              title="Loading favorites"
              description="Reading your pinned workspace shortcuts."
            />
          ) : pinned.length === 0 ? (
            <LuxRegisterEmptyState
              className="lux-register-empty--compact"
              icon="fe fe-star"
              title="No favorites yet"
              description="Star frequent routes from the catalog below."
            />
          ) : (
            <div className="lux-workspace-favorites__grid" role="list">
              {pinned.map((item) => (
                <article key={item.id || item.path} className="lux-workspace-favorites__card" role="listitem">
                  <Link
                    to={item.path}
                    className={classNames("lux-workspace-favorites__link", item.tone && `is-${item.tone}`)}
                  >
                    <span className="lux-workspace-favorites__icon" aria-hidden="true">
                      <i className={item.icon || "fe fe-star"} />
                    </span>
                    <span className="lux-workspace-favorites__copy">
                      <strong>{item.label}</strong>
                      <small>{item.module || "Workspace"}</small>
                    </span>
                  </Link>
                  <button
                    type="button"
                    className="lux-workspace-favorites__star is-active"
                    onClick={() => this.toggleFavorite(item)}
                    disabled={acting}
                    aria-label={`Remove ${item.label} from favorites`}
                  >
                    <i className="fe fe-star" aria-hidden="true" />
                  </button>
                </article>
              ))}
            </div>
          )}

          {showCatalog && (
            <div className="lux-workspace-favorites__catalog" role="list" aria-label="Favorite catalog">
              {WORKSPACE_FAVORITE_CATALOG.map((item) => {
                const active = isFavoritePath(pinned, item.path);
                return (
                  <button
                    key={item.path}
                    type="button"
                    role="listitem"
                    className={classNames("lux-workspace-favorites__catalog-item", item.tone && `is-${item.tone}`, {
                      "is-active": active,
                    })}
                    onClick={() => this.toggleFavorite(item)}
                    disabled={acting}
                  >
                    <i className={active ? "fe fe-star" : "fe fe-star"} aria-hidden="true" />
                    <span>{item.label}</span>
                  </button>
                );
              })}
            </div>
          )}
        </div>
      </section>
    );
  }
}
