export function readSummaryExpanded(storageKey, defaultExpanded) {
  if (defaultExpanded === undefined) {
    defaultExpanded = true;
  }
  try {
    const value = localStorage.getItem(storageKey);
    if (value === null) {
      return defaultExpanded;
    }
    return value === "true";
  } catch (e) {
    return defaultExpanded;
  }
}

export function writeSummaryExpanded(storageKey, expanded) {
  try {
    localStorage.setItem(storageKey, String(expanded));
  } catch (e) {
    /* ignore */
  }
}

/** Collapsed summary panel toggle label (expanded state shows "Collapse"). */
export function getSummaryToggleLabel(isExpanded) {
  return isExpanded ? "Collapse" : "Insights";
}
