import {
  buildBandDistribution,
  buildDepartmentDistribution,
  buildEmpTypeDetailed,
  buildGenderDistribution,
  buildHeadcountTrend,
  buildJoinExitTrend,
  buildLocationDistribution,
  buildSkillDistribution,
  buildTenureBuckets,
  DASHBOARD_CHART_COLORS,
  toAreaChart,
  toColumnChart,
  toDonutChart,
  toHorizontalBarChart,
  toLineChart,
} from "../dashboard/employeeDashboard.utils";

function hasPositiveValues(values) {
  return values.some((value) => value > 0);
}

function rowsToDonut(rows) {
  if (!rows || !rows.length) return null;
  return toDonutChart(
    rows.map((row) => row.label),
    rows.map((row) => row.count),
    DASHBOARD_CHART_COLORS
  );
}

function toInsightTreemapChart(rows, limit = 6) {
  const top = (rows || []).slice(0, limit);
  if (!top.length) return null;

  return {
    series: [
      {
        data: top.map((row) => ({
          x: row.label,
          y: row.count,
        })),
      },
    ],
    options: {
      chart: { type: "treemap", toolbar: { show: false }, fontFamily: "inherit" },
      legend: { show: false },
      colors: DASHBOARD_CHART_COLORS,
      dataLabels: {
        enabled: true,
        style: {
          fontSize: "11px",
          fontWeight: 700,
        },
        formatter(text, opts) {
          return [text, opts.value];
        },
      },
      plotOptions: {
        treemap: {
          distributed: true,
          enableShades: false,
          borderRadius: 6,
          dataLabels: {
            format: "truncate",
          },
        },
      },
      tooltip: {
        y: {
          formatter(value) {
            return `${value} employee${value === 1 ? "" : "s"}`;
          },
        },
      },
    },
  };
}

export function buildEmployeeSummaryCharts(items, userTeams) {
  const all = items || [];
  const activeList = all.filter((employee) => employee.active && !employee.deleted);

  const gender = buildGenderDistribution(activeList);
  const empTypeRows = buildEmpTypeDetailed(activeList);
  const tenure = buildTenureBuckets(activeList);
  const joinExit = buildJoinExitTrend(all, 6);
  const headcount = buildHeadcountTrend(all, 6);
  const skills = buildSkillDistribution(activeList, 8);
  const departments = buildDepartmentDistribution(activeList, userTeams, 8);
  const locations = buildLocationDistribution(activeList, 6);
  const bands = buildBandDistribution(activeList, 6);

  return {
    headcountTrend: hasPositiveValues(headcount.data)
      ? toLineChart(headcount.categories, headcount.data, DASHBOARD_CHART_COLORS, "Headcount")
      : null,
    joinExitTrend:
      hasPositiveValues(joinExit.joins) || hasPositiveValues(joinExit.exits)
        ? toAreaChart(
            joinExit.categories,
            [
              { name: "Joins", data: joinExit.joins },
              { name: "Exits", data: joinExit.exits },
            ],
            ["#14b8a6", "#f97316"]
          )
        : null,
    genderDonut: hasPositiveValues(gender.series)
      ? toDonutChart(gender.labels, gender.series, ["#3b82f6", "#ec4899", "#94a3b8"])
      : null,
    empTypeDonut: rowsToDonut(empTypeRows),
    tenureBar: hasPositiveValues(tenure.map((bucket) => bucket.count))
      ? toColumnChart(
          tenure.map((bucket) => bucket.label),
          tenure.map((bucket) => bucket.count),
          [DASHBOARD_CHART_COLORS[0]]
        )
      : null,
    skillsBar: skills.length
      ? toHorizontalBarChart(skills, [DASHBOARD_CHART_COLORS[4]])
      : null,
    departmentBar: departments.length
      ? toHorizontalBarChart(departments, [DASHBOARD_CHART_COLORS[0]])
      : null,
    locationBar: locations.length
      ? toColumnChart(
          locations.map((row) => row.label),
          locations.map((row) => row.count),
          [DASHBOARD_CHART_COLORS[7]]
        )
      : null,
    bandTreemap: toInsightTreemapChart(bands),
  };
}
