import {
  PERMISSION_MODULE_META,
  PERMISSION_MODULE_ORDER,
  ROLE_PERSONA_META,
  ROLE_PERMISSION_STATUSES,
  flattenPermissionFlags,
  normalizeRolePermissionProfile,
} from "config/role-permission.config";

export function buildRolePermissionMetrics(roles) {
  const rows = (roles || []).map(normalizeRolePermissionProfile).filter(Boolean);
  const active = rows.filter((row) => row.status === ROLE_PERMISSION_STATUSES.ACTIVE);
  const users = rows.reduce((sum, row) => sum + (row.userCount || 0), 0);
  let enabledFlags = 0;
  let totalFlags = 0;
  let adminGrants = 0;

  rows.forEach((row) => {
    const flags = flattenPermissionFlags(row.modules);
    totalFlags += flags.length;
    enabledFlags += flags.filter((flag) => flag.enabled).length;
    adminGrants += (flags.filter((flag) => flag.moduleKey === "adminModules" && flag.enabled).length);
  });

  return {
    totalRoles: rows.length,
    activeRoles: active.length,
    assignedUsers: users,
    enabledFlags,
    totalFlags,
    adminGrants,
    coverage: totalFlags > 0 ? Math.round((enabledFlags / totalFlags) * 100) : 0,
  };
}

export function buildRolePermissionInsights(roles) {
  const rows = (roles || []).map(normalizeRolePermissionProfile).filter(Boolean);
  const insights = [];
  const metrics = buildRolePermissionMetrics(rows);

  const highAdmin = rows.filter((row) => {
    const adminFlags = flattenPermissionFlags(row.modules).filter(
      (flag) => flag.moduleKey === "adminModules" && flag.enabled
    );
    return adminFlags.length >= 4;
  });
  if (highAdmin.length > 0) {
    insights.push({
      id: "admin-surface",
      tone: "amber",
      icon: "fe fe-shield",
      eyebrow: "Privilege",
      stat: highAdmin.length,
      title: "Broad admin surface",
      copy: `${highAdmin.length} role(s) enable 4+ admin modules.`,
      hint: "Tighten least-privilege before production rollout.",
    });
  }

  const noAudit = rows.filter((row) => {
    const flags = flattenPermissionFlags(row.modules);
    return !flags.some((flag) => flag.flagKey === "auditEnabled" && flag.enabled);
  });
  if (noAudit.length > 0 && rows.length > 1) {
    insights.push({
      id: "audit-gap",
      tone: "rose",
      icon: "fe fe-eye-off",
      eyebrow: "Compliance",
      stat: noAudit.length,
      title: "Audit visibility gap",
      copy: `${noAudit.length} role(s) lack audit console access.`,
      hint: "Give compliance reviewers read-only audit visibility.",
    });
  }

  const orphanActive = rows.filter(
    (row) => row.status === ROLE_PERMISSION_STATUSES.ACTIVE && !(row.userCount > 0)
  );
  if (orphanActive.length > 0) {
    insights.push({
      id: "orphan-active",
      tone: "blue",
      icon: "fe fe-user",
      eyebrow: "Assignment",
      stat: orphanActive.length,
      title: "Active roles with no users",
      copy: `${orphanActive.length} active profile(s) have zero mapped users.`,
      hint: "Confirm they are intentional templates or deactivate them.",
    });
  }

  const emptyMatrix = rows.filter((row) => {
    const flags = flattenPermissionFlags(row.modules);
    return flags.length > 0 && !flags.some((flag) => flag.enabled);
  });
  if (emptyMatrix.length > 0) {
    insights.push({
      id: "empty-matrix",
      tone: "amber",
      icon: "fe fe-slash",
      eyebrow: "Coverage",
      stat: emptyMatrix.length,
      title: "Empty permission matrix",
      copy: `${emptyMatrix.length} role(s) have no flags enabled.`,
      hint: "Grant persona or module access, or mark the role inactive.",
    });
  }

  if (metrics.coverage > 0 && metrics.coverage < 35 && rows.length > 1) {
    insights.push({
      id: "low-coverage",
      tone: "blue",
      icon: "fe fe-pie-chart",
      eyebrow: "Health",
      stat: `${metrics.coverage}%`,
      title: "Low org-wide coverage",
      copy: `Only ${metrics.enabledFlags} of ${metrics.totalFlags} flags are on.`,
      hint: "Expand carefully — prefer persona access over blanket module grants.",
    });
  }

  const inactive = rows.filter((row) => row.status !== ROLE_PERMISSION_STATUSES.ACTIVE);
  if (inactive.length > 0) {
    insights.push({
      id: "inactive",
      tone: "slate",
      icon: "fe fe-user-x",
      eyebrow: "Lifecycle",
      stat: inactive.length,
      title: "Inactive role profiles",
      copy: `${inactive.length} profile(s) are inactive.`,
      hint: "Archive or reassign users before removing legacy roles.",
    });
  }

  const personas = {};
  rows.forEach((row) => {
    personas[row.persona] = (personas[row.persona] || 0) + 1;
  });
  const dominant = Object.entries(personas).sort((a, b) => b[1] - a[1])[0];
  if (dominant && rows.length >= 4 && dominant[1] / rows.length >= 0.6) {
    const meta = getPersonaMeta(dominant[0]);
    insights.push({
      id: "persona-skew",
      tone: "slate",
      icon: meta.icon || "fe fe-layers",
      eyebrow: "Distribution",
      stat: `${Math.round((dominant[1] / rows.length) * 100)}%`,
      title: `${meta.label} skew`,
      copy: `${dominant[1]} of ${rows.length} roles use the ${meta.label} persona.`,
      hint: "Consider splitting elevated duties across manager or HR personas.",
    });
  }

  if (insights.length === 0) {
    insights.push({
      id: "healthy",
      tone: "green",
      icon: "fe fe-check-circle",
      eyebrow: "Status",
      stat: rows.length,
      title: "Role profiles aligned",
      copy: "Permission matrix looks healthy against Tracopus defaults.",
      hint: "Keep reviewing when adding admin or payroll grants.",
    });
  }

  return insights.slice(0, 6);
}

export function filterRolePermissionProfiles(roles, filters = {}) {
  const { status = "ALL", persona = "ALL", query = "" } = filters;
  const normalizedQuery = String(query || "").trim().toLowerCase();

  return (roles || [])
    .map(normalizeRolePermissionProfile)
    .filter(Boolean)
    .filter((row) => {
      if (status !== "ALL" && row.status !== status) {
        return false;
      }
      if (persona !== "ALL" && row.persona !== persona) {
        return false;
      }
      if (!normalizedQuery) {
        return true;
      }
      const haystack = [row.name, row.code, row.persona, row.description]
        .filter(Boolean)
        .join(" ")
        .toLowerCase();
      return haystack.includes(normalizedQuery);
    });
}

export function countEnabledFlagsForRole(role) {
  return flattenPermissionFlags(role && role.modules).filter((flag) => flag.enabled).length;
}

export function getRoleCoverageStats(role) {
  const flags = flattenPermissionFlags(role && role.modules);
  const enabled = flags.filter((flag) => flag.enabled).length;
  const total = flags.length;
  return {
    enabled,
    total,
    coverage: total > 0 ? Math.round((enabled / total) * 100) : 0,
  };
}

export function getPersonaMeta(persona) {
  return ROLE_PERSONA_META[persona] || { label: persona || "Role", icon: "fe fe-shield", tone: "slate" };
}

export function buildPersonaDistribution(roles) {
  const rows = (roles || []).map(normalizeRolePermissionProfile).filter(Boolean);
  if (rows.length === 0) {
    return [];
  }
  const counts = {};
  rows.forEach((row) => {
    counts[row.persona] = (counts[row.persona] || 0) + 1;
  });
  return Object.entries(counts)
    .map(([persona, count]) => ({
      persona,
      count,
      meta: getPersonaMeta(persona),
      pct: Math.round((count / rows.length) * 100),
    }))
    .sort((a, b) => b.count - a.count);
}

export function buildModuleGrantSeries(roles) {
  const rows = (roles || []).map(normalizeRolePermissionProfile).filter(Boolean);
  const moduleTotals = {};

  rows.forEach((row) => {
    flattenPermissionFlags(row.modules).forEach((flag) => {
      if (!moduleTotals[flag.moduleKey]) {
        moduleTotals[flag.moduleKey] = { enabled: 0, total: 0 };
      }
      moduleTotals[flag.moduleKey].total += 1;
      if (flag.enabled) {
        moduleTotals[flag.moduleKey].enabled += 1;
      }
    });
  });

  return [
    ...PERMISSION_MODULE_ORDER.filter((key) => moduleTotals[key]),
    ...Object.keys(moduleTotals).filter((key) => !PERMISSION_MODULE_ORDER.includes(key)),
  ].map((moduleKey) => ({
    moduleKey,
    meta: PERMISSION_MODULE_META[moduleKey] || { label: moduleKey, icon: "fe fe-circle", tone: "slate" },
    enabled: moduleTotals[moduleKey].enabled,
    total: moduleTotals[moduleKey].total,
    pct: moduleTotals[moduleKey].total > 0
      ? Math.round((moduleTotals[moduleKey].enabled / moduleTotals[moduleKey].total) * 100)
      : 0,
  }));
}

export function getModuleSections(role) {
  const profile = normalizeRolePermissionProfile(role);
  if (!profile) {
    return [];
  }

  const moduleKeys = [
    ...PERMISSION_MODULE_ORDER.filter((key) => profile.modules && profile.modules[key]),
    ...Object.keys(profile.modules || {}).filter((key) => !PERMISSION_MODULE_ORDER.includes(key)),
  ];

  return moduleKeys
    .map((moduleKey) => {
      if (moduleKey === "personaModules") {
        return null;
      }
      const flags = Object.entries(profile.modules[moduleKey] || {})
        .filter((entry) => typeof entry[1] === "boolean")
        .map(([flagKey, enabled]) => ({
          flagKey,
          enabled,
          label: flagKey.replace(/Enabled$/i, "").replace(/([A-Z])/g, " $1").trim(),
        }));
      if (flags.length === 0) {
        return null;
      }
      const enabledCount = flags.filter((flag) => flag.enabled).length;

      return {
        moduleKey,
        meta: PERMISSION_MODULE_META[moduleKey] || { label: moduleKey, icon: "fe fe-circle", tone: "slate" },
        flags,
        enabledCount,
        totalCount: flags.length,
        coverage: flags.length > 0 ? Math.round((enabledCount / flags.length) * 100) : 0,
      };
    })
    .filter(Boolean);
}

export function applyPermissionToggle(role, moduleKey, flagKey, enabled) {
  const profile = normalizeRolePermissionProfile(role);
  if (!profile) {
    return null;
  }
  const modules = { ...profile.modules };
  modules[moduleKey] = { ...(modules[moduleKey] || {}), [flagKey]: enabled };
  return { ...profile, modules, updatedAt: new Date().toISOString().slice(0, 10) };
}
