import envconfig from "env.config";

export const TRACOPUS_LOGO_SRC = "/assets/images/custom/tracopuslogo.png";
export const TRACOPUS_LOGO_WITH_PRO_SRC = "/assets/images/custom/tracopuslogo2.png";

export function isTracopusApp() {
  return (envconfig.APP_NAME || "").toLowerCase() === "tracopus";
}

export function getAppBrandName() {
  return envconfig.APP_NAME || "Tracopus";
}

export const MOBILE_APP_BRAND_NAME = getAppBrandName();

export function getTracopusLogoSrc(variant = "sidebar") {
  if (variant === "auth") {
    return TRACOPUS_LOGO_SRC;
  }
  return TRACOPUS_LOGO_WITH_PRO_SRC;
}

export function tracopusLogoIncludesPro(variant = "sidebar") {
  return isTracopusApp() && variant === "card";
}

export const brandUtils = {
  TRACOPUS_LOGO_SRC,
  TRACOPUS_LOGO_WITH_PRO_SRC,
  MOBILE_APP_BRAND_NAME,
  isTracopusApp,
  getAppBrandName,
  getTracopusLogoSrc,
  tracopusLogoIncludesPro,
};
