export function FinanceActionButton({
  to,
  children,
  icon,
  variant = "primary",
  onClick,
  disabled,
  className,
  type = "button",
  testId,
  "data-testid": dataTestId,
}) {
  const classes = classNames(
    "lux-onb-action",
    "lux-finance-action",
    `lux-onb-action--${variant}`,
    className
  );
  const resolvedTestId = testId || dataTestId;
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{children}</span>
    </>
  ) : (
    children
  );
  if (to && !onClick) {
    return (
      <Link to={to} className={classes} data-testid={resolvedTestId}>
        {content}
      </Link>
    );
  }
  return (
    <button
      type={type}
      className={classes}
      onClick={onClick}
      disabled={disabled}
      data-testid={resolvedTestId}
    >
      {content}
    </button>
  );
}

