export function FinanceMetricTiles({ tiles, testId }) {
  if (!tiles || !tiles.length) return null;
  return (
    <div className="lux-finance-metric-grid" role="list" data-testid={testId}>
      {tiles.map((tile) => (
        <article
          key={tile.id || tile.label}
          className={classNames("lux-finance-metric-card", tile.tone && `is-${tile.tone}`)}
          role="listitem"
        >
          <span className="lux-finance-metric-card__label">{tile.label}</span>
          <strong className="lux-finance-metric-card__value">{tile.value}</strong>
          {tile.hint ? <small>{tile.hint}</small> : null}
        </article>
      ))}
    </div>
  );
}

