import React, { Component } from "react";
import LuxListCountSkeleton from "views/common/fragments/LuxListCountSkeleton";
import { connect } from "react-redux";
import PageInnerHeader from "views/common/PageInnerHeader";
import { PageDataSourceReporter } from "views/common/PageChromeContext";
import LuxModuleIntro from "views/common/fragments/LuxModuleIntro";
import PageCreateButton from "views/common/fragments/PageCreateButton";
import { DENSE_PAGE_META } from "config/dense-page-meta.config";
import Calendar from "views/common/plugins/calendar/Calendar";
import ActivitiesCalendarHolidayCue from "./components/ActivitiesCalendarHolidayCue";
import { employeeActions } from "_actions";
import { workItemActions } from "_actions";
import { workItemConstants } from "_constants";
import { store } from "_helpers";
import { accessUtils } from "_helpers";
import { commonUtils } from "_helpers";
import dateUtils from "_helpers/date.utils";
import ActivitiesAssignWorkPanel from "./components/ActivitiesAssignWorkPanel";
import WorkItemActiveItems from "./components/WorkItemActiveItems";
import WorkItemPendingItems from "./components/WorkItemPendingItems";
import WorkItemActivitiesSummary from "./components/WorkItemActivitiesSummary";
import { buildWorkItemActivitySummary, paginateActivityRegister, ACTIVITY_DEFAULT_PAGE_SIZE, ACTIVITY_PAGE_SIZE_OPTIONS } from "./components/workItemActivity.utils";
import { checklistConstants } from "_constants";
import ConfigureChecklistSidebar from "./components/modal/ConfigureChecklistSidebar";
import LuxRegisterPagination from "views/common/fragments/LuxRegisterPagination";
import { AUDIT_ENTITY_TYPES, AUDIT_SCOPES } from "_constants/audit.constants";
import CollapsibleAuditPanel from "views/common/fragments/CollapsibleAuditPanel";

class WorkItemAcitivitiesCalendarPage extends Component {

  constructor() {
    super()
    this.state = {
      dateRange: { "startDateMoment": dateUtils.getCurrentTime(), "endDateMoment": dateUtils.getCurrentTime() },
      calendarSelectedDates: [dateUtils.getCurrentTime()],
      calendarViewMonthDate: dateUtils.getCurrentTime(),
      selectedEmployeeIds: [commonUtils.getCurrentUserId()],
      permission: accessUtils.getWorkItemsCalendarAccessControl(),
      currentMonthRange: {
        startMoment: dateUtils.getCurrentTime().clone().startOf('month').startOf("isoweek").startOf("days"),
        endMoment: dateUtils.getCurrentTime().clone().endOf('month').endOf("isoweek").endOf("days")
      },
      filterOptions: {
        SHOW: { options: [{ name: "ALL", label: "All" }, { name: "ONGOING", label: "On Going" }, { name: "COMPLETED", label: "Completed" }, { name: "ASSIGNED", label: "Assigned" }, { name: "CREATEDBYME", label: "Created By Me" }], selected: "COMPLETED" },
        SORT: { options: [{ name: "ACTUALSTARTDATE", label: "Start Date" }, { name: "ESTIMATEDENDDATE", label: "Due Date" }, { name: "CREATEDDATE", label: "Created Date" }, { name: "A-Z", label: "A-Z" }, { name: "PROJECT", label: "Project", hasDirection: false }, { name: "DELIVERABLE", label: "Deliverable", hasDirection: false }], selected: "A-Z", directionUp: true },
        filterText: null
      },
      assignContext: null,
    }
  }
  componentDidMount() {
    this.props.pageHeaderNameChangeHandler(this.props.routeProp.name)
    store.dispatch({ type: workItemConstants.INITIALIZE_WORK_ITEMS_ACTIVITIES, userTeams: this.props.userTeams, filterOptions: this.state.filterOptions });
    this.realoadTeamWorkItems([commonUtils.getCurrentUserId()], this.state.dateRange)
    this.realodHolidays(this.state.currentMonthRange.startMoment, this.state.currentMonthRange.endMoment,);
    this.loadPendingWorkItems();
    this.loadEmployeeList(commonUtils.getUserTeams(this.props.userTeams))
  }

  loadEmployeeList = (userTeams) => {
    let selectedUserTeamsIds = [];
    userTeams && userTeams.map(userTeam => userTeam.isChecked && selectedUserTeamsIds.push(userTeam.id));
    store.dispatch(this.props.getTeamsEmployees(selectedUserTeamsIds))
  }
  loadPendingWorkItems = () => {
    let startDate = dateUtils.substractXFromMoments(dateUtils.getCurrentTime().clone().startOf('day'), "days", 90).clone().format(dateUtils.SERVER_DATE_FORMAT);
    let endDate = dateUtils.addXToMoments(dateUtils.getCurrentTime().clone().endOf('day'), "days", 30).format(dateUtils.SERVER_DATE_FORMAT);
    store.dispatch(this.props.getWorkItemActivitiesPending({ employeeIds: [commonUtils.getCurrentUserId()], userTeamIds: [commonUtils.getCurrentUserTeamId()], startDate: startDate, endDate: endDate }));

  }

  realodHolidays = (startDate, endDate) => {
    store.dispatch(employeeActions.getHolidays({ startDate: startDate.format(dateUtils.SERVER_DATE_FORMAT), endDate: endDate.format(dateUtils.SERVER_DATE_FORMAT) }));
  }
  onSelectedDateChange = selectedDates => {
    const nextKeys = (selectedDates || [])
      .map((d) => (d && d.format ? d.format(dateUtils.DATE_PICKER_FORMAT) : String(d)))
      .join(",");
    const prevKeys = (this.state.calendarSelectedDates || [])
      .map((d) => (d && d.format ? d.format(dateUtils.DATE_PICKER_FORMAT) : String(d)))
      .join(",");
    if (nextKeys && nextKeys === prevKeys) {
      return;
    }

    let dateRange = { "startDateMoment": selectedDates[0].startOf("days"), "endDateMoment": selectedDates[selectedDates.length - 1].endOf("days") }
    this.setState({
      dateRange,
      calendarSelectedDates: selectedDates,
    })
    this.realoadTeamWorkItems(this.state.selectedEmployeeIds, dateRange)
  }

  onCalendarViewDate = (viewMonthMoment) => {
    let startDate = viewMonthMoment.clone().startOf('month').startOf("week").startOf("days")
    let endDate = viewMonthMoment.clone().endOf('month').endOf("week").endOf("days")
    this.realodHolidays(startDate, endDate)
    this.setState({
      calendarViewMonthDate: viewMonthMoment,
      currentMonthRange: {
        startMoment: startDate,
        endMoment: endDate
      }
    })
  }

  handleUserTeamsSelection = (userTeams) => {
    store.dispatch({ type: workItemConstants.INITIALIZE_WORK_ITEMS_ACTIVITIES, userTeams, filterOptions: this.props.filterOptions || this.state.filterOptions });
    this.loadEmployeeList(userTeams);
  }

  handleEmployeesSelection = (employees) => {
    let employeeIds = commonUtils.getSelectedEmployeeIds(employees);
    this.setState({ selectedEmployeeIds: employeeIds },
      () => {
        this.realoadTeamWorkItems(employeeIds, this.state.dateRange)
      });

  }

  handleFilterChange = (filterOptions) => {
    this.setState({ filterOptions },
      () => {
        store.dispatch({ type: workItemConstants.INITIALIZE_WORK_ITEMS_ACTIVITIES, userTeams: this.props.userTeams, filterOptions });
      });
  }

  handleSummaryQuickFilter = (showValue) => {
    const baseOptions = this.props.filterOptions || this.state.filterOptions;
    this.handleFilterChange({
      ...baseOptions,
      SHOW: { ...baseOptions.SHOW, selected: showValue },
    });
  };

  onFilterTextChange = (value) => {
    this.setState(prevState => ({
      filterOptions: {
        ...prevState.filterOptions,
        filterText: value
      }
    }),
      () => {
        this.handleFilterChange(this.state.filterOptions);
      }
    );
  }

  refreshWorkItems = () => {
    this.realoadTeamWorkItems(this.state.selectedEmployeeIds, this.state.dateRange);
    this.loadPendingWorkItems();
  }

  realoadTeamWorkItems = (employeeIds, dateRange) => {

    if (!employeeIds || employeeIds.length === 0) {
      employeeIds = [commonUtils.getCurrentUserId()];
    }

    let startDate = dateRange.startDateMoment.clone().format(dateUtils.SERVER_DATE_FORMAT);
    let endDate = dateRange.endDateMoment.clone().format(dateUtils.SERVER_DATE_FORMAT);

    store.dispatch(this.props.getWorkItemActivities({ employeeIds: employeeIds, userTeamIds: [], startDate: startDate, endDate: endDate }));
  }

  buildAssignContextFromSelection = () => {
    const employeeId =
      this.state.selectedEmployeeIds && this.state.selectedEmployeeIds.length > 0
        ? this.state.selectedEmployeeIds[0]
        : commonUtils.getCurrentUserId();
    const roster = this.props.employees || [];
    const match = roster.find((e) => String(e.id) === String(employeeId));
    const dayKey = this.state.dateRange.startDateMoment.format(dateUtils.SERVER_DATE_FORMAT);
    return {
      key: `activity-${employeeId}-${dayKey}`,
      employee: match
        ? {
            id: match.id,
            name: match.name,
            userTeamId: match.userTeamId,
          }
        : null,
      prefillDate: dayKey,
      prefillStartTime: "08:00",
    };
  };

  createItemClickHandler = () => {
    this.setState({ assignContext: this.buildAssignContextFromSelection() }, () => {
      store.dispatch({ type: workItemConstants.SHOW_TASKPLANNER_CREATE_WINDOW });
    });
  };

  closeCreateItemHandler = () => {
    store.dispatch({ type: workItemConstants.CLOSE_TASKPLANNER_CREATE_WINDOW });
    this.setState({ assignContext: null });
  };

  onCheklistItemClick = (selectedChecklistItem) => {
    this.setState(prevState => ({
      selectedChecklistItem
    }),
      () => {
        store.dispatch(this.props.getWorkItemInfo(selectedChecklistItem.id));
        store.dispatch({ type: checklistConstants.SHOW_CHECKLIST_ANSWER_WINDOW });
      }
    );
  }
  render() {
    const filterOptions = this.props.filterOptions || this.state.filterOptions;
    const summaryStats = buildWorkItemActivitySummary(this.props.workItems, this.props.pendingItems);
    const dateLabel = this.state.dateRange.startDateMoment.isSame(this.state.dateRange.endDateMoment, "day")
      ? this.state.dateRange.startDateMoment.format("ddd, MMM D YYYY")
      : `${this.state.dateRange.startDateMoment.format("MMM D")} – ${this.state.dateRange.endDateMoment.format("MMM D, YYYY")}`;

    return (
      <div className="workitemcalendarpage lux-bid-requests lux-activity-requests lux-register-page" data-testid="page-project-activities">
        <PageDataSourceReporter dataSource="api" />
        <LuxModuleIntro
          meta={DENSE_PAGE_META.projectActivities}
          actions={
            this.state.permission.createEnabled ? (
              <PageCreateButton onClick={this.createItemClickHandler}>Create task</PageCreateButton>
            ) : null
          }
        />
        <PageInnerHeader
          userTeams={commonUtils.getUserTeams(this.props.userTeams)}
          handleUserTeamsSelection={this.handleUserTeamsSelection}
          showGridListMenu={false}
          showFilter={true}
          showEmployeeMenu={true}
          employees={this.props.employees}
          handleEmployeesSelection={this.handleEmployeesSelection}
          showUserTeamMenu={true}
          isLoading={this.props.isLoadingCompleted}
          filterOptions={filterOptions}
          handleFilterChange={this.handleFilterChange}
          onFilterTextChange={this.onFilterTextChange}
          showDateRangeSelector={false}
          showActivityCalendarMenu={true}
          activityCalendarProps={{
            dateRange: this.state.dateRange,
            selectedDates: this.state.calendarSelectedDates,
            viewMonthDate: this.state.calendarViewMonthDate,
            holidayItems: this.props.holidayItems,
            onSelectedDateChange: this.onSelectedDateChange,
            onCalendarViewDate: this.onCalendarViewDate,
          }}
          permission={this.state.permission}
        />

        <WorkItemActivitiesSummary
          stats={summaryStats}
          dateLabel={dateLabel}
          isLoading={this.props.isLoadingCompleted}
          visibleCount={this.props.workItems ? this.props.workItems.length : 0}
          filterOptions={filterOptions}
          onQuickFilter={this.handleSummaryQuickFilter}
        />

        <div className="lux-activity-page">
          <div className="lux-activity-page__workspace">
          <aside className="lux-activity-page__sidebar xs-hide">
            <div className="lux-activity-panel lux-activity-panel--calendar lux-activity-panel--calendar-atelier">
              <Calendar
                className="customSmallCalendar lux-activity-cal--sidebar"
                selectedDates={this.state.calendarSelectedDates}
                viewMonthDate={this.state.calendarViewMonthDate}
                onSelectedDateChange={this.onSelectedDateChange}
                onCalendarViewDate={this.onCalendarViewDate}
                holidayItems={this.props.holidayItems}
                workItems={this.props.completedItems}
              />
              <ActivitiesCalendarHolidayCue holidayItems={this.props.holidayItems} />
            </div>
            <WorkItemPendingItems
              items={this.props.pendingItems}
              isLoading={this.props.isLoadingPending}
              permission={this.state.permission}
              reloadPendingTasks={this.loadPendingWorkItems}
              onCheklistItemClick={this.onCheklistItemClick}
            />
          </aside>

          <section className="lux-activity-page__main">
            <div className="lux-activity-panel lux-activity-panel--list">
              <WorkItemActivitesSection
                workItems={this.props.workItems}
                isLoadingCompleted={this.props.isLoadingCompleted}
                filterOptions={filterOptions}
                permission={this.state.permission}
                onCheklistItemClick={this.onCheklistItemClick}
              />
            </div>
          </section>
          </div>
        </div>

        <div className="lux-page-audit-footer">
          <CollapsibleAuditPanel
            panelKey={`work-item-calendar-${
              this.state.selectedEmployeeIds && this.state.selectedEmployeeIds.length > 0
                ? this.state.selectedEmployeeIds[0]
                : commonUtils.getCurrentUserId()
            }`}
            title="Work item audit feed"
            subtitle="Creates, time edits, and status changes on the activity register"
            icon="fe-activity"
            auditProps={{
              scope: AUDIT_SCOPES.ACTOR,
              actorUserId:
                this.state.selectedEmployeeIds && this.state.selectedEmployeeIds.length > 0
                  ? this.state.selectedEmployeeIds[0]
                  : commonUtils.getCurrentUserId(),
              lockedEntityFilter: AUDIT_ENTITY_TYPES.WORK_ITEM,
              showEntityFilters: false,
              emptyState: {
                eyebrow: "Activity register",
                title: "No work item audit events yet",
                description:
                  "Creates, time edits, and status changes will appear here once audit logging is active.",
                hints: [
                  "Click an activity row to open its dedicated audit trail",
                  "Only work-item actions are shown on this page",
                  "Events are grouped by day with field-level diffs",
                ],
              },
            }}
          />
        </div>

        <ActivitiesAssignWorkPanel
          show={this.props.showTaskPlannerCreateModel}
          onClose={this.closeCreateItemHandler}
          employees={this.props.employees}
          workItems={this.props.plannerWorkItems}
          permission={this.state.permission}
          holidayItems={this.props.holidayItems}
          dateRange={this.state.dateRange}
          assignContext={this.state.assignContext}
          handleReloadWorkItems={this.refreshWorkItems}
        />
        {this.props.selectedWorkItemInfo &&
          <>
            <ConfigureChecklistSidebar
              type={"TASK_ACTIVITY"}
              show={this.props.showChecklistConfigSidebar || this.props.showChecklistAnswerSidebar}
              showConfigWindow={this.props.showChecklistConfigSidebar}
              showChecklistQuestionsWindow={this.props.showChecklistAnswerSidebar}
              selectedItemInfo={this.props.selectedWorkItemInfo}
              permission={this.state.permission}
              configureDisabled={this.props.showChecklistAnswerSidebar}
            />
          </>
        }
      </div>
    );
  }
}

class WorkItemActivitesSection extends Component {
  constructor() {
    super();
    this.state = {
      page: 1,
      pageSize: ACTIVITY_DEFAULT_PAGE_SIZE,
    };
  }

  componentDidUpdate(prevProps) {
    const sortChanged = prevProps.filterOptions && this.props.filterOptions
      && prevProps.filterOptions.SORT.selected !== this.props.filterOptions.SORT.selected;
    const showChanged = prevProps.filterOptions && this.props.filterOptions
      && prevProps.filterOptions.SHOW.selected !== this.props.filterOptions.SHOW.selected;
    const filterTextChanged = prevProps.filterOptions && this.props.filterOptions
      && prevProps.filterOptions.filterText !== this.props.filterOptions.filterText;
    const countChanged = (prevProps.workItems || []).length !== (this.props.workItems || []).length;
    if (sortChanged || showChanged || filterTextChanged || countChanged) {
      this.setState({ page: 1 });
    }
  }

  handlePageChange = (page) => {
    this.setState({ page });
  };

  handlePageSizeChange = (pageSize) => {
    this.setState({ pageSize, page: 1 });
  };

  render() {
    const filterOptions = this.props.filterOptions;
    const allItems = this.props.workItems || [];
    const count = allItems.length;
    const showFlatHeader = filterOptions.SORT.selected !== "PROJECT" && filterOptions.SORT.selected !== "DELIVERABLE";
    const pagination = paginateActivityRegister(allItems, filterOptions.SORT.selected, this.state.page, this.state.pageSize);

    return (
      <div className="lux-activity-panel__body">
        <div className="lux-activity-register">
          <div className="lux-activity-register__bar">
            <span className="lux-activity-register__label">
              <i className="fe fe-activity" aria-hidden="true" />
              Activity register
            </span>
            <span className="lux-activity-register__count">
              {this.props.isLoadingCompleted && count === 0 ? (
                <LuxListCountSkeleton />
              ) : (
                `${count} record${count === 1 ? "" : "s"}`
              )}
            </span>
          </div>

          {showFlatHeader && count > 0 && (
            <div className="lux-activity-register__head" role="row">
              <span className="lux-activity-register__head-cell is-status">Status</span>
              <span className="lux-activity-register__head-cell is-ref">Ref</span>
              <span className="lux-activity-register__head-cell is-name">Activity</span>
              <span className="lux-activity-register__head-cell is-start">Start</span>
              <span className="lux-activity-register__head-cell is-category">Category</span>
              <span className="lux-activity-register__head-cell is-owner">Owner</span>
              <span className="lux-activity-register__head-cell is-duration">Duration</span>
              <span className="lux-activity-register__head-cell is-actions">Actions</span>
            </div>
          )}

          <WorkItemActiveItems
            items={pagination.items}
            isLoading={this.props.isLoadingCompleted}
            sortBy={filterOptions.SORT.selected}
            permission={this.props.permission}
            onCheklistItemClick={this.props.onCheklistItemClick}
          />

          {!this.props.isLoadingCompleted && count > 0 && (
            <LuxRegisterPagination
              pagination={pagination}
              onPageChange={this.handlePageChange}
              onPageSizeChange={this.handlePageSizeChange}
              pageSizeOptions={ACTIVITY_PAGE_SIZE_OPTIONS}
              summaryLabel={showFlatHeader ? "activities" : "groups"}
              className="lux-activity-register__pagination"
            />
          )}
        </div>
      </div>
    );
  }
}

const mapStateToProps = state => ({
  isLoadingCompleted: state.workItem.isLoadingCompleted,
  isLoadingPending: state.workItem.isLoadingPending,
  workItems: state.workItem.workItems && commonUtils.filterWorkItems(state.workItem.workItems, state.workItem.filterOptionsTaskActivity),
  plannerWorkItems: state.workItem.workItems,
  pendingItems: state.workItem.workItemsPending,
  employees: state.employees.teamEmployees && commonUtils.getActiveEmployees(state.employees.teamEmployees),
  holidayItems: state.employees.holidayItems,
  filterOptions: state.workItem.filterOptionsTaskActivity,
  showTaskPlannerCreateModel: state.workItem.showTaskPlannerCreateModel,
  selectedWorkItemInfo: state.workItem.selectedWorkItemInfo,
  showChecklistAnswerSidebar: state.checklist.isShowChecklistAnswerSidebar,
  showChecklistConfigSidebar: state.checklist.isShowConfigureChecklistSidebar
});

const mapDispatchToProps = dispatch => ({
  getTeamsEmployees: employeeActions.getTeamsEmployees,
  getWorkItemActivities: workItemActions.getWorkItemActivities,
  getWorkItemActivitiesPending: workItemActions.getWorkItemActivitiesPending,
  getWorkItemInfo: workItemActions.getWorkItemInfo,
});

export default connect(
  mapStateToProps,
  mapDispatchToProps
)(WorkItemAcitivitiesCalendarPage);
