/**
 * F06 — Timesheet intelligence APIs with client hour merge.
 * Team KPIs may come from the live API; billability/leakage always use the loaded week
 * (project / non-project / leave) so charts stay real when the API returns placeholder zeros.
 */
import { axiosUtils } from "../_helpers";
import urlConfig from "url.config";
import { shouldUseTimesheetIntelligenceApi } from "config/timesheet-enhancement.config";
import { buildTimesheetIntelligence } from "config/timesheet-intelligence.utils";
import { buildBillabilityLeakageAnalytics } from "config/timesheet-leakage.utils";
import { buildTimesheetRecommendationDraft } from "config/timesheet-recommendation.utils";
import { readTimesheetAgentDecision } from "config/timesheet-agent-decision.storage";

export const timesheetIntelligenceService = {
  getIntelligence,
  getBillabilityAnalytics,
  getRecommendation,
  getIntelligenceBundle,
};

async function getIntelligenceFromApi(userTeamId, weekStartDate) {
  const query = [
    userTeamId ? `userTeamId=${encodeURIComponent(userTeamId)}` : null,
    weekStartDate ? `weekStartDate=${encodeURIComponent(weekStartDate)}` : null,
  ]
    .filter(Boolean)
    .join("&");
  const response = await axiosUtils.get(`${urlConfig.TIMESHEET_INTELLIGENCE}?${query}`);
  return response && response.payload ? response.payload : response;
}

function clientIntelligence(context) {
  return {
    ...buildTimesheetIntelligence(context),
    source: "client",
  };
}

function hasClientWeekHours(client) {
  if (!client) return false;
  return (
    (client.totalMins || 0) > 0 ||
    (Array.isArray(client.weekDates) && client.weekDates.length > 0)
  );
}

/**
 * Prefer API team compliance fields; overlay client week hour fields for billability charts.
 */
export function mergeTimesheetIntelligence(apiPayload, client) {
  if (!apiPayload && !client) return null;
  if (!apiPayload) return client;
  if (!client) return { ...apiPayload, source: apiPayload.source || "api" };

  const useClientHours = hasClientWeekHours(client);
  return {
    ...apiPayload,
    billableMins: useClientHours ? client.billableMins || 0 : apiPayload.billableMins || 0,
    nonProjectMins: useClientHours ? client.nonProjectMins || 0 : apiPayload.nonProjectMins || 0,
    leaveOrHolidayMins: useClientHours
      ? client.leaveOrHolidayMins || 0
      : apiPayload.leaveOrHolidayMins || 0,
    totalMins: useClientHours ? client.totalMins || 0 : apiPayload.totalMins || 0,
    utilizationPct: useClientHours ? client.utilizationPct : apiPayload.utilizationPct,
    billableUtilizationPct: useClientHours
      ? client.billableUtilizationPct
      : apiPayload.billableUtilizationPct,
    pendingMins: useClientHours ? client.pendingMins || 0 : apiPayload.pendingMins || 0,
    dailyMap: useClientHours ? client.dailyMap || {} : apiPayload.dailyMap || {},
    weekDates: useClientHours ? client.weekDates || [] : apiPayload.weekDates || [],
    daysNeedingAttention: useClientHours
      ? client.daysNeedingAttention
      : apiPayload.daysNeedingAttention,
    dataQualityIssues: Math.max(client.dataQualityIssues || 0, apiPayload.dataQualityIssues || 0),
    openConflicts: Math.max(client.openConflicts || 0, apiPayload.openConflicts || 0),
    weekStatus: client.weekStatus || apiPayload.weekStatus,
    pendingApprovals:
      apiPayload.pendingApprovals != null ? apiPayload.pendingApprovals : client.pendingApprovals,
    defaulterCount:
      apiPayload.defaulterCount != null ? apiPayload.defaulterCount : client.defaulterCount,
    complianceRate:
      apiPayload.complianceRate != null ? apiPayload.complianceRate : client.complianceRate,
    source: "api",
    hourSource: useClientHours ? "client-week" : "api",
  };
}

async function getIntelligence(context) {
  const client = clientIntelligence(context);

  if (shouldUseTimesheetIntelligenceApi()) {
    try {
      const payload = await getIntelligenceFromApi(context.userTeamId, context.weekStartDate);
      if (payload) {
        return mergeTimesheetIntelligence({ ...payload, source: "api" }, client);
      }
    } catch (e) {
      console.warn("[TimesheetIntelligence] API unavailable — using client week metrics.", e);
      if (hasClientWeekHours(client)) {
        return { ...client, source: "client", apiFallback: true };
      }
      return { payload: null, source: "api-error", error: e };
    }
  }

  return client;
}

async function getBillabilityAnalytics(context, intelligenceOverride) {
  const intelligence = intelligenceOverride || (await getIntelligence(context));
  if (intelligence && intelligence.source === "api-error") {
    const client = clientIntelligence(context);
    if (hasClientWeekHours(client)) {
      return buildBillabilityLeakageAnalytics(client);
    }
    return { payload: null, source: "api-error" };
  }
  return buildBillabilityLeakageAnalytics(intelligence);
}

async function getRecommendation(context, intelligenceOverride, billabilityOverride) {
  const intelligence = intelligenceOverride || (await getIntelligence(context));
  if (intelligence && intelligence.source === "api-error") {
    const client = clientIntelligence(context);
    if (!hasClientWeekHours(client)) {
      return { payload: null, source: "api-error" };
    }
    const billability = buildBillabilityLeakageAnalytics(client);
    return hydrateRecommendationDecision(
      buildTimesheetRecommendationDraft(client, billability, context),
      context
    );
  }
  const billability =
    billabilityOverride || buildBillabilityLeakageAnalytics(intelligence);
  return hydrateRecommendationDecision(
    buildTimesheetRecommendationDraft(intelligence, billability, context),
    context
  );
}

function hydrateRecommendationDecision(recommendation, context) {
  if (!recommendation) return null;
  const stored = readTimesheetAgentDecision(context);
  if (!stored) return recommendation;
  return {
    ...recommendation,
    decision: stored.action,
    decisionAt: stored.at,
    decisionMessage: stored.message,
    draftOnly: false,
  };
}

/** One network round-trip + client hour merge for the Intelligence tab. */
async function getIntelligenceBundle(context) {
  const intelligence = await getIntelligence(context);
  if (intelligence && intelligence.source === "api-error") {
    const client = clientIntelligence(context);
    if (hasClientWeekHours(client)) {
      const billability = buildBillabilityLeakageAnalytics(client);
      const recommendation = hydrateRecommendationDecision(
        buildTimesheetRecommendationDraft(client, billability, context),
        context
      );
      return { intelligence: client, billability, recommendation };
    }
    return {
      intelligence: null,
      billability: { payload: null, source: "api-error" },
      recommendation: { payload: null, source: "api-error" },
    };
  }
  const billability = buildBillabilityLeakageAnalytics(intelligence);
  const recommendation = hydrateRecommendationDecision(
    buildTimesheetRecommendationDraft(intelligence, billability, context),
    context
  );
  return { intelligence, billability, recommendation };
}
