import React from "react";
import classNames from "classnames/bind";
import {
  countEnabledFlagsForRole,
  getPersonaMeta,
  getRoleCoverageStats,
} from "config/role-permission.utils";

export default function RolePermissionRegister({ roles, selectedId, onSelect }) {
  return (
    <div className="lux-rbac-role-list" role="list" aria-label="Role profiles">
      {(roles || []).map((role) => {
        const personaMeta = getPersonaMeta(role.persona);
        const coverage = getRoleCoverageStats(role);
        const enabledCount = countEnabledFlagsForRole(role);
        const isInactive = role.status === "Inactive";
        const selected = selectedId === role.id;

        return (
          <button
            key={role.id}
            type="button"
            role="listitem"
            className={classNames("lux-rbac-role-card", {
              "is-selected": selected,
              "is-inactive": isInactive,
            })}
            onClick={() => onSelect && onSelect(role)}
            aria-pressed={selected}
          >
            <span
              className={classNames(
                "lux-rbac-role-card__avatar",
                personaMeta.tone && `is-${personaMeta.tone}`
              )}
              aria-hidden="true"
            >
              <i className={personaMeta.icon} />
            </span>

            <span className="lux-rbac-role-card__body">
              <span className="lux-rbac-role-card__top">
                <strong className="lux-rbac-role-card__title">{role.name}</strong>
                <span
                  className={classNames("lux-rbac-role-card__status", {
                    "is-active": !isInactive,
                    "is-inactive": isInactive,
                  })}
                >
                  {isInactive ? "Off" : "Live"}
                </span>
              </span>

              <span className="lux-rbac-role-card__sub">
                <em>{role.code}</em>
                <span
                  className={classNames(
                    "lux-rbac-role-card__persona",
                    personaMeta.tone && `is-${personaMeta.tone}`
                  )}
                >
                  <i className={personaMeta.icon} aria-hidden="true" />
                  {personaMeta.label}
                </span>
                <span className="lux-rbac-role-card__users">
                  <i className="fe fe-users" aria-hidden="true" />
                  {role.userCount || 0}
                </span>
              </span>

              <span className="lux-rbac-role-card__meter" aria-hidden="true">
                <span className="lux-rbac-role-card__meter-track">
                  <span style={{ width: `${Math.max(coverage.coverage, 4)}%` }} />
                </span>
                <span className="lux-rbac-role-card__meter-label">
                  {coverage.coverage}% · {enabledCount}/{coverage.total}
                </span>
              </span>
            </span>
          </button>
        );
      })}
    </div>
  );
}
