import React from "react";
import ProjectDetailsTabShell from "views/project/components/ProjectDetailsTabShell";
import { formatProfileDate } from "views/hrms/components/profile/profilePage.utils";
import {
  isFieldVisible,
  resolveMaskedFieldValue,
} from "config/employee360-field.utils";

function EmploymentField({ label, value, fieldKey, maskingPolicy }) {
  if (fieldKey && !isFieldVisible(fieldKey, maskingPolicy)) {
    return null;
  }
  const displayValue =
    fieldKey && maskingPolicy
      ? resolveMaskedFieldValue(fieldKey, value, maskingPolicy)
      : value || "—";

  return (
    <div className="lux-employee-360__field">
      <span className="lux-employee-360__field-label">{label}</span>
      <strong className="lux-employee-360__field-value">{displayValue}</strong>
    </div>
  );
}

export default function Employee360EmploymentTab({ employee, summary, maskingPolicy }) {
  if (!employee) {
    return null;
  }

  const teamName = employee.defaultUserTeamDetails && employee.defaultUserTeamDetails.name;
  const roleName = employee.userAccessDetails && employee.userAccessDetails.name;

  return (
    <ProjectDetailsTabShell
      title="Employment"
      description="Role, team, and employment lifecycle details."
      stats={[]}
    >
      <div className="lux-employee-360__field-grid">
        <EmploymentField label="Employee code" value={employee.empCode} />
        <EmploymentField label="Role" value={roleName || (summary && summary.roleName)} />
        <EmploymentField label="Team" value={teamName || (summary && summary.teamName)} />
        <EmploymentField label="Date of join" value={formatProfileDate(employee.dateOfJoin)} />
        <EmploymentField label="Exit date" value={formatProfileDate(employee.exitDate)} />
        <EmploymentField
          label="Status"
          value={employee.active === false ? "Inactive" : "Active"}
        />
        <EmploymentField label="Manager" value={summary && summary.manager} />
        <EmploymentField label="Location" value={summary && summary.location} />
        <EmploymentField label="Employment type" value={summary && summary.employmentType} />
        <EmploymentField label="Payroll group" value={summary && summary.payrollGroup} fieldKey="payrollGroup" maskingPolicy={maskingPolicy} />
      </div>
    </ProjectDetailsTabShell>
  );
}
