import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isPerformanceManagementEnabled } from "config/performance-management.config";
import { FEEDBACK_PAGE_META } from "config/performance-management-nav.config";
import { performanceManagementService } from "_services/performanceManagement.service";
import PerformanceLuxPage, { PerformanceActionButton, PerformanceLuxPanel } from "views/performance/components/PerformanceLuxShared";
import FeedbackRegister from "views/performance/components/FeedbackRegister";
import { FeedbackCreateDrawer } from "views/performance/components/PerformanceCreateDrawers";

class ContinuousFeedbackPage extends Component {
  state = { loading: true, feedback: [], kpiCards: [], dataSource: null, createOpen: false, busy: false };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true });
    try {
      const [overview, feedbackResult] = await Promise.all([
        performanceManagementService.getOverview({}),
        performanceManagementService.listFeedback({}),
      ]);
      this.setState({
        loading: false,
        dataSource: feedbackResult.source,
        feedback: feedbackResult.payload || [],
        kpiCards: (overview.payload && overview.payload.kpiCards) || [],
      });
    } catch (error) {
      this.setState({ loading: false, feedback: [] });
    }
  };

  handleCreate = async (payload) => {
    this.setState({ busy: true });
    try {
      await performanceManagementService.createFeedback(payload);
      this.setState({ createOpen: false, busy: false });
      await this.loadData();
    } catch (error) {
      this.setState({ busy: false });
    }
  };

  render() {
    if (!isPerformanceManagementEnabled()) {
      return <PersonaAccessDenied featureLabel="Continuous feedback" />;
    }

    const { loading, feedback, kpiCards, dataSource, createOpen, busy } = this.state;

    return (
      <PerformanceLuxPage
        pageMeta={FEEDBACK_PAGE_META}
        pageId="feedback"
        shellTitle="Continuous feedback"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><PerformanceActionButton variant="primary" icon="fe fe-plus" onClick={() => this.setState({ createOpen: true })}>
              Give feedback
            </PerformanceActionButton>
          </>}
      >
        <PerformanceLuxPanel title="Feedback stream" meta="Praise, coaching, and constructive notes" icon="fe fe-message-circle" accent="emerald" featured>
          <FeedbackRegister feedback={feedback} loading={loading} />
        </PerformanceLuxPanel>
        <FeedbackCreateDrawer open={createOpen} onClose={() => this.setState({ createOpen: false })} onCreate={this.handleCreate} busy={busy} />
      </PerformanceLuxPage>
    );
  }
}

export default ContinuousFeedbackPage;
