import React from "react";
import classNames from "classnames/bind";
import { getApprovalDomainFilterOptions } from "config/universal-approval.config";

const STATUS_OPTIONS = [
  { id: "ALL", label: "All" },
  { id: "PENDING", label: "Pending" },
  { id: "APPROVED", label: "Approved" },
  { id: "REJECTED", label: "Rejected" },
];

const PRIORITY_OPTIONS = [
  { id: "ALL", label: "All priorities" },
  { id: "HIGH", label: "High" },
  { id: "NORMAL", label: "Normal" },
  { id: "LOW", label: "Low" },
];

const DEFAULT_FILTERS = {
  status: "PENDING",
  domain: "ALL",
  priority: "ALL",
  query: "",
};

function isNonDefault(filters) {
  return (
    (filters.status || "PENDING") !== DEFAULT_FILTERS.status ||
    (filters.domain || "ALL") !== DEFAULT_FILTERS.domain ||
    (filters.priority || "ALL") !== DEFAULT_FILTERS.priority ||
    Boolean((filters.query || "").trim())
  );
}

function UniversalApprovalFilterBar({ filters, onChange, resultCount, statusCounts }) {
  const domainOptions = getApprovalDomainFilterOptions();

  const setFilter = (key, value) => {
    onChange({ ...filters, [key]: value });
  };

  const clearFilters = () => {
    onChange({ ...DEFAULT_FILTERS });
  };

  return (
    <div className="lux-appr-toolbar lux-appr-toolbar--flush" data-testid="approval-filter-bar">
      <div className="lux-appr-toolbar__search">
        <i className="fe fe-search" aria-hidden="true" />
        <input
          type="search"
          className="lux-appr-toolbar__search-input"
          placeholder="Search requester, subject, or module…"
          value={filters.query || ""}
          onChange={(event) => setFilter("query", event.target.value)}
          aria-label="Search approvals"
        />
      </div>

      <span className="lux-appr-toolbar__count">
        <strong>{resultCount}</strong>
        <span>item{resultCount === 1 ? "" : "s"}</span>
      </span>

      <div className="lux-appr-toolbar__status" role="group" aria-label="Filter by status">
        {STATUS_OPTIONS.map((item) => {
          const count = statusCounts ? statusCounts[item.id] : null;
          return (
            <button
              key={item.id}
              type="button"
              className={classNames("lux-hrms-dash__filter-chip", {
                "is-active": filters.status === item.id,
              })}
              onClick={() => setFilter("status", item.id)}
            >
              {item.label}
              {count != null ? (
                <span className="lux-appr-toolbar__chip-count">{count}</span>
              ) : null}
            </button>
          );
        })}
      </div>

      <label className="lux-appr-toolbar__select-wrap">
        <span className="sr-only">Domain</span>
        <select
          className="lux-appr-toolbar__select"
          data-testid="approval-domain-filter"
          value={filters.domain || "ALL"}
          onChange={(event) => setFilter("domain", event.target.value)}
          aria-label="Filter by domain"
        >
          <option value="ALL">All domains</option>
          {domainOptions.map((item) => (
            <option key={item.id} value={item.id}>
              {item.label}
            </option>
          ))}
        </select>
      </label>

      <label className="lux-appr-toolbar__select-wrap">
        <span className="sr-only">Priority</span>
        <select
          className="lux-appr-toolbar__select"
          value={filters.priority || "ALL"}
          onChange={(event) => setFilter("priority", event.target.value)}
          aria-label="Filter by priority"
        >
          {PRIORITY_OPTIONS.map((item) => (
            <option key={item.id} value={item.id}>
              {item.label}
            </option>
          ))}
        </select>
      </label>

      {isNonDefault(filters) && (
        <button
          type="button"
          className="lux-appr-toolbar__clear"
          onClick={clearFilters}
          aria-label="Clear filters"
        >
          <i className="fe fe-x" aria-hidden="true" />
          Clear
        </button>
      )}
    </div>
  );
}

export default UniversalApprovalFilterBar;
