import React from "react";
import classNames from "classnames/bind";
import {
  getMilestoneStatusLabel,
  getMilestoneStatusTone,
} from "config/project-governance.utils";

export default function MilestoneRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-gov-register-wrap">
      <table className="lux-gov-register">
        <thead>
          <tr>
            <th>Milestone</th>
            <th>Project</th>
            <th>Owner</th>
            <th>Planned window</th>
            <th>Progress</th>
            <th>Status</th>
            <th>Path</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const tone = getMilestoneStatusTone(row.status);
            return (
              <tr
                key={row.id}
                className={classNames("lux-gov-register__row", {
                  "is-critical": row.onCriticalPath,
                  "is-risk": row.status === "AT_RISK",
                })}
              >
                <td>
                  <button type="button" className="lux-gov-register__link" onClick={() => onSelect(row)}>
                    <strong>{row.name}</strong>
                    {row.description ? <span>{row.description}</span> : null}
                  </button>
                </td>
                <td>
                  <span className="lux-gov-register__project">{row.projectName}</span>
                  {row.projectCode ? <span className="lux-gov-register__meta">{row.projectCode}</span> : null}
                </td>
                <td>{row.ownerName || "—"}</td>
                <td>
                  <span className="lux-gov-register__dates">
                    {row.plannedStart || "—"} → {row.plannedEnd || "—"}
                  </span>
                </td>
                <td>
                  <span className="lux-gov-register__progress">
                    <span className="lux-gov-register__progress-bar" style={{ width: `${row.percentComplete || 0}%` }} />
                    <em>{row.percentComplete || 0}%</em>
                  </span>
                </td>
                <td>
                  <span className={classNames("lux-doc-badge", `is-${tone}`)}>{getMilestoneStatusLabel(row.status)}</span>
                </td>
                <td>
                  {row.onCriticalPath ? (
                    <span className="lux-gov-register__chip is-critical">
                      Critical{row.slackDays === 0 ? " · 0d float" : ""}
                    </span>
                  ) : (
                    <span className="lux-gov-register__chip">
                      {row.slackDays != null ? `${row.slackDays}d float` : "Standard"}
                    </span>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
