import React, { Component } from "react";
import { connect } from "react-redux";
import classNames from "classnames/bind";
import { store } from "_helpers";
import { commonUtils } from "_helpers";
import { employeeActions, approvalDelegationActions } from "_actions";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import ApprovalDelegationForm from "./ApprovalDelegationForm";
import {
  buildDelegateOptions,
  buildDelegationScopePills,
  formatDelegationDateRange,
  getDelegationStatus,
  getDelegationStatusMeta,
  getEmployeeInitials,
  parseDelegationDate,
  sortDelegationsForDisplay,
  summarizeDelegations,
} from "_helpers/approvalDelegation.utils";

class ApprovalDelegationPanel extends Component {
  constructor(props) {
    super(props);
    this.state = {
      delegations: [],
      loading: false,
      saving: false,
      formOpen: false,
      editingDelegation: null,
    };
  }

  componentDidMount() {
    this.loadDelegations();
    if (!this.props.allEmployees || !this.props.allEmployees.length) {
      store.dispatch(employeeActions.getAllEmployees());
    }
  }

  loadDelegations = () => {
    const delegatorId = this.getDelegatorId();
    if (!delegatorId) {
      this.setState({ delegations: [] });
      return Promise.resolve([]);
    }
    this.setState({ loading: true });
    return store
      .dispatch(approvalDelegationActions.loadMine(delegatorId))
      .then((delegations) => {
        const list = delegations || [];
        this.setState({ delegations: list, loading: false });
        if (this.props.onDelegationsLoaded) {
          this.props.onDelegationsLoaded(list);
        }
        return list;
      })
      .catch(() => {
        this.setState({ loading: false });
        if (this.props.onDelegationsLoaded) {
          this.props.onDelegationsLoaded([]);
        }
        return [];
      });
  };

  getDelegatorId = () => {
    const { employee } = this.props;
    return employee && employee.id ? employee.id : commonUtils.getCurrentUserId();
  };

  openCreateForm = () => {
    this.setState({ formOpen: true, editingDelegation: null, initialForm: null });
  };

  openEditForm = (delegation) => {
    const start = parseDelegationDate(delegation.startDate);
    const end = parseDelegationDate(delegation.endDate);
    this.setState({
      formOpen: true,
      editingDelegation: delegation,
      initialForm: {
        delegateId: delegation.delegateId,
        approvalTypes: delegation.approvalTypes || [],
        startDate: start && start.isValid() ? start.format("YYYY-MM-DD") : "",
        endDate: end && end.isValid() ? end.format("YYYY-MM-DD") : "",
        note: delegation.note || "",
      },
    });
  };

  closeForm = () => {
    this.setState({ formOpen: false, editingDelegation: null, initialForm: null });
  };

  handleSubmit = (payload) => {
    const delegatorId = this.getDelegatorId();
    const { editingDelegation } = this.state;
    if (!delegatorId) return Promise.resolve();

    this.setState({ saving: true });
    const action = editingDelegation
      ? approvalDelegationActions.updateDelegation(delegatorId, editingDelegation.id, payload)
      : approvalDelegationActions.createDelegation(delegatorId, payload);

    return store
      .dispatch(action)
      .then(() => {
        this.closeForm();
        return this.loadDelegations();
      })
      .catch(() => {
        // Keep form open; toast already shows the API error.
        return null;
      })
      .finally(() => {
        this.setState({ saving: false });
      });
  };

  handleRevoke = (delegation) => {
    const delegatorId = this.getDelegatorId();
    if (!delegatorId || !delegation || !delegation.id) return;
    const delegateName = delegation.delegateName || "this delegate";
    if (!window.confirm(`End delegation for ${delegateName}? They will no longer see your pending approvals.`)) {
      return;
    }

    this.setState({ saving: true });
    store
      .dispatch(approvalDelegationActions.revokeDelegation(delegatorId, delegation.id))
      .then(() => this.loadDelegations())
      .finally(() => {
        this.setState({ saving: false });
      });
  };

  renderScopePills = (delegation) => {
    const pills = buildDelegationScopePills(delegation.approvalTypes);
    if (!pills.length) return <span className="lux-approval-delegation__scope-pill is-muted">—</span>;
    return pills.map((scope) => (
      <span key={scope.id} className={`lux-approval-delegation__scope-pill is-${scope.id.toLowerCase()}`}>
        <i className={`fe ${scope.icon}`} aria-hidden="true" />
        {scope.label}
      </span>
    ));
  };

  renderDelegationCard = (delegation) => {
    const status = getDelegationStatus(delegation);
    const statusMeta = getDelegationStatusMeta(status);
    const canModify = status === "active" || status === "upcoming";
    const { saving } = this.state;
    const delegateName = delegation.delegateName || "Delegate";

    return (
      <article
        key={delegation.id}
        className={classNames(
          "lux-approval-delegation__card",
          `lux-approval-delegation__card--${statusMeta.tone}`
        )}
      >
        <header className="lux-approval-delegation__card-head">
          <div className="lux-approval-delegation__card-identity">
            <span className="lux-approval-delegation__avatar" aria-hidden="true">
              {getEmployeeInitials(delegateName)}
            </span>
            <div>
              <h4 className="lux-approval-delegation__card-title">{delegateName}</h4>
              <p className="lux-approval-delegation__card-range">
                <i className="fe fe-calendar" aria-hidden="true" />
                {formatDelegationDateRange(delegation)}
              </p>
            </div>
          </div>
          <span className={`lux-approval-delegation__status lux-approval-delegation__status--${statusMeta.tone}`}>
            {statusMeta.label}
          </span>
        </header>

        <div className="lux-approval-delegation__scope-row" aria-label="Approval scope">
          {this.renderScopePills(delegation)}
        </div>

        {delegation.note ? (
          <blockquote className="lux-approval-delegation__note">
            <i className="fe fe-message-square" aria-hidden="true" />
            {delegation.note}
          </blockquote>
        ) : null}

        {canModify ? (
          <div className="lux-approval-delegation__card-actions">
            <button
              type="button"
              className="lux-approval-delegation__btn lux-approval-delegation__btn--ghost"
              onClick={() => this.openEditForm(delegation)}
              disabled={saving}
            >
              <i className="fe fe-edit-2" aria-hidden="true" />
              Edit
            </button>
            <button
              type="button"
              className="lux-approval-delegation__btn lux-approval-delegation__btn--danger"
              onClick={() => this.handleRevoke(delegation)}
              disabled={saving}
            >
              <i className="fe fe-slash" aria-hidden="true" />
              End early
            </button>
          </div>
        ) : null}
      </article>
    );
  };

  renderSummaryChips = (summary) => {
    if (!summary.total) return null;
    return (
      <div className="lux-approval-delegation__summary-chips" aria-label="Delegation summary">
        {summary.active > 0 ? (
          <span className="lux-approval-delegation__summary-chip is-active">
            <i className="fe fe-check-circle" aria-hidden="true" />
            {summary.active} active
          </span>
        ) : null}
        {summary.upcoming > 0 ? (
          <span className="lux-approval-delegation__summary-chip is-upcoming">
            <i className="fe fe-calendar" aria-hidden="true" />
            {summary.upcoming} upcoming
          </span>
        ) : null}
        {summary.ended > 0 ? (
          <span className="lux-approval-delegation__summary-chip is-ended">
            <i className="fe fe-archive" aria-hidden="true" />
            {summary.ended} past
          </span>
        ) : null}
      </div>
    );
  };

  render() {
    const { allEmployees, allEmployeesLoading } = this.props;
    const { delegations, loading, saving, formOpen, editingDelegation, initialForm } = this.state;
    const sorted = sortDelegationsForDisplay(delegations);
    const summary = summarizeDelegations(sorted);
    const delegateOptions = buildDelegateOptions(allEmployees, this.getDelegatorId());
    const isBusy = loading || saving || allEmployeesLoading;

    return (
      <section className="lux-approval-delegation" aria-label="Approval delegations">
        <header className="lux-approval-delegation__head">
          <div>
            <span className="lux-approval-delegation__eyebrow">Coverage</span>
            <h3 className="lux-approval-delegation__title">Your delegations</h3>
            <p className="lux-approval-delegation__subtitle">
              Assign trusted colleagues to approve attendance and timesheets while you are away.
              Delegates see your team&apos;s pending items with an &ldquo;Acting for you&rdquo; badge.
            </p>
            {this.renderSummaryChips(summary)}
          </div>
          {!formOpen ? (
            <button
              type="button"
              className="lux-approval-delegation__btn lux-approval-delegation__btn--primary"
              onClick={this.openCreateForm}
              disabled={isBusy}
            >
              <i className="fe fe-user-plus" aria-hidden="true" />
              Add delegate
            </button>
          ) : null}
        </header>

        {!formOpen && summary.active > 0 ? (
          <aside className="lux-approval-delegation__tip" role="note">
            <i className="fe fe-info" aria-hidden="true" />
            <span>
              Active delegates receive approval emails and can act from Attendance and Timesheet
              pending panels. You can still approve while coverage is active.
            </span>
          </aside>
        ) : null}

        <ApprovalDelegationForm
          open={formOpen}
          editing={!!editingDelegation}
          initialForm={initialForm}
          delegateOptions={delegateOptions}
          isLoading={isBusy}
          onSubmit={this.handleSubmit}
          onCancel={this.closeForm}
        />

        {loading && !sorted.length ? (
          <div className="lux-approval-delegation__loading" role="status">
            <i className="fe fe-loader" aria-hidden="true" />
            Loading delegations…
          </div>
        ) : null}

        {!loading && !sorted.length && !formOpen ? (
          <LuxRegisterEmptyState
            className="lux-register-empty--compact lux-approval-delegation__empty"
            variant="employees"
            eyebrow="Coverage"
            title="No delegations yet"
            description="Add a delegate before leave or travel so your team's attendance and timesheets keep moving."
            hints={[
              "Pick a colleague with timesheet approval permission for timesheet scope",
              "Set clear start and end dates for your absence",
              "End a delegation early when you are back in the office",
            ]}
          />
        ) : null}

        {sorted.length ? (
          <div className="lux-approval-delegation__list">{sorted.map(this.renderDelegationCard)}</div>
        ) : null}
      </section>
    );
  }
}

const mapStateToProps = (state) => ({
  allEmployees: state.employees.allEmployees,
  allEmployeesLoading: state.employees.allEmployeesLoading,
});

export default connect(mapStateToProps)(ApprovalDelegationPanel);
