/**
 * F04-T4: Leave analytics derived from history, calendar, and balances.
 */
import moment from "moment";
import {
  buildLeaveSummary,
  getWorkflowStatusMeta,
  isApprovedLeave,
  parseLeaveDate,
} from "views/hrms/components/leave/leave.utils";
import { isLwpLeaveType } from "config/leave-impact.utils";

function toNumber(value) {
  const n = parseFloat(value);
  return Number.isNaN(n) ? 0 : n;
}

export function buildLeaveAnalytics({ leaves, calendarLeaves, pendingLeaves, balances }) {
  const summary = buildLeaveSummary(leaves);
  const now = moment();
  const monthStart = now.clone().startOf("month");
  const monthEnd = now.clone().endOf("month");

  let lwpDays = 0;
  let upcomingDays = 0;
  let approvalPendingDays = 0;
  const utilizationByType = {};

  (leaves || []).forEach((leave) => {
    const code = leave.leaveTypeCode || leave.leave_type_code || "OTHER";
    const days = toNumber(leave.numberOfDays || leave.number_of_days);
    if (isApprovedLeave(leave)) {
      utilizationByType[code] = (utilizationByType[code] || 0) + days;
      if (isLwpLeaveType(code)) {
        lwpDays += days;
      }
      const from = parseLeaveDate(leave.applicationFromDate || leave.application_from_date);
      if (from && from.isAfter(now, "day")) {
        upcomingDays += days;
      }
    }
  });

  (pendingLeaves || []).forEach((leave) => {
    approvalPendingDays += toNumber(leave.numberOfDays || leave.number_of_days);
  });

  let entitlementTotal = 0;
  let balanceTotal = 0;
  (balances || []).forEach((row) => {
    entitlementTotal += toNumber(row.entitlement);
    balanceTotal += toNumber(row.balance);
  });

  const utilizationPct =
    entitlementTotal > 0
      ? Math.round(((entitlementTotal - balanceTotal) / entitlementTotal) * 100)
      : null;

  const calendarThisMonth = (calendarLeaves || []).filter((leave) => {
    const from = parseLeaveDate(leave.applicationFromDate || leave.application_from_date);
    return from && from.isBetween(monthStart, monthEnd, "day", "[]");
  });

  const coverageRiskDays = calendarThisMonth.length >= 3 ? "Elevated" : calendarThisMonth.length >= 1 ? "Moderate" : "Low";

  const typeChart = Object.keys(utilizationByType)
    .map((code) => ({
      code,
      days: Math.round(utilizationByType[code] * 10) / 10,
    }))
    .sort((a, b) => b.days - a.days)
    .slice(0, 6);

  const maxChartDays = typeChart.reduce((max, row) => Math.max(max, row.days), 0) || 1;

  return {
    ...summary,
    lwpDays: Math.round(lwpDays * 10) / 10,
    upcomingDays: Math.round(upcomingDays * 10) / 10,
    approvalPendingDays: Math.round(approvalPendingDays * 10) / 10,
    utilizationPct,
    coverageRiskDays,
    approvalSlaHint:
      summary.pending > 0 ? `${summary.pending} awaiting manager action` : "No pending approvals",
    typeChart: typeChart.map((row) => ({
      ...row,
      pct: Math.round((row.days / maxChartDays) * 100),
    })),
  };
}

export function buildApprovalSlaMetrics(pendingLeaves) {
  const list = pendingLeaves || [];
  if (list.length === 0) {
    return { avgDaysWaiting: 0, oldestDays: 0 };
  }
  const now = moment();
  const ages = list.map((leave) => {
    const submitted =
      parseLeaveDate(leave.submittedAt || leave.submitted_at || leave.createdAt || leave.created_at) ||
      parseLeaveDate(leave.applicationFromDate || leave.application_from_date);
    if (!submitted || !submitted.isValid()) return 0;
    return now.diff(submitted, "days");
  });
  const total = ages.reduce((sum, age) => sum + age, 0);
  return {
    avgDaysWaiting: Math.round((total / list.length) * 10) / 10,
    oldestDays: Math.max(...ages, 0),
  };
}
