export const UTIL_TONES = {
  available: { label: "Available", color: "#10b981", min: 0, max: 39 },
  light: { label: "Light", color: "#14b8a6", min: 40, max: 69 },
  balanced: { label: "Balanced", color: "#3b82f6", min: 70, max: 89 },
  high: { label: "High", color: "#f59e0b", min: 90, max: 100 },
  critical: { label: "Overbooked", color: "#ef4444", min: 101, max: 999 },
  leave: { label: "Leave / PTO", color: "#a855f7", min: 0, max: 0 },
};

export function getUtilizationTone(utilization, isOnLeave) {
  if (isOnLeave) return "leave";
  const u = utilization || 0;
  if (u > 100) return "critical";
  if (u >= 90) return "high";
  if (u >= 70) return "balanced";
  if (u >= 40) return "light";
  return "available";
}

export function getUtilizationColor(utilization) {
  return UTIL_TONES[getUtilizationTone(utilization)].color;
}

export function buildTeamHeatmap({
  employees,
  workItems,
  startMoment,
  horizonWeeks,
  holidayItems,
  reduceForHolidays,
  filterOptions,
  leaveMap,
  capacityOverrides,
  actualsByEmployee,
  showActuals,
}) {
  const days = getPlannerDays(startMoment.clone(), horizonWeeks);
  const holidayKeys = getHolidayDateKeys(holidayItems);
  const filtered = filterPlannerWorkItems(workItems, filterOptions, null);
  const roster = getPlannerRosterEmployees(employees);
  const rows = roster.map((employee) => {
    const dayCells = days.map((dayMoment) => {
      const dayKey = dayMoment.format("YYYY-MM-DD");
      const leaveInfo = getEmployeeLeaveOnDay(leaveMap, employee.id, dayKey);
      const isOnLeave = !!leaveInfo;
      const capacity = isOnLeave
        ? 0
        : getDayCapacityMinutesForEmployee(employee, dayMoment, {
            holidayKeys,
            reduceForHolidays,
            leaveKeys: null,
            capacityOverrides,
          });
      let allocated = 0;
      const items = [];

      filtered.forEach((item) => {
        if (isPlannerLeaveOrHolidayItem(item)) return;
        if (!employeeIdsMatch(getWorkItemEmployeeId(item), employee.id)) return;
        const start = getItemStartDate(item);
        if (!start) return;
        const end = getItemEndDate(item, start);
        const mins = getOverlappedMinutes(start, end, dayMoment);
        if (mins <= 0) return;
        allocated += mins;
        items.push({ item, minutes: mins });
      });

      const actualMinutes =
        showActuals && actualsByEmployee
          ? getActualMinutesForDay(actualsByEmployee, employee.id, dayKey)
          : 0;

      const utilization = isOnLeave
        ? 0
        : capacity > 0
          ? Math.round((allocated / capacity) * 100)
          : allocated > 0
            ? 100
            : 0;

      const varianceMins = showActuals ? actualMinutes - allocated : 0;

      return {
        dayKey,
        dayMoment,
        label: dayMoment.format("ddd"),
        dateLabel: dayMoment.format("DD MMM"),
        isWeekend: dayMoment.isoWeekday() >= 6,
        isHoliday: holidayKeys.has(dayKey),
        isOnLeave,
        leaveLabel: leaveInfo && leaveInfo.label,
        capacity,
        allocated,
        actualMinutes,
        varianceMins,
        free: Math.max(0, capacity - allocated),
        utilization,
        tone: getUtilizationTone(utilization, isOnLeave),
        items,
        hasBandwidth: !isOnLeave && capacity > 0 && allocated < capacity,
      };
    });

    const totalAllocated = dayCells.reduce((s, c) => s + c.allocated, 0);
    const totalCapacity = dayCells.reduce((s, c) => s + c.capacity, 0);
    const horizonUtil = Math.round((totalAllocated / Math.max(totalCapacity, 1)) * 100);
    const overbookedDays = dayCells.filter((c) => c.utilization > 100).length;
    const projectIds = new Set();
    filtered.forEach((item) => {
      if (!employeeIdsMatch(getWorkItemEmployeeId(item), employee.id)) return;
      if (item.projectId != null) projectIds.add(item.projectId);
    });

    return {
      employee,
      dayCells,
      totalAllocated,
      totalCapacity,
      horizonUtilization: horizonUtil,
      tone: getUtilizationTone(horizonUtil),
      freeMinutes: Math.max(0, totalCapacity - totalAllocated),
      overbookedDays,
      assignmentCount: filtered.filter((i) =>
        employeeIdsMatch(getWorkItemEmployeeId(i), employee.id)
      ).length,
      activeProjects: projectIds.size,
    };
  });

  rows.sort((a, b) => b.horizonUtilization - a.horizonUtilization);
  return { days, holidayKeys, rows };
}

export function buildPlanningAlerts({ heatmapRows, workItems, startMoment, horizonWeeks }) {
  const alerts = [];
  const now = dateUtils.getCurrentTime();
  const rangeEnd = startMoment.clone().add(horizonWeeks * 7 - 1, "days");

  (heatmapRows || []).forEach((row) => {
    if (row.horizonUtilization > 100) {
      alerts.push({
        id: `over-${row.employee.id}`,
        severity: "critical",
        title: `${row.employee.name} is over capacity`,
        detail: `${row.horizonUtilization}% utilization · ${row.overbookedDays} overbooked day(s)`,
        employeeId: row.employee.id,
      });
    } else if (row.horizonUtilization >= 90) {
      alerts.push({
        id: `high-${row.employee.id}`,
        severity: "warning",
        title: `${row.employee.name} is near limit`,
        detail: `${formatPlannerHours(row.freeMinutes)} remaining in horizon`,
        employeeId: row.employee.id,
      });
    } else if (row.horizonUtilization <= 45 && row.totalCapacity > 0) {
      alerts.push({
        id: `free-${row.employee.id}`,
        severity: "info",
        title: `${row.employee.name} has bandwidth`,
        detail: `${formatPlannerHours(row.freeMinutes)} available · good for new work`,
        employeeId: row.employee.id,
      });
    }
  });

  const unassigned = (workItems || []).filter((item) => {
    const eid = getWorkItemEmployeeId(item);
    return eid == null || eid === "";
  });
  if (unassigned.length > 0) {
    alerts.push({
      id: "unassigned",
      severity: "warning",
      title: `${unassigned.length} unassigned work item(s)`,
      detail: "Assign owners to stabilize the plan",
    });
  }

  let overdueCount = 0;
  (workItems || []).forEach((item) => {
    const end = getItemEndDate(item, getItemStartDate(item) || new Date());
    if (!end) return;
    const endM = dateUtils.convertDateToMoment(end);
    if (endM.isBefore(now) && !["COMPLETED", "CLOSED"].includes(normalizeWorkItemStatus(item.status))) {
      if (overdueCount >= 5) return;
      overdueCount += 1;
      alerts.push({
        id: `late-${item.id}`,
        severity: "critical",
        title: `Overdue: ${item.name || item.taskName || "Work item"}`,
        detail: `Due ${endM.format("DD MMM")} · ${item.projectName || "No project"}`,
        workItemId: item.id,
      });
    } else if (
      endM.isBefore(rangeEnd) &&
      endM.diff(now, "days") <= 3 &&
      !["COMPLETED", "CLOSED"].includes(normalizeWorkItemStatus(item.status))
    ) {
      alerts.push({
        id: `due-${item.id}`,
        severity: "warning",
        title: `Due soon: ${item.name || item.taskName || "Work item"}`,
        detail: `${endM.format("ddd DD MMM")} · ${getWorkItemEmployeeId(item) ? "assigned" : "unassigned"}`,
        workItemId: item.id,
      });
    }
  });

  const seen = new Set();
  return alerts.filter((a) => {
    if (seen.has(a.id)) return false;
    seen.add(a.id);
    return true;
  }).slice(0, 12);
}

export function buildProjectPortfolio(workItems, filterOptions, projectLookup) {
  const filtered = filterPlannerWorkItems(workItems, filterOptions, null);
  const map = new Map();

  filtered.forEach((item) => {
    const pid = item.projectId != null ? String(item.projectId) : "none";
    if (!map.has(pid)) {
      map.set(pid, {
        id: pid,
        detailsPath: resolveProjectDetailsPath(pid, projectLookup),
        name: item.projectName || "Non-project work",
        minutes: 0,
        items: [],
        people: new Set(),
        statuses: {},
      });
    }
    const row = map.get(pid);
    const start = getItemStartDate(item);
    const duration = item.estDurationInMins || 60;
    row.minutes += start ? item.estDurationInMins || duration : duration;
    row.items.push(item);
    const eid = getWorkItemEmployeeId(item);
    if (eid != null) row.people.add(String(eid));
    const st = normalizeWorkItemStatus(item.status);
    row.statuses[st] = (row.statuses[st] || 0) + 1;
  });

  return [...map.values()]
    .map((p) => ({
      ...p,
      peopleCount: p.people.size,
      people: undefined,
    }))
    .sort((a, b) => b.minutes - a.minutes);
}

export function buildTimelineSwimlanes({
  workItems,
  startMoment,
  horizonWeeks,
  viewMode,
  selectedEmployeeId,
  filterOptions,
}) {
  const days = getPlannerDays(startMoment.clone(), horizonWeeks);
  const totalDays = days.length;
  const rangeStart = days[0].clone().startOf("day");
  const rangeEnd = days[totalDays - 1].clone().endOf("day");
  const totalMs = rangeEnd.diff(rangeStart);
  const filtered = filterPlannerWorkItems(workItems, filterOptions, selectedEmployeeId);
  const lanesMap = new Map();

  filtered.forEach((item) => {
    const start = getItemStartDate(item);
    if (!start) return;
    const end = getItemEndDate(item, start);
    const { key, title } = resolvePlannerRowKeyAndTitle(item, viewMode);
    if (!lanesMap.has(key)) {
      lanesMap.set(key, {
        id: key,
        title,
        subtitle:
          viewMode === "WORK_ITEMS"
            ? [item.projectName, item.taskName].filter(Boolean).join(" · ")
            : viewMode === "PROJECTS"
              ? `${item.projectName || ""}`
              : item.projectName || item.taskName || "",
        segments: [],
        totalMinutes: 0,
      });
    }
    const lane = lanesMap.get(key);
    const startM = dateUtils.convertDateToMoment(start);
    const endM = dateUtils.convertDateToMoment(end);
    const dayWidthPct = 100 / Math.max(totalDays, 1);
    const spanPct = (endM.diff(startM) / totalMs) * 100;
    const leftPct = Math.max(0, (startM.diff(rangeStart) / totalMs) * 100);
    const widthPct = Math.min(
      100 - leftPct,
      Math.max(dayWidthPct * 0.92, spanPct, dayWidthPct)
    );
    const minutes = item.estDurationInMins || endM.diff(startM, "minutes");
    lane.totalMinutes += minutes;
    lane.segments.push({
      id: String(item.id),
      item,
      leftPct,
      widthPct,
      color: getWorkItemStatusColor(item.status),
      status: normalizeWorkItemStatus(item.status),
      label: item.name || item.taskActCategory || title,
      startLabel: startM.format("DD MMM"),
      endLabel: endM.format("DD MMM"),
      minutes,
    });
  });

  const lanes = [...lanesMap.values()].sort((a, b) => b.totalMinutes - a.totalMinutes);
  const todayPct = (() => {
    const now = dateUtils.getCurrentTime();
    if (now.isBefore(rangeStart) || now.isAfter(rangeEnd)) return null;
    return (now.diff(rangeStart) / totalMs) * 100;
  })();

  return { days, lanes, todayPct, rangeStart, rangeEnd };
}

export function buildGanttHourlyLanes({
  workItems,
  focusDayMoment,
  ganttAxis,
  ganttLevel,
  filterOptions,
  selectedEmployeeId,
}) {
  const slots = getPlannerHourSlots();
  const dayStart = focusDayMoment.clone().startOf("day");
  const rangeStart = dayStart.clone().hour(PLANNER_HOUR_START).minute(0).second(0);
  const rangeEnd = dayStart.clone().hour(PLANNER_HOUR_END).minute(0).second(0);
  const dayEnd = dayStart.clone().endOf("day");
  const totalHours = slots.length;
  const filtered = filterPlannerWorkItems(workItems, filterOptions, selectedEmployeeId);
  const groups = new Map();

  filtered.forEach((item) => {
    const start = getItemStartDate(item);
    if (!start) return;
    const end = getItemEndDate(item, start);
    const startM = dateUtils.convertDateToMoment(start);
    const endM = dateUtils.convertDateToMoment(end);
    if (endM.isBefore(dayStart) || startM.isAfter(dayEnd)) return;

    let groupKey;
    let groupLabel;
    if (ganttAxis === "PROJECT") {
      groupKey = String(item.projectId != null ? item.projectId : "none");
      groupLabel = item.projectName || "No project";
    } else {
      const eid = getWorkItemEmployeeId(item);
      groupKey = String(eid != null ? eid : "unassigned");
      groupLabel =
        item.employeeName ||
        (item.employee && item.employee.name) ||
        (eid ? `Employee ${eid}` : "Unassigned");
    }

    let barKey;
    let barLabel;
    if (ganttLevel === "TASK") {
      barKey = String(item.taskId != null ? item.taskId : item.id);
      barLabel = item.taskName || item.name || "Task";
    } else {
      barKey = String(item.id);
      barLabel = item.name || item.taskActCategory || "Work item";
    }

    if (!groups.has(groupKey)) {
      groups.set(groupKey, { id: groupKey, label: groupLabel, bars: new Map() });
    }
    const group = groups.get(groupKey);
    if (!group.bars.has(barKey)) {
      group.bars.set(barKey, {
        id: barKey,
        label: barLabel,
        items: [],
        segments: [],
      });
    }
    const bar = group.bars.get(barKey);
    const overlappedStart = startM.isAfter(rangeStart) ? startM : rangeStart;
    const overlappedEnd = endM.isBefore(rangeEnd) ? endM : rangeEnd;
    if (!overlappedEnd.isAfter(overlappedStart)) return;

    const offsetHours = overlappedStart.diff(rangeStart, "hours", true);
    const durationHours = Math.max(0.2, overlappedEnd.diff(overlappedStart, "hours", true));
    bar.items.push(item);
    bar.segments.push({
      item,
      offsetHours,
      durationHours,
      color: getWorkItemStatusColor(item.status),
      status: normalizeWorkItemStatus(item.status),
      projectName: item.projectName,
      taskName: item.taskName,
      minutes: item.estDurationInMins || 60,
    });
  });

  const now = dateUtils.getCurrentTime();
  let todayOffset = null;
  if (now.isSame(dayStart, "day") && !now.isBefore(rangeStart) && now.isBefore(rangeEnd)) {
    todayOffset = now.diff(rangeStart, "hours", true);
  }

  return {
    mode: "HOUR",
    slots,
    totalHours,
    totalDays: totalHours,
    rangeStart,
    focusDayMoment: dayStart,
    groups: [...groups.values()].map((g) => ({
      ...g,
      bars: [...g.bars.values()],
    })),
    todayOffset,
  };
}

export function buildGanttLanes({
  workItems,
  startMoment,
  horizonWeeks,
  ganttAxis,
  ganttLevel,
  filterOptions,
  selectedEmployeeId,
}) {
  const days = getPlannerDays(startMoment.clone(), horizonWeeks);
  const totalDays = days.length;
  const rangeStart = days[0].clone().startOf("day");
  const filtered = filterPlannerWorkItems(workItems, filterOptions, selectedEmployeeId);
  const groups = new Map();

  filtered.forEach((item) => {
    const start = getItemStartDate(item);
    if (!start) return;
    const end = getItemEndDate(item, start);
    let groupKey;
    let groupLabel;
    if (ganttAxis === "PROJECT") {
      groupKey = String(item.projectId != null ? item.projectId : "none");
      groupLabel = item.projectName || "No project";
    } else {
      const eid = getWorkItemEmployeeId(item);
      groupKey = String(eid != null ? eid : "unassigned");
      groupLabel =
        item.employeeName ||
        (item.employee && item.employee.name) ||
        (eid ? `Employee ${eid}` : "Unassigned");
    }

    let barKey;
    let barLabel;
    if (ganttLevel === "TASK") {
      barKey = String(item.taskId != null ? item.taskId : item.id);
      barLabel = item.taskName || item.name || "Task";
    } else {
      barKey = String(item.id);
      barLabel = item.name || item.taskActCategory || "Work item";
    }

    if (!groups.has(groupKey)) {
      groups.set(groupKey, { id: groupKey, label: groupLabel, bars: new Map() });
    }
    const group = groups.get(groupKey);
    if (!group.bars.has(barKey)) {
      group.bars.set(barKey, {
        id: barKey,
        label: barLabel,
        items: [],
        segments: [],
      });
    }
    const bar = group.bars.get(barKey);
    const startM = dateUtils.convertDateToMoment(start).startOf("day");
    const endM = dateUtils.convertDateToMoment(end).endOf("day");
    const offsetDays = startM.diff(rangeStart, "days", true);
    const durationDays = Math.max(endM.diff(startM, "days", true), 0.4);
    bar.items.push(item);
    bar.segments.push({
      item,
      offsetDays,
      durationDays,
      color: getWorkItemStatusColor(item.status),
      status: normalizeWorkItemStatus(item.status),
      projectName: item.projectName,
      taskName: item.taskName,
      minutes: item.estDurationInMins || PLANNER_DAY_CAPACITY_MINUTES / 2,
    });
  });

  const todayOffset = dateUtils.getCurrentTime().diff(rangeStart, "days", true);

  return {
    mode: "DAY",
    days,
    totalDays,
    rangeStart,
    groups: [...groups.values()].map((g) => ({
      ...g,
      bars: [...g.bars.values()],
    })),
    todayOffset,
  };
}

export function computePlanningHealthScore(kpis, alertCount) {
  let score = 100;
  if (kpis.avgUtilization > 95) score -= 25;
  else if (kpis.avgUtilization > 85) score -= 10;
  if (kpis.overbookedResources > 0) score -= 8 * Math.min(kpis.overbookedResources, 4);
  if (kpis.underbookedResources > kpis.rosterSize / 2) score -= 5;
  score -= Math.min(alertCount * 3, 24);
  return Math.max(0, Math.min(100, Math.round(score)));
}

