const STORAGE_KEY = 'famstack-guided-tour-v1';
const SESSION_HIDDEN_KEY = 'famstack-guided-tour-session-hidden';

const DEFAULT_STATE = {
  version: 1,
  permanentlyDismissed: false,
  shellCompleted: false,
  pagesCompleted: {},
};

function readJson(key, fallback) {
  try {
    const raw = localStorage.getItem(key);
    if (!raw) return fallback;
    return JSON.parse(raw);
  } catch (e) {
    return fallback;
  }
}

function writeJson(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch (e) {
    /* ignore */
  }
}

export function getGuidedTourState() {
  const stored = readJson(STORAGE_KEY, {});
  return { ...DEFAULT_STATE, ...stored };
}

export function saveGuidedTourState(patch) {
  const next = { ...getGuidedTourState(), ...patch };
  writeJson(STORAGE_KEY, next);
  return next;
}

export function isTourPermanentlyDismissed() {
  return getGuidedTourState().permanentlyDismissed === true;
}

export function setTourPermanentlyDismissed(value) {
  return saveGuidedTourState({ permanentlyDismissed: !!value });
}

export function isShellTourCompleted() {
  return getGuidedTourState().shellCompleted === true;
}

export function markShellTourCompleted() {
  return saveGuidedTourState({ shellCompleted: true });
}

export function isPageTourCompleted(pageKey) {
  const state = getGuidedTourState();
  return state.pagesCompleted && state.pagesCompleted[pageKey] === true;
}

export function markPageTourCompleted(pageKey) {
  const state = getGuidedTourState();
  const pagesCompleted = { ...(state.pagesCompleted || {}), [pageKey]: true };
  return saveGuidedTourState({ pagesCompleted });
}

export function getSessionHiddenPages() {
  try {
    const raw = sessionStorage.getItem(SESSION_HIDDEN_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch (e) {
    return [];
  }
}

export function hideTourForPageSession(pageKey) {
  const hidden = getSessionHiddenPages();
  if (hidden.indexOf(pageKey) >= 0) return hidden;
  const next = hidden.concat(pageKey);
  try {
    sessionStorage.setItem(SESSION_HIDDEN_KEY, JSON.stringify(next));
  } catch (e) {
    /* ignore */
  }
  return next;
}

export function isPageHiddenForSession(pageKey) {
  return getSessionHiddenPages().indexOf(pageKey) >= 0;
}

export function clearSessionHiddenForPage(pageKey) {
  const next = getSessionHiddenPages().filter((key) => key !== pageKey);
  try {
    sessionStorage.setItem(SESSION_HIDDEN_KEY, JSON.stringify(next));
  } catch (e) {
    /* ignore */
  }
}
