import React, { useCallback, useEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";

export const LUX_PAGE_HEADER_POPOVER_Z_INDEX = 1050;

const POPOVER_GAP_PX = 7;
const VIEWPORT_MARGIN_PX = 12;

export function getLuxPageHeaderPopoverStyle(anchorEl, align = "right") {
  if (!anchorEl || typeof window === "undefined") {
    return null;
  }

  const rect = anchorEl.getBoundingClientRect();
  const style = {
    position: "fixed",
    top: rect.bottom + POPOVER_GAP_PX,
    zIndex: LUX_PAGE_HEADER_POPOVER_Z_INDEX,
  };

  if (align === "left") {
    style.left = Math.max(VIEWPORT_MARGIN_PX, rect.left);
  } else {
    style.right = Math.max(VIEWPORT_MARGIN_PX, window.innerWidth - rect.right);
  }

  return style;
}

function LuxPageHeaderPopoverPortal({
  isOpen,
  anchorRef,
  align = "right",
  className,
  children,
  popoverRef,
  role,
  "aria-label": ariaLabel,
}) {
  const [style, setStyle] = useState(null);
  const internalRef = useRef(null);

  const setRefs = useCallback(
    (node) => {
      internalRef.current = node;
      if (!popoverRef) return;
      if (typeof popoverRef === "function") {
        popoverRef(node);
        return;
      }
      popoverRef.current = node;
    },
    [popoverRef]
  );

  const updatePosition = useCallback(() => {
    if (!isOpen || !anchorRef || !anchorRef.current) return;
    setStyle(getLuxPageHeaderPopoverStyle(anchorRef.current, align));
  }, [align, anchorRef, isOpen]);

  useEffect(() => {
    if (!isOpen) return undefined;
    updatePosition();
    window.addEventListener("resize", updatePosition);
    window.addEventListener("scroll", updatePosition, true);
    return () => {
      window.removeEventListener("resize", updatePosition);
      window.removeEventListener("scroll", updatePosition, true);
    };
  }, [isOpen, updatePosition]);

  if (!isOpen) {
    return null;
  }

  const popover = (
    <div
      ref={setRefs}
      className={classNames(className, "lux-page-header__popover--portal")}
      style={style || undefined}
      role={role}
      aria-label={ariaLabel}
    >
      {children}
    </div>
  );

  if (typeof document === "undefined") {
    return popover;
  }

  return createPortal(popover, document.body);
}

export default LuxPageHeaderPopoverPortal;
