import React, { Component } from "react";
import { createPortal } from "react-dom";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import {
  LEAVE_TYPE_OPTIONS,
  computeWorkingDaysBetween,
  buildLeaveCreatePayload,
  getSpecialLeaveUx,
  autoEndDateFromStart,
  canonicalizeLeaveTypeCode,
  maternityEntitlementDays,
  isFloatingLeaveType,
} from "./leave.utils";
import LeaveOverlapConflictBanner from "./LeaveOverlapConflictBanner";
import { leaveService } from "_services/leave.service";
import { leavePhase2Service } from "_services/leavePhase2.service";
import "../../leaveLuxForms.css";

const INITIAL = {
  leaveTypeCode: "AL",
  fromDate: null,
  toDate: null,
  halfDay: false,
  halfDaySession: "FIRST_HALF",
  reason: "",
  remarks: "",
  numberOfDays: 1,
  eventDate: "",
  childNumber: "",
};

const DRAWER_CLOSE_MS = 280;
const DEFAULT_WORKDAYS = [1, 2, 3, 4, 5];

function resolveLeaveTypeOptions(leaveTypes) {
  const configured = (leaveTypes || [])
    .filter((type) => type && type.active !== false && type.code)
    .map((type) => ({
      value: type.code,
      label: type.name || type.description || type.code,
    }));
  return configured.length > 0 ? configured : LEAVE_TYPE_OPTIONS;
}

class LeaveRequestDrawer extends Component {
  constructor(props) {
    super(props);
    this.state = {
      form: { ...INITIAL },
      workdays: DEFAULT_WORKDAYS,
      overlapError: null,
      checkingOverlap: false,
      submitting: false,
      visible: false,
      closing: false,
      floatingCatalogue: [],
      floatingCalendarId: null,
      floatingPickKey: "",
      floatingHint: null,
      floatingLoading: false,
    };
  }

  componentDidUpdate(prevProps) {
    if (this.props.open && !prevProps.open) {
      const options = resolveLeaveTypeOptions(this.props.leaveTypes);
      const leaveTypeCode = options[0] ? options[0].value : "AL";
      this.setState({
        form: { ...INITIAL, leaveTypeCode },
        overlapError: null,
        visible: true,
        closing: false,
        floatingCatalogue: [],
        floatingCalendarId: null,
        floatingPickKey: "",
        floatingHint: null,
        floatingLoading: false,
      });
      this.loadWorkingDayPattern();
      if (isFloatingLeaveType(leaveTypeCode)) {
        this.loadFloatingCatalogue();
      }
    }
    if (
      this.props.open &&
      this.props.employee &&
      prevProps.employee &&
      this.props.employee.id !== prevProps.employee.id
    ) {
      this.loadWorkingDayPattern();
    }
    if (!this.props.open && prevProps.open) {
      this.setState({ visible: false, closing: false });
    }
  }

  loadWorkingDayPattern = () => {
    const teamId = this.props.userTeamId || (this.props.employee && this.props.employee.userTeamId);
    const employeeId = this.props.employee && this.props.employee.id;
    if (!teamId || !leavePhase2Service.resolveWorkingDayPattern) return;
    leavePhase2Service
      .resolveWorkingDayPattern(teamId, employeeId)
      .then((payload) => {
        const workdays =
          payload && Array.isArray(payload.workdays) && payload.workdays.length
            ? payload.workdays.map(Number)
            : DEFAULT_WORKDAYS;
        this.setState((prev) => {
          const form = { ...prev.form };
          if (form.fromDate && form.toDate) {
            form.numberOfDays = computeWorkingDaysBetween(
              form.fromDate,
              form.toDate,
              form.halfDay,
              null,
              workdays
            );
          }
          return { workdays, form };
        }, () => {
          this.estimateDayCountFromApi();
        });
      })
      .catch(() => {
        /* keep Mon–Fri default */
      });
  };

  requestClose = () => {
    if (this.state.closing) return;
    this.setState({ closing: true });
    window.setTimeout(() => {
      this.setState({ visible: false, closing: false });
      this.props.onClose();
    }, DRAWER_CLOSE_MS);
  };

  updateForm = (patch) => {
    const leaveTypeChanged =
      patch &&
      Object.prototype.hasOwnProperty.call(patch, "leaveTypeCode") &&
      patch.leaveTypeCode !== this.state.form.leaveTypeCode;
    this.setState(
      (prev) => {
        const form = { ...prev.form, ...patch };
        const ux = getSpecialLeaveUx(form.leaveTypeCode);
        // CFA-LEAVE-W2/P6 — MAT child-aware auto end / PAT exact block.
        if (ux && form.fromDate && form.fromDate.isValid && form.fromDate.isValid()) {
          if (ux.daysByChildNumber || ux.autoEndDays) {
            const days = ux.daysByChildNumber
              ? maternityEntitlementDays(form.childNumber)
              : ux.autoEndDays;
            form.toDate = autoEndDateFromStart(form.fromDate, days);
            form.numberOfDays = days;
            form.halfDay = false;
          } else if (ux.exactDays) {
            form.toDate = autoEndDateFromStart(form.fromDate, ux.exactDays);
            form.numberOfDays = ux.exactDays;
            form.halfDay = false;
          }
        }
        const from = form.fromDate;
        const to = form.toDate || form.fromDate;
        // BE half-day math only applies to single-day ranges.
        if (from && to && from.isValid && to.isValid && !from.isSame(to, "day")) {
          form.halfDay = false;
        }
        if (
          from &&
          to &&
          !(ux && (ux.daysByChildNumber || ux.autoEndDays || ux.exactDays))
        ) {
          // Weekend/workday-only fallback until BE day-count returns (no unscoped holiday list).
          form.numberOfDays = computeWorkingDaysBetween(
            from,
            to,
            form.halfDay,
            null,
            prev.workdays
          );
        }
        const next = { form, overlapError: null };
        if (leaveTypeChanged && !isFloatingLeaveType(form.leaveTypeCode)) {
          next.floatingCatalogue = [];
          next.floatingCalendarId = null;
          next.floatingPickKey = "";
          next.floatingHint = null;
          next.floatingLoading = false;
        }
        return next;
      },
      () => {
        if (leaveTypeChanged && isFloatingLeaveType(this.state.form.leaveTypeCode)) {
          this.loadFloatingCatalogue();
        }
        this.scheduleDayCountRefresh();
        this.scheduleOverlapCheck();
      }
    );
  };

  /** CFA-LEAVE-P6 — load published floating/client catalogue for picker. */
  loadFloatingCatalogue = () => {
    const teamId = this.props.userTeamId || (this.props.employee && this.props.employee.userTeamId);
    if (!teamId || !leavePhase2Service.listCalendarVersions) {
      this.setState({
        floatingHint: "Floating catalogue unavailable — enter the holiday date manually.",
        floatingCatalogue: [],
        floatingLoading: false,
      });
      return;
    }
    this.setState({ floatingLoading: true, floatingHint: null });
    leavePhase2Service
      .listCalendarVersions(teamId)
      .then((versions) => {
        const list = Array.isArray(versions) ? versions : [];
        const published = list.filter(
          (v) =>
            v &&
            String(v.status || "").toUpperCase() === "PUBLISHED" &&
            String(v.countryCode || v.country || "IN").toUpperCase() === "IN"
        );
        const preferred =
          published.find((v) => String(v.code || "").includes("CFA-PH")) ||
          published[0] ||
          list.find((v) => String(v.status || "").toUpperCase() === "PUBLISHED") ||
          list[0];
        if (!preferred || !preferred.id) {
          this.setState({
            floatingLoading: false,
            floatingCatalogue: [],
            floatingCalendarId: null,
            floatingHint: "No published holiday calendar — enter floating date manually.",
          });
          return null;
        }
        return leavePhase2Service
          .listFloatingCatalogue(preferred.id)
          .then((entries) => ({ calendarId: preferred.id, entries }));
      })
      .then((result) => {
        if (!result) return;
        const entries = Array.isArray(result.entries)
          ? result.entries
          : result.entries && result.entries.payload
            ? result.entries.payload
            : [];
        const catalogue = (Array.isArray(entries) ? entries : []).filter(
          (e) => e && (e.holidayDate || e.date)
        );
        this.setState({
          floatingLoading: false,
          floatingCalendarId: result.calendarId,
          floatingCatalogue: catalogue,
          floatingHint: catalogue.length
            ? null
            : "Catalogue empty — enter a floating holiday date manually, or run P4 expand SQL.",
        });
      })
      .catch(() => {
        this.setState({
          floatingLoading: false,
          floatingCatalogue: [],
          floatingHint: "Could not load floating catalogue — enter the date manually.",
        });
      });
  };

  applyFloatingPick = (pickKey) => {
    const { floatingCatalogue } = this.state;
    const idx = Number(String(pickKey || "").split("|").pop());
    const entry =
      Number.isFinite(idx) && floatingCatalogue && floatingCatalogue[idx]
        ? floatingCatalogue[idx]
        : null;
    if (!entry) {
      this.setState({ floatingPickKey: pickKey });
      return;
    }
    const raw = entry.holidayDate || entry.date;
    const fromDate = raw ? dateUtils.convertDateToMoment(String(raw).slice(0, 10)) : null;
    this.setState({ floatingPickKey: pickKey });
    if (fromDate && fromDate.isValid && fromDate.isValid()) {
      this.updateForm({ fromDate, toDate: fromDate.clone(), halfDay: false });
    }
  };

  holidayTimer = null;
  overlapTimer = null;

  scheduleDayCountRefresh = () => {
    clearTimeout(this.holidayTimer);
    const { form } = this.state;
    if (!form.fromDate || !form.toDate) return;
    this.holidayTimer = setTimeout(() => {
      this.estimateDayCountFromApi();
    }, 250);
  };

  estimateDayCountFromApi = () => {
    const { employee, userTeamId } = this.props;
    const { form } = this.state;
    if (!employee || !form.fromDate || !form.toDate) return;

    const teamId = userTeamId || employee.userTeamId;
    leaveService
      .estimateDayCount({
        userTeamId: teamId,
        employeeId: employee.id,
        fromDate: form.fromDate.format("DD-MM-YYYY"),
        toDate: form.toDate.format("DD-MM-YYYY"),
        halfDay: form.halfDay,
      })
      .then((response) => {
        const payload = response && response.payload != null ? response.payload : response;
        let days = null;
        if (payload != null && typeof payload !== "object") {
          days = payload;
        } else if (payload && typeof payload === "object") {
          days =
            payload.numberOfDays != null
              ? payload.numberOfDays
              : payload.days != null
                ? payload.days
                : null;
        }
        if (days == null || days === "") return;
        const numberOfDays = Number(days);
        if (!Number.isFinite(numberOfDays)) return;
        this.setState((prev) => ({
          form: { ...prev.form, numberOfDays },
        }));
      })
      .catch(() => {
        // Keep client computeWorkingDaysBetween fallback.
      });
  };

  scheduleOverlapCheck = () => {
    clearTimeout(this.overlapTimer);
    const { employee } = this.props;
    const { form } = this.state;
    if (!employee || !form.fromDate || !form.toDate) return;

    this.overlapTimer = setTimeout(() => {
      this.checkOverlap();
    }, 400);
  };

  checkOverlap = () => {
    const { employee } = this.props;
    const { form } = this.state;
    if (!employee || !form.fromDate || !form.toDate) return;

        const fromDate = form.fromDate.format("DD-MM-YYYY");
    const toDate = form.toDate.format("DD-MM-YYYY");

    this.setState({ checkingOverlap: true, overlapError: null });
    leaveService
      .checkOverlap(employee.id, fromDate, toDate)
      .then((response) => {
        const hasOverlap = response && response.payload === true;
        this.setState({
          checkingOverlap: false,
          overlapError: hasOverlap
            ? "These dates overlap an existing leave from HR or Tracopus. Adjust dates or contact HR."
            : null,
        });
      })
      .catch(() => {
        this.setState({
          checkingOverlap: false,
          overlapError:
            "Unable to verify leave overlap right now. Fix your connection and try again before submitting.",
        });
      });
  };

  handleSubmit = (e) => {
    e.preventDefault();
    const { employee, onSubmit } = this.props;
    const { form, overlapError, checkingOverlap } = this.state;
    if (!employee || overlapError || checkingOverlap) return;
    if (!form.reason || !form.reason.trim()) {
      this.setState({ overlapError: "Please provide a reason for your leave." });
      return;
    }
    if (!form.fromDate || !form.toDate) return;

    const specialUx = getSpecialLeaveUx(form.leaveTypeCode);
    const payload = buildLeaveCreatePayload(
      {
        ...form,
        fromDate: form.fromDate.format("DD-MM-YYYY"),
        toDate: form.toDate.format("DD-MM-YYYY"),
        eventDate: form.eventDate
          ? (form.eventDate.format
            ? form.eventDate.format("DD-MM-YYYY")
            : form.eventDate)
          : null,
        childNumber: specialUx && specialUx.needsChildNumber ? form.childNumber : null,
      },
      employee,
      this.props.actorId
    );

    this.setState({ submitting: true });
    onSubmit(payload, () => {
      this.setState({ submitting: false });
    });
  };

  renderField = (label, icon, children) => (
    <label className="lux-leave-drawer__field">
      <span className="lux-leave-drawer__label">
        {icon && <i className={`fe ${icon}`} aria-hidden="true" />}
        {label}
      </span>
      {children}
    </label>
  );

  render() {
    const { open, employee, leaveTypes } = this.props;
    const {
      form,
      overlapError,
      checkingOverlap,
      submitting,
      visible,
      closing,
      floatingCatalogue,
      floatingPickKey,
      floatingHint,
      floatingLoading,
    } = this.state;
    const leaveTypeOptions = resolveLeaveTypeOptions(leaveTypes);
    const specialUx = getSpecialLeaveUx(form.leaveTypeCode);
    const specialCode = canonicalizeLeaveTypeCode(form.leaveTypeCode);
    const floatingSelected = isFloatingLeaveType(form.leaveTypeCode);
    const maternityDays =
      specialUx && specialUx.daysByChildNumber
        ? maternityEntitlementDays(form.childNumber)
        : specialUx && specialUx.autoEndDays
          ? specialUx.autoEndDays
          : null;

    if (!open && !visible) return null;

    return createPortal(
      <div
        className={classNames("lux-onb-drawer-backdrop lux-leave-drawer-backdrop", { "is-closing": closing })}
        role="presentation"
        onClick={this.requestClose}
      >
        <aside
          className={classNames("lux-onb-drawer lux-leave-drawer lux-onb-drawer--warning", {
            "is-closing": closing,
          })}
          role="dialog"
          aria-modal="true"
          aria-labelledby="leave-drawer-title"
          onClick={(event) => event.stopPropagation()}
        >
          <header className="lux-onb-drawer__head">
            <div className="lux-onb-drawer__head-main">
              <span className="lux-onb-drawer__category-icon" aria-hidden="true">
                <i className="fe fe-sun" />
              </span>
              <div className="lux-onb-drawer__head-copy">
                <span className="lux-leave-drawer__eyebrow">Leave · New request</span>
                <h2 id="leave-drawer-title">Apply for leave</h2>
                <p>
                  {employee ? `Submitting as ${employee.name}` : "Submit to your manager for approval."}
                </p>
              </div>
            </div>
            <button type="button" className="lux-onb-drawer__close" aria-label="Close" onClick={this.requestClose}>
              <i className="fe fe-x" aria-hidden="true" />
            </button>
          </header>

          <form className="lux-onb-drawer__body lux-leave-drawer__body" onSubmit={this.handleSubmit}>
            <div className="lux-leave-drawer__scroll">
              <LeaveOverlapConflictBanner
                message={overlapError}
                onDismiss={() => this.setState({ overlapError: null })}
              />

              {this.renderField(
                "Leave type",
                "fe-layers",
                <select
                  id="leave-type"
                  className="lux-leave-drawer__input"
                  value={form.leaveTypeCode}
                  onChange={(e) => this.updateForm({ leaveTypeCode: e.target.value })}
                >
                  {leaveTypeOptions.map((opt) => (
                    <option key={opt.value} value={opt.value}>
                      {opt.label}
                    </option>
                  ))}
                </select>
              )}

              {floatingSelected && (
                this.renderField(
                  "Floating / client holiday",
                  "fe-flag",
                  <div>
                    <select
                      id="leave-floating-pick"
                      className="lux-leave-drawer__input"
                      data-testid="leave-floating-catalogue"
                      value={floatingPickKey}
                      disabled={floatingLoading || !(floatingCatalogue && floatingCatalogue.length)}
                      onChange={(e) => this.applyFloatingPick(e.target.value)}
                    >
                      <option value="">
                        {floatingLoading
                          ? "Loading catalogue…"
                          : floatingCatalogue && floatingCatalogue.length
                            ? "Select from catalogue…"
                            : "No catalogue entries"}
                      </option>
                      {(floatingCatalogue || []).map((entry, idx) => {
                        const date = entry.holidayDate || entry.date;
                        const name = entry.name || entry.label || entry.category || "Holiday";
                        const key = `${date}|${idx}`;
                        return (
                          <option key={key} value={key}>
                            {date} — {name}
                          </option>
                        );
                      })}
                    </select>
                    {floatingHint && (
                      <p className="lux-leave-drawer__doc-note" role="note">
                        {floatingHint}
                      </p>
                    )}
                  </div>
                )
              )}

              <div className="lux-leave-drawer__grid">
                {this.renderField(
                  "From",
                  "fe-calendar",
                  <input
                    id="leave-from"
                    type="date"
                    className="lux-leave-drawer__input"
                    onChange={(e) =>
                      this.updateForm({
                        fromDate: e.target.value
                          ? dateUtils.convertDateToMoment(e.target.value)
                          : null,
                        toDate: form.toDate || dateUtils.convertDateToMoment(e.target.value),
                      })
                    }
                  />
                )}
                {this.renderField(
                  "To",
                  "fe-calendar",
                  <input
                    id="leave-to"
                    type="date"
                    className="lux-leave-drawer__input"
                    onChange={(e) =>
                      this.updateForm({
                        toDate: e.target.value ? dateUtils.convertDateToMoment(e.target.value) : null,
                      })
                    }
                  />
                )}
              </div>

              <div className="lux-leave-drawer__half-row">
                <label className="lux-leave-drawer__check">
                  <input
                    type="checkbox"
                    data-testid="leave-half-day"
                    checked={form.halfDay}
                    disabled={
                      !!(
                        form.fromDate &&
                        form.toDate &&
                        form.fromDate.isValid &&
                        form.toDate.isValid &&
                        !form.fromDate.isSame(form.toDate, "day")
                      )
                    }
                    onChange={(e) => this.updateForm({ halfDay: e.target.checked })}
                  />
                  <span>Half day (single date only)</span>
                </label>
                {form.halfDay && (
                  <select
                    className="lux-leave-drawer__input"
                    data-testid="leave-half-day-session"
                    value={form.halfDaySession}
                    onChange={(e) => this.updateForm({ halfDaySession: e.target.value })}
                  >
                    <option value="FIRST_HALF">First half</option>
                    <option value="SECOND_HALF">Second half</option>
                  </select>
                )}
              </div>

              <div className="lux-leave-drawer__computed">
                <i className="fe fe-clock" aria-hidden="true" />
                <span>Working days</span>
                <strong>{form.numberOfDays}</strong>
                {checkingOverlap && <em>Checking overlap…</em>}
              </div>

              {specialUx && specialUx.needsEventDate && (
                this.renderField(
                  specialCode === "PATERNITY" ? "Delivery / event date" : "Event date",
                  "fe-heart",
                  <input
                    id="leave-event-date"
                    type="date"
                    className="lux-leave-drawer__input"
                    required
                    onChange={(e) =>
                      this.updateForm({
                        eventDate: e.target.value
                          ? dateUtils.convertDateToMoment(e.target.value)
                          : "",
                      })
                    }
                  />
                )
              )}

              {specialUx && specialUx.needsChildNumber && (
                this.renderField(
                  maternityDays
                    ? `Child number (${maternityDays} calendar days)`
                    : "Child number",
                  "fe-user",
                  <select
                    id="leave-child-number"
                    className="lux-leave-drawer__input"
                    data-testid="leave-child-number"
                    value={form.childNumber || ""}
                    onChange={(e) => this.updateForm({ childNumber: e.target.value })}
                  >
                    <option value="">Select…</option>
                    <option value="1">1st child (182 days)</option>
                    <option value="2">2nd child (182 days)</option>
                    <option value="3">3rd child (84 days)</option>
                    <option value="4">4th+ child (84 days)</option>
                  </select>
                )
              )}

              <div className="lux-leave-drawer__doc-note" role="note">
                <i className="fe fe-paperclip" aria-hidden="true" />
                <span>
                  If proof is required (sick / maternity), submit saves a draft. Use{" "}
                  <strong>Link proof</strong> on My leave history (vault ID), then{" "}
                  <strong>Submit</strong>. HR can also mark linked under Document review.
                </span>
              </div>

              {this.renderField(
                "Reason",
                "fe-message-square",
                <textarea
                  id="leave-reason"
                  className="lux-leave-drawer__textarea"
                  rows={3}
                  value={form.reason}
                  onChange={(e) => this.updateForm({ reason: e.target.value })}
                  placeholder="Brief reason for your manager…"
                  required
                />
              )}

              {this.renderField(
                "Notes (optional)",
                "fe-edit-3",
                <input
                  id="leave-remarks"
                  type="text"
                  className="lux-leave-drawer__input"
                  value={form.remarks}
                  onChange={(e) => this.updateForm({ remarks: e.target.value })}
                />
              )}
            </div>

            <footer className="lux-onb-drawer__foot">
              <div className="lux-onb-drawer__foot-actions">
                <button type="button" className="lux-leave-drawer__btn is-ghost" onClick={this.requestClose}>
                  Cancel
                </button>
                <button
                  type="submit"
                  className="lux-leave-drawer__btn is-primary"
                  disabled={submitting || !!overlapError || checkingOverlap}
                >
                  {submitting ? "Submitting…" : "Submit for approval"}
                </button>
              </div>
            </footer>
          </form>
        </aside>
      </div>,
      document.body
    );
  }
}

export default LeaveRequestDrawer;
