import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { leaveService } from '_services/leave.service';
import { shouldUseLeaveManagement } from '_helpers/leave.config';
import { accessUtils } from '_helpers';
import {
  buildBalanceCardsFromApi,
  buildLeaveSummary,
  getLeaveTypeLabel,
} from './leave.utils';

function ProfileLeaveSummary({ employeeId, employeeName, userTeamId }) {
  const [loading, setLoading] = useState(false);
  const [balances, setBalances] = useState([]);
  const [leaves, setLeaves] = useState([]);
  const [leaveTypes, setLeaveTypes] = useState([]);

  const permission = accessUtils.getLeaveAccessControl();
  const moduleEnabled = shouldUseLeaveManagement();

  useEffect(() => {
    if (!employeeId || !moduleEnabled || !permission.viewEnabled) {
      setBalances([]);
      setLeaves([]);
      return;
    }

    setLoading(true);
    const typePromise = userTeamId
      ? leaveService.listLeaveTypes(userTeamId)
      : Promise.resolve({ payload: [] });

    Promise.all([
      leaveService.getBalances(employeeId),
      leaveService.listByEmployee(employeeId),
      typePromise,
    ])
      .then(([balRes, leaveRes, typesRes]) => {
        setBalances((balRes && balRes.payload) || []);
        setLeaves((leaveRes && leaveRes.payload) || []);
        setLeaveTypes((typesRes && typesRes.payload) || []);
        setLoading(false);
      })
      .catch(() => {
        setBalances([]);
        setLeaves([]);
        setLoading(false);
      });
  }, [employeeId, userTeamId, moduleEnabled, permission.viewEnabled]);

  if (!moduleEnabled || !permission.viewEnabled || !employeeId) {
    return null;
  }

  const summary = buildLeaveSummary(leaves);
  const cards = buildBalanceCardsFromApi(balances, leaveTypes).slice(0, 3);
  const label = employeeName ? `${employeeName}'s leave` : 'Leave';

  return (
    <section className="lux-profile-aside-card lux-profile-leave-card">
      <header className="lux-profile-aside-card__head">
        <span className="lux-profile-aside-card__icon" aria-hidden="true">
          <i className="fe fe-calendar" />
        </span>
        <h2 className="lux-profile-aside-card__title">{label}</h2>
      </header>
      <div className="lux-profile-aside-card__body">
        {loading ? (
          <p className="lux-profile-leave-card__loading">Loading leave…</p>
        ) : (
          <>
            <div className="lux-profile-leave-card__kpis">
              <article>
                <span>Pending</span>
                <strong>{summary.pending}</strong>
              </article>
              <article>
                <span>Approved</span>
                <strong>{summary.approved}</strong>
              </article>
              <article>
                <span>Days (YTD)</span>
                <strong>{summary.totalDaysApproved}</strong>
              </article>
            </div>
            {cards.length > 0 && (
              <ul className="lux-profile-leave-card__balances">
                {cards.map((card) => (
                  <li key={card.code}>
                    <span>{getLeaveTypeLabel(card.code, card.label)}</span>
                    <strong>
                      {card.hasEntitlement
                        ? `${card.available != null ? card.available : card.balance} avail`
                        : `${card.usedDays} used`}
                    </strong>
                  </li>
                ))}
              </ul>
            )}
            <Link to="/people/leaves" className="lux-profile-leave-card__link">
              Open leave management
              <i className="fe fe-arrow-right" aria-hidden />
            </Link>
          </>
        )}
      </div>
    </section>
  );
}

export default ProfileLeaveSummary;
