import { commonUtils } from "_helpers/common.utils";
import { buildAuditHeadline } from "_helpers/audit.utils";
import { AUDIT_WRITE_SOURCE } from "_constants/audit.constants";

const SENSITIVE_KEY_PATTERN =
  /password|passwd|secret|token|ssn|pan|aadhaar|bank|account|salary|compensation|apikey|api_key|credential/i;

const MAX_METADATA_DEPTH = 4;
const MAX_METADATA_KEYS = 24;
const MAX_STRING_LENGTH = 240;

export function redactAuditMetadata(metadata, depth = 0) {
  if (metadata == null || depth > MAX_METADATA_DEPTH) {
    return null;
  }
  if (Array.isArray(metadata)) {
    return metadata.slice(0, 8).map((item) => redactAuditMetadata(item, depth + 1));
  }
  if (typeof metadata !== "object") {
    return truncateAuditValue(metadata);
  }

  const redacted = {};
  let keyCount = 0;
  Object.entries(metadata).forEach(([key, value]) => {
    if (keyCount >= MAX_METADATA_KEYS) {
      return;
    }
    if (SENSITIVE_KEY_PATTERN.test(key)) {
      redacted[key] = "[REDACTED]";
      keyCount += 1;
      return;
    }
    if (value != null && typeof value === "object") {
      redacted[key] = redactAuditMetadata(value, depth + 1);
    } else {
      redacted[key] = truncateAuditValue(value);
    }
    keyCount += 1;
  });
  return redacted;
}

function truncateAuditValue(value) {
  if (value == null) {
    return value;
  }
  const str = String(value);
  if (str.length <= MAX_STRING_LENGTH) {
    return value;
  }
  return `${str.slice(0, MAX_STRING_LENGTH)}…`;
}

export function buildAuditNaturalKey({ actionType, entityType, entityId, correlationId }) {
  const parts = [
    entityType || "UNKNOWN",
    entityId != null ? String(entityId) : "na",
    actionType || "EVENT",
  ];
  if (correlationId) {
    parts.push(String(correlationId));
  }
  return parts.join(":");
}

export function buildAuditRecordRequest(input = {}) {
  const actorUserId = input.actorUserId || commonUtils.getCurrentUserId();
  const userTeamId = input.userTeamId || commonUtils.getCurrentUserTeamId();
  const actionType = input.actionType;
  const entityType = input.entityType;
  const entityId = input.entityId;
  const entityRef = input.entityRef;
  const correlationId = input.correlationId;
  const metadata = redactAuditMetadata(input.metadata);

  const headline =
    input.headline ||
    buildAuditHeadline({
      actionType,
      entityType,
      entityRef,
      entity: { type: entityType, id: entityId, ref: entityRef },
    });

  const eventNaturalKey =
    input.eventNaturalKey ||
    buildAuditNaturalKey({ actionType, entityType, entityId, correlationId });

  return {
    userTeamId,
    actorType: input.actorType || "USER",
    actorUserId,
    actionType,
    entityType,
    entityId,
    entityRef,
    headline,
    correlationId,
    eventNaturalKey,
    metadata,
    source: input.source || AUDIT_WRITE_SOURCE,
  };
}

const REDUX_ACTION_AUDIT_MAP = {
  CHECKLIST_ITEM_UPDATE_SUCCESS: { actionType: "UPDATED", entityType: "DELIVERABLE" },
  CONFIG_PROPERTY_UPDATE_SUCCESS: { actionType: "UPDATED", entityType: "ADMIN_CONFIG" },
};

export function mapReduxActionToAudit(action) {
  if (!action || !action.type) {
    return null;
  }
  const mapped = REDUX_ACTION_AUDIT_MAP[action.type];
  if (mapped) {
    return {
      ...mapped,
      metadata: { reduxAction: action.type },
    };
  }
  if (!action.type.endsWith("_SUCCESS")) {
    return null;
  }
  if (!/(CREATE|UPDATE|DELETE|APPROVE|REJECT|SUBMIT|SAVE|REVOKE|ENABLE|DISABLE)/i.test(action.type)) {
    return null;
  }
  const actionType = resolveActionTypeFromRedux(action.type);
  if (!actionType) {
    return null;
  }
  return {
    actionType,
    entityType: resolveEntityTypeFromRedux(action.type),
    metadata: { reduxAction: action.type },
  };
}

function resolveActionTypeFromRedux(type) {
  const upper = String(type).toUpperCase();
  if (upper.includes("APPROV")) return "APPROVED";
  if (upper.includes("REJECT")) return "REJECTED";
  if (upper.includes("SUBMIT")) return "SUBMITTED";
  if (upper.includes("DELETE") || upper.includes("REMOVE")) return "DELETED";
  if (upper.includes("CREATE") || upper.includes("ADD")) return "CREATED";
  if (upper.includes("REVOKE")) return "STATUS_CHANGED";
  if (upper.includes("UPDATE") || upper.includes("SAVE")) return "UPDATED";
  return null;
}

function resolveEntityTypeFromRedux(type) {
  const upper = String(type).toUpperCase();
  if (upper.includes("LEAVE")) return "LEAVE";
  if (upper.includes("TIMESHEET")) return "TIMESHEET_WEEK";
  if (upper.includes("ATTENDANCE")) return "ATTENDANCE";
  if (upper.includes("EMPLOYEE")) return "EMPLOYEE";
  if (upper.includes("PROJECT")) return "PROJECT";
  if (upper.includes("PAYROLL")) return "PAYROLL";
  if (upper.includes("APPROVAL") || upper.includes("DELEGAT")) return "APPROVAL";
  if (upper.includes("WORKSPACE") || upper.includes("NOTIFICATION")) return "WORKSPACE";
  if (upper.includes("ORG")) return "ORG_STRUCTURE";
  if (upper.includes("DOCUMENT")) return "DOCUMENT";
  if (upper.includes("ASSET")) return "ASSET";
  if (upper.includes("LIFECYCLE") || upper.includes("ONBOARD")) return "LIFECYCLE";
  if (upper.includes("CONFIG") || upper.includes("ADMIN")) return "ADMIN_CONFIG";
  return "ADMIN_CONFIG";
}

export function mergeBufferedAuditEvents(events, bufferedRows) {
  const base = Array.isArray(events) ? events : [];
  const buffered = (bufferedRows || []).map((row) => ({
    ...row,
    id: row.id || `client-${row.eventNaturalKey || Date.now()}`,
    createdDate: row.createdDate || row.createdAt || new Date().toISOString(),
    source: row.source || AUDIT_WRITE_SOURCE,
  }));
  return [...buffered, ...base];
}
