import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import ClientPortalNav from "./ClientPortalNav";

class ClientSignOffsPage extends Component {
  state = { loading: false, error: null, signOffs: [] };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client sign-offs");
    }
    this.load();
  }

  load = async () => {
    this.setState({ loading: true, error: null });
    try {
      const result = await clientPortalService.listSignOffs();
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          error: "Unable to load sign-offs. Sign in at /client/login.",
          signOffs: [],
        });
        return;
      }
      this.setState({
        loading: false,
        signOffs: (result.payload && result.payload.signOffs) || [],
      });
    } catch (e) {
      this.setState({ loading: false, error: (e && e.message) || "Unable to load sign-offs." });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage>
          <LuxRegisterEmptyState title="Client portal unavailable" description="Enable REACT_APP_USE_CLIENT_PORTAL_API." />
        </ClientLuxPage>
      );
    }
    const { loading, error, signOffs } = this.state;
    return (
      <ClientLuxPage
        testId="client-signoffs-page"
        className="lux-client-portal-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-check-circle",
          eyebrow: "Client portal",
          titleLead: "Sign-offs",
          titleAccent: "status",
          lede: "Project client sign-off status from governance gates.",
        }}
        heroActions={
          <ClientActionButton variant="primary" onClick={this.load} disabled={loading}>
            Refresh
          </ClientActionButton>
        }
      >
        <ClientPortalNav />
        {error ? (
          <LuxInlineAlert tone="warning" title="Unable to load sign-offs">
            {error}
          </LuxInlineAlert>
        ) : null}
        <ClientLuxPanel title="Sign-offs" icon="fe fe-list" meta={`${signOffs.length} project${signOffs.length === 1 ? "" : "s"}`}>
          {signOffs.length === 0 && !loading && !error ? (
            <LuxRegisterEmptyState title="No sign-offs" description="Permitted projects will appear here with sign-off status." showCreate={false} />
          ) : (
            <ul className="lux-client-portal-list lux-client-portal-list--plain">
              {signOffs.map((row) => (
                <li key={row.projectId}>
                  Project {row.projectId}: {row.signedOff ? "Signed off" : "Pending"} ({row.accessLevel})
                </li>
              ))}
            </ul>
          )}
        </ClientLuxPanel>
      </ClientLuxPage>
    );
  }
}

export default ClientSignOffsPage;
