import { shouldUseTimesheetApprovalWorkflow } from "./timesheetApproval.config";

const APPROVED_REPORTING_STATUSES = new Set([
  "APPROVED",
  "LOCKED",
  "PAYROLL_PROCESSED",
]);

function normalizeStatus(rawStatus) {
  if (!rawStatus) return null;
  return String(rawStatus).trim().toUpperCase().replace(/[\s-]+/g, "_");
}

function readStatus(entry) {
  if (!entry) return null;
  const raw = entry.status != null ? entry.status : entry.timesheetStatus;
  return normalizeStatus(raw);
}

/**
 * When org flag is off, every logged minute counts for reporting (legacy).
 * When flag is on, only approved TaskActivity / approved layers count.
 */
export function isTimesheetEntryApprovedForReporting(entry) {
  if (!shouldUseTimesheetApprovalWorkflow()) {
    return true;
  }
  if (!entry) {
    return false;
  }
  if (entry.isStaged === true) {
    return false;
  }
  if (entry.dataLayer === "APPROVED") {
    return true;
  }
  const status = readStatus(entry);
  if (status && APPROVED_REPORTING_STATUSES.has(status)) {
    return true;
  }
  if (!status && parseInt(entry.timesheetTimeMins || 0, 10) > 0) {
    const source = entry.source ? String(entry.source).toUpperCase() : "";
    return source === "TASK_BOARD" || source === "LEGACY" || source === "TIMESHEET";
  }
  return false;
}

export function getReportingMinutesFromEntry(entry) {
  if (!isTimesheetEntryApprovedForReporting(entry)) {
    return 0;
  }
  return parseInt((entry && entry.timesheetTimeMins) || 0, 10);
}

export function isTimesheetEntryPendingForReporting(entry) {
  if (!shouldUseTimesheetApprovalWorkflow() || !entry) {
    return false;
  }
  const mins = parseInt(entry.timesheetTimeMins || 0, 10);
  if (mins <= 0) {
    return false;
  }
  return !isTimesheetEntryApprovedForReporting(entry);
}
