import React, { Component } from "react";
import classNames from "classnames/bind";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { CHANGE_REQUEST_STATUSES, DECISION_TYPES, GATE_STAGES, isProjectGovernanceEnabled } from "config/project-governance.config";
import {
  buildChangeInsights,
  buildChangeMetrics,
  buildDecisionInsights,
  buildDecisionMetrics,
  buildGateComplianceModel,
  buildGateInsights,
  buildGateMetrics,
  buildIssueAgingModel,
  buildIssueInsights,
  buildIssueMetrics,
  buildProjectOptionsFromGates,
  buildRiskHeatmap,
  buildRiskInsights,
  buildRiskMetrics,
  CHANGE_STATUS_FILTER_OPTIONS,
  DECISION_TYPE_FILTER_OPTIONS,
  filterChangeRequests,
  filterDecisions,
  filterGates,
  GATE_STAGE_FILTER_OPTIONS,
  GATE_STATUS_FILTER_OPTIONS,
  validateChangeRequestPayload,
  validateDecisionPayload,
  validateGatePayload,
} from "config/project-governance.utils";
import { GOVERNANCE_PAGE_IDS, getGovernanceQuickLinks } from "config/project-governance-nav.config";
import { projectGovernanceService } from "_services/projectGovernance.service";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import { ResourcesActionButton } from "views/resources/components/ResourcesLuxShared";
import GovernanceLuxPage, {
  GovernanceLuxFilters,
  GovernanceLuxPanel,
} from "views/project/components/ProjectGovernanceLuxShared";
import ChangeRequestDrawer from "views/project/components/ChangeRequestDrawer";
import ChangeRequestRegister from "views/project/components/ChangeRequestRegister";
import DecisionRegister from "views/project/components/DecisionRegister";
import GateCompliancePanel from "views/project/components/GateCompliancePanel";
import GateDrawer from "views/project/components/GateDrawer";
import GateRegister from "views/project/components/GateRegister";
import GovernanceAnalyticsPanel from "views/project/components/GovernanceAnalyticsPanel";
import IssueAgingPanel from "views/project/components/IssueAgingPanel";
import IssueRegister from "views/project/components/IssueRegister";
import ProjectClosurePanel from "views/project/components/ProjectClosurePanel";
import RiskHeatmapPanel from "views/project/components/RiskHeatmapPanel";
import RiskRegister from "views/project/components/RiskRegister";

class ProjectGovernancePage extends Component {
  state = {
    risks: [],
    issues: [],
    actions: [],
    gates: [],
    decisions: [],
    changes: [],
    analytics: null,
    summary: null,
    loading: true,
    loadError: null,
    dataSource: null,
    gateQuery: "",
    gateStatusFilter: "ALL",
    gateStageFilter: "ALL",
    gateProjectFilter: "ALL",
    drawerOpen: false,
    selectedGate: null,
    creatingGate: false,
    createGateError: null,
    gateDraft: {
      name: "",
      projectId: "",
      stage: GATE_STAGES.DELIVER,
      approverName: "",
      dueDate: "",
      criteria: "",
    },
    decisionQuery: "",
    decisionTypeFilter: "ALL",
    changeQuery: "",
    changeStatusFilter: "ALL",
    changeDrawerOpen: false,
    selectedChange: null,
    creatingDecision: false,
    creatingChange: false,
    createDecisionError: null,
    createChangeError: null,
    decisionDraft: {
      title: "",
      projectId: "",
      type: DECISION_TYPES.GOVERNANCE,
      decidedBy: "",
      rationale: "",
      impact: "",
    },
    changeDraft: {
      title: "",
      projectId: "",
      requestedBy: "",
      impactSummary: "",
      baselineScope: "",
      proposedScope: "",
    },
  };

  componentDidMount() {
    const { pageHeaderNameChangeHandler } = this.props;
    if (pageHeaderNameChangeHandler) {
      pageHeaderNameChangeHandler("Governance");
    }
    this.loadData();
  }

  loadData = async () => {
    this.setState({ loading: true, loadError: null });
    try {
      const [risksRes, issuesRes, actionsRes, gatesRes, decisionsRes, changesRes, analyticsRes, summaryRes] =
        await Promise.all([
          projectGovernanceService.listRisks(),
          projectGovernanceService.listIssues(),
          projectGovernanceService.listIssueActions(),
          projectGovernanceService.listGates(),
          projectGovernanceService.listDecisions(),
          projectGovernanceService.listChangeRequests(),
          projectGovernanceService.getGovernanceAnalytics(),
          projectGovernanceService.getGovernanceSummary(),
        ]);
      this.setState({
        risks: risksRes.payload || [],
        issues: issuesRes.payload || [],
        actions: actionsRes.payload || [],
        gates: gatesRes.payload || [],
        decisions: decisionsRes.payload || [],
        changes: changesRes.payload || [],
        analytics: analyticsRes.payload,
        summary: summaryRes.payload,
        loading: false,
        dataSource: gatesRes.source || null,
      });
    } catch (e) {
      this.setState({ loading: false, loadError: "Unable to load governance data." });
    }
  };

  openGateDrawer = async (gate) => {
    const detail = await projectGovernanceService.getGate(gate.id);
    this.setState({
      drawerOpen: true,
      selectedGate: (detail && detail.payload) || gate,
    });
  };

  closeGateDrawer = () => {
    this.setState({ drawerOpen: false, selectedGate: null });
  };

  handleSaveGate = async (gateId, payload) => {
    await projectGovernanceService.updateGate(gateId, payload);
    await this.loadData();
  };

  handleApproveGate = async (gateId, payload) => {
    await projectGovernanceService.approveGate(gateId, payload);
    await this.loadData();
  };

  handleRejectGate = async (gateId, payload) => {
    await projectGovernanceService.rejectGate(gateId, payload);
    await this.loadData();
  };

  handleWaiveGate = async (gateId, payload) => {
    await projectGovernanceService.waiveGate(gateId, payload);
    await this.loadData();
  };

  openChangeDrawer = async (change) => {
    const detail = await projectGovernanceService.getChangeRequest(change.id);
    this.setState({
      changeDrawerOpen: true,
      selectedChange: (detail && detail.payload) || change,
    });
  };

  closeChangeDrawer = () => {
    this.setState({ changeDrawerOpen: false, selectedChange: null });
  };

  handleSaveChange = async (changeId, payload) => {
    await projectGovernanceService.updateChangeRequest(changeId, payload);
    await this.loadData();
  };

  handleApproveChange = async (changeId, payload) => {
    await projectGovernanceService.approveChangeRequest(changeId, payload);
    await this.loadData();
  };

  handleRejectChange = async (changeId, payload) => {
    await projectGovernanceService.rejectChangeRequest(changeId, payload);
    await this.loadData();
  };

  handleCreateDecision = async (e) => {
    e.preventDefault();
    const { decisionDraft, gates } = this.state;
    const project = buildProjectOptionsFromGates(gates).find((row) => row.id === decisionDraft.projectId);
    const payload = {
      ...decisionDraft,
      projectName: project && project.label,
      projectCode: project && project.code,
    };
    const validation = validateDecisionPayload(payload);
    if (!validation.valid) {
      this.setState({ createDecisionError: validation.reason });
      return;
    }
    this.setState({ creatingDecision: true, createDecisionError: null });
    try {
      await projectGovernanceService.createDecision(payload);
      await this.loadData();
      this.setState({
        creatingDecision: false,
        decisionDraft: {
          title: "",
          projectId: "",
          type: DECISION_TYPES.GOVERNANCE,
          decidedBy: "",
          rationale: "",
          impact: "",
        },
      });
    } catch (err) {
      this.setState({
        creatingDecision: false,
        createDecisionError: (err && err.message) || "Unable to log decision.",
      });
    }
  };

  handleCreateChange = async (e) => {
    e.preventDefault();
    const { changeDraft, gates } = this.state;
    const project = buildProjectOptionsFromGates(gates).find((row) => row.id === changeDraft.projectId);
    const payload = {
      ...changeDraft,
      projectName: project && project.label,
      projectCode: project && project.code,
      status: CHANGE_REQUEST_STATUSES.SUBMITTED,
      submittedAt: new Date().toISOString().slice(0, 10),
    };
    const validation = validateChangeRequestPayload(payload);
    if (!validation.valid) {
      this.setState({ createChangeError: validation.reason });
      return;
    }
    this.setState({ creatingChange: true, createChangeError: null });
    try {
      await projectGovernanceService.createChangeRequest(payload);
      await this.loadData();
      this.setState({
        creatingChange: false,
        changeDraft: {
          title: "",
          projectId: "",
          requestedBy: "",
          impactSummary: "",
          baselineScope: "",
          proposedScope: "",
        },
      });
    } catch (err) {
      this.setState({
        creatingChange: false,
        createChangeError: (err && err.message) || "Unable to submit change request.",
      });
    }
  };

  handleCreateGate = async (e) => {
    e.preventDefault();
    const { gateDraft, gates } = this.state;
    const project = buildProjectOptionsFromGates(gates).find((row) => row.id === gateDraft.projectId);
    const payload = {
      ...gateDraft,
      projectName: project && project.label,
      projectCode: project && project.code,
      status: "PENDING",
    };
    const validation = validateGatePayload(payload);
    if (!validation.valid) {
      this.setState({ createGateError: validation.reason });
      return;
    }

    this.setState({ creatingGate: true, createGateError: null });
    try {
      await projectGovernanceService.createGate(payload);
      await this.loadData();
      this.setState({
        creatingGate: false,
        gateDraft: {
          name: "",
          projectId: "",
          stage: GATE_STAGES.DELIVER,
          approverName: "",
          dueDate: "",
          criteria: "",
        },
      });
    } catch (err) {
      this.setState({
        creatingGate: false,
        createGateError: (err && err.message) || "Unable to create gate.",
      });
    }
  };

  render() {
    if (!isProjectGovernanceEnabled()) {
      return <PersonaAccessDenied featureLabel="Project governance" />;
    }

    const {
      risks,
      issues,
      actions,
      gates,
      summary,
      loading,
      loadError,
      dataSource,
      gateQuery,
      gateStatusFilter,
      gateStageFilter,
      gateProjectFilter,
      drawerOpen,
      selectedGate,
      creatingGate,
      createGateError,
      gateDraft,
      decisions,
      changes,
      analytics,
      decisionQuery,
      decisionTypeFilter,
      changeQuery,
      changeStatusFilter,
      changeDrawerOpen,
      selectedChange,
      creatingDecision,
      creatingChange,
      createDecisionError,
      createChangeError,
      decisionDraft,
      changeDraft,
    } = this.state;

    const riskMetrics = buildRiskMetrics(risks);
    const riskInsights = buildRiskInsights(riskMetrics, risks);
    const riskHeatmap = buildRiskHeatmap(risks);
    const issueMetrics = buildIssueMetrics(issues, actions);
    const issueInsights = buildIssueInsights(issueMetrics, issues);
    const issueAging = buildIssueAgingModel(issues);
    const gateMetrics = buildGateMetrics(gates);
    const gateInsights = buildGateInsights(gateMetrics, gates);
    const gateCompliance = buildGateComplianceModel(gates, { projectId: gateProjectFilter });
    const decisionMetrics = buildDecisionMetrics(decisions);
    const changeMetrics = buildChangeMetrics(changes);
    const decisionInsights = buildDecisionInsights(decisionMetrics, decisions);
    const changeInsights = buildChangeInsights(changeMetrics, changes);
    const gateProjectOptions = buildProjectOptionsFromGates(gates);
    const filteredDecisions = filterDecisions(decisions, { query: decisionQuery, type: decisionTypeFilter });
    const filteredChanges = filterChangeRequests(changes, { query: changeQuery, status: changeStatusFilter });
    const filteredGates = filterGates(gates, {
      query: gateQuery,
      status: gateStatusFilter,
      stage: gateStageFilter,
      projectId: gateProjectFilter === "ALL" ? undefined : gateProjectFilter,
    });

    const insights = [...gateInsights, ...decisionInsights, ...changeInsights, ...riskInsights, ...issueInsights].slice(0, 4);

    return (
      <GovernanceLuxPage
        pageId={GOVERNANCE_PAGE_IDS.GOVERNANCE}
        dataSource={dataSource}
        loading={loading}
        insights={insights}
        quickLinks={getGovernanceQuickLinks(GOVERNANCE_PAGE_IDS.GOVERNANCE)}
        kpiCards={
          summary
            ? [
                {
                  id: "gates",
                  label: "Gate compliance",
                  value: `${summary.gateComplianceRate || gateMetrics.complianceRate}%`,
                  tone: "green",
                  icon: "fe fe-shield",
                },
                {
                  id: "pending",
                  label: "Pending gates",
                  value: summary.gatesPending != null ? summary.gatesPending : gateMetrics.pending,
                  tone: "amber",
                  icon: "fe fe-clock",
                },
                {
                  id: "risk",
                  label: "Open risks",
                  value: summary.openRisks,
                  tone: "rose",
                  icon: "fe fe-alert-triangle",
                },
                {
                  id: "iss",
                  label: "Open issues",
                  value: summary.openIssues,
                  tone: "violet",
                  icon: "fe fe-alert-circle",
                },
                {
                  id: "chg",
                  label: "Pending changes",
                  value: summary.changesPending != null ? summary.changesPending : changeMetrics.pending,
                  tone: "blue",
                  icon: "fe fe-git-pull-request",
                },
              ]
            : []
        }
        heroActions={
          <ResourcesActionButton to="/project/timeline" icon="fe fe-bar-chart-2" variant="ghost">
            Delivery Gantt
          </ResourcesActionButton>
        }
      >
        <GovernanceLuxPanel
          title="Governance analytics"
          meta={
            analytics
              ? `Health ${analytics.healthScore} · ${analytics.criticalPathDays || 0}d critical path`
              : "Delivery health dashboard"
          }
          icon="fe fe-activity"
          accent="violet"
          className="lux-gov-panel--analytics"
        >
          <GovernanceAnalyticsPanel analytics={analytics} loading={loading} />
        </GovernanceLuxPanel>

        <GovernanceLuxPanel
          title="Project closure readiness"
          meta="Live checklist · initiate closure · executive sign-off"
          icon="fe fe-lock"
          accent="rose"
          className="lux-gov-panel--closure"
        >
          <ProjectClosurePanel
            projectOptions={buildProjectOptionsFromGates(gates)}
            onClosed={() => this.loadData()}
          />
        </GovernanceLuxPanel>

        {loadError ? (
          <LuxRegisterEmptyState title="Unable to load governance hub" copy={loadError} onRetry={this.loadData} />
        ) : (
          <>
            <GovernanceLuxPanel
              title="Stage gate compliance"
              meta={`${gateCompliance.overallApprovedPct}% approved · ${gateMetrics.pending} pending`}
              icon="fe fe-shield"
              accent="gates"
              className="lux-gov-panel--gates"
            >
              <GateCompliancePanel model={gateCompliance} loading={loading} />
            </GovernanceLuxPanel>

            <GovernanceLuxPanel
              title="Stage gates"
              meta={`${filteredGates.length} visible · approve or waive pending gates`}
              icon="fe fe-check-circle"
              accent="violet"
            >
              <GovernanceLuxFilters>
                <label className="lux-gov-filters__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    placeholder="Search gate, project, approver, or criteria"
                    value={gateQuery}
                    onChange={(e) => this.setState({ gateQuery: e.target.value })}
                  />
                </label>
                <select
                  className="lux-gov-filters__select"
                  value={gateProjectFilter}
                  onChange={(e) => this.setState({ gateProjectFilter: e.target.value })}
                >
                  {gateProjectOptions.map((option) => (
                    <option key={option.id} value={option.id}>
                      {option.label}
                    </option>
                  ))}
                </select>
                <div className="lux-gov-filters__chips" role="tablist" aria-label="Gate status">
                  {GATE_STATUS_FILTER_OPTIONS.map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      role="tab"
                      aria-selected={gateStatusFilter === option.id}
                      className={classNames("lux-gov-filters__chip", { "is-active": gateStatusFilter === option.id })}
                      onClick={() => this.setState({ gateStatusFilter: option.id })}
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
                <div className="lux-gov-filters__chips" role="tablist" aria-label="Gate stage">
                  {GATE_STAGE_FILTER_OPTIONS.map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      role="tab"
                      aria-selected={gateStageFilter === option.id}
                      className={classNames("lux-gov-filters__chip", { "is-active": gateStageFilter === option.id })}
                      onClick={() => this.setState({ gateStageFilter: option.id })}
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </GovernanceLuxFilters>

              <form className="lux-gov-gate-form" onSubmit={this.handleCreateGate}>
                <p className="lux-gov-gate-form__title">Add stage gate</p>
                <div className="lux-gov-gate-form__fields">
                  <label>
                    Gate name
                    <input
                      value={gateDraft.name}
                      onChange={(e) => this.setState({ gateDraft: { ...gateDraft, name: e.target.value } })}
                    />
                  </label>
                  <label>
                    Project
                    <select
                      value={gateDraft.projectId}
                      onChange={(e) => this.setState({ gateDraft: { ...gateDraft, projectId: e.target.value } })}
                    >
                      <option value="">Select project</option>
                      {gateProjectOptions
                        .filter((row) => row.id !== "ALL")
                        .map((option) => (
                          <option key={option.id} value={option.id}>
                            {option.label}
                          </option>
                        ))}
                    </select>
                  </label>
                  <label>
                    Stage
                    <select
                      value={gateDraft.stage}
                      onChange={(e) => this.setState({ gateDraft: { ...gateDraft, stage: e.target.value } })}
                    >
                      {Object.values(GATE_STAGES).map((value) => (
                        <option key={value} value={value}>
                          {value}
                        </option>
                      ))}
                    </select>
                  </label>
                  <label>
                    Approver
                    <input
                      value={gateDraft.approverName}
                      onChange={(e) => this.setState({ gateDraft: { ...gateDraft, approverName: e.target.value } })}
                    />
                  </label>
                  <label>
                    Due
                    <input
                      type="date"
                      value={gateDraft.dueDate}
                      onChange={(e) => this.setState({ gateDraft: { ...gateDraft, dueDate: e.target.value } })}
                    />
                  </label>
                  <button type="submit" className="lux-gov-gate-form__submit" disabled={creatingGate}>
                    {creatingGate ? "Adding…" : "Add gate"}
                  </button>
                </div>
                <label className="lux-gov-gate-form__wide">
                  Criteria
                  <textarea
                    rows={2}
                    value={gateDraft.criteria}
                    onChange={(e) => this.setState({ gateDraft: { ...gateDraft, criteria: e.target.value } })}
                  />
                </label>
                {createGateError ? <p className="lux-gov-gate-form__error">{createGateError}</p> : null}
              </form>

              <GateRegister rows={filteredGates} loading={loading} onSelect={this.openGateDrawer} />
            </GovernanceLuxPanel>

            <GovernanceLuxPanel
              title="Risk heatmap"
              meta={`${riskHeatmap.rows.length} projects`}
              icon="fe fe-grid"
              accent="amber"
            >
              <RiskHeatmapPanel heatmap={riskHeatmap} loading={loading} />
              <RiskRegister rows={risks} loading={loading} onSelect={() => {}} />
            </GovernanceLuxPanel>

            <GovernanceLuxPanel
              title="Issue aging"
              meta={`${issueAging.openCount} open · ${issueMetrics.actionSlaRate}% action SLA`}
              icon="fe fe-bar-chart"
              accent="rose"
            >
              <IssueAgingPanel model={issueAging} loading={loading} />
              <IssueRegister rows={issues} loading={loading} onSelect={() => {}} />
            </GovernanceLuxPanel>

            <GovernanceLuxPanel
              title="Decision log"
              meta={`${filteredDecisions.length} visible · ${decisionMetrics.recent30Days} in last 30 days`}
              icon="fe fe-book-open"
              accent="indigo"
            >
              <GovernanceLuxFilters>
                <label className="lux-gov-filters__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    placeholder="Search decision, rationale, or owner"
                    value={decisionQuery}
                    onChange={(e) => this.setState({ decisionQuery: e.target.value })}
                  />
                </label>
                <div className="lux-gov-filters__chips" role="tablist" aria-label="Decision type">
                  {DECISION_TYPE_FILTER_OPTIONS.map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      role="tab"
                      aria-selected={decisionTypeFilter === option.id}
                      className={classNames("lux-gov-filters__chip", {
                        "is-active": decisionTypeFilter === option.id,
                      })}
                      onClick={() => this.setState({ decisionTypeFilter: option.id })}
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </GovernanceLuxFilters>

              <form className="lux-gov-decision-form" onSubmit={this.handleCreateDecision}>
                <p className="lux-gov-decision-form__title">Log steering decision</p>
                <div className="lux-gov-decision-form__fields">
                  <label>
                    Title
                    <input
                      value={decisionDraft.title}
                      onChange={(e) => this.setState({ decisionDraft: { ...decisionDraft, title: e.target.value } })}
                    />
                  </label>
                  <label>
                    Project
                    <select
                      value={decisionDraft.projectId}
                      onChange={(e) => this.setState({ decisionDraft: { ...decisionDraft, projectId: e.target.value } })}
                    >
                      <option value="">Select project</option>
                      {gateProjectOptions
                        .filter((row) => row.id !== "ALL")
                        .map((option) => (
                          <option key={option.id} value={option.id}>
                            {option.label}
                          </option>
                        ))}
                    </select>
                  </label>
                  <label>
                    Type
                    <select
                      value={decisionDraft.type}
                      onChange={(e) => this.setState({ decisionDraft: { ...decisionDraft, type: e.target.value } })}
                    >
                      {Object.values(DECISION_TYPES).map((value) => (
                        <option key={value} value={value}>
                          {value}
                        </option>
                      ))}
                    </select>
                  </label>
                  <label>
                    Decided by
                    <input
                      value={decisionDraft.decidedBy}
                      onChange={(e) => this.setState({ decisionDraft: { ...decisionDraft, decidedBy: e.target.value } })}
                    />
                  </label>
                  <button type="submit" className="lux-gov-decision-form__submit" disabled={creatingDecision}>
                    {creatingDecision ? "Logging…" : "Log decision"}
                  </button>
                </div>
                <label className="lux-gov-decision-form__wide">
                  Rationale
                  <textarea
                    rows={2}
                    value={decisionDraft.rationale}
                    onChange={(e) => this.setState({ decisionDraft: { ...decisionDraft, rationale: e.target.value } })}
                  />
                </label>
                {createDecisionError ? <p className="lux-gov-decision-form__error">{createDecisionError}</p> : null}
              </form>

              <DecisionRegister rows={filteredDecisions} loading={loading} />
            </GovernanceLuxPanel>

            <GovernanceLuxPanel
              title="Change requests"
              meta={`${filteredChanges.length} visible · ${changeMetrics.pending} awaiting approval`}
              icon="fe fe-git-pull-request"
              accent="blue"
            >
              <GovernanceLuxFilters>
                <label className="lux-gov-filters__search">
                  <i className="fe fe-search" aria-hidden="true" />
                  <input
                    type="search"
                    placeholder="Search change, requester, or impact"
                    value={changeQuery}
                    onChange={(e) => this.setState({ changeQuery: e.target.value })}
                  />
                </label>
                <div className="lux-gov-filters__chips" role="tablist" aria-label="Change status">
                  {CHANGE_STATUS_FILTER_OPTIONS.map((option) => (
                    <button
                      key={option.id}
                      type="button"
                      role="tab"
                      aria-selected={changeStatusFilter === option.id}
                      className={classNames("lux-gov-filters__chip", {
                        "is-active": changeStatusFilter === option.id,
                      })}
                      onClick={() => this.setState({ changeStatusFilter: option.id })}
                    >
                      {option.label}
                    </button>
                  ))}
                </div>
              </GovernanceLuxFilters>

              <form className="lux-gov-change-form" onSubmit={this.handleCreateChange}>
                <p className="lux-gov-change-form__title">Submit change request</p>
                <div className="lux-gov-change-form__fields">
                  <label>
                    Title
                    <input
                      value={changeDraft.title}
                      onChange={(e) => this.setState({ changeDraft: { ...changeDraft, title: e.target.value } })}
                    />
                  </label>
                  <label>
                    Project
                    <select
                      value={changeDraft.projectId}
                      onChange={(e) => this.setState({ changeDraft: { ...changeDraft, projectId: e.target.value } })}
                    >
                      <option value="">Select project</option>
                      {gateProjectOptions
                        .filter((row) => row.id !== "ALL")
                        .map((option) => (
                          <option key={option.id} value={option.id}>
                            {option.label}
                          </option>
                        ))}
                    </select>
                  </label>
                  <label>
                    Requested by
                    <input
                      value={changeDraft.requestedBy}
                      onChange={(e) => this.setState({ changeDraft: { ...changeDraft, requestedBy: e.target.value } })}
                    />
                  </label>
                  <button type="submit" className="lux-gov-change-form__submit" disabled={creatingChange}>
                    {creatingChange ? "Submitting…" : "Submit change"}
                  </button>
                </div>
                <label className="lux-gov-change-form__wide">
                  Proposed scope
                  <textarea
                    rows={2}
                    value={changeDraft.proposedScope}
                    onChange={(e) => this.setState({ changeDraft: { ...changeDraft, proposedScope: e.target.value } })}
                  />
                </label>
                {createChangeError ? <p className="lux-gov-change-form__error">{createChangeError}</p> : null}
              </form>

              <ChangeRequestRegister rows={filteredChanges} loading={loading} onSelect={this.openChangeDrawer} />
            </GovernanceLuxPanel>
          </>
        )}

        <GateDrawer
          open={drawerOpen}
          gate={selectedGate}
          onClose={this.closeGateDrawer}
          onSave={this.handleSaveGate}
          onApprove={this.handleApproveGate}
          onReject={this.handleRejectGate}
          onWaive={this.handleWaiveGate}
        />

        <ChangeRequestDrawer
          open={changeDrawerOpen}
          change={selectedChange}
          onClose={this.closeChangeDrawer}
          onSave={this.handleSaveChange}
          onApprove={this.handleApproveChange}
          onReject={this.handleRejectChange}
        />
      </GovernanceLuxPage>
    );
  }
}

export default ProjectGovernancePage;
