import React, { Component } from "react";
import PersonaAccessDenied from "components/persona/PersonaAccessDenied";
import { isKnowledgeRcaEnabled } from "config/knowledge-rca.config";
import { LESSONS_PAGE_META } from "config/knowledge-rca-nav.config";
import { knowledgeRcaService } from "_services/knowledgeRca.service";
import KnowledgeLuxPage, {
  KnowledgeActionButton,
  KnowledgeInsightPanel,
  KnowledgeLuxPanel,
} from "views/knowledge/components/KnowledgeLuxShared";
import LessonRegister from "views/knowledge/components/LessonRegister";
import PatternInsightsPanel from "views/knowledge/components/PatternInsightsPanel";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";

class LessonsLearnedPage extends Component {
  state = {
    loading: true,
    loadError: null,
    dataSource: null,
    lessons: [],
    kpiCards: [],
    insights: [],
    analytics: null,
    statusFilter: "ALL",
    busy: false,
  };

  componentDidMount() {
    this.loadData();
  }

  loadData = async () => {
    const { statusFilter } = this.state;
    this.setState({ loading: true, loadError: null });
    try {
      const filters = statusFilter !== "ALL" ? { status: statusFilter } : {};
      const result = await knowledgeRcaService.getLessonsOverview(filters);
      const payload = result.payload || {};
      this.setState({
        loading: false,
        dataSource: result.source,
        lessons: payload.lessons || [],
        kpiCards: payload.kpiCards || [],
        insights: payload.insights || [],
        analytics: { patterns: payload.patterns || [] },
      });
    } catch (error) {
      this.setState({
        loading: false,
        loadError: (error && error.message) || "Unable to load lessons.",
      });
    }
  };

  handlePublish = async (lesson) => {
    this.setState({ busy: true });
    try {
      await knowledgeRcaService.publishLesson(lesson.id);
      await this.loadData();
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Unable to publish lesson." });
    } finally {
      this.setState({ busy: false });
    }
  };

  handleExport = async () => {
    try {
      const result = await knowledgeRcaService.exportLessonsCsv({});
      const blob = new Blob([result.payload || ""], { type: "text/csv;charset=utf-8;" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "lessons-learned.csv";
      link.click();
      URL.revokeObjectURL(url);
    } catch (error) {
      this.setState({ loadError: (error && error.message) || "Export failed." });
    }
  };

  render() {
    if (!isKnowledgeRcaEnabled()) {
      return <PersonaAccessDenied featureLabel="Lessons learned" />;
    }

    const { loading, loadError, dataSource, lessons, kpiCards, insights, analytics, statusFilter, busy } = this.state;

    return (
      <KnowledgeLuxPage
        pageMeta={LESSONS_PAGE_META}
        shellTitle="Lessons learned"
        dataSource={dataSource}
        kpiCards={kpiCards}
        loading={loading}
        pageHeaderNameChangeHandler={this.props.pageHeaderNameChangeHandler}
        onRefresh={this.loadData}
        refreshLoading={loading}
        heroActions={<><KnowledgeActionButton icon="fe fe-download" onClick={this.handleExport}>
              Export CSV
            </KnowledgeActionButton>
          </>}
      >
        {loadError ? <LuxInlineAlert message={loadError} onDismiss={() => this.setState({ loadError: null })} /> : null}
        <KnowledgeInsightPanel insights={insights} loading={loading} />
        <PatternInsightsPanel analytics={analytics} loading={loading} />

        <KnowledgeLuxPanel
          title="Lesson register"
          meta="Linked tickets, risks, and projects"
          icon="fe fe-book-open"
          accent="emerald"
          featured
          actions={
            <select
              className="lux-krca-filter"
              value={statusFilter}
              onChange={(e) => this.setState({ statusFilter: e.target.value }, this.loadData)}
            >
              <option value="ALL">All statuses</option>
              <option value="draft">Draft</option>
              <option value="published">Published</option>
            </select>
          }
        >
          <LessonRegister lessons={lessons} loading={loading} onPublish={this.handlePublish} busy={busy} />
        </KnowledgeLuxPanel>
      </KnowledgeLuxPage>
    );
  }
}

export default LessonsLearnedPage;
