import React, { Component } from "react";
import { getQuestionLayoutSpan } from "../../feedbackForm.utils";
import LuxFeedbackQuestionLabel from "./LuxFeedbackQuestionLabel";

class DecisionOptionSelectInput extends Component {
  onChange = (value) => {
    this.props.onChange({ ...this.props.questionConfig, answer: value });
  };

  render() {
    const { questionConfig, readonly } = this.props;
    if (!questionConfig) return null;
    const span = getQuestionLayoutSpan(questionConfig.type);
    const groupName = `lux-fb-bool-${questionConfig.id}`;

    return (
      <div className={`lux-fb-q lux-fb-q--${span}`}>
        <div className="lux-fb-q__card">
          <LuxFeedbackQuestionLabel questionConfig={questionConfig} />
          <div className="lux-fb-bool-options">
            <div className="radioField">
              <input
                type="radio"
                className="radio"
                name={groupName}
                id={`${groupName}-yes`}
                disabled={readonly}
                onChange={() => this.onChange(true)}
                checked={questionConfig.answer === true}
              />
              <label htmlFor={`${groupName}-yes`}>Yes</label>
            </div>
            <div className="radioField">
              <input
                type="radio"
                className="radio"
                name={groupName}
                id={`${groupName}-no`}
                disabled={readonly}
                onChange={() => this.onChange(false)}
                checked={questionConfig.answer === false}
              />
              <label htmlFor={`${groupName}-no`}>No</label>
            </div>
          </div>
        </div>
      </div>
    );
  }
}
export default DecisionOptionSelectInput;
