import React, { Component, createRef } from "react";
import classNames from "classnames/bind";
import envconfig from "env.config";
import { brandUtils } from "_helpers";
import {
  BRAND_TAGLINE_TEXT,
  attachBrandTaglineFit,
} from "_helpers/brandTaglineFit.utils";

class BrandNameLogo extends Component {
  logoWrapRef = createRef();
  taglineShellRef = createRef();
  taglineRef = createRef();
  taglineFitCleanup = null;

  componentDidMount() {
    window.requestAnimationFrame(() => this.bindTaglineFit());
  }

  componentDidUpdate(prevProps) {
    if (
      prevProps.tagline !== this.props.tagline ||
      prevProps.variant !== this.props.variant ||
      prevProps.showTagline !== this.props.showTagline ||
      prevProps.showAiTagline !== this.props.showAiTagline
    ) {
      this.bindTaglineFit();
    }
  }

  componentWillUnmount() {
    this.unbindTaglineFit();
  }

  unbindTaglineFit = () => {
    if (this.taglineFitCleanup) {
      this.taglineFitCleanup();
      this.taglineFitCleanup = null;
    }
  };

  bindTaglineFit = () => {
    this.unbindTaglineFit();
    if (!this.shouldShowTagline()) {
      return;
    }

    const logoEl = this.logoWrapRef.current;
    const shellEl = this.taglineShellRef.current;
    const taglineEl = this.taglineRef.current;
    if (!logoEl || !shellEl || !taglineEl) {
      return;
    }

    this.taglineFitCleanup = attachBrandTaglineFit(logoEl, shellEl, taglineEl);
  };

  getVariant = () => this.props.variant || "sidebar";

  renderLogo = () => {
    const variant = this.getVariant();

    return (
      <img
        src={brandUtils.getTracopusLogoSrc(variant)}
        alt={brandUtils.getAppBrandName()}
        className={classNames("app-brand-logo", this.props.logoClassName, {
          "app-brand-logo--sidebar": variant === "sidebar",
          "app-brand-logo--auth": variant === "auth",
          "app-brand-logo--rail": variant === "rail",
          "app-brand-logo--card": variant === "card",
          "app-brand-logo--with-pro": variant !== "auth",
        })}
      />
    );
  };

  renderTextBrand = () => {
    const variant = this.getVariant();

    return (
      <span
        className={classNames({
          "auth-screen__brand-name": variant === "auth",
          "brand-name": variant !== "auth",
        })}
      >
        {envconfig.APP_NAME}
      </span>
    );
  };

  renderProBadges = () => {
    if (this.props.showProBadge === false) return null;
    if (brandUtils.tracopusLogoIncludesPro(this.getVariant())) return null;

    const variant = this.getVariant();
    const isAuth = variant === "auth";
    const isMainPage = variant === "sidebar" || variant === "rail";
    const showRegistered = !brandUtils.isTracopusApp() || isMainPage;

    return (
      <>
        {showRegistered && (
          <span className={isAuth ? "auth-screen__brand-reg" : "brand-registered"}>&#174;</span>
        )}
        <span
          className={isAuth ? "auth-screen__brand-pro" : "brand-pro"}
          title={`${envconfig.APP_NAME} Pro edition`}
        >
          Pro
        </span>
      </>
    );
  };

  renderBrandContent = () => (
    <>
      {brandUtils.isTracopusApp() ? this.renderLogo() : this.renderTextBrand()}
      {this.renderProBadges()}
    </>
  );

  shouldShowTagline = () => {
    const { showTagline } = this.props;
    if (showTagline === false || !brandUtils.isTracopusApp()) return false;
    return this.getVariant() !== "rail";
  };

  renderTagline = () => {
    if (!this.shouldShowTagline()) return null;

    const { tagline, showAiTagline } = this.props;
    const variant = this.getVariant();
    const text = tagline || BRAND_TAGLINE_TEXT;

    return (
      <div className="app-brand-wordmark__footer">
        <span className="app-brand-wordmark__rule" aria-hidden="true" />
        <span className="app-brand-tagline-shell" ref={this.taglineShellRef}>
          <span
            ref={this.taglineRef}
            className={classNames("app-brand-tagline", `app-brand-tagline--${variant}`)}
          >
            {text}
          </span>
        </span>
        {showAiTagline ? (
          <span className="app-brand-tagline-ai" aria-label="AI-enabled">
            AI-enabled
          </span>
        ) : null}
      </div>
    );
  };

  renderBrandBlock = (wrapperClassName, className) => {
    const useWordmarkLayout = this.shouldShowTagline() && brandUtils.isTracopusApp();

    return (
      <div
        className={classNames("app-brand-block", wrapperClassName, {
          "app-brand-block--wordmark": useWordmarkLayout,
        })}
      >
        {useWordmarkLayout ? (
          <div className="app-brand-wordmark__mark">
            <div className="app-brand-wordmark__logo-col">
              <div
                ref={this.logoWrapRef}
                className={classNames(
                  "brand-logo-wrapper",
                  "brand-logo-wrapper--image",
                  "brand-logo-wrapper--logo-only",
                  className
                )}
              >
                {this.renderLogo()}
              </div>
              {this.renderTagline()}
            </div>
            {this.renderProBadges()}
          </div>
        ) : (
          <div
            className={classNames(
              "brand-logo-wrapper",
              { "brand-logo-wrapper--image": brandUtils.isTracopusApp() },
              className
            )}
          >
            {this.renderBrandContent()}
          </div>
        )}
      </div>
    );
  };

  render() {
    const { className, wrapperClassName } = this.props;
    const variant = this.getVariant();

    if (variant === "auth") {
      return (
        <div className={classNames("auth-screen__brand-name-row", wrapperClassName)}>
          {this.renderBrandBlock(null, className)}
        </div>
      );
    }

    if (variant === "rail") {
      return (
        <div className={classNames("brand-logo-wrapper", "brand-logo-wrapper--rail", className)}>
          {this.renderBrandContent()}
        </div>
      );
    }

    return (
      <div className={classNames("text-center mb-1", wrapperClassName)}>
        <div className="header-brand">{this.renderBrandBlock(null, className)}</div>
      </div>
    );
  }
}

BrandNameLogo.defaultProps = {
  showTagline: true,
  showAiTagline: false,
};

export default BrandNameLogo;
