import React from "react";
import LuxBackNav from "views/common/fragments/LuxBackNav";

function LifecycleBackNav({ lifecycle = "onboarding", label }) {
  const backPath = lifecycle === "offboarding" ? "/people/offboarding" : "/people/onboarding";
  const backLabel = lifecycle === "offboarding" ? "Offboarding queue" : "Onboarding queue";

  return (
    <LuxBackNav
      to={backPath}
      destinationLabel={backLabel}
      currentLabel={label}
      navClassName="lux-onb-back-nav"
    />
  );
}

export default LifecycleBackNav;
