import { employeeIdsMatch } from "../planner/planner.utils";

/** Build a map of id variants → display name for taskboard roster lookups. */
export function buildEmployeeNameLookup(employeeLists) {
  const map = new Map();
  const lists = Array.isArray(employeeLists) ? employeeLists : [employeeLists];
  lists.filter(Boolean).forEach((list) => {
    (list || []).forEach((emp) => {
      if (!emp) return;
      const name = emp.name || emp.fullName || emp.label;
      if (!name) return;
      [emp.id, emp.userId, emp.employeeId, emp.value].forEach((key) => {
        if (key != null && key !== "") {
          map.set(String(key), name);
        }
      });
    });
  });
  return map;
}

export function resolveEmployeeName(employeeId, lookup, employees) {
  if (employeeId == null || employeeId === "") return null;
  if (lookup && lookup.size) {
    const hit = lookup.get(String(employeeId));
    if (hit) return hit;
  }
  if (employees && employees.length) {
    const match = employees.find((e) => employeeIdsMatch(e.id, employeeId));
    if (match && match.name) return match.name;
    const byUser = employees.find(
      (e) => e.userId != null && employeeIdsMatch(e.userId, employeeId)
    );
    if (byUser && byUser.name) return byUser.name;
  }
  return null;
}

export function collectTaskboardTeamIds(taskboardItems, extraTeamId) {
  const ids = new Set();
  if (extraTeamId != null && extraTeamId !== "") ids.add(String(extraTeamId));
  (taskboardItems || []).forEach((board) => {
    if (board && board.userTeamId != null && board.userTeamId !== "") {
      ids.add(String(board.userTeamId));
    }
  });
  return Array.from(ids);
}
