/**
 * Shared luxury action button — canonical CTA for all modules.
 * Module wrappers should only add a tone class (e.g. lux-recruiting-action).
 */
import React from "react";
import { Link } from "react-router-dom";
import classNames from "classnames/bind";

export default function LuxActionButton({
  to,
  href,
  onClick,
  children,
  label,
  icon,
  variant = "primary",
  type = "button",
  disabled = false,
  className,
  moduleClass,
  testId,
  "data-testid": dataTestId,
  form,
}) {
  const resolvedTestId = testId || dataTestId;
  const classes = classNames(
    "lux-onb-action",
    moduleClass,
    `lux-onb-action--${variant}`,
    className
  );
  const text = children != null ? children : label;
  const content = icon ? (
    <>
      <i className={icon} aria-hidden="true" />
      <span>{text}</span>
    </>
  ) : (
    text
  );

  if (to && !onClick) {
    return (
      <Link to={to} className={classes} data-testid={resolvedTestId}>
        {content}
      </Link>
    );
  }
  if (href) {
    return (
      <a href={href} className={classes} data-testid={resolvedTestId}>
        {content}
      </a>
    );
  }
  return (
    <button
      type={type}
      form={form}
      className={classes}
      onClick={onClick}
      disabled={disabled}
      data-testid={resolvedTestId}
    >
      {content}
    </button>
  );
}
