import React from "react";
import classNames from "classnames/bind";

export const PROJECT_FORM_LEFT_SECTIONS = ["projectBasics", "clientStudy", "serviceScope"];
export const PROJECT_FORM_RIGHT_SECTIONS = [
  "fieldworkSample",
  "scopeSettings",
  "teamEstimates",
  "taskAccess",
];

export function FormCluster({ title, hint, icon, children, compact }) {
  return (
    <div className={classNames("lux-project-form__cluster", { "is-compact": compact })}>
      {(title || hint) && (
        <header className="lux-project-form__cluster-head">
          {icon && <i className={icon} aria-hidden="true" />}
          <div>
            {title && <strong>{title}</strong>}
            {hint && <span>{hint}</span>}
          </div>
        </header>
      )}
      <div className="lux-project-form__cluster-body">{children}</div>
    </div>
  );
}

/** Responsive field grid — 2 cols wizard, up to 4 cols in full form. */
export function FieldGrid({ cols = 2, children }) {
  return (
    <div
      className={classNames(
        "lux-project-form__grid",
        cols === 1 && "lux-project-form__grid--1",
        cols === 3 && "lux-project-form__grid--3",
        cols === 4 && "lux-project-form__grid--4"
      )}
    >
      {children}
    </div>
  );
}

export function FieldCell({ span = 1, children }) {
  return (
    <div
      className={classNames(
        "lux-project-form__cell",
        span === "full" && "is-full",
        span === 2 && "is-wide",
        span === 3 && "is-triple"
      )}
    >
      {children}
    </div>
  );
}

export function gridCols(isFullForm, wizardCols = 2, fullCols = 4) {
  return isFullForm ? fullCols : wizardCols;
}
