import React, { Component } from "react";
import LuxRegisterEmptyState from "views/common/fragments/LuxRegisterEmptyState";
import LuxInlineAlert from "views/common/fragments/LuxInlineAlert";
import ClientLuxPage, {
  ClientActionButton,
  ClientLuxPanel,
} from "views/client/components/ClientLuxShared";
import { isClientPortalEnabled } from "config/client-portal.config";
import { clientPortalService } from "_services/clientPortal.service";
import { commonUtils } from "_helpers";
import ClientPortalNav from "./ClientPortalNav";

/**
 * W23 — Client portal IdP / session login.
 */
class ClientLoginPage extends Component {
  state = {
    email: "",
    externalSubject: "",
    idToken: "",
    loading: false,
    error: null,
    session: null,
  };

  componentDidMount() {
    if (this.props.pageHeaderNameChangeHandler) {
      this.props.pageHeaderNameChangeHandler("Client login");
    }
  }

  handleChange = (field) => (event) => {
    this.setState({ [field]: event.target.value });
  };

  handleLogin = async () => {
    const { email, externalSubject, idToken } = this.state;
    this.setState({ loading: true, error: null, session: null });
    try {
      const result = await clientPortalService.resolveSession({
        email: String(email || "").trim(),
        externalSubject: String(externalSubject || "").trim() || undefined,
        idToken: String(idToken || "").trim() || undefined,
        userTeamId: commonUtils.getCurrentUserTeamId(),
      });
      if (!result || result.source === "api-error") {
        this.setState({
          loading: false,
          error: "Login failed — mapping missing, IdP misconfigured, or API unavailable.",
        });
        return;
      }
      this.setState({ loading: false, session: result.payload });
      if (this.props.history) {
        this.props.history.push("/client/projects");
      }
    } catch (e) {
      this.setState({ loading: false, error: (e && e.message) || "Login failed." });
    }
  };

  render() {
    if (!isClientPortalEnabled()) {
      return (
        <ClientLuxPage testId="client-login-flag-off">
          <LuxRegisterEmptyState
            variant="employees"
            title="Client portal unavailable"
            description="Enable REACT_APP_USE_CLIENT_PORTAL_API."
          />
        </ClientLuxPage>
      );
    }

    const { email, externalSubject, idToken, loading, error, session } = this.state;

    return (
      <ClientLuxPage
        testId="client-login-page"
        className="lux-client-portal-page"
        pageMeta={{
          tone: "indigo",
          icon: "fe fe-log-in",
          eyebrow: "Client portal",
          titleLead: "Client",
          titleAccent: "login",
          lede: "IdP token exchange resolves mapped client portal users only.",
        }}
        heroActions={
          <ClientActionButton variant="primary" onClick={this.handleLogin} disabled={loading}>
            {loading ? "Signing in…" : "Sign in"}
          </ClientActionButton>
        }
      >
        <ClientPortalNav />
        <ClientLuxPanel title="Credentials" icon="fe fe-key">
          <label className="form-label" htmlFor="client-login-email">
            Email
          </label>
          <input
            id="client-login-email"
            className="form-control mb-2"
            value={email}
            onChange={this.handleChange("email")}
            placeholder="client@example.com"
          />
          <label className="form-label" htmlFor="client-login-subject">
            External subject (optional)
          </label>
          <input
            id="client-login-subject"
            className="form-control mb-2"
            value={externalSubject}
            onChange={this.handleChange("externalSubject")}
          />
          <label className="form-label" htmlFor="client-login-token">
            IdP id token (required when IdP enabled)
          </label>
          <textarea
            id="client-login-token"
            className="form-control mb-2"
            rows={3}
            value={idToken}
            onChange={this.handleChange("idToken")}
          />
        </ClientLuxPanel>
        {error ? (
          <LuxInlineAlert tone="warning" title="Login failed">
            {error}
          </LuxInlineAlert>
        ) : null}
        {session ? (
          <LuxInlineAlert tone="success" title="Signed in" testId="client-login-session">
            Signed in as client user {session.clientUserId} (account {session.accountId}).
          </LuxInlineAlert>
        ) : null}
      </ClientLuxPage>
    );
  }
}

export default ClientLoginPage;
