import React from "react";
import Skeleton, { SkeletonTheme } from "react-loading-skeleton";
import { LUX_SKELETON_THEME } from "./luxSkeleton.constants";
import { getRegisterSkeletonRowKeys } from "./luxRegisterListSkeleton.utils";

/**
 * Card grid skeleton for project / employee grid list views.
 */
export default function LuxRegisterGridSkeleton({
  count,
  pageSize,
  itemClassName = "lux-project-grid__item",
  height = 360,
}) {
  const keys = getRegisterSkeletonRowKeys(count, pageSize);

  return (
    <SkeletonTheme
      baseColor={LUX_SKELETON_THEME.baseColor}
      highlightColor={LUX_SKELETON_THEME.highlightColor}
    >
      {keys.map((key) => (
        <div key={key} className={itemClassName} aria-hidden="true">
          <Skeleton height={height} borderRadius={20} style={{ width: "100%", display: "block" }} />
        </div>
      ))}
    </SkeletonTheme>
  );
}
