import React, { useCallback, useEffect, useState } from "react";
import classNames from "classnames/bind";
import { getAppBrandName } from "_helpers/brand.utils";
import ProfileSection from "./ProfileSection";
import {
  ProfileChannelCard,
  ProfileSettingToggle,
  ProfileSettingsBanner,
} from "./ProfileSettingsShared";
import {
  DEFAULT_NOTIFICATIONS,
  readProfileNotifications,
  writeProfileNotifications,
} from "./profileSettings.storage";

const CATEGORY_ITEMS = [
  {
    key: "notifyTimesheet",
    icon: "fe fe-clock",
    label: "Timesheet reminders",
    description: "Missing entries, submission deadlines, and approvals",
  },
  {
    key: "notifyLeave",
    icon: "fe fe-sun",
    label: "Leave & attendance",
    description: "Requests, approvals, and balance updates",
  },
  {
    key: "notifyProject",
    icon: "fe fe-layers",
    label: "Projects & tasks",
    description: "Assignments, due dates, and status changes",
  },
  {
    key: "notifyHr",
    icon: "fe fe-users",
    label: "HR announcements",
    description: "Policy updates and company-wide notices",
  },
  {
    key: "notifySecurity",
    icon: "fe fe-shield",
    label: "Security alerts",
    description: "Password, login, and permission changes",
  },
];

function ProfileNotificationsView({ employee, readOnly }) {
  const [settings, setSettings] = useState(DEFAULT_NOTIFICATIONS);
  const disabled = !!readOnly;

  useEffect(() => {
    if (employee && employee.id) {
      setSettings(readProfileNotifications(employee.id));
    }
  }, [employee]);

  const updateSetting = useCallback(
    (key, value) => {
      if (disabled || !employee || !employee.id) return;
      setSettings((prev) => {
        const next = { ...prev, [key]: value };
        writeProfileNotifications(employee.id, next);
        return next;
      });
    },
    [disabled, employee]
  );

  if (!employee) return null;

  const appName = getAppBrandName();
  const anyChannelOn = settings.channelEmail || settings.channelInApp;

  return (
    <div className="profile-settings profile-notifications lux-settings-tab__stack">
      <ProfileSettingsBanner readOnly={disabled} variant="preview" />

      <ProfileSection
        title="Delivery channels"
        subtitle="Where alerts can reach you"
        icon="fe fe-send"
      >
        <div className="profile-channel-grid">
          <ProfileChannelCard
            icon="fe fe-mail"
            label="Email"
            description="Summaries and actionable links"
            enabled={settings.channelEmail}
            disabled={disabled}
            onChange={(v) => updateSetting("channelEmail", v)}
          />
          <ProfileChannelCard
            icon="fe fe-bell"
            label="In-app"
            description="Bell menu and profile alerts"
            enabled={settings.channelInApp}
            disabled={disabled}
            onChange={(v) => updateSetting("channelInApp", v)}
          />
          <ProfileChannelCard
            icon="fe fe-smartphone"
            label="Mobile push"
            description={`Requires the ${appName} mobile app`}
            enabled={settings.channelPush}
            disabled
            comingSoon
          />
        </div>
        {!anyChannelOn && !disabled && (
          <p className="profile-settings-inline-hint is-warning">
            <i className="fe fe-alert-triangle" aria-hidden="true" />
            Turn on at least one channel to receive notifications.
          </p>
        )}
      </ProfileSection>

      <ProfileSection
        title="Alert categories"
        subtitle="Choose what you want to hear about"
        icon="fe fe-filter"
      >
        <div className="profile-setting-list">
          {CATEGORY_ITEMS.map((item) => (
            <ProfileSettingToggle
              key={item.key}
              icon={item.icon}
              label={item.label}
              description={item.description}
              checked={settings[item.key]}
              disabled={disabled || !anyChannelOn}
              onChange={(v) => updateSetting(item.key, v)}
            />
          ))}
        </div>
      </ProfileSection>

      <ProfileSection
        title="Quiet hours"
        subtitle="Pause non-critical alerts overnight"
        icon="fe fe-moon"
      >
        <div className="profile-setting-list">
          <ProfileSettingToggle
            icon="fe fe-moon"
            label="Enable quiet hours"
            description="Security alerts still come through"
            checked={settings.quietHoursEnabled}
            disabled={disabled || !anyChannelOn}
            onChange={(v) => updateSetting("quietHoursEnabled", v)}
          />
          <div
            className={classNames("profile-quiet-hours", {
              "is-disabled": disabled || !settings.quietHoursEnabled || !anyChannelOn,
            })}
          >
            <label className="profile-quiet-hours__field">
              <span>From</span>
              <input
                type="time"
                className="profile-quiet-hours__input"
                value={settings.quietHoursStart}
                disabled={disabled || !settings.quietHoursEnabled || !anyChannelOn}
                onChange={(e) => updateSetting("quietHoursStart", e.target.value)}
              />
            </label>
            <label className="profile-quiet-hours__field">
              <span>Until</span>
              <input
                type="time"
                className="profile-quiet-hours__input"
                value={settings.quietHoursEnd}
                disabled={disabled || !settings.quietHoursEnabled || !anyChannelOn}
                onChange={(e) => updateSetting("quietHoursEnd", e.target.value)}
              />
            </label>
          </div>
        </div>
      </ProfileSection>
    </div>
  );
}

export default ProfileNotificationsView;
