import { workspaceService } from "_services/workspace.service";
import { universalApprovalService } from "_services/universalApproval.service";
import { UNIVERSAL_APPROVAL_STATUSES } from "config/universal-approval.config";
import { apiErrorResult } from "config/mock-fallback.utils";

function asArray(result) {
  if (!result || result.source === "api-error") {
    return [];
  }
  return Array.isArray(result.payload) ? result.payload : [];
}

function dedupeById(rows) {
  const seen = new Set();
  return (rows || []).filter((row) => {
    if (!row || !row.id || seen.has(row.id)) {
      return false;
    }
    seen.add(row.id);
    return true;
  });
}

export function mapApprovalToWorkItem(item) {
  const isHigh = String(item.priority || "").toUpperCase() === "HIGH";
  return {
    id: `approval-work-${item.id}`,
    title: item.subject || `${item.domainLabel || item.domain} approval`,
    subtitle: item.requester ? `From ${item.requester}` : item.domainLabel,
    category: "APPROVAL",
    priority: isHigh ? "HIGH" : "NORMAL",
    status: "OPEN",
    path: "/workspace/approvals",
    icon: item.domainIcon || "fe fe-check-circle",
    dueLabel: item.dueLabel || null,
  };
}

export function mapApprovalToNotification(item) {
  const isHigh = String(item.priority || "").toUpperCase() === "HIGH";
  return {
    id: `approval-notif-${item.id}`,
    type: "APPROVAL",
    title: item.subject || `${item.domainLabel || item.domain} approval required`,
    body: item.requester ? `Action needed for ${item.requester}` : "Review in your approvals inbox.",
    priority: isHigh ? "HIGH" : "HIGH",
    status: "UNREAD",
    path: "/workspace/approvals",
    icon: item.domainIcon || "fe fe-check-circle",
    tone: "rose",
    createdAt: item.submittedAt || new Date().toISOString(),
    synthetic: true,
  };
}

export function mergeHeaderWorkItems(primaryItems, approvalItems) {
  const merged = dedupeById([
    ...(primaryItems || []),
    ...(approvalItems || []).map(mapApprovalToWorkItem),
  ]);
  return merged.filter((row) => row.status === "OPEN" || !row.status);
}

export function mergeHeaderNotifications(primaryItems, approvalItems) {
  const base = [...(primaryItems || [])];
  const existingKeys = new Set(
    base.map((row) => `${row.type}:${row.title}:${row.body || ""}`.toLowerCase())
  );

  (approvalItems || []).forEach((item) => {
    const synth = mapApprovalToNotification(item);
    const key = `${synth.type}:${synth.title}:${synth.body || ""}`.toLowerCase();
    if (!existingKeys.has(key)) {
      base.push(synth);
      existingKeys.add(key);
    }
  });

  return base;
}

export async function loadHeaderPopoverData() {
  const [workResult, notificationResult, approvalResult, homeResult] = await Promise.all([
    workspaceService.getMyWorkQueue().catch(() => apiErrorResult([])),
    workspaceService.getNotifications().catch(() => apiErrorResult([])),
    universalApprovalService.listInbox({ status: UNIVERSAL_APPROVAL_STATUSES.PENDING }).catch(() => ({
      payload: [],
      source: "api-error",
    })),
    workspaceService.getHomeDashboard().catch(() => ({ payload: null, source: "api-error" })),
  ]);

  let workItems = asArray(workResult);
  let notifications = asArray(notificationResult);

  const home = homeResult && homeResult.payload;
  if (home) {
    if (!workItems.length && Array.isArray(home.recentWork)) {
      workItems = home.recentWork;
    }
    if (!notifications.length && Array.isArray(home.recentNotifications)) {
      notifications = home.recentNotifications;
    }
  }

  const pendingApprovals = asArray(approvalResult).filter(
    (row) => row.status === UNIVERSAL_APPROVAL_STATUSES.PENDING
  );

  workItems = mergeHeaderWorkItems(workItems, pendingApprovals);
  notifications = mergeHeaderNotifications(notifications, pendingApprovals);

  const sources = [
    workResult && workResult.source,
    notificationResult && notificationResult.source,
    approvalResult && approvalResult.source,
    homeResult && homeResult.source,
  ].filter(Boolean);

  return {
    workItems,
    notifications,
    pendingApprovals,
    sources,
    workspaceApiBlocked:
      workResult.source === "api-error" && notificationResult.source === "api-error",
  };
}

export function isSyntheticHeaderNotification(row) {
  return Boolean(row && (row.synthetic === true || String(row.id || "").startsWith("approval-notif-")));
}

const DISMISSED_STORAGE_KEY = "tracopus.headerDismissedNotifications";

export function readDismissedHeaderNotificationIds() {
  if (typeof sessionStorage === "undefined") {
    return new Set();
  }
  try {
    const raw = sessionStorage.getItem(DISMISSED_STORAGE_KEY);
    const parsed = JSON.parse(raw || "[]");
    return new Set(Array.isArray(parsed) ? parsed : []);
  } catch (_error) {
    return new Set();
  }
}

export function writeDismissedHeaderNotificationIds(ids) {
  if (typeof sessionStorage === "undefined") {
    return;
  }
  try {
    sessionStorage.setItem(DISMISSED_STORAGE_KEY, JSON.stringify([...(ids || [])]));
  } catch (_error) {
    // Ignore storage failures; in-memory dismissals still apply for this session.
  }
}

export function applyHeaderNotificationDismissals(notifications, dismissedIds) {
  const dismissed = dismissedIds instanceof Set ? dismissedIds : new Set(dismissedIds || []);
  return (notifications || []).map((row) =>
    dismissed.has(row.id) ? { ...row, status: "READ" } : row
  );
}

export function markAllHeaderNotificationsRead(notifications, dismissedIds) {
  const nextDismissed = new Set(dismissedIds || []);
  (notifications || []).forEach((row) => {
    if (row.status === "UNREAD") {
      nextDismissed.add(row.id);
    }
  });
  writeDismissedHeaderNotificationIds(nextDismissed);
  return {
    notifications: applyHeaderNotificationDismissals(notifications, nextDismissed),
    dismissedIds: nextDismissed,
  };
}

export function dismissHeaderNotification(notifications, dismissedIds, notificationId) {
  const nextDismissed = new Set(dismissedIds || []);
  nextDismissed.add(notificationId);
  writeDismissedHeaderNotificationIds(nextDismissed);
  return {
    notifications: applyHeaderNotificationDismissals(notifications, nextDismissed),
    dismissedIds: nextDismissed,
  };
}
