import React from "react";
import classNames from "classnames/bind";

function HealthRing({ score }) {
  const tone = score >= 80 ? "green" : score >= 60 ? "amber" : "rose";
  return (
    <div className={classNames("lux-gov-analytics__health", `is-${tone}`)}>
      <strong>{score}</strong>
      <span>Health score</span>
    </div>
  );
}

export default function GovernanceAnalyticsPanel({ analytics, loading }) {
  if (loading) {
    return (
      <div className="lux-gov-analytics lux-gov-analytics--loading" aria-busy="true">
        <p>Loading governance analytics…</p>
      </div>
    );
  }

  if (!analytics) {
    return (
      <div className="lux-gov-analytics lux-gov-analytics--empty">
        <p>No analytics available. Load milestones, risks, and gates to populate the dashboard.</p>
      </div>
    );
  }

  const { healthScore, plannedVsActual, milestoneMetrics, gateMetrics, issueMetrics, riskMetrics } = analytics;

  return (
    <div className="lux-gov-analytics">
      <div className="lux-gov-analytics__top">
        <HealthRing score={healthScore} />
        <div className="lux-gov-analytics__kpis">
          <div>
            <strong>{milestoneMetrics.completionRate}%</strong>
            <span>Milestone completion</span>
          </div>
          <div>
            <strong>{milestoneMetrics.onCriticalPath}</strong>
            <span>Critical path items</span>
          </div>
          <div>
            <strong>{gateMetrics.complianceRate}%</strong>
            <span>Gate compliance</span>
          </div>
          <div>
            <strong>{issueMetrics.actionSlaRate}%</strong>
            <span>Action SLA</span>
          </div>
          <div>
            <strong>{riskMetrics.open}</strong>
            <span>Open risks</span>
          </div>
        </div>
      </div>

      <div className="lux-gov-analytics__planned">
        <header>
          <h3>Planned vs actual</h3>
          <span>
            Avg variance {plannedVsActual.avgVarianceDays > 0 ? "+" : ""}
            {plannedVsActual.avgVarianceDays} days
          </span>
        </header>
        {plannedVsActual.rows.length ? (
          <div className="lux-gov-analytics__bars">
            {plannedVsActual.rows.map((row) => (
              <div key={row.id} className="lux-gov-analytics__bar-row">
                <span className="lux-gov-analytics__label">{row.label}</span>
                <div className="lux-gov-analytics__tracks">
                  <div className="lux-gov-analytics__track">
                    <div
                      className="lux-gov-analytics__fill is-planned"
                      style={{ width: `${Math.round((row.plannedDays / plannedVsActual.maxDays) * 100)}%` }}
                    />
                  </div>
                  <div className="lux-gov-analytics__track">
                    <div
                      className="lux-gov-analytics__fill is-actual"
                      style={{ width: `${Math.round((row.actualDays / plannedVsActual.maxDays) * 100)}%` }}
                    />
                  </div>
                </div>
                <span className="lux-gov-analytics__variance">
                  {row.varianceDays > 0 ? `+${row.varianceDays}` : row.varianceDays}d
                </span>
              </div>
            ))}
          </div>
        ) : (
          <p className="lux-gov-analytics__hint">Add milestones with planned dates to chart schedule variance.</p>
        )}
        <div className="lux-gov-analytics__legend">
          <span><i className="is-planned" /> Planned duration</span>
          <span><i className="is-actual" /> Actual / progress</span>
        </div>
      </div>
    </div>
  );
}
