import React from "react";
import classNames from "classnames/bind";
import {
  getEmployeeInitials,
  getStaffingPriorityTone,
  getStaffingStatusTone,
} from "config/resource-planning.utils";

function formatDueLabel(dueAt) {
  if (!dueAt) return "No due date";
  return `Due ${dueAt}`;
}

export default function StaffingRequestRegister({ rows, loading, onSelect }) {
  if (loading) {
    return null;
  }

  return (
    <div className="lux-demand-queue" aria-label="Staffing demand queue">
      <ul className="lux-demand-queue__list">
        {rows.map((row) => {
          const statusTone = getStaffingStatusTone(row.status);
          const priorityTone = getStaffingPriorityTone(row.priority);
          const priority = String(row.priority || "NORMAL").toUpperCase();
          const isUrgent = priority === "HIGH" && (row.status === "Pending" || row.status === "Approved");
          const isOpen = row.status === "Pending" || row.status === "Approved";
          const initials = getEmployeeInitials(row.requesterName || row.title || "?");

          return (
            <li key={row.id}>
              <button
                type="button"
                className={classNames("lux-demand-queue__card", `is-status-${statusTone}`, {
                  "is-urgent": isUrgent,
                  "is-open": isOpen,
                })}
                onClick={() => onSelect && onSelect(row)}
              >
                <span className="lux-demand-queue__accent" aria-hidden="true" />

                <span className={classNames("lux-demand-queue__avatar", `is-${priorityTone}`)} aria-hidden="true">
                  {initials}
                </span>

                <div className="lux-demand-queue__main">
                  <div className="lux-demand-queue__title-row">
                    <strong className="lux-demand-queue__title">{row.title}</strong>
                    {isUrgent ? (
                      <span className="lux-demand-queue__urgent-pill">
                        <i className="fe fe-zap" aria-hidden="true" />
                        Urgent
                      </span>
                    ) : null}
                  </div>

                  <div className="lux-demand-queue__project">
                    <i className="fe fe-folder" aria-hidden="true" />
                    <span>{row.projectName || "Unassigned project"}</span>
                  </div>

                  {row.notes ? (
                    <p className="lux-demand-queue__notes">{row.notes}</p>
                  ) : null}

                  <div className="lux-demand-queue__meta">
                    <span className="lux-demand-queue__chip">
                      <i className="fe fe-briefcase" aria-hidden="true" />
                      {row.roleNeeded || "Role TBD"}
                    </span>
                    <span className="lux-demand-queue__chip is-count">
                      <i className="fe fe-users" aria-hidden="true" />
                      {row.headcount || 0} HC
                    </span>
                    <span className="lux-demand-queue__chip">
                      <i className="fe fe-calendar" aria-hidden="true" />
                      {formatDueLabel(row.dueAt)}
                    </span>
                    <span className="lux-demand-queue__chip is-muted">
                      <i className="fe fe-user" aria-hidden="true" />
                      {row.requesterName || "Unknown"}
                    </span>
                  </div>
                </div>

                <div className="lux-demand-queue__aside">
                  <span className={classNames("lux-demand-queue__priority", `is-${priorityTone}`)}>
                    {priority}
                  </span>
                  <span className={classNames("lux-demand-queue__status", `is-${statusTone}`)}>
                    {row.status}
                  </span>
                  <span className="lux-demand-queue__open">
                    Open
                    <i className="fe fe-chevron-right" aria-hidden="true" />
                  </span>
                </div>
              </button>
            </li>
          );
        })}
      </ul>
    </div>
  );
}
