import React, { Component } from "react";
import classNames from "classnames/bind";
import moment from "moment";
import {
  APPROVAL_DELEGATION_SCOPES,
  DELEGATION_DATE_PRESETS,
  applyDelegationDatePreset,
  buildDelegationPayload,
  getEmployeeInitials,
} from "_helpers/approvalDelegation.utils";

const EMPTY_FORM = {
  delegateId: null,
  // Default to attendance + leave. Timesheet needs enableTimeSheetApproval on the delegate —
  // users can add it explicitly so create does not fail for non-timesheet approvers.
  approvalTypes: ["ATTENDANCE", "LEAVE"],
  startDate: moment().format("YYYY-MM-DD"),
  endDate: moment().add(7, "days").format("YYYY-MM-DD"),
  note: "",
};

class ApprovalDelegationForm extends Component {
  constructor(props) {
    super(props);
    this.state = {
      form: props.initialForm || EMPTY_FORM,
      delegateQuery: "",
      formError: null,
      activePreset: null,
    };
  }

  componentDidUpdate(prevProps) {
    if (prevProps.initialForm !== this.props.initialForm && this.props.initialForm) {
      this.setState({ form: this.props.initialForm, formError: null, delegateQuery: "", activePreset: null });
    }
    if (prevProps.open !== this.props.open && this.props.open && !this.props.editing) {
      this.setState({ form: EMPTY_FORM, formError: null, delegateQuery: "", activePreset: null });
    }
  }

  setField = (field, value) => {
    this.setState((prevState) => ({
      form: { ...prevState.form, [field]: value },
      formError: null,
      activePreset: field === "startDate" || field === "endDate" ? null : prevState.activePreset,
    }));
  };

  toggleScope = (scopeId) => {
    this.setState((prevState) => {
      const current = prevState.form.approvalTypes || [];
      const hasScope = current.some((type) => String(type).toUpperCase() === scopeId);
      const approvalTypes = hasScope
        ? current.filter((type) => String(type).toUpperCase() !== scopeId)
        : current.concat(scopeId);
      return {
        form: { ...prevState.form, approvalTypes },
        formError: null,
      };
    });
  };

  applyPreset = (presetId) => {
    const dates = applyDelegationDatePreset(presetId, this.state.form.startDate);
    if (!dates) return;
    this.setState({
      form: {
        ...this.state.form,
        startDate: dates.startDate,
        endDate: dates.endDate,
      },
      formError: null,
      activePreset: presetId,
    });
  };

  validateForm = () => {
    const { form } = this.state;
    if (!form.delegateId) {
      return "Select a delegate.";
    }
    if (!form.approvalTypes || !form.approvalTypes.length) {
      return "Select at least one approval scope.";
    }
    if (!form.startDate || !form.endDate) {
      return "Start and end dates are required.";
    }
    const start = moment(form.startDate, "YYYY-MM-DD", true);
    const end = moment(form.endDate, "YYYY-MM-DD", true);
    if (!start.isValid() || !end.isValid()) {
      return "Enter valid dates.";
    }
    if (start.isAfter(end)) {
      return "Start date must be on or before end date.";
    }
    return null;
  };

  handleSubmit = (event) => {
    event.preventDefault();
    const { onSubmit, isLoading } = this.props;
    if (isLoading || !onSubmit) return;
    const formError = this.validateForm();
    if (formError) {
      this.setState({ formError });
      return;
    }
    onSubmit(buildDelegationPayload(this.state.form));
  };

  getFilteredDelegates = () => {
    const { delegateOptions } = this.props;
    const query = (this.state.delegateQuery || "").trim().toLowerCase();
    if (!query) return delegateOptions || [];
    return (delegateOptions || []).filter((employee) => {
      const name = (employee.name || "").toLowerCase();
      const code = (employee.empCode || "").toLowerCase();
      return name.indexOf(query) !== -1 || code.indexOf(query) !== -1;
    });
  };

  render() {
    const { open, editing, isLoading, onCancel, delegateOptions } = this.props;
    const { form, formError, delegateQuery, activePreset } = this.state;
    if (!open) return null;

    const selectedDelegate =
      (delegateOptions || []).find((employee) => String(employee.id) === String(form.delegateId)) ||
      null;
    const filteredDelegates = this.getFilteredDelegates();

    return (
      <form className="lux-approval-delegation__form" onSubmit={this.handleSubmit}>
        <header className="lux-approval-delegation__form-head">
          <span className="lux-approval-delegation__form-icon" aria-hidden="true">
            <i className="fe fe-user-check" />
          </span>
          <div>
            <h3>{editing ? "Edit delegation" : "New delegation"}</h3>
            <p>Choose who can approve on your behalf, what they can approve, and for how long.</p>
          </div>
        </header>

        <label className="lux-approval-delegation__field">
          <span className="lux-approval-delegation__label">Delegate</span>
          <div className="lux-approval-delegation__search-wrap">
            <i className="fe fe-search" aria-hidden="true" />
            <input
              type="search"
              className="lux-approval-delegation__input lux-approval-delegation__input--search"
              placeholder="Search by name or employee code…"
              value={delegateQuery}
              onChange={(event) => this.setState({ delegateQuery: event.target.value, formError: null })}
              disabled={isLoading || editing}
            />
          </div>
          {!editing && (
            <div className="lux-approval-delegation__delegate-list" role="listbox" aria-label="Delegates">
              {filteredDelegates.length ? (
                filteredDelegates.map((employee) => {
                  const selected = String(form.delegateId) === String(employee.id);
                  return (
                    <button
                      key={employee.id}
                      type="button"
                      role="option"
                      aria-selected={selected}
                      className={classNames("lux-approval-delegation__delegate-option", {
                        "is-selected": selected,
                      })}
                      onClick={() => this.setField("delegateId", employee.id)}
                      disabled={isLoading}
                    >
                      <span className="lux-approval-delegation__delegate-avatar" aria-hidden="true">
                        {getEmployeeInitials(employee.name)}
                      </span>
                      <span className="lux-approval-delegation__delegate-meta">
                        <strong>{employee.name}</strong>
                        {employee.empCode ? <em>{employee.empCode}</em> : null}
                      </span>
                      {selected ? <i className="fe fe-check" aria-hidden="true" /> : null}
                    </button>
                  );
                })
              ) : (
                <p className="lux-approval-delegation__empty-hint">No matching employees. Try another search.</p>
              )}
            </div>
          )}
          {editing && selectedDelegate ? (
            <div className="lux-approval-delegation__selected-delegate">
              <span className="lux-approval-delegation__avatar" aria-hidden="true">
                {getEmployeeInitials(selectedDelegate.name)}
              </span>
              <span>
                Delegating to <strong>{selectedDelegate.name}</strong>
              </span>
            </div>
          ) : null}
          {!editing && selectedDelegate ? (
            <p className="lux-approval-delegation__selected-hint">
              <i className="fe fe-check-circle" aria-hidden="true" />
              Selected: <strong>{selectedDelegate.name}</strong>
            </p>
          ) : null}
        </label>

        <div className="lux-approval-delegation__field-row">
          <label className="lux-approval-delegation__field">
            <span className="lux-approval-delegation__label">Start date</span>
            <input
              type="date"
              className="lux-approval-delegation__input"
              value={form.startDate || ""}
              onChange={(event) => this.setField("startDate", event.target.value)}
              disabled={isLoading}
            />
          </label>
          <label className="lux-approval-delegation__field">
            <span className="lux-approval-delegation__label">End date</span>
            <input
              type="date"
              className="lux-approval-delegation__input"
              value={form.endDate || ""}
              onChange={(event) => this.setField("endDate", event.target.value)}
              disabled={isLoading}
            />
          </label>
        </div>

        {!editing ? (
          <div className="lux-approval-delegation__presets" role="group" aria-label="Quick duration">
            <span className="lux-approval-delegation__label">Quick duration</span>
            <div className="lux-approval-delegation__preset-row">
              {DELEGATION_DATE_PRESETS.map((preset) => (
                <button
                  key={preset.id}
                  type="button"
                  className={classNames("lux-approval-delegation__preset-btn", {
                    "is-active": activePreset === preset.id,
                  })}
                  onClick={() => this.applyPreset(preset.id)}
                  disabled={isLoading}
                >
                  {preset.label}
                </button>
              ))}
            </div>
          </div>
        ) : null}

        <fieldset className="lux-approval-delegation__scopes">
          <legend className="lux-approval-delegation__label">What can they approve?</legend>
          <div className="lux-approval-delegation__scope-grid">
            {APPROVAL_DELEGATION_SCOPES.map((scope) => {
              const checked = (form.approvalTypes || []).some(
                (type) => String(type).toUpperCase() === scope.id
              );
              return (
                <label
                  key={scope.id}
                  className={classNames("lux-approval-delegation__scope-card", {
                    "is-checked": checked,
                  })}
                >
                  <input
                    type="checkbox"
                    checked={checked}
                    onChange={() => this.toggleScope(scope.id)}
                    disabled={isLoading}
                  />
                  <span className="lux-approval-delegation__scope-card-icon" aria-hidden="true">
                    <i className={`fe ${scope.icon}`} />
                  </span>
                  <span className="lux-approval-delegation__scope-card-copy">
                    <strong>{scope.label}</strong>
                    <em>{scope.hint}</em>
                  </span>
                </label>
              );
            })}
          </div>
        </fieldset>

        <label className="lux-approval-delegation__field">
          <span className="lux-approval-delegation__label">Note for your records (optional)</span>
          <textarea
            className="lux-approval-delegation__textarea"
            rows={3}
            placeholder="e.g. Vacation coverage — contact me only for escalations"
            value={form.note || ""}
            onChange={(event) => this.setField("note", event.target.value)}
            disabled={isLoading}
          />
        </label>

        {formError ? (
          <p className="lux-approval-delegation__error" role="alert">
            <i className="fe fe-alert-circle" aria-hidden="true" />
            {formError}
          </p>
        ) : null}

        <div className="lux-approval-delegation__form-actions">
          <button
            type="button"
            className="lux-approval-delegation__btn lux-approval-delegation__btn--ghost"
            onClick={onCancel}
            disabled={isLoading}
          >
            Cancel
          </button>
          <button
            type="submit"
            className="lux-approval-delegation__btn lux-approval-delegation__btn--primary"
            disabled={isLoading}
          >
            <i className="fe fe-check" aria-hidden="true" />
            {editing ? "Save changes" : "Create delegation"}
          </button>
        </div>
      </form>
    );
  }
}

export default ApprovalDelegationForm;
