export function getPortfolioShellPageTitle(variant = PORTFOLIO_PAGE_VARIANTS.PORTFOLIO) {
  const meta = PORTFOLIO_PAGE_META[variant] || PORTFOLIO_PAGE_META.portfolio;
  return [meta.titleLead, meta.titleAccent].filter(Boolean).join(" ").trim();
}
