import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import classNames from "classnames/bind";
import dateUtils from "_helpers/date.utils";
import { store } from "_helpers";
import { workItemActions } from "_actions";
import { buildGanttHourlyLanes, buildGanttLanes, formatPlannerHours, UTIL_TONES } from "./plannerAnalytics.utils";
import { enrichWorkItemDetail, PLANNER_HOUR_START } from "./plannerHourly.utils";
import {
  getItemEndDate,
  getItemStartDate,
  getPlannerFocusEmployeeName,
  getPlannerScheduleEmptyState,
} from "./planner.utils";
import PlannerViewHero from "./components/PlannerViewHero";
import PlannerLuxPanel from "./components/PlannerLuxPanel";
import PlannerScheduleEmptyState from "./components/PlannerScheduleEmptyState";

const SIDEBAR_WIDTH = 220;
const ROW_HEIGHT = 44;
const GROUP_HEADER_HEIGHT = 36;
const MIN_PX_PER_DAY = 48;
const MIN_PX_PER_HOUR = 44;

export default function TeamCapacityGanttView({
  workItems,
  weekStartMoment,
  horizonWeeks,
  ganttAxis,
  ganttLevel,
  filterOptions,
  selectedEmployeeId,
  canEdit,
  onRescheduled,
  onGanttAxisChange,
  onGanttLevelChange,
  history,
  timeGranularity = "DAY",
  focusDayMoment,
  onFocusDayChange,
  employees,
}) {
  const frameRef = useRef(null);
  const headScrollRef = useRef(null);
  const tracksScrollRef = useRef(null);
  const sidebarScrollRef = useRef(null);
  const scrollSyncLock = useRef(false);
  const [dragState, setDragState] = useState(null);
  const [selectedBar, setSelectedBar] = useState(null);
  const [collapsedGroups, setCollapsedGroups] = useState({});
  const [trackWidth, setTrackWidth] = useState(800);

  const isHourly = timeGranularity === "HOUR";
  const focusDay = (focusDayMoment || weekStartMoment).clone().startOf("day");

  const model = useMemo(() => {
    if (isHourly) {
      return buildGanttHourlyLanes({
        workItems,
        focusDayMoment: focusDay,
        ganttAxis,
        ganttLevel,
        filterOptions,
        selectedEmployeeId,
      });
    }
    return buildGanttLanes({
      workItems,
      startMoment: weekStartMoment,
      horizonWeeks,
      ganttAxis,
      ganttLevel,
      filterOptions,
      selectedEmployeeId,
    });
  }, [
    isHourly,
    workItems,
    focusDay,
    weekStartMoment,
    horizonWeeks,
    ganttAxis,
    ganttLevel,
    filterOptions,
    selectedEmployeeId,
  ]);

  const unitCount = Math.max(model.totalDays, 1);
  const pxPerUnit = isHourly
    ? Math.max(MIN_PX_PER_HOUR, trackWidth / unitCount)
    : Math.max(MIN_PX_PER_DAY, trackWidth / unitCount);
  const todayLeft =
    model.todayOffset != null && model.todayOffset >= 0 && model.todayOffset <= unitCount
      ? model.todayOffset * pxPerUnit
      : null;

  useEffect(() => {
    const el = frameRef.current;
    if (!el || typeof ResizeObserver === "undefined") return undefined;

    const measure = () => {
      const timelineEl = tracksScrollRef.current || el.querySelector(".lux-planner-gantt__tracks-scroll");
      const w = timelineEl ? timelineEl.clientWidth : el.clientWidth - SIDEBAR_WIDTH;
      const minWidth = isHourly ? model.totalDays * MIN_PX_PER_HOUR : model.totalDays * MIN_PX_PER_DAY;
      setTrackWidth(Math.max(w, minWidth));
    };

    measure();
    const ro = new ResizeObserver(measure);
    ro.observe(el);
    if (tracksScrollRef.current) ro.observe(tracksScrollRef.current);
    window.addEventListener("resize", measure);
    return () => {
      ro.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [model.totalDays, horizonWeeks, isHourly]);

  const syncFromTracks = useCallback(() => {
    if (scrollSyncLock.current) return;
    const tracks = tracksScrollRef.current;
    if (!tracks) return;
    scrollSyncLock.current = true;
    if (headScrollRef.current) {
      headScrollRef.current.scrollLeft = tracks.scrollLeft;
    }
    if (sidebarScrollRef.current) {
      sidebarScrollRef.current.scrollTop = tracks.scrollTop;
    }
    requestAnimationFrame(() => {
      scrollSyncLock.current = false;
    });
  }, []);

  const syncFromSidebar = useCallback(() => {
    if (scrollSyncLock.current) return;
    const sidebar = sidebarScrollRef.current;
    const tracks = tracksScrollRef.current;
    if (!sidebar || !tracks) return;
    scrollSyncLock.current = true;
    tracks.scrollTop = sidebar.scrollTop;
    requestAnimationFrame(() => {
      scrollSyncLock.current = false;
    });
  }, []);

  const syncFromHead = useCallback(() => {
    if (scrollSyncLock.current) return;
    const head = headScrollRef.current;
    const tracks = tracksScrollRef.current;
    if (!head || !tracks) return;
    scrollSyncLock.current = true;
    tracks.scrollLeft = head.scrollLeft;
    requestAnimationFrame(() => {
      scrollSyncLock.current = false;
    });
  }, []);

  const persistReschedule = useCallback(
    (item, deltaUnits) => {
      const start = getItemStartDate(item);
      if (!start || !canEdit) return;
      const startM = dateUtils.convertDateToMoment(start);
      if (isHourly) {
        startM.add(deltaUnits, "hours");
      } else {
        startM.add(deltaUnits, "days");
      }
      const end = getItemEndDate(item, start);
      const durationMins = Math.max(
        15,
        dateUtils.convertDateToMoment(end).diff(dateUtils.convertDateToMoment(start), "minutes")
      );
      store.dispatch(
        workItemActions.updateWorkItem({
          ...item,
          estStartTime: startM.format(dateUtils.SERVER_DATE_FORMAT),
          estDurationInMins: item.estDurationInMins || durationMins,
        })
      );
      onRescheduled && onRescheduled();
    },
    [canEdit, onRescheduled, isHourly]
  );

  const onBarPointerDown = (e, item) => {
    if (!canEdit) return;
    e.preventDefault();
    e.stopPropagation();
    setDragState({ item, startX: e.clientX, deltaUnits: 0 });
  };

  const onMouseMove = (e) => {
    if (!dragState) return;
    const deltaUnits = Math.round((e.clientX - dragState.startX) / pxPerUnit);
    setDragState((prev) => (prev ? { ...prev, deltaUnits } : null));
  };

  const onMouseUp = () => {
    if (!dragState) return;
    if (dragState.deltaUnits !== 0) {
      persistReschedule(dragState.item, dragState.deltaUnits);
    }
    setDragState(null);
  };

  const toggleGroup = (id) => {
    setCollapsedGroups((prev) => ({ ...prev, [id]: !prev[id] }));
  };

  const totalBars = model.groups.reduce((s, g) => s + g.bars.length, 0);
  const canvasWidth = model.totalDays * pxPerUnit;
  const emptyState = getPlannerScheduleEmptyState({
    workItems,
    filterOptions,
    selectedEmployeeId,
    employees,
    laneFilterText: "",
    visibleLaneCount: model.groups.length,
  });
  const focusLabel =
    selectedEmployeeId != null
      ? getPlannerFocusEmployeeName(employees, selectedEmployeeId)
      : "All team";

  const panelProps = selectedBar
    ? (() => {
        const d = enrichWorkItemDetail(selectedBar.seg.item, selectedBar.seg.minutes);
        const actions = [];
        if (d.item.taskId) {
          actions.push({
            key: "task",
            icon: "fe-layers",
            label: "Open deliverable",
            sublabel: d.taskName,
            variant: "primary",
            onClick: () => history && history.push(`/project/deliverable/${d.item.taskId}`),
          });
        }
        if (d.item.projectId) {
          actions.push({
            key: "project",
            icon: "fe-briefcase",
            label: "Open project",
            sublabel: d.projectName,
            variant: "ghost",
            onClick: () => history && history.push(`/project/details/${d.item.projectId}`),
          });
        }
        return {
          open: true,
          onClose: () => setSelectedBar(null),
          title: selectedBar.bar.label,
          subtitle: `${d.statusMeta.label} · ${d.durationLabel}`,
          statusMeta: d.statusMeta,
          metrics: [
            { label: "Project", value: d.projectName },
            { label: "Task", value: d.taskName },
            { label: "Planned", value: d.durationLabel },
          ],
          assignments: selectedBar.bar.items.map((item) => ({
            item,
            minutes: item.estDurationInMins || 60,
          })),
          primaryItem: { item: d.item, minutes: d.minutes },
          actions,
        };
      })()
    : null;

  return (
    <div
      className={classNames("lux-planner-gantt lux-planner-gantt--fluid", {
        "is-hourly": isHourly,
      })}
      ref={frameRef}
      onMouseMove={onMouseMove}
      onMouseUp={onMouseUp}
      onMouseLeave={onMouseUp}
    >
      <PlannerViewHero
        eyebrow="Gantt"
        eyebrowVariant="planner-gantt"
        title="Schedule & reschedule"
        description={
          isHourly
            ? `Hour-level Gantt for ${focusDay.format("dddd DD MMM")} (8am–6pm). Drag bars to shift start time.`
            : "Timeline expands to full width for your selected horizon. Drag bars to shift dates; click for rich details."
        }
        meta={
          isHourly
            ? `${focusLabel} · ${model.groups.length} groups · ${totalBars} bars · ${pxPerUnit.toFixed(0)}px/hour`
            : `${focusLabel} · ${model.groups.length} groups · ${totalBars} bars · ${pxPerUnit.toFixed(0)}px/day`
        }
        actions={
          <>
            <div className="lux-planner-segment">
              <button type="button" className={classNames({ "is-active": ganttAxis === "EMPLOYEE" })} onClick={() => onGanttAxisChange && onGanttAxisChange("EMPLOYEE")}>
                By employee
              </button>
              <button type="button" className={classNames({ "is-active": ganttAxis === "PROJECT" })} onClick={() => onGanttAxisChange && onGanttAxisChange("PROJECT")}>
                By project
              </button>
            </div>
            <div className="lux-planner-segment">
              <button type="button" className={classNames({ "is-active": ganttLevel === "TASK" })} onClick={() => onGanttLevelChange && onGanttLevelChange("TASK")}>
                Tasks
              </button>
              <button type="button" className={classNames({ "is-active": ganttLevel === "WORK_ITEM" })} onClick={() => onGanttLevelChange && onGanttLevelChange("WORK_ITEM")}>
                Work items
              </button>
            </div>
            {isHourly && onFocusDayChange && (
              <input
                type="date"
                className="lux-planner-gantt__date-pick"
                value={focusDay.format("YYYY-MM-DD")}
                onChange={(e) => {
                  const m = dateUtils.convertDateStringToMoment(e.target.value);
                  if (m && m.isValid()) onFocusDayChange(m);
                }}
                aria-label="Focus day for hourly Gantt"
              />
            )}
          </>
        }
      />

      <div className="lux-planner-gantt__legend">
        {Object.keys(UTIL_TONES).map((key) => (
          <span key={key}>
            <i style={{ background: UTIL_TONES[key].color }} />
            {UTIL_TONES[key].label}
          </span>
        ))}
        <span className="lux-planner-gantt__legend-note">
          {canEdit ? "Drag bars to reschedule · timeline uses full available width" : "View-only"}
        </span>
      </div>

      <div
        className={classNames("lux-planner-gantt__frame lux-planner-gantt__frame--fluid", {
          "is-hourly": isHourly,
        })}
        style={{ "--gantt-sidebar-width": `${SIDEBAR_WIDTH}px` }}
      >
        <div className="lux-planner-gantt__sidebar-head" style={{ width: SIDEBAR_WIDTH }}>
          {isHourly ? focusDay.format("ddd DD MMM") : "Resource / work"}
        </div>
        <div
          className="lux-planner-gantt__timeline-head lux-planner-gantt__timeline-head--fluid"
          ref={headScrollRef}
          onScroll={syncFromHead}
        >
          <div className="lux-planner-gantt__timeline-inner" style={{ width: canvasWidth }}>
            {isHourly
              ? (model.slots || []).map((slot) => {
                  const period = slot.hour < 12 ? "AM" : "PM";
                  const displayHour = slot.hour % 12 === 0 ? 12 : slot.hour % 12;
                  return (
                    <div
                      key={slot.hour}
                      className={classNames("lux-planner-gantt__day lux-planner-gantt__day--hour", {
                        "is-now":
                          todayLeft != null &&
                          Math.floor(model.todayOffset) === slot.hour - PLANNER_HOUR_START,
                      })}
                      style={{ width: pxPerUnit, flex: `0 0 ${pxPerUnit}px` }}
                    >
                      <strong>{displayHour}</strong>
                      <span>{period}</span>
                    </div>
                  );
                })
              : model.days.map((d) => (
                  <div
                    key={d.format("YYYY-MM-DD")}
                    className={classNames("lux-planner-gantt__day", {
                      "is-weekend": d.isoWeekday() >= 6,
                      "is-today": d.isSame(dateUtils.getCurrentTime(), "day"),
                    })}
                    style={{ width: pxPerUnit, flex: `0 0 ${pxPerUnit}px` }}
                  >
                    <span>{d.format("ddd")}</span>
                    <strong>{d.format("DD MMM")}</strong>
                  </div>
                ))}
          </div>
        </div>

        <div className="lux-planner-gantt__body lux-planner-gantt__body--fluid">
          <div
            className="lux-planner-gantt__sidebar"
            style={{ width: SIDEBAR_WIDTH }}
            ref={sidebarScrollRef}
            onScroll={syncFromSidebar}
          >
            {emptyState && (
              <PlannerScheduleEmptyState
                className="lux-planner-schedule-empty--gantt"
                title={emptyState.title}
                detail={emptyState.detail}
              />
            )}
            {model.groups.map((group) => (
              <div key={group.id} className="lux-planner-gantt__sidebar-group">
                <button
                  type="button"
                  className="lux-planner-gantt__sidebar-group-btn"
                  style={{ height: GROUP_HEADER_HEIGHT }}
                  onClick={() => toggleGroup(group.id)}
                >
                  <i className={`fe fe-chevron-${collapsedGroups[group.id] ? "right" : "down"}`} />
                  <span className="text-truncate">{group.label}</span>
                  <em>{group.bars.length}</em>
                </button>
                {!collapsedGroups[group.id] &&
                  group.bars.map((bar) => (
                    <div
                      key={bar.id}
                      className="lux-planner-gantt__sidebar-row text-truncate"
                      style={{ height: ROW_HEIGHT }}
                      title={bar.label}
                    >
                      {bar.label}
                    </div>
                  ))}
              </div>
            ))}
          </div>

          <div
            className="lux-planner-gantt__tracks-scroll"
            ref={tracksScrollRef}
            onScroll={syncFromTracks}
          >
            <div className="lux-planner-gantt__canvas" style={{ width: canvasWidth }}>
              <div className="lux-planner-gantt__grid-cols" aria-hidden>
                {isHourly
                  ? (model.slots || []).map((slot) => (
                      <div
                        key={slot.hour}
                        className={classNames("lux-planner-gantt__grid-col", {
                          "is-hour": true,
                          "is-now":
                            todayLeft != null &&
                            Math.floor(model.todayOffset) === slot.hour - PLANNER_HOUR_START,
                        })}
                        style={{ width: pxPerUnit, flex: `0 0 ${pxPerUnit}px` }}
                      />
                    ))
                  : model.days.map((d) => (
                      <div
                        key={d.format("YYYY-MM-DD")}
                        className={classNames("lux-planner-gantt__grid-col", {
                          "is-weekend": d.isoWeekday() >= 6,
                        })}
                        style={{ width: pxPerUnit, flex: `0 0 ${pxPerUnit}px` }}
                      />
                    ))}
              </div>
              {todayLeft != null && (
                <div className="lux-planner-gantt__today-line" style={{ left: todayLeft }} />
              )}
              <div className="lux-planner-gantt__bars-layer">
                {model.groups.map((group) => (
                  <div key={group.id} className="lux-planner-gantt__track-group">
                    <div
                      className="lux-planner-gantt__group-spacer"
                      style={{ height: GROUP_HEADER_HEIGHT, width: canvasWidth }}
                      aria-hidden
                    />
                    {collapsedGroups[group.id]
                      ? null
                      : group.bars.map((bar) => (
                          <div
                            key={`${group.id}-${bar.id}`}
                            className="lux-planner-gantt__track-row"
                            style={{ height: ROW_HEIGHT, width: canvasWidth }}
                          >
                            {bar.segments.map((seg, idx) => {
                              const dragOffset =
                                dragState && dragState.item.id === seg.item.id
                                  ? dragState.deltaUnits * pxPerUnit
                                  : 0;
                              const left =
                                (isHourly ? seg.offsetHours : seg.offsetDays) * pxPerUnit +
                                dragOffset;
                              const span = isHourly ? seg.durationHours : seg.durationDays;
                              const width = span * pxPerUnit;
                              return (
                                <button
                                  type="button"
                                  key={`${bar.id}-${idx}`}
                                  className={classNames("lux-planner-gantt__bar", {
                                    "is-draggable": canEdit,
                                  })}
                                  style={{
                                    left,
                                    width: Math.max(width, pxPerUnit * 0.35),
                                    background: seg.color,
                                  }}
                                  onClick={() => setSelectedBar({ bar, seg })}
                                  onMouseDown={(e) => onBarPointerDown(e, seg.item)}
                                >
                                  <span className="text-truncate">{bar.label}</span>
                                </button>
                              );
                            })}
                          </div>
                        ))}
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </div>

      {panelProps && <PlannerLuxPanel {...panelProps} />}
    </div>
  );
}
