import { appConfigService } from '../_services';
import { commonUtils } from './common.utils';

/** Organization app-config key (boolean). Default true when unset — tours available from Assist, not auto-launched. */
export const GUIDED_NAVIGATION_CONFIG_KEY = 'guidedNavigationEnabled';

/** When false, tours only start from Assist → Guided tour (no auto-start on navigation). */
export const GUIDED_TOUR_AUTO_START_ENABLED = false;

export const GUIDED_NAVIGATION_CONFIG_CHANGED = 'famstack-guided-navigation-config-changed';

let orgGuidedNavigationEnabled = true;
let configLoaded = false;
let loadPromise = null;

function parseGuidedNavigationEnabled(value) {
  if (value === undefined || value === null) {
    return true;
  }
  if (value === false || value === 'false') {
    return false;
  }
  if (value === true || value === 'true') {
    return true;
  }
  return true;
}

export function isGuidedNavigationEnabledFromConfig(configList) {
  if (!configList || !configList.length) {
    return true;
  }
  const value = commonUtils.getAppConfigValue(configList, GUIDED_NAVIGATION_CONFIG_KEY);
  return parseGuidedNavigationEnabled(value);
}

export function applyGuidedNavigationConfig(configList) {
  orgGuidedNavigationEnabled = isGuidedNavigationEnabledFromConfig(configList);
  configLoaded = true;
  return orgGuidedNavigationEnabled;
}

export function isGuidedNavigationOrgEnabled() {
  return orgGuidedNavigationEnabled;
}

export function isGuidedNavigationConfigLoaded() {
  return configLoaded;
}

export function notifyGuidedNavigationConfigChanged() {
  if (typeof window !== 'undefined') {
    window.dispatchEvent(new CustomEvent(GUIDED_NAVIGATION_CONFIG_CHANGED));
  }
}

export function loadGuidedNavigationConfig(force) {
  if (!force && configLoaded) {
    return Promise.resolve(orgGuidedNavigationEnabled);
  }
  if (!force && loadPromise) {
    return loadPromise;
  }

  const teamId = commonUtils.getCurrentUserTeamId();
  if (!teamId) {
    orgGuidedNavigationEnabled = true;
    configLoaded = true;
    return Promise.resolve(true);
  }

  loadPromise = appConfigService
    .getModuleConfig(teamId, 'PROJECT')
    .then((response) => {
      const list = response && response.payload;
      applyGuidedNavigationConfig(list);
      notifyGuidedNavigationConfigChanged();
      return orgGuidedNavigationEnabled;
    })
    .catch(() => {
      orgGuidedNavigationEnabled = true;
      configLoaded = true;
      return true;
    })
    .finally(() => {
      loadPromise = null;
    });

  return loadPromise;
}

export function refreshGuidedNavigationConfig() {
  configLoaded = false;
  return loadGuidedNavigationConfig(true);
}
