import React from "react";
import classNames from "classnames/bind";

export default function DependencyRegister({ rows, criticalDependencyIds = [], validationIssues = [], loading }) {
  if (loading) {
    return null;
  }

  const criticalSet = new Set(criticalDependencyIds);
  const issueByDependency = {};
  validationIssues.forEach((issue) => {
    if (issue.dependencyId) {
      issueByDependency[issue.dependencyId] = issue;
    }
  });

  if (!rows.length) {
    return (
      <div className="lux-gov-deps-empty">
        <p>No dependencies linked yet. Add finish-to-start links to unlock critical-path analysis.</p>
      </div>
    );
  }

  return (
    <div className="lux-gov-register-wrap">
      <table className="lux-gov-register lux-gov-register--deps">
        <thead>
          <tr>
            <th>Predecessor</th>
            <th>Successor</th>
            <th>Type</th>
            <th>Lag</th>
            <th>Path</th>
            <th>Checks</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => {
            const issue = issueByDependency[row.id];
            return (
              <tr
                key={row.id}
                className={classNames("lux-gov-register__row", {
                  "is-critical": criticalSet.has(row.id),
                  "is-risk": issue && issue.severity === "warning",
                })}
              >
                <td>{row.predecessorName || row.predecessorId}</td>
                <td>{row.successorName || row.successorId}</td>
                <td>{(row.type || "FINISH_TO_START").replace(/_/g, " ").toLowerCase()}</td>
                <td>{row.lagDays || 0}d</td>
                <td>
                  {criticalSet.has(row.id) ? (
                    <span className="lux-gov-register__chip is-critical">Critical link</span>
                  ) : (
                    <span className="lux-gov-register__chip">Standard</span>
                  )}
                </td>
                <td>
                  {issue ? (
                    <span className={classNames("lux-gov-deps-issue", `is-${issue.severity}`)}>{issue.copy}</span>
                  ) : (
                    <span className="lux-gov-deps-issue is-ok">Aligned</span>
                  )}
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
}
