export function getRecruitingNavActiveId(pathname) {
  const path = String(pathname || "");
  const match = RECRUITING_MODULE_NAV.find(
    (item) => path === item.path || path.startsWith(`${item.path}/`)
  );
  return match ? match.id : "/recruiting/dashboard";
}
