import React from "react";
import { Redirect, Route } from "react-router-dom";
import { ROUTE_ALIASES } from "config/navigation.config";

/**
 * F01-T4: Legacy URL aliases → canonical routes (redesigned-menu §5).
 * Returns flat Switch children — must NOT wrap in Fragment (breaks Switch matching).
 */
export function buildNavigationAliasRoutes() {
  const routes = ROUTE_ALIASES.map((alias) => {
    if (alias.preserveSearch || alias.defaultSearch) {
      return (
        <Route
          key={alias.from}
          exact
          path={alias.from}
          render={({ location }) => (
            <Redirect
              to={{
                pathname: alias.to,
                search: location.search || alias.defaultSearch || "",
              }}
            />
          )}
        />
      );
    }
    return <Redirect key={alias.from} exact from={alias.from} to={alias.to} />;
  });

  routes.push(
    <Route
      key="/sales/bidrequest/:bidRequestId"
      exact
      path="/sales/bidrequest/:bidRequestId"
      render={({ match, location }) => (
        <Redirect
          to={{
            pathname: `/finance/bidrequest/${match.params.bidRequestId}`,
            search: location.search,
            state: location.state,
          }}
        />
      )}
    />
  );

  routes.push(
    <Route
      key="/sales/purchaseorder/:purchaseOrderId"
      exact
      path="/sales/purchaseorder/:purchaseOrderId"
      render={({ match, location }) => (
        <Redirect
          to={{
            pathname: `/finance/purchaseorder/${match.params.purchaseOrderId}`,
            search: location.search,
            state: location.state,
          }}
        />
      )}
    />
  );

  routes.push(
    <Route
      key="/people/profile/:employeeId"
      exact
      path="/people/profile/:employeeId"
      render={({ match, location }) => (
        <Redirect
          to={{
            pathname: `/people/employees/${match.params.employeeId}`,
            search: location.search,
            state: location.state,
          }}
        />
      )}
    />
  );

  routes.push(
    <Route
      key="/hrms/profile/:employeeId"
      exact
      path="/hrms/profile/:employeeId"
      render={({ match, location }) => (
        <Redirect
          to={{
            pathname: `/people/employees/${match.params.employeeId}`,
            search: location.search,
            state: location.state,
          }}
        />
      )}
    />
  );

  routes.push(
    <Route
      key="/hrms/employees/:employeeId/360"
      exact
      path="/hrms/employees/:employeeId/360"
      render={({ match, location }) => (
        <Redirect
          to={{
            pathname: `/people/employees/${match.params.employeeId}/360`,
            search: location.search,
            state: location.state,
          }}
        />
      )}
    />
  );

  routes.push(
    <Route
      key="/hrms/employees/:employeeId"
      exact
      path="/hrms/employees/:employeeId"
      render={({ match, location }) => (
        <Redirect
          to={{
            pathname: `/people/employees/${match.params.employeeId}`,
            search: location.search,
            state: location.state,
          }}
        />
      )}
    />
  );

  return routes;
}

export default buildNavigationAliasRoutes;
