import React, { Component } from "react";
import { QRCodeSVG } from "qrcode.react";
import urlConfig from "url.config";
import { userUtils } from "_helpers";
import envconfig from "env.config";
import { brandUtils } from "_helpers";
import { FAMSTACK_GOOGLE_PLAY_URL } from "../mobileApp.constants";

const STEPS = [
  {
    title: "Download the app",
    text: "Scan the Android QR code or tap Get it on Google Play.",
  },
  {
    title: "Open Tracopus Mobile",
    text: "Launch the app and sign in with your organization account.",
  },
  {
    title: "Scan registration QR",
    text: "Use the in-app scanner on the registration code below.",
  },
  {
    title: "Complete registration",
    text: "Follow the prompts to pair your device securely.",
  },
];

const DOWNLOAD_QR_SIZE = 112;
const REGISTER_QR_SIZE = 128;
const QR_LOGO = 16;

class MobileAppRegistrationPanel extends Component {
  renderQr = (value, title, size) => (
    <QRCodeSVG
      value={value}
      title={title}
      size={size}
      bgColor="#ffffff"
      fgColor="#0f172a"
      level="M"
      marginSize={2}
      imageSettings={{
        src: envconfig.BACK_END_API_ENDPOINT + "/favicon.ico",
        height: QR_LOGO,
        width: QR_LOGO,
        opacity: 1,
        excavate: true,
      }}
    />
  );

  render() {
    const embedded = this.props.embedded === true;
    const registrationUrl =
      envconfig.BACK_END_API_ENDPOINT +
      urlConfig.DEVICE_REGISTRATION_URL +
      "?emailId=" +
      userUtils.getCurrentUserEmail() +
      "&userId=" +
      userUtils.getCurrentUserId();

    return (
      <div
        className={`lux-mobile-app${embedded ? " lux-mobile-app--embedded" : " lux-mobile-app--popup"}`}
      >
        <header className="lux-mobile-app__hero">
          <div className="lux-mobile-app__hero-icon" aria-hidden="true">
            <i className="fe fe-smartphone" />
          </div>
          <div className="lux-mobile-app__hero-copy">
            <p className="lux-mobile-app__kicker">Mobile workspace</p>
            <h3 className="lux-mobile-app__title">{brandUtils.MOBILE_APP_BRAND_NAME} Mobile</h3>
            <p className="lux-mobile-app__subtitle">
              Connect your mobile device to {brandUtils.MOBILE_APP_BRAND_NAME} for secure timesheets,
              tasks, and project updates on the go.
            </p>
          </div>
        </header>

        <div className="lux-mobile-app__split">
          <section className="lux-mobile-app__zone lux-mobile-app__zone--download">
            <div className="lux-mobile-app__zone-head">
              <h4 className="lux-mobile-app__zone-title">Download the app</h4>
              <p className="lux-mobile-app__zone-desc">
                Choose your platform and install {brandUtils.MOBILE_APP_BRAND_NAME} Mobile.
              </p>
            </div>

            <div className="lux-mobile-app__platform-row">
              <article className="lux-mobile-app__platform lux-mobile-app__platform--android">
                <span className="lux-mobile-app__pill lux-mobile-app__pill--accent">
                  <i className="fa fa-android" aria-hidden="true" />
                  Android
                </span>
                <h5 className="lux-mobile-app__platform-title">Google Play</h5>
                <p className="lux-mobile-app__platform-text">Scan to download</p>
                <div className="lux-mobile-app__qr-frame lux-mobile-app__qr-frame--sm">
                  {this.renderQr(
                    FAMSTACK_GOOGLE_PLAY_URL,
                    brandUtils.MOBILE_APP_BRAND_NAME + " on Google Play",
                    DOWNLOAD_QR_SIZE
                  )}
                </div>
                <a
                  href={FAMSTACK_GOOGLE_PLAY_URL}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="lux-mobile-app__store-link"
                  data-ga-action="mobile_app_google_play"
                  data-ga-category="engagement"
                  data-ga-label="Google Play download"
                >
                  <img
                    src="/assets/images/custom/google-store-btn.png"
                    alt="Get it on Google Play"
                  />
                </a>
              </article>

              <article
                className="lux-mobile-app__platform lux-mobile-app__platform--ios lux-mobile-app__platform--disabled"
                aria-disabled="true"
              >
                <span className="lux-mobile-app__pill lux-mobile-app__pill--muted">
                  <i className="fa fa-apple" aria-hidden="true" />
                  iOS
                </span>
                <h5 className="lux-mobile-app__platform-title">App Store</h5>
                <p className="lux-mobile-app__platform-text">Coming soon</p>
                <div className="lux-mobile-app__qr-frame lux-mobile-app__qr-frame--placeholder lux-mobile-app__qr-frame--sm">
                  <i className="fa fa-apple lux-mobile-app__apple-icon" aria-hidden="true" />
                  <span className="lux-mobile-app__soon-badge">Unavailable</span>
                </div>
                <span className="lux-mobile-app__store-link lux-mobile-app__store-link--disabled">
                  <img
                    src="/assets/images/custom/apple-store-btn.png"
                    alt="Download on the App Store — coming soon"
                  />
                </span>
                <span className="lux-mobile-app__coming-soon">Coming soon on iOS</span>
              </article>
            </div>
          </section>

          <div className="lux-mobile-app__divider" role="separator" aria-hidden="true" />

          <section className="lux-mobile-app__zone lux-mobile-app__zone--register">
            <div className="lux-mobile-app__zone-head">
              <h4 className="lux-mobile-app__zone-title">Register this device</h4>
              <p className="lux-mobile-app__zone-desc">
                After installing the app, scan this code to pair your phone with {brandUtils.MOBILE_APP_BRAND_NAME}.
              </p>
            </div>

            <div className="lux-mobile-app__register-body">
              <div className="lux-mobile-app__register-qr">
                <span className="lux-mobile-app__pill">
                  <i className="fe fe-link" aria-hidden="true" />
                  Registration
                </span>
                <div className="lux-mobile-app__qr-frame lux-mobile-app__qr-frame--register">
                  {this.renderQr(
                    registrationUrl,
                    brandUtils.MOBILE_APP_BRAND_NAME + " Mobile App Registration",
                    REGISTER_QR_SIZE
                  )}
                </div>
                <p className="lux-mobile-app__scan-label">
                  <i className="fa fa-qrcode" aria-hidden="true" />
                  Scan with the mobile app
                </p>
              </div>
            </div>
          </section>
        </div>

        <section className="lux-mobile-app__steps-bar">
          <h4 className="lux-mobile-app__section-title">Quick guide</h4>
          <ol className="lux-mobile-app__steps">
            {STEPS.map((step, index) => (
              <li key={step.title} className="lux-mobile-app__step">
                <span className="lux-mobile-app__step-num">{index + 1}</span>
                <div className="lux-mobile-app__step-body">
                  <strong>{step.title}</strong>
                  <p>{step.text}</p>
                </div>
              </li>
            ))}
          </ol>
        </section>

        <footer className="lux-mobile-app__tip">
          <i className="fe fe-info" aria-hidden="true" />
          <span>
            For the smoothest registration, keep your phone and computer on the same network.
          </span>
          <a className="d-none" href={registrationUrl}>
            Registration Link
          </a>
        </footer>
      </div>
    );
  }
}

export default MobileAppRegistrationPanel;
