export function getAiWorkIntelligenceShellPageTitle(routePath) {
  if (!routePath) {
    return "AI agents";
  }
  if (routePath.startsWith(AI_WORK_INTELLIGENCE_ROUTES.RECOMMENDATIONS)) {
    return "AI recommendations";
  }
  if (routePath.startsWith(AI_WORK_INTELLIGENCE_ROUTES.WBS)) {
    return "WBS assistant";
  }
  if (routePath.startsWith(AI_WORK_INTELLIGENCE_ROUTES.STAFFING)) {
    return "Staffing agent";
  }
  if (routePath.startsWith(AI_WORK_INTELLIGENCE_ROUTES.PAYROLL)) {
    return "Payroll readiness";
  }
  if (routePath.startsWith(AI_WORK_INTELLIGENCE_ROUTES.TIMESHEET)) {
    return "Timesheet agent";
  }
  if (routePath.startsWith(AI_WORK_INTELLIGENCE_ROUTES.RISK)) {
    return "Risk agent";
  }
  if (routePath.startsWith(AI_WORK_INTELLIGENCE_ROUTES.EXECUTIVE)) {
    return "Executive briefing";
  }
  return "AI agent console";
}
