/**
 * F20-T4 — Feature flag administration service.
 */
import { axiosUtils, commonUtils } from "../_helpers";
import urlConfig from "url.config";
import { isFeatureFlagsAdminEnabled, normalizeFeatureFlag } from "config/feature-flag.config";
import { refreshTracopusPilotConfig } from "config/tracopus-pilot.config";
import { recordAuditEvent } from "config/audit-write.service";
import { AUDIT_ENTITY_TYPES } from "_constants/audit.constants";

import { apiErrorResult } from "config/mock-fallback.utils";

export const featureFlagService = {
  listFlags,
  getFlag,
  updateFlag,
  setFlagStatus,
};

const API_BASE = `${urlConfig.APPCONFIG_API_PATH}/feature-flags`;

function teamQuery(extra) {
  const query = { userTeamId: commonUtils.getCurrentUserTeamId() };
  if (extra) {
    Object.keys(extra).forEach((key) => {
      if (extra[key] != null && extra[key] !== "") {
        query[key] = extra[key];
      }
    });
  }
  return query;
}

function canUseFeatureFlagsAdminApi() {
  return isFeatureFlagsAdminEnabled() === true;
}

async function refreshPilotConfigAfterFlagChange() {
  try {
    if (typeof refreshTracopusPilotConfig === "function") {
      await refreshTracopusPilotConfig();
    }
  } catch (e) {
    // Flag save succeeded; refresh is best-effort so menus pick up org config.
  }
}

async function listFlags() {
  if (canUseFeatureFlagsAdminApi()) {
    try {
      const response = await axiosUtils.getWithParam(API_BASE, teamQuery());
      const rows = (response && response.payload) || response || [];
      return {
        payload: (Array.isArray(rows) ? rows : []).map(normalizeFeatureFlag).filter(Boolean),
        source: "api",
      };
    } catch (e) {
      // fall through
    }
  }

  return apiErrorResult(null);
}

async function getFlag(flagId) {
  if (canUseFeatureFlagsAdminApi()) {
    try {
      const response = await axiosUtils.getWithParam(`${API_BASE}/${flagId}`, teamQuery());
      const row = (response && response.payload) || response;
      return { payload: normalizeFeatureFlag(row), source: "api" };
    } catch (e) {
      // fall through
    }
  }
  return apiErrorResult(null);
}

async function updateFlag(flagId, enabled) {
  if (canUseFeatureFlagsAdminApi()) {
    try {
      const response = await axiosUtils.patch(
        `${API_BASE}/${flagId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
        { enabled }
      );
      const row = (response && response.payload) || response;
      const result = { payload: normalizeFeatureFlag(row), source: "api" };
      recordAuditEvent({
        actionType: enabled ? "UPDATED" : "STATUS_CHANGED",
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: `${result.payload && result.payload.name} · ${result.payload && result.payload.key}`,
        metadata: { flagId, enabled, scope: result.payload && result.payload.scope },
      });
      await refreshPilotConfigAfterFlagChange();
      return result;
    } catch (e) {
      // fall through
    }
  }
  throw new Error("Unable to complete action via API.");
}

async function setFlagStatus(flagId, status) {
  if (canUseFeatureFlagsAdminApi()) {
    try {
      const response = await axiosUtils.patch(
        `${API_BASE}/${flagId}?userTeamId=${commonUtils.getCurrentUserTeamId()}`,
        { status }
      );
      const row = (response && response.payload) || response;
      const result = { payload: normalizeFeatureFlag(row), source: "api" };
      recordAuditEvent({
        actionType: "STATUS_CHANGED",
        entityType: AUDIT_ENTITY_TYPES.ADMIN_CONFIG,
        entityRef: result.payload && result.payload.name,
        metadata: { flagId, status },
      });
      await refreshPilotConfigAfterFlagChange();
      return result;
    } catch (e) {
      // fall through
    }
  }
  throw new Error("Unable to complete action via API.");
}
