import { accessUtils, commonUtils } from "_helpers";
import { ROUTE_ALIASES, GLOBAL_RAIL, GLOBAL_RAIL_TOOLS } from "config/navigation.config";
import { findSidebarItemForPath } from "config/persona-route.utils";
import { getTracopusPilotOrgFlags, ORG_CONFIG_GROUPS } from "config/tracopus-pilot.config";
import {
  ACCESS_BINDING_BY_FLAG,
  ACCESS_BINDING_BY_SEGMENT,
  APP_CONFIG_ASSIST_PATH,
  FLAG_MODULE_LABELS,
  ORG_GROUPS_BY_FLAG_MODULE,
  ORG_GROUPS_BY_MENU_FLAG,
  ORG_GROUP_LABELS,
  PERMISSION_KEY_SKIP,
  PERMISSION_KEY_DESCRIPTIONS,
  ROLE_ASSIST_ORG_MIRROR_KEYS,
  buildHowToSteps,
  buildOrgHowToSteps,
  humanizePermissionKey,
} from "./page-permission-assist.config";

function normalizePath(pathname) {
  return (pathname || "").split("?")[0].replace(/\/+$/, "") || "/";
}

function applyRouteAliases(pathname) {
  let path = normalizePath(pathname);
  for (const alias of ROUTE_ALIASES || []) {
    const from = normalizePath(alias.from);
    if (!from.includes(":")) {
      if (path === from || path.startsWith(`${from}/`)) {
        const to = normalizePath(alias.to);
        path = path === from ? to : `${to}${path.slice(from.length)}`;
        break;
      }
    }
  }
  return path;
}

function isActionPermissionKey(key) {
  if (!key || PERMISSION_KEY_SKIP.has(key)) {
    return false;
  }
  return (
    /Enabled$/i.test(key) ||
    /^enable[A-Z_]/.test(key) ||
    /^allow[A-Z_]/.test(key) ||
    key === "enableTimeSheetEntry" ||
    key === "enableTimeSheetEdit" ||
    key === "enableTimeSheetApproval" ||
    key === "enableTimeSheetReopen"
  );
}

function extractBooleanPermissions(source, configSetting, options = {}) {
  if (!source || typeof source !== "object") {
    return [];
  }
  const excludeOrgMirrors = options.excludeOrgMirrors === true;
  return Object.keys(source)
    .filter((key) => typeof source[key] === "boolean" && isActionPermissionKey(key))
    .filter((key) => !(excludeOrgMirrors && ROLE_ASSIST_ORG_MIRROR_KEYS.has(key)))
    .map((key) => ({
      id: key,
      label: humanizePermissionKey(key),
      description: PERMISSION_KEY_DESCRIPTIONS[key] || null,
      enabled: source[key] === true,
      configKey: key,
      configSetting,
      kind: "flag",
    }));
}

function resolveBinding(path, menuFlag) {
  if (menuFlag && ACCESS_BINDING_BY_FLAG[menuFlag]) {
    return ACCESS_BINDING_BY_FLAG[menuFlag];
  }
  const segments = path.split("/").filter(Boolean);
  for (let i = segments.length - 1; i >= 0; i -= 1) {
    const segment = String(segments[i] || "").toLowerCase();
    if (ACCESS_BINDING_BY_SEGMENT[segment]) {
      return ACCESS_BINDING_BY_SEGMENT[segment];
    }
  }
  return null;
}

function inferRawAccessKeys(path) {
  const segments = path.split("/").filter(Boolean);
  if (!segments.length) {
    return [];
  }
  const last = segments[segments.length - 1];
  const camel = last.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
  const candidates = [camel, `${camel}s`, last.replace(/-/g, ""), last];
  const found = [];
  const seen = new Set();
  candidates.forEach((key) => {
    if (!key || seen.has(key)) {
      return;
    }
    seen.add(key);
    try {
      const blob = accessUtils.getAccessControll(key);
      if (blob && typeof blob === "object" && Object.keys(blob).length > 0) {
        found.push(key);
        const additional = `${key}Additional`;
        const extra = accessUtils.getAccessControll(additional);
        if (extra && typeof extra === "object" && Object.keys(extra).length > 0) {
          found.push(additional);
        }
      }
    } catch (error) {
      /* ignore */
    }
  });
  return found;
}

function loadActionPermissions(binding, path) {
  const permissions = [];
  const seen = new Set();

  const pushUnique = (items) => {
    (items || []).forEach((item) => {
      const dedupeKey = `${item.configSetting || ""}::${item.configKey || item.id}`;
      if (seen.has(dedupeKey)) {
        return;
      }
      seen.add(dedupeKey);
      permissions.push(item);
    });
  };

  if (binding && binding.getter && typeof accessUtils[binding.getter] === "function") {
    try {
      const source = accessUtils[binding.getter]() || {};
      // Getter blobs mix role RBAC with org mirrors — keep only role keys here.
      pushUnique(
        extractBooleanPermissions(source, binding.setting || "Module permissions", {
          excludeOrgMirrors: true,
        })
      );
      return {
        permissions,
        configSetting: binding.setting || null,
        moduleLabel: binding.moduleLabel || null,
        source: `getter:${binding.getter}`,
      };
    } catch (error) {
      /* fall through */
    }
  }

  const keys =
    (binding && binding.keys && binding.keys.length && binding.keys) || inferRawAccessKeys(path);

  keys.forEach((key) => {
    try {
      const blob = accessUtils.getAccessControll(key) || {};
      const settingLabel =
        (binding && binding.setting) ||
        humanizePermissionKey(key.replace(/Additional$/i, "")) ||
        key;
      const isAdditional = /Additional$/i.test(key);
      // *Additional blobs are org config — skip in role assist (shown under Org tab).
      if (isAdditional) {
        return;
      }
      pushUnique(
        extractBooleanPermissions(blob, settingLabel, {
          excludeOrgMirrors: true,
        })
      );
    } catch (error) {
      /* ignore */
    }
  });

  return {
    permissions,
    configSetting: (binding && binding.setting) || (keys[0] ? humanizePermissionKey(keys[0]) : null),
    moduleLabel: (binding && binding.moduleLabel) || null,
    source: keys.length ? `raw:${keys.join(",")}` : "none",
  };
}

function resolveMenuContext(path) {
  const match = findSidebarItemForPath(path);
  if (match && match.item) {
    return buildMenuContextFromItem(match.item, match.group);
  }
  // Rail-only pages (e.g. Application config moved off Admin sidebar) still need
  // menu-flag context for the access guide.
  const railItem = findRailItemForPath(path);
  if (railItem) {
    return buildMenuContextFromItem(
      {
        name: railItem.title,
        flagModule: railItem.flagModule,
        flag: railItem.flag,
      },
      { label: FLAG_MODULE_LABELS[railItem.flagModule] || "Module" }
    );
  }
  return null;
}

function findRailItemForPath(path) {
  const normalized = normalizePath(path);
  const catalog = [...(GLOBAL_RAIL || []), ...(GLOBAL_RAIL_TOOLS || [])];
  let best = null;
  catalog.forEach((item) => {
    if (!item || item.type !== "link" || !item.path) {
      return;
    }
    const itemPath = normalizePath(item.path);
    const matches =
      normalized === itemPath || normalized.startsWith(`${itemPath}/`);
    if (!matches) {
      return;
    }
    if (!best || itemPath.length > normalizePath(best.path).length) {
      best = item;
    }
  });
  return best;
}

function buildMenuContextFromItem(item, group) {
  const flagModule = item.flagModule || null;
  const flag = item.flag || null;
  let menuAccess = {};
  try {
    menuAccess = accessUtils.getMenuAccessControl() || {};
  } catch (error) {
    menuAccess = {};
  }
  const moduleFlags = (flagModule && menuAccess[flagModule]) || {};
  const moduleActive = moduleFlags.active === true || moduleFlags.active == null;
  const pageEnabled = flag ? moduleFlags[flag] === true : true;

  return {
    title: item.name || item.title || (group && group.label) || "This page",
    flagModule,
    flag,
    groupLabel: (group && group.label) || FLAG_MODULE_LABELS[flagModule] || null,
    moduleLabel: FLAG_MODULE_LABELS[flagModule] || (group && group.label) || null,
    moduleActive,
    pageEnabled,
    menuAccess,
  };
}

function resolveOrgGroupsForPage(menu, binding, path) {
  const groups = [];
  const seen = new Set();
  const push = (key) => {
    if (!key || seen.has(key)) return;
    seen.add(key);
    groups.push(key);
  };

  if (menu && menu.flag && ORG_GROUPS_BY_MENU_FLAG[menu.flag]) {
    ORG_GROUPS_BY_MENU_FLAG[menu.flag].forEach(push);
  }
  if (menu && menu.flagModule && ORG_GROUPS_BY_FLAG_MODULE[menu.flagModule]) {
    ORG_GROUPS_BY_FLAG_MODULE[menu.flagModule].forEach(push);
  }
  if (binding && Array.isArray(binding.keys)) {
    binding.keys
      .filter((key) => /Additional$/i.test(key) || key === "approvalDelegation")
      .forEach(push);
  }

  const lower = String(path || "").toLowerCase();
  if (lower.includes("work-graph")) push("tracopusWorkspaceAdditional");
  if (lower.includes("onboarding") || lower.includes("offboarding")) {
    push("lifecycleAdditional");
    push("tracopusPeopleAdditional");
  }
  if (lower.includes("payroll") || lower.includes("paycheck") || lower.includes("benefits")) {
    push("tracopusPayrollAdditional");
  }
  if (lower.includes("analytics") || lower.includes("/ai/")) push("tracopusAnalyticsAdditional");
  if (lower.includes("/admin/")) {
    push("tracopusAdminAdditional");
    push("auditAdditional");
  }

  if (groups.length === 0) {
    Object.values(ORG_CONFIG_GROUPS || {}).forEach(push);
  }
  return groups;
}

function formatOrgPropertyValue(value) {
  if (value == null) {
    return "—";
  }
  if (typeof value === "boolean") {
    return value ? "On" : "Off";
  }
  if (typeof value === "number") {
    return String(value);
  }
  if (typeof value === "string") {
    return value.trim() === "" ? "(empty)" : value;
  }
  if (Array.isArray(value)) {
    if (value.length === 0) {
      return "0 items";
    }
    if (value.every((item) => typeof item === "string" || typeof item === "number")) {
      const preview = value.slice(0, 3).map(String).join(", ");
      return value.length > 3 ? `${preview}… (${value.length})` : preview;
    }
    return `${value.length} item${value.length === 1 ? "" : "s"}`;
  }
  if (typeof value === "object") {
    const keys = Object.keys(value);
    return keys.length === 0 ? "{ }" : `${keys.length} key${keys.length === 1 ? "" : "s"}`;
  }
  return String(value);
}

function loadOrgGroupBlob(groupKey) {
  try {
    const blob = accessUtils.getAccessControll(groupKey);
    if (blob && typeof blob === "object" && !Array.isArray(blob) && Object.keys(blob).length > 0) {
      return blob;
    }
  } catch (error) {
    /* ignore */
  }
  return {};
}

/**
 * Current user role + org labels from the logged-in employee payload.
 * Org path walks defaultUserTeamDetails.parent when nested.
 */
export function resolveCurrentIdentity() {
  let user = null;
  try {
    user = commonUtils.getCurrentUser && commonUtils.getCurrentUser();
  } catch (error) {
    user = null;
  }

  const roleId =
    (user && user.userAccessDetails && user.userAccessDetails.id) ||
    (user && user.userRole) ||
    (commonUtils.getCurrentUserRoleId && commonUtils.getCurrentUserRoleId()) ||
    null;
  const roleName =
    (user && user.userAccessDetails && user.userAccessDetails.name) || null;
  const roleLabel = roleName || (roleId != null ? `Role #${roleId}` : null);

  const team = (user && user.defaultUserTeamDetails) || null;
  const teamId =
    (team && team.id) ||
    (commonUtils.getCurrentUserTeamId && commonUtils.getCurrentUserTeamId()) ||
    null;
  const teamName =
    (team && team.name) ||
    (commonUtils.getCurrentUserTeamName && commonUtils.getCurrentUserTeamName()) ||
    null;

  const pathParts = [];
  let cursor = team;
  const seen = new Set();
  while (cursor && cursor.name && !seen.has(String(cursor.id != null ? cursor.id : cursor.name))) {
    seen.add(String(cursor.id != null ? cursor.id : cursor.name));
    pathParts.unshift(cursor.name);
    cursor = cursor.parent || null;
  }

  const orgPath = pathParts.length > 0 ? pathParts.join(" / ") : teamName || null;
  const orgLabel =
    orgPath || (teamId != null ? `Team #${teamId}` : null);

  return {
    roleId,
    roleName,
    roleLabel,
    teamId,
    teamName,
    orgPath,
    orgLabel,
  };
}

/**
 * Resolve role permission guidance for any route from sidebar + access control.
 */
export function resolvePagePermissionAssist(pathname) {
  const path = applyRouteAliases(pathname);
  const menu = resolveMenuContext(path);
  const binding = resolveBinding(path, menu && menu.flag);
  const actionLoad = loadActionPermissions(binding, path);
  const identity = resolveCurrentIdentity();

  const permissions = [];

  if (menu) {
    permissions.push({
      id: "menu-access",
      label: `Open ${menu.title}`,
      description: menu.flag
        ? `Menu flag ${menu.flagModule}.${menu.flag}`
        : "Page menu access for your role",
      enabled: menu.moduleActive && menu.pageEnabled,
      configKey: menu.flag || "active",
      configSetting: `${menu.moduleLabel || "Module"} → Module access`,
      kind: "flag",
    });

    if (menu.flagModule) {
      permissions.push({
        id: "module-active",
        label: `${menu.moduleLabel || "Module"} module active`,
        description: `Module group ${menu.flagModule}`,
        enabled: menu.moduleActive,
        configKey: "active",
        configSetting: `${menu.moduleLabel || "Module"} module`,
        kind: "flag",
      });
    }
  }

  (actionLoad.permissions || []).forEach((item) => {
    permissions.push(item);
  });

  const title = (menu && menu.title) || actionLoad.configSetting || "This page";
  const moduleLabel = actionLoad.moduleLabel || (menu && menu.moduleLabel) || null;
  const configSetting =
    actionLoad.configSetting ||
    (menu && menu.flag ? humanizePermissionKey(menu.flag) : null);
  const hasActionPermissions = (actionLoad.permissions || []).length > 0;
  const supported = Boolean(menu || hasActionPermissions);

  const enabledCount = permissions.filter((item) => item.enabled).length;
  const disabledCount = permissions.length - enabledCount;

  return {
    path,
    scope: "role",
    supported,
    id: (menu && menu.flag) || (binding && binding.setting) || "page",
    title,
    moduleLabel,
    configSetting,
    howTo: buildHowToSteps({
      moduleLabel,
      configSetting,
      hasActionPermissions,
      pageTitle: title,
    }),
    permissions,
    properties: [],
    enabledCount,
    disabledCount,
    appConfigPath: APP_CONFIG_ASSIST_PATH,
    crudSource: actionLoad.source,
    menuFlag: menu ? `${menu.flagModule}.${menu.flag}` : null,
    teamId: identity.teamId,
    roleId: identity.roleId,
    roleName: identity.roleName,
    roleLabel: identity.roleLabel,
    teamName: identity.teamName,
    orgPath: identity.orgPath,
    orgLabel: identity.orgLabel,
  };
}

/**
 * Resolve org-level flags + property configs for the current team / page.
 */
export function resolvePageOrgAssist(pathname) {
  const path = applyRouteAliases(pathname);
  const menu = resolveMenuContext(path);
  const binding = resolveBinding(path, menu && menu.flag);
  const groupKeys = resolveOrgGroupsForPage(menu, binding, path);
  const identity = resolveCurrentIdentity();
  const teamId = identity.teamId;

  let pilotFlags = {};
  try {
    pilotFlags = getTracopusPilotOrgFlags() || {};
  } catch (error) {
    pilotFlags = {};
  }

  const flags = [];
  const properties = [];
  const seenFlags = new Set();
  const seenProps = new Set();
  const groupLabels = [];
  const blobsByGroup = {};

  groupKeys.forEach((groupKey) => {
    const label = ORG_GROUP_LABELS[groupKey] || humanizePermissionKey(groupKey);
    groupLabels.push(label);
    const blob = loadOrgGroupBlob(groupKey);
    blobsByGroup[groupKey] = blob;
    const settingPath = `Org → HRMS.${groupKey}`;

    Object.keys(blob).forEach((key) => {
      if (PERMISSION_KEY_SKIP.has(key)) {
        return;
      }
      const value = blob[key];
      if (typeof value === "boolean" || /Enabled$/i.test(key) || /^allow/i.test(key)) {
        const dedupe = `${groupKey}.${key}`;
        if (seenFlags.has(dedupe)) return;
        seenFlags.add(dedupe);
        const enabled =
          typeof value === "boolean"
            ? value === true
            : Object.prototype.hasOwnProperty.call(pilotFlags, key)
              ? pilotFlags[key] === true
              : false;
        flags.push({
          id: `org-flag-${groupKey}-${key}`,
          label: humanizePermissionKey(key),
          description: PERMISSION_KEY_DESCRIPTIONS[key] || `${settingPath}.${key}`,
          enabled,
          configKey: key,
          configSetting: settingPath,
          kind: "flag",
          groupKey,
        });
        return;
      }
      const dedupe = `${groupKey}.${key}`;
      if (seenProps.has(dedupe)) return;
      seenProps.add(dedupe);
      properties.push({
        id: `org-prop-${groupKey}-${key}`,
        label: humanizePermissionKey(key),
        description: `${settingPath}.${key}`,
        enabled: value != null && value !== "" && !(Array.isArray(value) && value.length === 0),
        valueText: formatOrgPropertyValue(value),
        configKey: key,
        configSetting: settingPath,
        kind: "property",
        groupKey,
      });
    });
  });

  Object.keys(pilotFlags).forEach((key) => {
    if (typeof pilotFlags[key] !== "boolean") {
      return;
    }
    const already = [...seenFlags].some((id) => id.endsWith(`.${key}`));
    if (already) {
      return;
    }
    const owningGroup = groupKeys.find((groupKey) =>
      Object.prototype.hasOwnProperty.call(blobsByGroup[groupKey] || {}, key)
    );
    // When groups are narrow (page-scoped), include unmatched pilot flags that likely belong
    if (!owningGroup && groupKeys.length > 4) {
      return;
    }
    const groupKey = owningGroup || groupKeys[0];
    if (!groupKey) {
      return;
    }
    const settingPath = `Org → HRMS.${groupKey}`;
    const dedupe = `${groupKey}.${key}`;
    if (seenFlags.has(dedupe)) return;
    seenFlags.add(dedupe);
    flags.push({
      id: `org-pilot-${key}`,
      label: humanizePermissionKey(key),
      description: `${settingPath}.${key}`,
      enabled: pilotFlags[key] === true,
      configKey: key,
      configSetting: settingPath,
      kind: "flag",
      groupKey,
    });
  });

  flags.sort((a, b) => Number(b.enabled) - Number(a.enabled) || a.label.localeCompare(b.label));
  properties.sort((a, b) => a.label.localeCompare(b.label));

  const title = (menu && menu.title) || "This page";
  const supported = flags.length > 0 || properties.length > 0;
  const enabledCount = flags.filter((item) => item.enabled).length;
  const disabledCount = flags.length - enabledCount;

  return {
    path,
    scope: "org",
    supported,
    id: `org:${(menu && menu.flag) || "page"}`,
    title,
    moduleLabel: (menu && menu.moduleLabel) || "Organization",
    configSetting: groupLabels.slice(0, 3).join(", ") || "Org Additional Config",
    howTo: buildOrgHowToSteps({
      groupLabels: groupLabels.slice(0, 4),
      teamId,
      orgLabel: identity.orgLabel,
      orgPath: identity.orgPath,
    }),
    permissions: flags,
    properties,
    enabledCount,
    disabledCount,
    propertyCount: properties.length,
    appConfigPath: APP_CONFIG_ASSIST_PATH,
    crudSource: `org:${groupKeys.join(",")}`,
    menuFlag: menu ? `${menu.flagModule}.${menu.flag}` : null,
    teamId,
    teamName: identity.teamName,
    orgPath: identity.orgPath,
    orgLabel: identity.orgLabel,
    roleId: identity.roleId,
    roleName: identity.roleName,
    roleLabel: identity.roleLabel,
    groupKeys,
  };
}
