import { commonUtils } from "_helpers/common.utils";
import {
  normalizeFavorite,
  normalizeSavedView,
  WORKSPACE_PERSONALIZATION_CHANGED,
} from "config/workspace-personalization.config";

const STORAGE_PREFIX = "famstack-workspace-personalization";

function storageKey() {
  const userId = commonUtils.getCurrentUserId();
  return userId ? `${STORAGE_PREFIX}-${userId}` : `${STORAGE_PREFIX}-anonymous`;
}

function readStore() {
  if (typeof window === "undefined") {
    return { favorites: [], savedViews: [] };
  }
  try {
    const raw = localStorage.getItem(storageKey());
    if (!raw) {
      return { favorites: [], savedViews: [] };
    }
    const parsed = JSON.parse(raw);
    return {
      favorites: Array.isArray(parsed.favorites) ? parsed.favorites : [],
      savedViews: Array.isArray(parsed.savedViews) ? parsed.savedViews : [],
    };
  } catch (e) {
    return { favorites: [], savedViews: [] };
  }
}

function writeStore(store) {
  if (typeof window === "undefined") {
    return store;
  }
  localStorage.setItem(storageKey(), JSON.stringify(store));
  window.dispatchEvent(new CustomEvent(WORKSPACE_PERSONALIZATION_CHANGED, { detail: store }));
  return store;
}

export function notifyPersonalizationChanged() {
  if (typeof window !== "undefined") {
    window.dispatchEvent(new CustomEvent(WORKSPACE_PERSONALIZATION_CHANGED));
  }
}

export function listFavoritesFromStorage() {
  return readStore().favorites.map(normalizeFavorite).filter(Boolean);
}

export function listSavedViewsFromStorage(surface) {
  const rows = readStore().savedViews.map(normalizeSavedView).filter(Boolean);
  if (!surface) {
    return rows;
  }
  return rows.filter((row) => row.surface === surface);
}

export function addFavoriteToStorage(entry) {
  const favorite = normalizeFavorite(entry);
  if (!favorite) {
    return listFavoritesFromStorage();
  }
  const store = readStore();
  if (store.favorites.some((row) => row.path === favorite.path)) {
    return store.favorites.map(normalizeFavorite).filter(Boolean);
  }
  store.favorites = [...store.favorites, favorite];
  writeStore(store);
  return store.favorites.map(normalizeFavorite).filter(Boolean);
}

export function removeFavoriteFromStorage(path) {
  const store = readStore();
  store.favorites = store.favorites.filter((row) => row.path !== path);
  writeStore(store);
  return store.favorites.map(normalizeFavorite).filter(Boolean);
}

export function createSavedViewInStorage(entry) {
  const view = normalizeSavedView({
    ...entry,
    id: entry.id || `wsv-${Date.now()}`,
    createdAt: entry.createdAt || new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  });
  if (!view) {
    return listSavedViewsFromStorage();
  }
  const store = readStore();
  store.savedViews = [...store.savedViews, view];
  writeStore(store);
  return store.savedViews.map(normalizeSavedView).filter(Boolean);
}

export function deleteSavedViewFromStorage(viewId) {
  const store = readStore();
  store.savedViews = store.savedViews.filter((row) => row.id !== viewId);
  writeStore(store);
  return store.savedViews.map(normalizeSavedView).filter(Boolean);
}

export function replacePersonalizationStore(nextStore) {
  writeStore({
    favorites: (nextStore && nextStore.favorites) || [],
    savedViews: (nextStore && nextStore.savedViews) || [],
  });
}
